SCADE ON DELETE CASCADE not valid","alter table \\"public\\".\\"subservices\\" validate constraint \\"subservices_service_id_fkey\\"","alter table \\"public\\".\\"suppliers\\" add constraint \\"suppliers_business_id_fkey\\" FOREIGN KEY (business_id) REFERENCES businesses(business_id) ON UPDATE CASCADE ON DELETE CASCADE not valid","alter table \\"public\\".\\"suppliers\\" validate constraint \\"suppliers_business_id_fkey\\"","alter table \\"public\\".\\"suppliers\\" add constraint \\"suppliers_org_id_fkey\\" FOREIGN KEY (org_id) REFERENCES organizations(org_id) ON UPDATE CASCADE ON DELETE CASCADE not valid","alter table \\"public\\".\\"suppliers\\" validate constraint \\"suppliers_org_id_fkey\\"","alter table \\"public\\".\\"taxes\\" add constraint \\"taxes_business_id_fkey\\" FOREIGN KEY (business_id) REFERENCES businesses(business_id) ON UPDATE CASCADE ON DELETE CASCADE not valid","alter table \\"public\\".\\"taxes\\" validate constraint \\"taxes_business_id_fkey\\"","alter table \\"public\\".\\"taxes\\" add constraint \\"taxes_org_id_fkey\\" FOREIGN KEY (org_id) REFERENCES organizations(org_id) ON UPDATE CASCADE ON DELETE CASCADE not valid","alter table \\"public\\".\\"taxes\\" validate constraint \\"taxes_org_id_fkey\\"","alter table \\"public\\".\\"transaction_entries\\" add constraint \\"transaction_entries_account_id_fkey\\" FOREIGN KEY (account_id) REFERENCES accounts(account_id) ON UPDATE CASCADE ON DELETE CASCADE not valid","alter table \\"public\\".\\"transaction_entries\\" validate constraint \\"transaction_entries_account_id_fkey\\"","alter table \\"public\\".\\"transaction_entries\\" add constraint \\"transaction_entries_transaction_id_fkey\\" FOREIGN KEY (transaction_id) REFERENCES transactions(transaction_id) ON DELETE CASCADE not valid","alter table \\"public\\".\\"transaction_entries\\" validate constraint \\"transaction_entries_transaction_id_fkey\\"","alter table \\"public\\".\\"transactions\\" add constraint \\"fk_reverses_transaction\\" FOREIGN KEY (reverses_transaction_id) REFERENCES transactions(transaction_id) ON DELETE SET NULL not valid","alter table \\"public\\".\\"transactions\\" validate constraint \\"fk_reverses_transaction\\"","alter table \\"public\\".\\"transactions\\" add constraint \\"fk_transactions_item_id\\" FOREIGN KEY (item_id) REFERENCES items(item_id) ON DELETE SET NULL not valid","alter table \\"public\\".\\"transactions\\" validate constraint \\"fk_transactions_item_id\\"","alter table \\"public\\".\\"transactions\\" add constraint \\"transactions_business_id_fkey\\" FOREIGN KEY (business_id) REFERENCES businesses(business_id) ON DELETE CASCADE not valid","alter table \\"public\\".\\"transactions\\" validate constraint \\"transactions_business_id_fkey\\"","alter table \\"public\\".\\"transactions\\" add constraint \\"transactions_business_id_reference_no_key\\" UNIQUE using index \\"transactions_business_id_reference_no_key\\"","alter table \\"public\\".\\"transactions\\" add constraint \\"transactions_created_by_fkey\\" FOREIGN KEY (created_by) REFERENCES users(user_id) not valid","alter table \\"public\\".\\"transactions\\" validate constraint \\"transactions_created_by_fkey\\"","alter table \\"public\\".\\"units\\" add constraint \\"units_business_id_fkey\\" FOREIGN KEY (business_id) REFERENCES businesses(business_id) ON UPDATE CASCADE ON DELETE CASCADE not valid","alter table \\"public\\".\\"units\\" validate constraint \\"units_business_id_fkey\\"","alter table \\"public\\".\\"units\\" add constraint \\"units_org_id_fkey\\" FOREIGN KEY (org_id) REFERENCES organizations(org_id) ON UPDATE CASCADE ON DELETE CASCADE not valid","alter table \\"public\\".\\"units\\" validate constraint \\"units_org_id_fkey\\"","alter table \\"public\\".\\"users\\" add constraint \\"users_email_key\\" UNIQUE using index \\"users_email_key\\"","alter table \\"public\\".\\"users\\" add constraint \\"users_phone_key\\" UNIQUE using index \\"users_phone_key\\"","alter table \\"public\\".\\"users\\" add constraint \\"users_user_id_fkey\\" FOREIGN KEY (user_id) REFERENCES auth.users(id) ON UPDATE CASCADE ON DELETE CASCADE not valid","alter table \\"public\\".\\"users\\" validate constraint \\"users_user_id_fkey\\"","alter table \\"public\\".\\"whatsapp_integration\\" add constraint \\"whatsapp_integration_business_id_fkey\\" FOREIGN KEY (business_id) REFERENCES businesses(business_id) ON UPDATE CASCADE ON DELETE CASCADE not valid","alter table \\"public\\".\\"whatsapp_integration\\" validate constraint \\"whatsapp_integration_business_id_fkey\\"","alter table \\"public\\".\\"whatsapp_integration\\" add constraint \\"whatsapp_integration_business_id_key\\" UNIQUE using index \\"whatsapp_integration_business_id_key\\"","set check_function_bodies = off","CREATE OR REPLACE FUNCTION public.adjust_stock(p_adjustment_json jsonb, p_business_id uuid, p_org_id uuid)\r\n RETURNS uuid\r\n LANGUAGE plpgsql\r\nAS $function$\r\nDECLARE\r\n    -- Input Data\r\n    v_reference               TEXT := p_adjustment_json->>'reference_number'; -- User-provided reference\r\n    v_reason                  TEXT := p_adjustment_json->>'reason';\r\n    v_adjusted_date           TIMESTAMPTZ := COALESCE((p_adjustment_json->>'adjusted_date')::timestamptz, now());\r\n    v_adjusted_items          JSONB := p_adjustment_json->'adjusted_items';\r\n\r\n    -- Internal Vars\r\n    v_transaction_id          UUID;\r\n    v_adjustment_id           UUID := gen_random_uuid(); -- PK for stock_adjustments table\r\n    v_item_adjustment_value   NUMERIC;\r\n    v_total_adjustment_abs_value NUMERIC := 0; -- Sum of absolute value changes for transaction header\r\n    v_item_data               RECORD; -- For looping through JSON array\r\n    v_item_cost               NUMERIC; -- Cost of the item being adjusted\r\n    v_user_id                 UUID := auth.uid();\r\n\r\n    -- Account IDs & Codes\r\n    v_inventory_account_id    UUID;\r\n    v_adjustment_offset_account_id UUID; -- Account to balance inventory change\r\n    v_inventory_code          TEXT := '1030';\r\n    v_adjustment_offset_code  TEXT := '6095'; -- Stock Adjustment Expense\r\n\r\nBEGIN\r\n    -- Validate Inputs\r\n    IF p_business_id IS NULL OR p_org_id IS NULL THEN\r\n        RAISE EXCEPTION 'Business ID and Org ID cannot be null.';\r\n    END IF;\r\n    IF v_adjusted_items IS NULL OR jsonb_array_length(v_adjusted_items) = 0 THEN\r\n        RAISE EXCEPTION 'adjusted_items array cannot be null or empty.';\r\n    END IF;\r\n    -- Add more validation for fields inside v_adjusted_items if needed\r\n\r\n    -- Fetch required account IDs for the business\r\n    SELECT account_id INTO v_inventory_account_id FROM public.accounts WHERE business_id = p_business_id AND code = v_inventory_code;\r\n    SELECT account_id INTO v_adjustment_offset_account_id FROM public.accounts WHERE business_id = p_business_id AND code = v_adjustment_offset_code;\r\n\r\n    IF v_inventory_account_id IS NULL THEN\r\n         RAISE EXCEPTION 'Inventory account (Code: %) not found for business %.', v_inventory_code, p_business_id;\r\n    END IF;\r\n    IF v_adjustment_offset_account_id IS NULL THEN\r\n         RAISE EXCEPTION 'Stock Adjustment Expense account (Code: %) not found for business %.', v_adjustment_offset_code, p_business_id;\r\n    END IF;\r\n\r\n    -- Ensure reference number is not empty, generate if needed\r\n    IF v_reference IS NULL OR v_reference = '' THEN\r\n        v_reference := 'ADJ-' || to_char(v_adjusted_date, 'YYYYMMDD') || '-' || upper(substring(gen_random_uuid()::text from 1 for 6));\r\n    END IF;\r\n\r\n    -- Calculate total absolute adjustment value for the transaction header\r\n    FOR v_item_data IN SELECT * FROM jsonb_array_elements(v_adjusted_items)\r\n    LOOP\r\n        -- Fetch item cost (using purchase_price as placeholder, replace if you have better cost data)\r\n        SELECT COALESCE(i.purchase_price, 0) INTO v_item_cost\r\n        FROM public.items i\r\n        WHERE i.item_id = (v_item_data.value->>'item_id')::uuid\r\n          AND i.business_id = p_business_id; -- Ensure item belongs to the business\r\n\r\n        IF NOT FOUND THEN\r\n             RAISE EXCEPTION 'Item ID % not found for business %.', (v_item_data.value->>'item_id')::uuid, p_business_id;\r\n        END IF;\r\n\r\n        v_item_adjustment_value := (v_item_data.value->>'adjusted_quantity')::numeric * v_item_cost;\r\n        v_total_adjustment_abs_value := v_total_adjustment_abs_value + abs(v_item_adjustment_value);\r\n    END LOOP;\r\n\r\n    -- Create the Transaction Header\r\n    INSERT INTO public.transactions (\r\n        reference_no, transaction_type, transaction_date, status,\r\n        total_amount, paid_amount, due_amount, -- Total amount reflects the magnitude of value adjusted\r\n        notes, business_id, created_by\r\n    ) VALUES (\r\n        v_reference, 'STOCK_ADJUSTMENT'::public.transaction_type, v_adjusted_date, 'PAID'::public.transaction_status, -- Adjustment is complete\r\n        v_total_adjustment_abs_value, v_total_adjustment_abs_value, 0,\r\n        'Stock Adjustment: ' || COALESCE(v_reason,'No reason provided.'), p_business_id, v_user_id\r\n    ) RETURNING transaction_id INTO v_transaction_id;\r\n\r\n    -- Create stock adjustment header record\r\n    INSERT INTO public.stock_adjustments (\r\n        adjustment_id, reason, reference, performed_at, performed_by,\r\n        business_id, org_id, transaction_id\r\n    ) VALUES (\r\n        v_adjustment_id, v_reason, v_reference, v_adjusted_date, v_user_id,\r\n        p_business_id, p_org_id, v_transaction_id\r\n    );\r\n\r\n    -- Loop through items again to update stock and create GL entries\r\n    FOR v_item_data IN SELECT * FROM jsonb_array_elements(v_adjusted_items)\r\n    LOOP\r\n        DECLARE\r\n            v_item_id           UUID := (v_item_data.value->>'item_id')::uuid;\r\n            v_adjusted_quantity NUMERIC := (v_item_data.value->>'adjusted_quantity')::numeric;\r\n            v_current_quantity  NUMERIC := (v_item_data.value->>'current_quantity')::numeric; -- From input JSON\r\n            v_new_quantity      NUMERIC := (v_item_data.value->>'new_quantity')::numeric;     -- From input JSON\r\n            v_item_name         TEXT;\r\n        BEGIN\r\n            -- Fetch item cost and name again\r\n            SELECT COALESCE(i.purchase_price, 0), i.name INTO v_item_cost, v_item_name\r\n            FROM public.items i\r\n            WHERE i.item_id = v_item_id AND i.business_id = p_business_id;\r\n            -- We know item exists from previous loop/check\r\n\r\n            v_item_adjustment_value := v_adjusted_quantity * v_item_cost;\r\n\r\n            -- Create Balanced Transaction Entries for THIS item\r\n            IF v_adjusted_quantity > 0 THEN\r\n                -- Increase Inventory: Debit Inventory, Credit Offset Account\r\n                INSERT INTO public.transaction_entries (transaction_id, account_id, entry_type, amount, description)\r\n                VALUES\r\n                    (v_transaction_id, v_inventory_account_id, 'DEBIT'::public.entry_type, v_item_adjustment_value, 'Stock Increase Adj: ' || v_item_name),\r\n                    (v_transaction_id, v_adjustment_offset_account_id, 'CREDIT'::public.entry_type, v_item_adjustment_value, 'Stock Increase Adj Offset: ' || v_item_name);\r\n            ELSIF v_adjusted_quantity < 0 THEN\r\n                -- Decrease Inventory: Debit Offset Account, Credit Inventory\r\n                INSERT INTO public.transaction_entries (transaction_id, account_id, entry_type, amount, description)\r\n                VALUES\r\n                    (v_transaction_id, v_adjustment_offset_account_id, 'DEBIT'::public.entry_type, abs(v_item_adjustment_value), 'Stock Decrease Adj Offset: ' || v_item_name),\r\n                    (v_transaction_id, v_inventory_account_id, 'CREDIT'::public.entry_type, abs(v_item_adjustment_value), 'Stock Decrease Adj: ' || v_item_name);\r\n            END IF;\r\n            -- If v_adjusted_quantity is 0, no GL entries needed for this item.\r\n\r\n            -- Create stock adjustment item detail record\r\n            INSERT INTO public.stock_adjustment_items (\r\n                adjustment_id, item_id, quantity_adjusted, previous_quantity, new_quantity\r\n            ) VALUES (\r\n                v_adjustment_id, v_item_id, v_adjusted_quantity, v_current_quantity, v_new_quantity\r\n            );\r\n\r\n            -- Update item's stock quantity ONLY\r\n            UPDATE public.items\r\n            SET stock_quantity = v_new_quantity, -- Trusting the input JSON for new quantity\r\n                updated_at = now()\r\n                -- DO NOT update stock_value here. It should reflect cost based on purchases/production.\r\n                -- The GL entry correctly reflects the value change in the Inventory account.\r\n            WHERE item_id = v_item_id\r\n              AND business_id = p_business_id;\r\n        END;\r\n    END LOOP;\r\n\r\n    -- Verify the overall transaction balance\r\n    PERFORM public.verify_transaction_balance(v_transaction_id);\r\n\r\n    RETURN v_transaction_id;\r\n\r\nEXCEPTION\r\n    WHEN unique_violation THEN\r\n        RAISE EXCEPTION 'Failed to adjust stock: Unique constraint violated. Check reference number \\"%\\". Detail: %', v_reference, SQLERRM;\r\n    WHEN others THEN\r\n        RAISE EXCEPTION 'Failed to adjust stock: %', SQLERRM;\r\nEND;\r\n$function$","CREATE OR REPLACE FUNCTION public.archive_customer(p_customer_id uuid, p_business_id uuid)\r\n RETURNS void\r\n LANGUAGE plpgsql\r\nAS $function$\r\nDECLARE\r\n    v_customer_balance NUMERIC;\r\nBEGIN\r\n    -- 1. Check the balance for this customer specifically within the given business\r\n    SELECT bc.customer_balance\r\n    INTO v_customer_balance\r\n    FROM public.business_customers bc\r\n    WHERE bc.customer_id = p_customer_id\r\n      AND bc.business_id = p_business_id;\r\n\r\n    -- If the relationship doesn't exist for this business, we might allow archiving the central record,\r\n    -- or raise an error depending on requirements. Here, we proceed if no specific balance exists.\r\n    -- If a balance DOES exist, it MUST be zero.\r\n    IF v_customer_balance IS NOT NULL AND v_customer_balance != 0 THEN\r\n        RAISE EXCEPTION 'Cannot archive customer ID % for business ID %: Outstanding balance of % exists. Please settle or write off the balance first.',\r\n            p_customer_id, p_business_id, v_customer_balance;\r\n    END IF;\r\n\r\n    -- 2. Check balances across ALL businesses (stricter check - optional)\r\n    -- If you want to prevent archiving a central customer if they have a balance with ANY business:\r\n    /*\r\n    PERFORM 1\r\n    FROM public.business_customers bc\r\n    WHERE bc.customer_id = p_customer_id\r\n      AND bc.customer_balance != 0;\r\n\r\n    IF FOUND THEN\r\n         RAISE EXCEPTION 'Cannot archive customer ID %: Outstanding balance exists with one or more businesses.', p_customer_id;\r\n    END IF;\r\n    */\r\n\r\n    -- 3. Mark the central customer record as inactive\r\n    UPDATE public.business_customers\r\n    SET is_active = FALSE\r\n    WHERE customer_id = p_customer_id;\r\n\r\n    IF NOT FOUND THEN\r\n        RAISE WARNING 'Customer ID % not found in central customers table.', p_customer_id;\r\n    END IF;\r\n\r\n    -- Note: No direct GL entries are made here. Archiving is an administrative action.\r\n    -- The financial settlement must happen via separate transactions (payments, write-offs).\r\n\r\nEND;\r\n$function$","CREATE OR REPLACE FUNCTION public.archive_item(p_item_id uuid, p_business_id uuid)\r\n RETURNS void\r\n LANGUAGE plpgsql\r\nAS $function$\r\nDECLARE\r\n    v_stock_quantity NUMERIC;\r\n    v_transaction_exists BOOLEAN := FALSE;\r\nBEGIN\r\n    -- 1. Check if the item exists for the given business\r\n    SELECT stock_quantity INTO v_stock_quantity\r\n    FROM public.items i\r\n    WHERE i.item_id = p_item_id\r\n      AND i.business_id = p_business_id;\r\n\r\n    IF NOT FOUND THEN\r\n        RAISE EXCEPTION 'Item ID % not found for business ID %.', p_item_id, p_business_id;\r\n    END IF;\r\n\r\n    -- 2. Check for existing transactions linked to this item\r\n    -- We look beyond just the Opening Stock transaction. Any transaction linked\r\n    -- via the optional transactions.item_id or potentially via transaction_entries\r\n    -- if item details are stored there (less ideal) indicates usage.\r\n    -- This example primarily checks transactions.item_id.\r\n    SELECT EXISTS (\r\n        SELECT 1\r\n        FROM public.transactions t\r\n        WHERE t.business_id = p_business_id\r\n          AND t.item_id = p_item_id\r\n          AND t.transaction_type != 'OPENING_STOCK' -- Exclude the OB transaction itself\r\n    ) INTO v_transaction_exists;\r\n\r\n    -- Alternatively, or additionally, you might need to check line item tables\r\n    -- if items are linked there instead of directly on the transaction header.\r\n    -- Example (assuming a 'sale_items' table):\r\n    /*\r\n    IF NOT v_transaction_exists THEN\r\n        SELECT EXISTS (\r\n            SELECT 1 FROM public.sale_items si -- Replace with your actual line item table(s)\r\n            JOIN public.sales s ON si.sale_id = s.sale_id -- Join to get business_id if needed\r\n            WHERE si.item_id = p_item_id\r\n              AND s.business_id = p_business_id -- Ensure check is scoped to the business\r\n        ) INTO v_transaction_exists;\r\n    END IF;\r\n    -- Add similar checks for purchase line items, adjustment line items etc.\r\n    */\r\n\r\n    IF v_transaction_exists THEN\r\n        RAISE EXCEPTION 'Cannot archive item ID %: Item has associated transaction history (e.g., sales, purchases, adjustments).', p_item_id;\r\n    END IF;\r\n\r\n    -- 3. Check for current stock quantity (optional but recommended for inventory items)\r\n    -- This prevents archiving items that physically exist in inventory.\r\n    -- Adjust this check based on whether v_stock_quantity could be null for non-inventory items.\r\n    IF v_stock_quantity IS NOT NULL AND v_stock_quantity != 0 THEN\r\n        RAISE EXCEPTION 'Cannot archive item ID %: Item has a current stock quantity of %. Please perform a stock adjustment first.',\r\n            p_item_id, v_stock_quantity;\r\n    END IF;\r\n\r\n    -- 4. Mark the item as inactive\r\n    UPDATE public.items\r\n    SET is_active = FALSE,\r\n        updated_at = now()\r\n    WHERE item_id = p_item_id\r\n      AND business_id = p_business_id; -- Redundant check but safe\r\n\r\n    RAISE NOTICE 'Item ID % successfully archived.', p_item_id;\r\n\r\n    -- Note: Archiving does not typically create GL entries.\r\n    -- If stock quantity was non-zero and needed adjustment before archiving,\r\n    -- that adjustment transaction would create the necessary GL entries\r\n    -- (e.g., Dr Stock Adjustment Expense, Cr Inventory).\r\n\r\nEND;\r\n$function$","CREATE OR REPLACE FUNCTION public.archive_supplier(p_supplier_id uuid)\r\n RETURNS void\r\n LANGUAGE plpgsql\r\nAS $function$\r\nDECLARE\r\n    v_supplier_balance NUMERIC;\r\nBEGIN\r\n    -- 1. Check the supplier's balance\r\n    SELECT s.supplier_balance\r\n    INTO v_supplier_balance\r\n    FROM public.suppliers s\r\n    WHERE s.supplier_id = p_supplier_id;\r\n\r\n    IF NOT FOUND THEN\r\n         RAISE EXCEPTION 'Supplier ID % not found.', p_supplier_id;\r\n    END IF;\r\n\r\n    IF v_supplier_balance != 0 THEN\r\n        RAISE EXCEPTION 'Cannot archive supplier ID %: Outstanding balance of % exists. Please settle the balance first.',\r\n            p_supplier_id, v_supplier_balance;\r\n    END IF;\r\n\r\n    -- 2. Mark the supplier record as inactive\r\n    UPDATE public.suppliers\r\n    SET is_active = FALSE,\r\n        updated_at = now() -- Also update timestamp\r\n    WHERE supplier_id = p_supplier_id;\r\n\r\n    -- Note: No GL entries made here. Financial settlement happens via other transactions.\r\n\r\nEND;\r\n$function$","CREATE OR REPLACE FUNCTION public.build_account_node(_account_id uuid, _business_id uuid)\r\n RETURNS jsonb\r\n LANGUAGE plpgsql\r\n STABLE\r\nAS $function$\r\nDECLARE\r\n    v_account record;\r\n    v_children jsonb := '[]'::jsonb; -- Default to empty array for children\r\nBEGIN\r\n    -- Fetch the details of the current account\r\n    SELECT\r\n        account_id,\r\n        name,\r\n        code,\r\n        description,\r\n        balance,\r\n        is_group,\r\n        parent_account_id,\r\n        category_id\r\n    INTO v_account\r\n    FROM public.accounts a\r\n    WHERE a.account_id = _account_id\r\n      AND a.business_id = _business_id; -- Ensure it belongs to the correct business\r\n\r\n    -- If account not found for the business, return NULL\r\n    IF NOT FOUND THEN\r\n        RETURN NULL;\r\n    END IF;\r\n\r\n    -- If the current account is a group, find its children recursively\r\n    IF v_account.is_group THEN\r\n        SELECT jsonb_agg(child_node ORDER BY child_code) -- Order children by code for consistency\r\n        INTO v_children\r\n        FROM (\r\n            SELECT public.build_account_node(a.account_id, _business_id) as child_node, a.code as child_code\r\n            FROM public.accounts a\r\n            WHERE a.parent_account_id = _account_id\r\n              AND a.business_id = _business_id -- Ensure children belong to the same business\r\n        ) AS children_subquery\r\n        WHERE child_node IS NOT NULL; -- Exclude potential NULLs if a child wasn't found (shouldn't happen with FKs)\r\n\r\n        -- If no children found, jsonb_agg returns NULL, default back to empty array\r\n        IF v_children IS NULL THEN\r\n            v_children := '[]'::jsonb;\r\n        END IF;\r\n    END IF;\r\n\r\n    -- Build the JSON object for the current account\r\n    RETURN jsonb_build_object(\r\n        'account_id', v_account.account_id,\r\n        'name', v_account.name,\r\n        'code', v_account.code,\r\n        'description', v_account.description,\r\n        'balance', v_account.balance,\r\n        'is_group', v_account.is_group,\r\n        'parent_account_id', v_account.parent_account_id, -- Included for reference, though structure shows hierarchy\r\n        'category_id', v_account.category_id,             -- Included for reference\r\n        'children', v_children                            -- Add the children array (empty if not a group or no children)\r\n    );\r\nEND;\r\n$function$","CREATE OR REPLACE FUNCTION public.bulk_import_items(p_import_data jsonb)\r\n RETURNS jsonb\r\n LANGUAGE plpgsql\r\nAS $function$\r\nDECLARE\r\n    -- Input Params\r\n    v_items_array        JSONB := p_import_data->'p_items';\r\n    v_business_id      UUID := (p_import_data->>'p_business_id')::uuid;\r\n    v_skip_duplicates  BOOLEAN := COALESCE((p_import_data->>'p_skip_duplicates')::boolean, true); -- Default to skipping\r\n\r\n    -- Loop Vars\r\n    item_data          JSONB;\r\n    v_item_name        TEXT;\r\n    v_category_name    TEXT;\r\n    v_brand_name       TEXT;\r\n    v_unit_name        TEXT;\r\n    v_item_code        TEXT; -- From \\"Item Code/Barcode\\"\r\n    v_sale_price       NUMERIC;\r\n    v_retail_price     NUMERIC; -- Use if needed, otherwise default\r\n    v_purchase_price   NUMERIC;\r\n    v_opening_qty      NUMERIC; -- Assuming opening qty/value might be in import\r\n    v_opening_value    NUMERIC;\r\n\r\n    -- Resolved IDs\r\n    v_item_category_id UUID;\r\n    v_brand_id         UUID;\r\n    v_unit_id          UUID;\r\n    v_existing_item_id UUID;\r\n    v_item_id_out      UUID; -- For newly inserted item\r\n\r\n    -- Accounting Vars (only for new items with opening stock)\r\n    v_transaction_id        UUID;\r\n    v_ob_ref_no             TEXT;\r\n    v_inventory_account_id  UUID;\r\n    v_ob_equity_account_id  UUID;\r\n    v_inventory_code        TEXT := '1030';\r\n    v_ob_equity_code        TEXT := '3900';\r\n\r\n    -- Internal State\r\n    v_org_id           UUID;\r\n    v_user_id          UUID := auth.uid();\r\n    v_processed_count  INTEGER := 0;\r\n    v_inserted_count   INTEGER := 0;\r\n    v_updated_count    INTEGER := 0;\r\n    v_skipped_count    INTEGER := 0;\r\n    v_error_count      INTEGER := 0;\r\n    v_errors           TEXT[] := '{}';\r\n\r\nBEGIN\r\n    -- Validate top-level inputs\r\n    IF v_business_id IS NULL THEN\r\n        RAISE EXCEPTION 'p_business_id is required.';\r\n    END IF;\r\n    IF v_items_array IS NULL OR jsonb_typeof(v_items_array) != 'array' OR jsonb_array_length(v_items_array) = 0 THEN\r\n        RAISE EXCEPTION 'p_items array is required and cannot be empty.';\r\n    END IF;\r\n\r\n    -- Get Org ID once\r\n    SELECT org_id INTO v_org_id FROM public.businesses WHERE business_id = v_business_id;\r\n    IF v_org_id IS NULL THEN\r\n        RAISE EXCEPTION 'Cannot find org_id for business %', v_business_id;\r\n    END IF;\r\n\r\n    -- Fetch account IDs once if needed for opening stock\r\n    SELECT account_id INTO v_inventory_account_id FROM public.accounts WHERE business_id = v_business_id AND code = v_inventory_code;\r\n    SELECT account_id INTO v_ob_equity_account_id FROM public.accounts WHERE business_id = v_business_id AND code = v_ob_equity_code;\r\n    -- Add validation checks if needed later inside the loop if OB exists\r\n\r\n    -- Loop through each item in the input array\r\n    FOR item_data IN SELECT * FROM jsonb_array_elements(v_items_array)\r\n    LOOP\r\n        BEGIN -- Start block for individual item processing and error handling\r\n            v_processed_count := v_processed_count + 1;\r\n            v_existing_item_id := NULL; -- Reset for each iteration\r\n            v_item_id_out := NULL;\r\n\r\n            -- Extract data for the current item (Use ->> for text)\r\n            v_item_name := trim(item_data->>'Item Name');\r\n            v_category_name := item_data->>'Category'; -- Pass NULL if key doesn't exist\r\n            v_brand_name := item_data->>'Brand';\r\n            v_unit_name := item_data->>'Item Unit';\r\n            v_item_code := item_data->>'Item Code/Barcode'; -- Can be NULL or text/number\r\n            v_sale_price := COALESCE((item_data->>'Sale Price')::numeric, 0);\r\n            v_retail_price := COALESCE((item_data->>'Retail Price')::numeric, v_sale_price); -- Default retail to sale price\r\n            v_purchase_price := COALESCE((item_data->>'Purchase Price')::numeric, 0);\r\n            -- Handle potential opening stock - adjust keys if different in your import\r\n            v_opening_qty := COALESCE((item_data->>'Opening Stock Qty')::numeric, 0);\r\n            v_opening_value := COALESCE((item_data->>'Opening Stock Value')::numeric, 0);\r\n\r\n            -- Basic Validation for required item fields\r\n            IF v_item_name IS NULL OR v_item_name = '' THEN\r\n                RAISE EXCEPTION 'Item Name is required.';\r\n            END IF;\r\n\r\n            -- Resolve foreign keys using helper functions\r\n            v_item_category_id := public.get_or_create_item_category(v_business_id, v_category_name);\r\n            v_brand_id := public.get_or_create_brand(v_business_id, v_brand_name);\r\n            v_unit_id := public.get_or_create_unit(v_business_id, v_unit_name); -- Assumes unit name is unique identifier\r\n\r\n            -- Check if item already exists by NAME for this business\r\n            SELECT item_id INTO v_existing_item_id\r\n            FROM public.items\r\n            WHERE business_id = v_business_id AND lower(name) = lower(v_item_name);\r\n\r\n            -- Handle duplicates based on flag\r\n            IF v_existing_item_id IS NOT NULL THEN\r\n                IF v_skip_duplicates THEN\r\n                    RAISE WARNING 'Skipping duplicate item (name): \\"%\\"', v_item_name;\r\n                    v_skipped_count := v_skipped_count + 1;\r\n                    CONTINUE; -- Go to the next item in the loop\r\n                ELSE\r\n                    -- UPDATE existing item\r\n                    UPDATE public.items SET\r\n                        -- Update relevant fields from import data\r\n                        item_category_id = COALESCE(v_item_category_id, item_category_id),\r\n                        brand_id = COALESCE(v_brand_id, brand_id),\r\n                        unit_id = COALESCE(v_unit_id, unit_id),\r\n                        item_code = COALESCE(v_item_code, item_code), -- Update code if provided\r\n                        sale_price = v_sale_price,\r\n                        purchase_price = v_purchase_price,\r\n                        -- Add other updatable fields as needed (retail_price, etc.)\r\n                        updated_at = now()\r\n                    WHERE item_id = v_existing_item_id;\r\n                    v_updated_count := v_updated_count + 1;\r\n                    -- DO NOT process opening stock on update\r\n                END IF;\r\n            ELSE\r\n                -- INSERT new item\r\n                 -- Check unique item code constraint before attempting insert\r\n                IF v_item_code IS NOT NULL THEN\r\n                    PERFORM 1 FROM public.items WHERE business_id = v_business_id AND item_code = v_item_code;\r\n                    IF FOUND THEN\r\n                        IF v_skip_duplicates THEN\r\n                           RAISE WARNING 'Skipping item \\"%\\": Item Code \\"%\\" already exists.', v_item_name, v_item_code;\r\n                           v_skipped_count := v_skipped_count + 1;\r\n                           CONTINUE;\r\n                        ELSE\r\n                            RAISE EXCEPTION 'Item Code \\"%\\" already exists for item \\"%\\". Cannot insert.', v_item_code, v_item_name;\r\n                        END IF;\r\n                    END IF;\r\n                END IF;\r\n\r\n                INSERT INTO public.items (\r\n                    name, item_type, item_code, item_category_id, brand_id, unit_id,\r\n                    sales_enabled, purchase_enabled, inventory_enabled, is_returnable, -- Assuming defaults\r\n                    sale_price, purchase_price, alert_quantity, -- Assuming default alert qty\r\n                    business_id, org_id,\r\n                    stock_quantity, stock_value, -- Initial stock is opening stock\r\n                    opening_stock_qty, opening_stock_value,\r\n                    created_at, updated_at\r\n                ) VALUES (\r\n                    v_item_name, 'goods'::public.item_type, v_item_code, v_item_category_id, v_brand_id, v_unit_id,\r\n                    true, true, true, false, -- Sensible defaults\r\n                    v_sale_price, v_purchase_price, 0, -- Default alert quantity\r\n                    v_business_id, v_org_id,\r\n                    v_opening_qty, v_opening_value,\r\n                    v_opening_qty, v_opening_value,\r\n                    now(), now()\r\n                )\r\n                RETURNING item_id INTO v_item_id_out;\r\n                v_inserted_count := v_inserted_count + 1;\r\n\r\n                -- Handle Opening Stock Accounting (Only if INSERTED and value > 0)\r\n                IF v_opening_value != 0 THEN\r\n                    -- Validate required accounts fetched earlier\r\n                    IF v_inventory_account_id IS NULL OR v_ob_equity_account_id IS NULL THEN\r\n                        RAISE EXCEPTION 'Cannot process opening stock for \\"%\\": Required accounts (Inventory/OB Equity) missing.', v_item_name;\r\n                    END IF;\r\n\r\n                    v_ob_ref_no := 'OB-ITEM-' || v_item_id_out::text;\r\n\r\n                    INSERT INTO public.transactions (\r\n                        reference_no, transaction_type, transaction_date, status,\r\n                        total_amount, paid_amount, due_amount,\r\n                        notes, business_id, created_by, item_id\r\n                    ) VALUES (\r\n                        v_ob_ref_no, 'OPENING_STOCK'::public.transaction_type, now(), 'PAID'::public.transaction_status,\r\n                        abs(v_opening_value), abs(v_opening_value), 0,\r\n                        'Opening stock value for item ' || v_item_name || ' (' || COALESCE(v_item_code,'N/A') || ')', v_business_id, v_user_id, v_item_id_out\r\n                    ) RETURNING transaction_id INTO v_transaction_id;\r\n\r\n                    INSERT INTO public.transaction_entries (transaction_id, account_id, entry_type, amount, description)\r\n                    VALUES\r\n                        (v_transaction_id, v_inventory_account_id, 'DEBIT'::public.entry_type, v_opening_value, 'Opening stock value'),\r\n                        (v_transaction_id, v_ob_equity_account_id, 'CREDIT'::public.entry_type, v_opening_value, 'Opening balance equity offset');\r\n\r\n                    PERFORM public.verify_transaction_balance(v_transaction_id);\r\n                END IF; -- End opening stock handling\r\n\r\n            END IF; -- End INSERT/UPDATE logic\r\n\r\n        EXCEPTION\r\n            WHEN unique_violation THEN\r\n                 v_error_count := v_error_count + 1;\r\n                 v_errors := array_append(v_errors, format('Item \\"%s\\": Failed due to unique constraint violation (Name or Code?). Detail: %s', COALESCE(v_item_name, 'N/A'), SQLERRM));\r\n                 RAISE WARNING 'Unique violation for Item \\"%\\": %', COALESCE(v_item_name, 'N/A'), SQLERRM;\r\n            WHEN others THEN\r\n                 v_error_count := v_error_count + 1;\r\n                 v_errors := array_append(v_errors, format('Item \\"%s\\": Failed with error: %s', COALESCE(v_item_name, 'N/A'), SQLERRM));\r\n                 RAISE WARNING 'Error processing Item \\"%\\": %', COALESCE(v_item_name, 'N/A'), SQLERRM;\r\n        END; -- End block for individual item\r\n\r\n    END LOOP; -- End loop through items array\r\n\r\n    RETURN jsonb_build_object(\r\n        'processed_count', v_processed_count,\r\n        'inserted_count', v_inserted_count,\r\n        'updated_count', v_updated_count,\r\n        'skipped_count', v_skipped_count,\r\n        'error_count', v_error_count,\r\n        'errors', v_errors\r\n    );\r\n\r\nEND;\r\n$function$","create or replace view \\"public\\".\\"business_customer_view\\" as  SELECT bc.business_id,\r\n    c.customer_id,\r\n    bc.name,\r\n    u.email,\r\n    u.phone,\r\n    bc.address,\r\n    bc.image,\r\n    bc.customer_balance,\r\n    bc.is_active\r\n   FROM ((business_customers bc\r\n     JOIN customers c ON ((bc.customer_id = c.customer_id)))\r\n     JOIN users u ON ((c.customer_id = u.user_id)))","CREATE OR REPLACE FUNCTION public.clear_sequences(business_id uuid)\r\n RETURNS void\r\n LANGUAGE plpgsql\r\nAS $function$\r\nDECLARE\r\n    v_base_name text;\r\nBEGIN\r\n    v_base_name := business_id::text;\r\n    \r\n    -- Drop sequences if they exist\r\n    EXECUTE format('DROP SEQUENCE IF EXISTS %I', v_base_name || '_purchase_invoice');\r\n    EXECUTE format('DROP SEQUENCE IF EXISTS %I', v_base_name || '_sale_invoice');\r\n    EXECUTE format('DROP SEQUENCE IF EXISTS %I', v_base_name || '_purchase_return_code');\r\n    EXECUTE format('DROP SEQUENCE IF EXISTS %I', v_base_name || '_sale_return_code');\r\n    EXECUTE format('DROP SEQUENCE IF EXISTS %I', v_base_name || '_item_code');\r\n    EXECUTE format('DROP SEQUENCE IF EXISTS %I', v_base_name || '_employee_code');\r\nEND;\r\n$function$","CREATE OR REPLACE FUNCTION public.create_default_chart_of_accounts(p_business_id uuid, p_org_id uuid)\r\n RETURNS void\r\n LANGUAGE plpgsql\r\nAS $function$\r\nDECLARE\r\n    -- Category IDs\r\n    v_asset_category_id UUID;\r\n    v_liability_category_id UUID;\r\n    v_equity_category_id UUID;\r\n    v_revenue_category_id UUID;\r\n    v_cost_of_sales_category_id UUID;\r\n    v_operating_expenses_category_id UUID;\r\n\r\n    -- Account Group IDs\r\n    v_current_assets_group_id UUID;\r\n    v_fixed_assets_group_id UUID;\r\n    v_current_liabilities_group_id UUID;\r\n    v_sales_revenue_group_id UUID;\r\n    v_cost_of_goods_sold_group_id UUID;\r\n    v_sga_expenses_group_id UUID;\r\n\r\nBEGIN\r\n    -- 1. Create Account Categories\r\n    INSERT INTO public.account_categories (name, code, description, business_id) VALUES\r\n    ('ASSETS', 'AST', 'Asset accounts', p_business_id) RETURNING category_id INTO v_asset_category_id;\r\n    INSERT INTO public.account_categories (name, code, description, business_id) VALUES\r\n    ('LIABILITIES', 'LBT', 'Liability accounts', p_business_id) RETURNING category_id INTO v_liability_category_id;\r\n    INSERT INTO public.account_categories (name, code, description, business_id) VALUES\r\n    ('EQUITIES', 'EQT', 'Equity accounts', p_business_id) RETURNING category_id INTO v_equity_category_id;\r\n    INSERT INTO public.account_categories (name, code, description, business_id) VALUES\r\n    ('REVENUES', 'RVN', 'Revenue accounts', p_business_id) RETURNING category_id INTO v_revenue_category_id;\r\n    INSERT INTO public.account_categories (name, code, description, business_id) VALUES\r\n    ('COST OF SALES', 'COS', 'Cost of Sales accounts', p_business_id) RETURNING category_id INTO v_cost_of_sales_category_id;\r\n    INSERT INTO public.account_categories (name, code, description, business_id) VALUES\r\n    ('OPERATING EXPENSES', 'OPE', 'Operating expenses accounts', p_business_id) RETURNING category_id INTO v_operating_expenses_category_id;\r\n\r\n    -- 2. Create Assets Hierarchy\r\n    INSERT INTO public.accounts (category_id, name, code, description, is_group, parent_account_id, business_id, org_id) VALUES\r\n    (v_asset_category_id, 'Current Assets', '1000', NULL, TRUE, NULL, p_business_id, p_org_id) RETURNING account_id INTO v_current_assets_group_id;\r\n    INSERT INTO public.accounts (category_id, name, code, description, is_group, parent_account_id, business_id, org_id) VALUES\r\n    (v_asset_category_id, 'Fixed Assets', '1100', NULL, TRUE, NULL, p_business_id, p_org_id) RETURNING account_id INTO v_fixed_assets_group_id;\r\n\r\n    -- 2.2 Current Asset Accounts\r\n    INSERT INTO public.accounts (category_id, name, code, description, is_group, parent_account_id, business_id, org_id) VALUES\r\n    (v_asset_category_id, 'Petty Cash', '1010', 'Cash on hand.', FALSE, v_current_assets_group_id, p_business_id, p_org_id),\r\n    (v_asset_category_id, 'Cash in Bank', '1011', 'Cash in bank accounts.', FALSE, v_current_assets_group_id, p_business_id, p_org_id),\r\n    -- Refined A/R accounts\r\n    (v_asset_category_id, 'Accounts Receivable - Customers', '1020', 'Money owed to the business by customers for goods/services sold.', FALSE, v_current_assets_group_id, p_business_id, p_org_id),\r\n    (v_asset_category_id, 'Receivables from Suppliers', '1021', 'Money owed to the business by suppliers (e.g., refunds, overpayments).', FALSE, v_current_assets_group_id, p_business_id, p_org_id),\r\n    -- End Refined A/R\r\n    (v_asset_category_id, 'Inventory', '1030', 'Value of goods held for sale.', FALSE, v_current_assets_group_id, p_business_id, p_org_id);\r\n\r\n    -- 2.3 Fixed Asset Accounts\r\n    INSERT INTO public.accounts (category_id, name, code, description, is_group, parent_account_id, business_id, org_id) VALUES\r\n    (v_asset_category_id, 'Land', '1110', 'Value of land owned.', FALSE, v_fixed_assets_group_id, p_business_id, p_org_id),\r\n    (v_asset_category_id, 'Buildings', '1120', 'Value of buildings owned.', FALSE, v_fixed_assets_group_id, p_business_id, p_org_id),\r\n    (v_asset_category_id, 'Equipment', '1130', 'Value of machinery and equipment owned.', FALSE, v_fixed_assets_group_id, p_business_id, p_org_id);\r\n\r\n    -- 3. Create Liabilities Hierarchy\r\n    INSERT INTO public.accounts (category_id, name, code, description, is_group, parent_account_id, business_id, org_id) VALUES\r\n    (v_liability_category_id, 'Current Liabilities', '2000', NULL, TRUE, NULL, p_business_id, p_org_id) RETURNING account_id INTO v_current_liabilities_group_id;\r\n\r\n    -- 3.2 Current Liability Accounts\r\n    -- Refined A/P accounts\r\n    INSERT INTO public.accounts (category_id, name, code, description, is_group, parent_account_id, business_id, org_id) VALUES\r\n    (v_liability_category_id, 'Accounts Payable - Suppliers', '2010', 'Money owed by the business to suppliers for goods/services received.', FALSE, v_current_liabilities_group_id, p_business_id, p_org_id),\r\n    (v_liability_category_id, 'Payables to Customers', '2011', 'Money owed by the business to customers (e.g., refunds due, overpayments, deposits).', FALSE, v_current_liabilities_group_id, p_business_id, p_org_id),\r\n    -- End Refined A/P\r\n    (v_liability_category_id, 'Sales Tax Payable', '2020', 'Sales tax collected from customers but not yet remitted.', FALSE, v_current_liabilities_group_id, p_business_id, p_org_id);\r\n\r\n    -- 4. Create Revenue Hierarchy (as before)\r\n    INSERT INTO public.accounts (category_id, name, code, description, is_group, parent_account_id, business_id, org_id) VALUES\r\n    (v_revenue_category_id, 'Sales Revenue', '4000', NULL, TRUE, NULL, p_business_id, p_org_id) RETURNING account_id INTO v_sales_revenue_group_id;\r\n    INSERT INTO public.accounts (category_id, name, code, description, is_group, parent_account_id, business_id, org_id) VALUES\r\n    (v_revenue_category_id, 'Sales of Goods', '4010', 'Revenue from the sale of physical goods.', FALSE, v_sales_revenue_group_id, p_business_id, p_org_id),\r\n    (v_revenue_category_id, 'Sales of Services', '4020', 'Revenue from the sale of services.', FALSE, v_sales_revenue_group_id, p_business_id, p_org_id);\r\n    INSERT INTO public.accounts (category_id, name, code, description, is_group, parent_account_id, business_id, org_id) VALUES\r\n    (v_revenue_category_id, 'Income from Other Sources', '4030', 'Income from other sources, such as interest or dividends.', FALSE, NULL, p_business_id, p_org_id);\r\n\tINSERT INTO public.accounts (category_id, name, code, description, is_group, parent_account_id, business_id, org_id) VALUES\r\n\t(v_revenue_category_id, 'Shipping Revenue', '4040', 'Revenue earned from shipping charges billed to customers.', FALSE, NULL, p_business_id, p_org_id); -- Or parent under Sales Revenue (4000)? Decide based on reporting needs.\r\n\tINSERT INTO public.accounts (category_id, name, code, description, is_group, parent_account_id, business_id, org_id) VALUES\r\n\t(v_revenue_category_id, 'Sales Discount', '4900', 'Discounts on sale', FALSE, NULL, p_business_id, p_org_id);\r\n\r\n    -- 5. Create Cost of Sales Hierarchy (as before)\r\n    INSERT INTO public.accounts (category_id, name, code, description, is_group, parent_account_id, business_id, org_id) VALUES\r\n    (v_cost_of_sales_category_id, 'Cost of Sales', '5000', NULL, TRUE, NULL, p_business_id, p_org_id) RETURNING account_id INTO v_cost_of_goods_sold_group_id;\r\n    INSERT INTO public.accounts (category_id, name, code, description, is_group, parent_account_id, business_id, org_id) VALUES\r\n    (v_cost_of_sales_category_id, 'Direct Materials', '5010', 'Cost of raw materials used in production.', FALSE, v_cost_of_goods_sold_group_id, p_business_id, p_org_id),\r\n    (v_cost_of_sales_category_id, 'Direct Labor', '5020', 'Wages paid to workers directly involved in production.', FALSE, v_cost_of_goods_sold_group_id, p_business_id, p_org_id),\r\n    (v_cost_of_sales_category_id, 'Purchase Discount', '5030', 'Discount added to the item when purchasing.', FALSE, v_cost_of_goods_sold_group_id, p_business_id, p_org_id),\r\n\t(v_cost_of_sales_category_id, 'Shipping Costs (Purchases)', '5040', 'Freight and shipping costs for purchased goods.', FALSE, v_cost_of_goods_sold_group_id, p_business_id, p_org_id),\r\n\t(v_cost_of_sales_category_id, 'Cost of Goods Sold', '5015', 'Cost of inventory sold.', FALSE, v_cost_of_goods_sold_group_id, p_business_id, p_org_id);\r\n\r\n    -- 6. Create Operating Expenses Hierarchy (including default general expense)\r\n    INSERT INTO public.accounts (category_id, name, code, description, is_group, parent_account_id, business_id, org_id) VALUES\r\n    (v_operating_expenses_category_id, 'Selling, General, and Administrative Expenses', '6000', NULL, TRUE, NULL, p_business_id, p_org_id) RETURNING account_id INTO v_sga_expenses_group_id;\r\n    INSERT INTO public.accounts (category_id, name, code, description, is_group, parent_account_id, business_id, org_id) VALUES\r\n    (v_operating_expenses_category_id, 'General Expense', '6090', 'Default account for uncategorized operating expenses.', FALSE, v_sga_expenses_group_id, p_business_id, p_org_id);\r\n\tINSERT INTO public.accounts (category_id, name, code, description, is_group, parent_account_id, business_id, org_id) VALUES\r\n\t(v_operating_expenses_category_id, 'Stock Adjustment Expense', '6095', 'Expenses related to inventory adjustments (shrinkage, damage, etc.).', FALSE, v_sga_expenses_group_id, p_business_id, p_org_id);\r\n\r\n    -- 7. Create Equity Hierarchy (as before)\r\n    INSERT INTO public.accounts (category_id, name, code, description, is_group, parent_account_id, is_system, business_id, org_id) VALUES\r\n    (v_equity_category_id, 'Retained Earnings', '3000', 'Accumulated profits retained by the business', FALSE, NULL, TRUE, p_business_id, p_org_id);\r\n    -- *** ADDED OPENING BALANCE EQUITY ACCOUNT ***\r\n    INSERT INTO public.accounts (category_id, name, code, description, is_group, parent_account_id, is_system, business_id, org_id) VALUES\r\n    (v_equity_category_id, 'Opening Balance Equity', '3900', 'Contra-equity account for setting up initial balances.', FALSE, NULL, TRUE, p_business_id, p_org_id);\r\n    -- *** END ADDED ***\r\n\r\n    RETURN;\r\nEXCEPTION\r\n    WHEN OTHERS THEN\r\n        RAISE EXCEPTION 'Error creating default chart of accounts structure for business_id %: %', p_business_id, SQLERRM;\r\nEND;\r\n$function$","CREATE OR REPLACE FUNCTION public.create_purchase(p_purchase_json jsonb)\r\n RETURNS jsonb\r\n LANGUAGE plpgsql\r\nAS $function$\r\nDECLARE\r\n    -- Input Data Parsed\r\n    v_business_id         UUID := (p_purchase_json->>'business_id')::uuid;\r\n    v_supplier_id         UUID := (p_purchase_json->>'supplier_id')::uuid;\r\n    v_user_provided_inv_no TEXT := p_purchase_json->>'purchase_invoice'; -- User's invoice #\r\n    v_purchase_date       TIMESTAMPTZ := COALESCE((p_purchase_json->>'purchase_date')::timestamptz, now());\r\n    v_notes               TEXT := p_purchase_json->>'notes';\r\n    v_attachment_url      TEXT := p_purchase_json->>'attachment';\r\n    v_subtotal            NUMERIC := COALESCE((p_purchase_json->>'subtotal')::numeric, 0); -- Sum of item lines before discounts/tax/shipping\r\n    v_discount_amount     NUMERIC := COALESCE((p_purchase_json->>'discount_amount')::numeric, 0);\r\n    v_shipping_charge     NUMERIC := COALESCE((p_purchase_json->>'shipping')::numeric, 0);\r\n    v_tax_amount          NUMERIC := COALESCE((p_purchase_json->>'tax_amount')::numeric, 0); -- Assuming tax is calculated correctly client-side\r\n    v_grand_total         NUMERIC := COALESCE((p_purchase_json->>'grand_total')::numeric, 0); -- Final amount payable\r\n    v_paid_amount         NUMERIC := COALESCE((p_purchase_json->>'paid_amount')::numeric, 0); -- Amount paid immediately\r\n    v_due_amount          NUMERIC := COALESCE((p_purchase_json->>'balance')::numeric, 0); -- Amount remaining\r\n    v_purchase_items      JSONB := p_purchase_json->'purchase_items';\r\n    v_payment_details     JSONB := p_purchase_json->'payment_details'; -- e.g., {\\"cash\\": 100, \\"bank\\": 100}\r\n\r\n    -- Internal Vars\r\n    v_transaction_id      UUID;\r\n    v_purchase_id         UUID;\r\n    v_gen_reference_no    TEXT; -- Our internal reference\r\n    v_status              public.transaction_status;\r\n    v_user_id             UUID := auth.uid();\r\n    v_item_total_value    NUMERIC := 0;\r\n    v_payment_id          UUID;\r\n    v_purchase_item_data  RECORD;\r\n    v_payment_method      TEXT;\r\n    v_payment_amount      NUMERIC;\r\n    v_calculated_due_amount NUMERIC; -- Use this for insertion\r\n\t\r\n    -- Account IDs & Codes\r\n    v_inventory_acc_id         UUID;\r\n    v_ap_supplier_acc_id       UUID;\r\n    v_shipping_exp_acc_id      UUID;\r\n    v_cash_in_bank_acc_id      UUID; -- Default payment source/destination\r\n    v_petty_cash_acc_id        UUID; -- For 'cash' payments\r\n    v_purchase_discount_acc_id UUID; -- <<< Corrected: Was missing previously\r\n\r\n    v_inventory_code           TEXT := '1030';\r\n    v_ap_supplier_code         TEXT := '2010';\r\n    v_shipping_exp_code        TEXT := '5040'; -- Or '6096' if you prefer OpEx\r\n    v_cash_in_bank_code        TEXT := '1011';\r\n    v_petty_cash_code          TEXT := '1010';\r\n    v_purchase_discount_code   TEXT := '5030';\r\n\r\nBEGIN\r\n    -- Debug logging: Function entry\r\n    RAISE LOG 'create_purchase: Starting function execution with business_id: %, supplier_id: %', v_business_id, v_supplier_id;\r\n    RAISE LOG 'create_purchase: Purchase details - date: %, subtotal: %, discount: %, shipping: %, tax: %, grand_total: %, paid: %, due: %',\r\n        v_purchase_date, v_subtotal, v_discount_amount, v_shipping_charge, v_tax_amount, v_grand_total, v_paid_amount, v_due_amount;\r\n    RAISE LOG 'create_purchase: Items count: %, Payment details: %', \r\n        CASE WHEN v_purchase_items IS NULL THEN 0 ELSE jsonb_array_length(v_purchase_items) END, v_payment_details;\r\n\r\n    -- Validate Inputs\r\n    IF v_business_id IS NULL OR v_supplier_id IS NULL OR v_purchase_items IS NULL OR jsonb_array_length(v_purchase_items) = 0 THEN\r\n        RAISE LOG 'create_purchase: Validation failed - Missing required fields';\r\n        RAISE EXCEPTION 'business_id, supplier_id, and at least one purchase_item are required.';\r\n    END IF;\r\n    -- Basic validation of amounts (e.g., grand_total should roughly match components)\r\n    IF abs(v_subtotal - v_discount_amount + v_shipping_charge + v_tax_amount - v_grand_total) > 0.01 THEN\r\n         RAISE LOG 'create_purchase: Grand total (%) does not match sum of components (Sub:%, Disc:%, Ship:%, Tax:%)',\r\n             v_grand_total, v_subtotal, v_discount_amount, v_shipping_charge, v_tax_amount;\r\n         RAISE WARNING 'Grand total % does not match sum of components (Sub:%, Disc:%, Ship:%, Tax:%). Check input JSON.',\r\n           v_grand_total, v_subtotal, v_discount_amount, v_shipping_charge, v_tax_amount;\r\n    END IF;\r\n    -- Validation: Check relationship allowing negative due_amount\r\n    IF abs(v_grand_total - (v_paid_amount + v_due_amount)) > 0.01 THEN\r\n        RAISE LOG 'create_purchase: Balance validation failed - GT:%, Paid:%, Due:%', \r\n            v_grand_total, v_paid_amount, v_due_amount;\r\n        RAISE EXCEPTION 'Relationship Grand Total = Paid Amount + Due Amount violated. GT:%, Paid:%, Due:%. Check input JSON.',\r\n            v_grand_total, v_paid_amount, v_due_amount;\r\n    END IF;\r\n\r\n    -- Fetch Account IDs\r\n    RAISE LOG 'create_purchase: Fetching account IDs for business_id: %', v_business_id;\r\n    SELECT account_id INTO v_inventory_acc_id FROM public.accounts WHERE business_id = v_business_id AND code = v_inventory_code;\r\n    SELECT account_id INTO v_ap_supplier_acc_id FROM public.accounts WHERE business_id = v_business_id AND code = v_ap_supplier_code;\r\n    SELECT account_id INTO v_shipping_exp_acc_id FROM public.accounts WHERE business_id = v_business_id AND code = v_shipping_exp_code;\r\n    SELECT account_id INTO v_cash_in_bank_acc_id FROM public.accounts WHERE business_id = v_business_id AND code = v_cash_in_bank_code;\r\n    SELECT account_id INTO v_petty_cash_acc_id FROM public.accounts WHERE business_id = v_business_id AND code = v_petty_cash_code;\r\n    SELECT account_id INTO v_purchase_discount_acc_id FROM public.accounts WHERE business_id = v_business_id AND code = v_purchase_discount_code; -- <<< Added Fetch\r\n\r\n    -- Debug account IDs\r\n    RAISE LOG 'create_purchase: Account IDs - Inventory: %, AP: %, Shipping: %, Bank: %, Cash: %, Discount: %',\r\n        v_inventory_acc_id, v_ap_supplier_acc_id, v_shipping_exp_acc_id, \r\n        v_cash_in_bank_acc_id, v_petty_cash_acc_id, v_purchase_discount_acc_id;\r\n\r\n    -- Check ALL required accounts\r\n    IF v_inventory_acc_id IS NULL OR v_ap_supplier_acc_id IS NULL OR v_shipping_exp_acc_id IS NULL\r\n       OR v_cash_in_bank_acc_id IS NULL OR v_petty_cash_acc_id IS NULL OR v_purchase_discount_acc_id IS NULL THEN -- <<< Added Check\r\n        RAISE LOG 'create_purchase: Missing required account(s) for business_id: %', v_business_id;\r\n        RAISE EXCEPTION 'One or more required accounts (Inventory, A/P-Supplier, Shipping Exp, Cash, Bank, Purchase Discount) not found for business %.', v_business_id;\r\n    END IF;\r\n\r\n    -- Generate Internal Reference Number\r\n    -- Assuming public.get_next_purchase_code exists and handles sequence incrementing\r\n    SELECT public.get_next_purchase_code(v_business_id)\r\n    INTO v_gen_reference_no;\r\n    RAISE LOG 'create_purchase: Generated reference number: %', v_gen_reference_no;\r\n\r\n    -- *** CORRECTED Status and Due Amount Calculation ***\r\n    v_calculated_due_amount := v_grand_total - v_paid_amount;\r\n\r\n    -- Using ROUND to handle potential minor precision issues with NUMERIC comparisons\r\n    IF ROUND(v_paid_amount, 2) >= ROUND(v_grand_total, 2) THEN\r\n        -- Handles fully paid and potential overpayments/credits applied\r\n        v_status := 'PAID'::public.transaction_status;\r\n        -- Ensure due amount reflects potential overpayment if needed, or cap at 0\r\n        v_calculated_due_amount := LEAST(v_calculated_due_amount, 0); -- Cap due amount at 0 or less if overpaid\r\n    ELSIF v_paid_amount > 0 THEN\r\n        v_status := 'PARTIALLY_PAID'::public.transaction_status;\r\n    ELSE -- paid_amount <= 0\r\n        v_status := 'PENDING'::public.transaction_status;\r\n    END IF;\r\n\r\n\t-- 1. Create Purchase Transaction Header\r\n\tRAISE LOG 'create_purchase: Creating transaction header with reference: %', v_gen_reference_no;\r\n\tINSERT INTO public.transactions (\r\n\t    reference_no, transaction_type, transaction_date, status,\r\n\t    total_amount, paid_amount, due_amount,\r\n\t    notes, business_id, created_by, supplier_id -- Link supplier\r\n\t) VALUES (\r\n\t    v_gen_reference_no, 'PURCHASE'::public.transaction_type, v_purchase_date, v_status,\r\n\t    v_grand_total, v_paid_amount, v_due_amount,\r\n\t    v_notes, v_business_id, v_user_id, v_supplier_id\r\n\t) RETURNING transaction_id INTO v_transaction_id;\r\n\tRAISE LOG 'create_purchase: Created transaction ID: %', v_transaction_id;\r\n\t\r\n\t-- 2. Create Purchase Header Record\r\n\tRAISE LOG 'create_purchase: Creating purchase header record';\r\n\tINSERT INTO public.purchases (\r\n\t    purchase_id, invoice_no, supplier_id, purchase_date, transaction_id,\r\n\t    subtotal, discount_amount, tax_amount, shipping_charge, total_amount,\r\n\t    paid_amount, due_amount, business_id, created_by, notes,\r\n\t    attachment_url, purchase_invoice, -- Storing user's invoice #\r\n\t    created_at, updated_at\r\n\t) VALUES (\r\n\t    gen_random_uuid(), v_gen_reference_no, v_supplier_id, v_purchase_date, v_transaction_id,\r\n\t    v_subtotal, v_discount_amount, v_tax_amount, v_shipping_charge, v_grand_total,\r\n\t    v_paid_amount, v_due_amount, v_business_id, v_user_id, v_notes,\r\n\t    v_attachment_url, v_user_provided_inv_no,\r\n\t    now(), now()\r\n\t) RETURNING purchases.purchase_id INTO v_purchase_id;\r\n\tRAISE LOG 'create_purchase: Created purchase ID: %', v_purchase_id;\r\n\t\r\n\t\r\n\t-- 3. Process Purchase Items and Initial GL Entries\r\n\tRAISE LOG 'create_purchase: Processing purchase items, count: %', jsonb_array_length(v_purchase_items);\r\n\t-- Loop through items to create purchase_items, update quantity, and generate Inventory Dr entries\r\n\tFOR v_purchase_item_data IN SELECT * FROM jsonb_to_recordset(v_purchase_items) AS x(item_id uuid, quantity numeric, unit_price numeric)\r\n\tLOOP\r\n\t    DECLARE\r\n\t        v_item_id UUID := v_purchase_item_data.item_id;\r\n\t        v_quantity NUMERIC := v_purchase_item_data.quantity;\r\n\t        v_unit_price NUMERIC := v_purchase_item_data.unit_price;\r\n\t        v_line_total NUMERIC := v_quantity * v_unit_price;\r\n\t        v_inventory_enabled BOOLEAN;\r\n\t    BEGIN\r\n\t        RAISE LOG 'create_purchase: Processing item ID: %, quantity: %, unit_price: %, line_total: %', \r\n\t            v_item_id, v_quantity, v_unit_price, v_line_total;\r\n\t        \r\n\t        -- Insert purchase item line\r\n\t        INSERT INTO public.purchase_items (purchase_id, item_id, quantity, unit_price)\r\n\t        VALUES (v_purchase_id, v_item_id, v_quantity, v_unit_price);\r\n\t\r\n\t        -- Check if inventory tracking is enabled for this item\r\n\t        SELECT i.inventory_enabled INTO v_inventory_enabled\r\n\t        FROM public.items i\r\n\t        WHERE i.item_id = v_item_id AND i.business_id = v_business_id;\r\n\t\r\n\t        IF FOUND AND v_inventory_enabled THEN\r\n\t            RAISE LOG 'create_purchase: Item % is inventory enabled, updating stock', v_item_id;\r\n\t            -- Update item stock quantity\r\n\t            UPDATE public.items\r\n\t            SET stock_quantity = stock_quantity + v_quantity,\r\n\t                updated_at = now()\r\n\t            WHERE item_id = v_item_id;\r\n\t\r\n\t            -- Create GL Entry: Debit Inventory\r\n\t            INSERT INTO public.transaction_entries (transaction_id, account_id, entry_type, amount, description)\r\n\t            VALUES (v_transaction_id, v_inventory_acc_id, 'DEBIT', v_line_total, 'Purchase: Item ' || v_item_id::text);\r\n\t\r\n\t            v_item_total_value := v_item_total_value + v_line_total; -- Accumulate value for inventory portion\r\n\t            RAISE LOG 'create_purchase: Updated item_total_value to: %', v_item_total_value;\r\n\t        ELSE\r\n\t            -- Item not found, not inventory enabled, or service: Post to an expense account?\r\n\t            -- Option: Post v_line_total to a default Purchase Expense account instead of Inventory.\r\n\t            -- For simplicity now, we assume items exist and are inventory-enabled if listed. Add error handling if needed.\r\n\t            RAISE LOG 'create_purchase: WARNING - Item % not found or inventory not enabled', v_item_id;\r\n\t            RAISE WARNING 'Item % not found or inventory not enabled; cost not posted to Inventory GL.', v_item_id;\r\n\t            v_item_total_value := v_item_total_value + v_line_total; -- Still count towards subtotal for AP balancing\r\n\t        END IF;\r\n\t    END;\r\n\tEND LOOP;\r\n\t\r\n\t-- 4. Create Remaining Purchase GL Entries (Shipping, Discount Offset, A/P Credit)\r\n\tRAISE LOG 'create_purchase: Creating additional GL entries';\r\n\t\r\n\t-- Debit Shipping Costs\r\n\tIF v_shipping_charge > 0 THEN\r\n\t    RAISE LOG 'create_purchase: Adding shipping GL entry for amount: %', v_shipping_charge;\r\n\t    INSERT INTO public.transaction_entries (transaction_id, account_id, entry_type, amount, description)\r\n\t    VALUES (v_transaction_id, v_shipping_exp_acc_id, 'DEBIT', v_shipping_charge, 'Purchase: Shipping');\r\n\tEND IF;\r\n\t\r\n\t-- Handle Discount (Reduce the Credit to A/P) - The A/P credit below will be net amount\r\n\tIF v_discount_amount > 0 THEN\r\n\t    RAISE LOG 'create_purchase: Adding discount GL entry for amount: %', v_discount_amount;\r\n\t    INSERT INTO public.transaction_entries (transaction_id, account_id, entry_type, amount, description)\r\n\t    VALUES (v_transaction_id, v_purchase_discount_acc_id, 'CREDIT', v_discount_amount, 'Purchase: Discount Received');\r\n\tEND IF;\r\n\t\r\n\t-- Handle Tax (Assume included in v_grand_total calculation for A/P) - If tax needs separate GL, add Dr Tax Asset/Expense entry here.\r\n\t\r\n\t-- Credit Accounts Payable for the total owed\r\n\tRAISE LOG 'create_purchase: Adding AP credit entry for grand total: %', v_grand_total;\r\n\t-- Total credit should balance the debits (Inventory + Shipping + potentially Tax - Discount)\r\n\tINSERT INTO public.transaction_entries (transaction_id, account_id, entry_type, amount, description)\r\n\tVALUES (v_transaction_id, v_ap_supplier_acc_id, 'CREDIT', v_grand_total, 'Purchase: Payable to Supplier ' || v_supplier_id::text);\r\n\t\r\n\t-- Verify the balance of the PURCHASE transaction entries BEFORE payment\r\n\t-- Debits = SUM(item lines) + shipping + (tax if separate)\r\n\t-- Credits = grand_total (includes effect of discount)\r\n\t-- PERFORM public.verify_transaction_balance(v_transaction_id); -- This may fail until payment entries are added if paid_amount > 0\r\n\t\r\n\t\r\n\t-- 5. Process Immediate Payment (if any)\r\n\tIF v_paid_amount > 0 THEN\r\n\t    RAISE LOG 'create_purchase: Processing immediate payment of: %', v_paid_amount;\r\n\t    -- Create Payment GL Entries: Debit A/P, Credit Cash/Bank\r\n\t    FOR v_payment_method, v_payment_amount IN SELECT key, value::text::numeric FROM jsonb_each_text(v_payment_details) WHERE value::text::numeric > 0\r\n\t    LOOP\r\n\t         DECLARE\r\n\t             v_payment_account_id UUID;\r\n\t         BEGIN\r\n\t             RAISE LOG 'create_purchase: Processing payment method: %, amount: %', v_payment_method, v_payment_amount;\r\n\t             -- Map payment method to account (Simplified: cash->Petty Cash, others->Bank)\r\n\t             IF lower(v_payment_method) = 'cash' THEN\r\n\t                v_payment_account_id := v_petty_cash_acc_id;\r\n\t                RAISE LOG 'create_purchase: Using petty cash account: %', v_payment_account_id;\r\n\t             ELSE\r\n\t                v_payment_account_id := v_cash_in_bank_acc_id;\r\n\t                RAISE LOG 'create_purchase: Using bank account: %', v_payment_account_id;\r\n\t             END IF;\r\n\t\r\n\t             -- Debit Accounts Payable (Reducing liability)\r\n\t             INSERT INTO public.transaction_entries (transaction_id, account_id, entry_type, amount, description)\r\n\t             VALUES (v_transaction_id, v_ap_supplier_acc_id, 'DEBIT', v_payment_amount, 'Payment for Purchase Ref ' || v_gen_reference_no);\r\n\t\r\n\t             -- Credit Cash/Bank (Reducing asset)\r\n\t             INSERT INTO public.transaction_entries (transaction_id, account_id, entry_type, amount, description)\r\n\t             VALUES (v_transaction_id, v_payment_account_id, 'CREDIT', v_payment_amount, 'Payment for Purchase Ref ' || v_gen_reference_no);\r\n\t\r\n\t             -- Create Payment Record\r\n\t             INSERT INTO public.payments (\r\n\t                 transaction_id, payment_date, amount, payment_method, reference_no, created_by\r\n\t             ) VALUES (\r\n\t                 v_transaction_id, v_purchase_date, v_payment_amount, v_payment_method, v_gen_reference_no, v_user_id\r\n\t             ); -- Returning payment_id if needed\r\n\t             RAISE LOG 'create_purchase: Created payment record for method: %, amount: %', v_payment_method, v_payment_amount;\r\n\t         END;\r\n\t    END LOOP;\r\n\t\r\n\t    -- Verify the balance of the FULL transaction (Purchase + Payment)\r\n\t    RAISE LOG 'create_purchase: Verifying transaction balance after payment';\r\n\t    PERFORM public.verify_transaction_balance(v_transaction_id);\r\n\t\r\n\tELSE\r\n\t    -- If no payment, verify the balance of just the purchase entries\r\n\t    RAISE LOG 'create_purchase: No immediate payment, verifying purchase transaction balance';\r\n\t    PERFORM public.verify_transaction_balance(v_transaction_id);\r\n\tEND IF;\r\n\r\n    -- 6. Remove Direct Supplier Update (remains the same)\r\n    RAISE LOG 'create_purchase: Purchase processing completed successfully';\r\n\r\n    -- 7. Return Result\r\n    PERFORM nextval(v_business_id::text || '_purchase_invoice'); -- <<< Removed Redundant Call\r\n    RAISE LOG 'create_purchase: Returning purchase data for purchase_id: %', v_purchase_id;\r\n    RETURN (SELECT row_to_json(purchase_view)\r\n    FROM purchase_view\r\n    WHERE purchase_id = v_purchase_id);\r\n\r\nEXCEPTION\r\n\tWHEN unique_violation THEN\r\n\t-- Could be user invoice no, generated ref no etc.\r\n\tRAISE LOG 'create_purchase: ERROR - Unique violation with invoice no \\"%\\" or reference no \\"%\\"', v_user_provided_inv_no, v_gen_reference_no;\r\n\tRAISE EXCEPTION 'Failed to create purchase: Unique constraint violated. Check Invoice No \\"%\\" or Reference No \\"%\\". Detail: %',\r\n\tv_user_provided_inv_no, v_gen_reference_no, SQLERRM;\r\n\tWHEN others THEN\r\n\tRAISE LOG 'create_purchase: ERROR - General exception: %', SQLERRM;\r\n\tRAISE EXCEPTION 'Failed to create purchase: %', SQLERRM;\r\nEND;\r\n$function$","CREATE OR REPLACE FUNCTION public.create_purchase_return(p_data jsonb)\r\n RETURNS void\r\n LANGUAGE plpgsql\r\nAS $function$\r\nDECLARE\r\n    v_transaction_id uuid;\r\n    v_return_id uuid;\r\n    v_business_id uuid;\r\n    v_purchase_id uuid;\r\n    v_main_account_id uuid;\r\n    v_payable_account_id uuid;\r\n    v_return_date timestamp with time zone;\r\n    v_return_item record;\r\n    v_total_amount numeric := 0;\r\n    v_supplier_id uuid;\r\nBEGIN\r\n    -- Extract key values\r\n    v_business_id := (p_data->>'business_id')::uuid;\r\n    v_purchase_id := (p_data->>'purchase_id')::uuid;\r\n    v_return_date := (p_data->>'return_date')::timestamp with time zone;\r\n    \r\n    -- Get supplier_id from purchase\r\n    SELECT supplier_id INTO v_supplier_id\r\n    FROM purchases\r\n    WHERE purchase_id = v_purchase_id;\r\n    \r\n    -- Calculate total amount\r\n    SELECT SUM(quantity * unit_price)::numeric INTO v_total_amount\r\n    FROM jsonb_to_recordset(p_data->'items') \r\n    AS x(quantity numeric, unit_price numeric);\r\n    \r\n    -- Get account IDs\r\n    SELECT account_id INTO v_main_account_id\r\n    FROM accounts \r\n    WHERE business_id = v_business_id AND code = 'MOA';\r\n    \r\n    SELECT account_id INTO v_payable_account_id\r\n    FROM accounts \r\n    WHERE business_id = v_business_id AND code = 'TRP';\r\n    \r\n    -- Create transaction\r\n    INSERT INTO transactions (\r\n        reference_no,\r\n        transaction_type,\r\n        transaction_date,\r\n        status,\r\n        total_amount,\r\n        paid_amount,\r\n        due_amount,\r\n        business_id,\r\n        metadata\r\n    ) VALUES (\r\n        p_data->>'return_invoice',\r\n        'PURCHASE_RETURN',\r\n        v_return_date,\r\n        'PAID',\r\n        v_total_amount,\r\n        v_total_amount,\r\n        0,\r\n        v_business_id,\r\n        p_data\r\n    ) RETURNING transaction_id INTO v_transaction_id;\r\n    \r\n    -- Create transaction entries (reverse of purchase entries)\r\n    INSERT INTO transaction_entries (\r\n        transaction_id,\r\n        account_id,\r\n        entry_type,\r\n        amount,\r\n        description\r\n    ) VALUES\r\n    (v_transaction_id, v_main_account_id, 'CREDIT', v_total_amount, 'Purchase return credit'),\r\n    (v_transaction_id, v_payable_account_id, 'DEBIT', v_total_amount, 'Purchase return debit');\r\n    \r\n    -- Create purchase return record\r\n    INSERT INTO purchase_returns (\r\n        purchase_id,\r\n        return_invoice,\r\n        return_date,\r\n        reason,\r\n        notes,\r\n        total_amount,\r\n        transaction_id,\r\n        business_id\r\n    ) VALUES (\r\n        v_purchase_id,\r\n        p_data->>'return_invoice',\r\n        v_return_date,\r\n        p_data->>'reason',\r\n        p_data->>'notes',\r\n        v_total_amount,\r\n        v_transaction_id,\r\n        v_business_id\r\n    ) RETURNING return_id INTO v_return_id;\r\n    \r\n    -- Create return items and update inventory\r\n    FOR v_return_item IN \r\n        SELECT \r\n            x.*,\r\n            i.item_type\r\n        FROM jsonb_to_recordset(p_data->'items') \r\n        AS x(item_id uuid, original_item_id uuid, quantity numeric, unit_price numeric)\r\n        JOIN items i ON i.item_id = x.item_id\r\n    LOOP\r\n        -- Insert return item\r\n        INSERT INTO purchase_return_items (\r\n            return_id,\r\n            purchase_item_id,\r\n            quantity,\r\n            unit_price\r\n        ) VALUES (\r\n            v_return_id,\r\n            v_return_item.original_item_id,\r\n            v_return_item.quantity,\r\n            v_return_item.unit_price\r\n        );\r\n        \r\n        -- Update item inventory if it's a good\r\n        IF v_return_item.item_type = 'goods' THEN\r\n            UPDATE items\r\n            SET \r\n                stock_quantity = CASE \r\n                    WHEN inventory_enabled THEN stock_quantity - v_return_item.quantity \r\n                    ELSE stock_quantity \r\n                END,\r\n                stock_value = CASE \r\n                    WHEN inventory_enabled THEN stock_value - (v_return_item.quantity * v_return_item.unit_price)\r\n                    ELSE stock_value \r\n                END\r\n            WHERE item_id = v_return_item.item_id;\r\n        END IF;\r\n    END LOOP;\r\n    \r\n    -- Create refund payment\r\n    INSERT INTO payments (\r\n        transaction_id,\r\n        payment_date,\r\n        amount,\r\n        payment_method,\r\n        reference_no,\r\n        created_by\r\n    ) VALUES (\r\n        v_transaction_id,\r\n        v_return_date,\r\n        v_total_amount,\r\n        'CASH',  -- You might want to make this configurable\r\n        p_data->>'return_invoice',\r\n        auth.uid()\r\n    );\r\n    \r\n    -- Update purchase due amount\r\n    UPDATE purchases \r\n    SET due_amount = due_amount - v_total_amount\r\n    WHERE purchase_id = v_purchase_id;\r\n    \r\n    -- Update supplier due amount\r\n    UPDATE suppliers \r\n    SET due = due - v_total_amount\r\n    WHERE business_id = v_business_id \r\n    AND supplier_id = v_supplier_id;\r\n\r\n\tPERFORM nextval(v_business_id::text || '_purchase_return_code');\r\n    \r\nEXCEPTION\r\n    WHEN others THEN\r\n        RAISE EXCEPTION 'Error in create_purchase_return: %', SQLERRM;\r\nEND;\r\n$function$","CREATE OR REPLACE FUNCTION public.create_sale(p_sale_json jsonb)\r\n RETURNS jsonb\r\n LANGUAGE plpgsql\r\nAS $function$\r\nDECLARE\r\n    -- Input Data Parsed (remain the same)\r\n    v_business_id         UUID := (p_sale_json->>'business_id')::uuid;\r\n    v_customer_id         UUID := (p_sale_json->>'customer_id')::uuid; -- Nullable for walk-in?\r\n    v_sale_date           TIMESTAMPTZ := COALESCE((p_sale_json->>'sale_date')::timestamptz, now());\r\n    v_notes               TEXT := p_sale_json->>'notes';\r\n    v_attachment_url      TEXT := p_sale_json->>'attachment';\r\n    v_subtotal            NUMERIC := COALESCE((p_sale_json->>'subtotal')::numeric, 0);\r\n    v_discount_amount     NUMERIC := COALESCE((p_sale_json->>'discount_amount')::numeric, 0);\r\n    v_shipping_charge     NUMERIC := COALESCE((p_sale_json->>'shipping')::numeric, 0);\r\n    v_tax_amount          NUMERIC := COALESCE((p_sale_json->>'tax_total')::numeric, 0); -- Renamed input key assumption\r\n    v_grand_total         NUMERIC := COALESCE((p_sale_json->>'grand_total')::numeric, 0);\r\n    v_paid_amount         NUMERIC := COALESCE((p_sale_json->>'paid_amount')::numeric, 0);\r\n    v_sale_items          JSONB := p_sale_json->'sale_items';\r\n    v_payment_details     JSONB := p_sale_json->'payment_details';\r\n    v_order_mode          BOOLEAN := COALESCE((p_sale_json->>'order_mode')::boolean, false);\r\n\r\n    -- Internal Vars (remain the same)\r\n    v_transaction_id      UUID;\r\n    v_sale_id             UUID;\r\n    v_status_id           UUID;\r\n    v_gen_reference_no    TEXT; -- Our internal invoice number\r\n    v_status              public.transaction_status;\r\n    v_user_id             UUID := COALESCE((p_sale_json->>'employee_id')::uuid, auth.uid()); -- Prefer employee_id if passed\r\n    v_sale_item_data      RECORD;\r\n    v_subservice_data     RECORD;\r\n    v_payment_method      TEXT;\r\n    v_payment_amount      NUMERIC;\r\n    v_calculated_due_amount NUMERIC;\r\n    v_total_cogs_value    NUMERIC := 0;\r\n    v_total_revenue_value NUMERIC := 0;\r\n    v_sale_item_id_gen    UUID;\r\n\r\n    -- Account IDs & Codes (remain the same)\r\n    v_ar_cust_acc_id           UUID;\r\n    v_sales_goods_acc_id       UUID;\r\n    v_sales_services_acc_id    UUID;\r\n    v_tax_payable_acc_id       UUID;\r\n    v_shipping_revenue_acc_id  UUID; -- Ensure account 4040 exists\r\n    v_inventory_acc_id         UUID;\r\n    v_cogs_acc_id              UUID; -- Ensure account 5015 exists\r\n    v_cash_in_bank_acc_id      UUID;\r\n    v_petty_cash_acc_id        UUID;\r\n\tv_sales_discount_acc_id    UUID;\r\n\t\r\n\tv_sales_discount_code      TEXT := '4900'; -- Or your chosen code\r\n    v_ar_cust_code             TEXT := '1020';\r\n    v_sales_goods_code         TEXT := '4010';\r\n    v_sales_services_code      TEXT := '4020';\r\n    v_tax_payable_code         TEXT := '2020';\r\n    v_shipping_revenue_code    TEXT := '4040';\r\n    v_inventory_code           TEXT := '1030';\r\n    v_cogs_code                TEXT := '5015';\r\n    v_cash_in_bank_code        TEXT := '1011';\r\n    v_petty_cash_code          TEXT := '1010';\r\n\r\nBEGIN\r\n    RAISE LOG 'create_sale: Starting function execution for business_id: %', v_business_id;\r\n\r\n    -- Validate Inputs (remain the same)\r\n    IF v_business_id IS NULL OR v_sale_items IS NULL OR jsonb_array_length(v_sale_items) = 0 THEN\r\n        RAISE EXCEPTION 'business_id and at least one sale_item are required.'; -- Removed status_id requirement here\r\n    END IF;\r\n    IF abs(v_subtotal - v_discount_amount + v_shipping_charge + v_tax_amount - v_grand_total) > 0.01 THEN\r\n         RAISE WARNING 'Grand total % does not match sum of components (Sub:%, Disc:%, Ship:%, Tax:%). Check input JSON.',\r\n           v_grand_total, v_subtotal, v_discount_amount, v_shipping_charge, v_tax_amount;\r\n    END IF;\r\n\r\n    -- Get default status ID for sales\r\n    SELECT status_id INTO v_status_id\r\n    FROM public.statuses\r\n    WHERE business_id = v_business_id AND is_default = true AND type = 'sale'::public.status_type\r\n    LIMIT 1;\r\n    -- Handle case where default status is not found\r\n    IF v_status_id IS NULL THEN\r\n        RAISE EXCEPTION 'Default sale status not found for business ID: %', v_business_id;\r\n    END IF;\r\n\r\n    -- Fetch Account IDs (remain the same)\r\n    RAISE LOG 'create_sale: Fetching accounts for business: %', v_business_id;\r\n    SELECT account_id INTO v_ar_cust_acc_id FROM public.accounts WHERE business_id = v_business_id AND code = v_ar_cust_code;\r\n    SELECT account_id INTO v_sales_goods_acc_id FROM public.accounts WHERE business_id = v_business_id AND code = v_sales_goods_code;\r\n    SELECT account_id INTO v_sales_services_acc_id FROM public.accounts WHERE business_id = v_business_id AND code = v_sales_services_code;\r\n    SELECT account_id INTO v_tax_payable_acc_id FROM public.accounts WHERE business_id = v_business_id AND code = v_tax_payable_code;\r\n    -- Fetch shipping revenue account only if needed, check later\r\n    SELECT account_id INTO v_inventory_acc_id FROM public.accounts WHERE business_id = v_business_id AND code = v_inventory_code;\r\n    SELECT account_id INTO v_cogs_acc_id FROM public.accounts WHERE business_id = v_business_id AND code = v_cogs_code;\r\n    SELECT account_id INTO v_cash_in_bank_acc_id FROM public.accounts WHERE business_id = v_business_id AND code = v_cash_in_bank_code;\r\n    SELECT account_id INTO v_petty_cash_acc_id FROM public.accounts WHERE business_id = v_business_id AND code = v_petty_cash_code;\r\n\r\n    -- Fetch optional accounts only if needed\r\n    IF v_shipping_charge > 0 THEN\r\n        SELECT account_id INTO v_shipping_revenue_acc_id FROM public.accounts WHERE business_id = v_business_id AND code = v_shipping_revenue_code;\r\n        IF v_shipping_revenue_acc_id IS NULL THEN\r\n             RAISE EXCEPTION 'Shipping Revenue account (Code: %) not found for business %.', v_shipping_revenue_code, v_business_id;\r\n        END IF;\r\n    END IF;\r\n\r\n\tIF v_discount_amount > 0 THEN\r\n\t    SELECT account_id INTO v_sales_discount_acc_id FROM public.accounts WHERE business_id = v_business_id AND code = v_sales_discount_code;\r\n\t    IF v_sales_discount_acc_id IS NULL THEN\r\n\t         RAISE EXCEPTION 'Sales Discount account (Code: %) not found for business %.', v_sales_discount_code, v_business_id;\r\n\t    END IF;\r\n\tEND IF;\r\n\r\n    -- Check required core accounts exist\r\n    IF v_ar_cust_acc_id IS NULL OR v_sales_goods_acc_id IS NULL OR v_sales_services_acc_id IS NULL OR v_tax_payable_acc_id IS NULL\r\n       OR v_inventory_acc_id IS NULL OR v_cogs_acc_id IS NULL OR v_cash_in_bank_acc_id IS NULL OR v_petty_cash_acc_id IS NULL THEN\r\n        RAISE EXCEPTION 'One or more required core accounts (A/R, Sales, Tax, Inventory, COGS, Cash, Bank) not found for business %.', v_business_id;\r\n    END IF;\r\n\r\n\r\n\r\n\r\n    -- Generate Internal Invoice Number (remain the same)\r\n    SELECT public.get_next_sale_code(v_business_id) INTO v_gen_reference_no;\r\n    RAISE LOG 'create_sale: Using Invoice No: %', v_gen_reference_no;\r\n\r\n    -- Calculate Status and Due Amount (remain the same)\r\n    v_calculated_due_amount := v_grand_total - v_paid_amount;\r\n    IF ROUND(v_paid_amount, 2) >= ROUND(v_grand_total, 2) THEN\r\n        v_status := 'PAID'::public.transaction_status;\r\n        v_calculated_due_amount := LEAST(v_calculated_due_amount, 0);\r\n    ELSIF v_paid_amount > 0 THEN\r\n        v_status := 'PARTIALLY_PAID'::public.transaction_status;\r\n    ELSE\r\n        v_status := 'PENDING'::public.transaction_status;\r\n    END IF;\r\n    RAISE LOG 'create_sale: Calculated Status: %, Due Amount: %', v_status, v_calculated_due_amount;\r\n\r\n    -- 1. Create Sale Transaction Header (remain the same)\r\n    RAISE LOG 'create_sale: Creating transaction header';\r\n    INSERT INTO public.transactions (\r\n        reference_no, transaction_type, transaction_date, status,\r\n        total_amount, paid_amount, due_amount,\r\n        notes, business_id, created_by, customer_id\r\n    ) VALUES (\r\n        v_gen_reference_no, 'SALE'::public.transaction_type, v_sale_date, v_status,\r\n        v_grand_total, v_paid_amount, v_calculated_due_amount,\r\n        v_notes, v_business_id, v_user_id, v_customer_id\r\n    ) RETURNING transaction_id INTO v_transaction_id;\r\n    RAISE LOG 'create_sale: Created Transaction ID: %', v_transaction_id;\r\n\r\n    -- 2. Create Sale Header Record (remain the same)\r\n    RAISE LOG 'create_sale: Creating sale header record';\r\n    INSERT INTO public.sales (\r\n        sale_id, customer_id, sale_date, transaction_id,\r\n        subtotal, discount_amount, tax_amount, shipping_charge, total_amount,\r\n        paid_amount, due_amount, business_id, created_by, notes,\r\n        attachment_url, sale_invoice, status_id, order_mode, metadata,\r\n        created_at, updated_at\r\n    ) VALUES (\r\n        gen_random_uuid(), v_customer_id, v_sale_date, v_transaction_id,\r\n        v_subtotal, v_discount_amount, v_tax_amount, v_shipping_charge, v_grand_total,\r\n        v_paid_amount, v_calculated_due_amount, v_business_id, v_user_id, v_notes,\r\n        v_attachment_url, v_gen_reference_no, v_status_id, v_order_mode, p_sale_json->'metadata',\r\n        now(), now()\r\n    ) RETURNING sales.sale_id INTO v_sale_id;\r\n    RAISE LOG 'create_sale: Created Sale ID: %', v_sale_id;\r\n\r\n    -- 3. Process Sale Items, Inventory, COGS, and Revenue GL Entries\r\n    RAISE LOG 'create_sale: Processing sale items';\r\n    FOR v_sale_item_data IN\r\n        SELECT\r\n            x.item_id,\r\n            x.quantity,\r\n            x.unit_price,\r\n            x.subservices,\r\n            i.item_type,\r\n            i.inventory_enabled,\r\n            COALESCE(i.purchase_price, 0) as item_cost\r\n        FROM jsonb_to_recordset(v_sale_items)\r\n            AS x(item_id uuid, quantity numeric, unit_price numeric, subservices jsonb)\r\n        JOIN public.items i ON i.item_id = x.item_id\r\n        WHERE i.business_id = v_business_id\r\n    LOOP\r\n        DECLARE\r\n            v_item_id               UUID := v_sale_item_data.item_id;\r\n            v_quantity              NUMERIC := v_sale_item_data.quantity;\r\n            v_unit_price            NUMERIC := v_sale_item_data.unit_price;\r\n            v_line_total            NUMERIC := v_quantity * v_unit_price;\r\n            v_item_type             public.item_type := v_sale_item_data.item_type;\r\n            v_inventory_enabled     BOOLEAN := v_sale_item_data.inventory_enabled;\r\n            v_item_cost             NUMERIC := v_sale_item_data.item_cost;\r\n            v_cogs_amount           NUMERIC := 0;\r\n            v_revenue_account_id    UUID;\r\n            v_item_name             TEXT;\r\n            v_subservice_revenue    NUMERIC := 0; -- Accumulate subservice revenue for this line\r\n        BEGIN\r\n            SELECT i.name INTO v_item_name FROM public.items i WHERE i.item_id = v_item_id;\r\n            RAISE LOG 'create_sale: Processing Item ID: %, Name: %, Qty: %, Price: %', v_item_id, v_item_name, v_quantity, v_unit_price;\r\n\r\n            -- Insert Sale Item Line\r\n            INSERT INTO public.sale_items (sale_id, item_id, quantity, unit_price, created_at, updated_at)\r\n            VALUES (v_sale_id, v_item_id, v_quantity, v_unit_price, now(), now())\r\n            RETURNING sale_item_id INTO v_sale_item_id_gen;\r\n\r\n            -- Determine Revenue Account for main item/service\r\n            IF v_item_type = 'goods' THEN\r\n                v_revenue_account_id := v_sales_goods_acc_id;\r\n            ELSIF v_item_type = 'services' THEN\r\n                v_revenue_account_id := v_sales_services_acc_id;\r\n            ELSE\r\n                RAISE WARNING 'Unknown item_type \\"%\\" for item %; defaulting revenue to Sales of Goods.', v_item_type, v_item_id;\r\n                v_revenue_account_id := v_sales_goods_acc_id;\r\n            END IF;\r\n\r\n            -- Create GL Entry: Credit Sales Revenue for main item/service price\r\n            INSERT INTO public.transaction_entries (transaction_id, account_id, entry_type, amount, description)\r\n            VALUES (v_transaction_id, v_revenue_account_id, 'CREDIT', v_line_total, 'Sale: Item ' || v_item_name);\r\n            v_total_revenue_value := v_total_revenue_value + v_line_total;\r\n\r\n            -- Handle Subservices (Insert links AND Add GL Credit)\r\n            IF v_item_type = 'services' AND v_sale_item_data.subservices IS NOT NULL AND jsonb_array_length(v_sale_item_data.subservices) > 0 THEN\r\n                RAISE LOG 'create_sale: Processing subservices for item: %', v_item_id;\r\n                FOR v_subservice_data IN\r\n                    SELECT\r\n                       x->>'sub_service_id' as sub_service_id, -- Assuming sub_service_id is text/uuid in JSON\r\n                       (x->>'quantity')::numeric as quantity,\r\n                       (x->>'additional_price')::numeric as additional_price,\r\n                       ss.name as sub_service_name -- Join to get name for description\r\n                    FROM jsonb_array_elements(v_sale_item_data.subservices) x\r\n                    LEFT JOIN public.subservices ss ON ss.sub_service_id = (x->>'sub_service_id')::uuid\r\n                LOOP\r\n                    DECLARE\r\n                        v_sub_line_total NUMERIC;\r\n                    BEGIN\r\n                        -- Insert link record\r\n                        INSERT INTO public.sale_item_subservices (sale_item_id, sub_service_id, quantity, additional_price, created_at, updated_at)\r\n                        VALUES (v_sale_item_id_gen, (v_subservice_data.sub_service_id)::uuid, v_subservice_data.quantity, v_subservice_data.additional_price, now(), now());\r\n\r\n                        -- *** ADD GL CREDIT FOR SUBSERVICE REVENUE ***\r\n                        v_sub_line_total := v_subservice_data.quantity * v_subservice_data.additional_price;\r\n                        INSERT INTO public.transaction_entries (transaction_id, account_id, entry_type, amount, description)\r\n                        VALUES (v_transaction_id, v_sales_services_acc_id, 'CREDIT', v_sub_line_total, 'Sale: Subservice ' || COALESCE(v_subservice_data.sub_service_name,'Unknown') || ' for ' || v_item_name);\r\n\r\n                        v_subservice_revenue := v_subservice_revenue + v_sub_line_total; -- Accumulate for logging/validation if needed\r\n                    END;\r\n                END LOOP;\r\n                v_total_revenue_value := v_total_revenue_value + v_subservice_revenue; -- Add to overall revenue total\r\n            END IF;\r\n\r\n            -- Handle Inventory and COGS for Goods (remain the same)\r\n            IF v_item_type = 'goods' AND v_inventory_enabled THEN\r\n                RAISE LOG 'create_sale: Processing COGS/Inventory for Item: %, Cost: %', v_item_id, v_item_cost;\r\n                UPDATE public.items\r\n                SET stock_quantity = stock_quantity - v_quantity,\r\n                    updated_at = now()\r\n                WHERE item_id = v_item_id;\r\n\r\n                v_cogs_amount := v_quantity * v_item_cost;\r\n                v_total_cogs_value := v_total_cogs_value + v_cogs_amount;\r\n\r\n                INSERT INTO public.transaction_entries (transaction_id, account_id, entry_type, amount, description)\r\n                VALUES (v_transaction_id, v_cogs_acc_id, 'DEBIT', v_cogs_amount, 'COGS for Sale: ' || v_item_name);\r\n\r\n                INSERT INTO public.transaction_entries (transaction_id, account_id, entry_type, amount, description)\r\n                VALUES (v_transaction_id, v_inventory_acc_id, 'CREDIT', v_cogs_amount, 'Inventory Sold: ' || v_item_name);\r\n            END IF;\r\n        END;\r\n    END LOOP;\r\n    RAISE LOG 'create_sale: Item processing complete. Total Revenue Posted: %, Total COGS Posted: %', v_total_revenue_value, v_total_cogs_value;\r\n\r\n    -- 4. Create Remaining Sale GL Entries (Tax, Shipping, AR) (remain the same)\r\n    RAISE LOG 'create_sale: Creating Tax/Shipping/AR entries';\r\n    IF v_tax_amount > 0 THEN\r\n        INSERT INTO public.transaction_entries (transaction_id, account_id, entry_type, amount, description)\r\n        VALUES (v_transaction_id, v_tax_payable_acc_id, 'CREDIT', v_tax_amount, 'Sales Tax');\r\n    END IF;\r\n\r\n    IF v_shipping_charge > 0 THEN\r\n        INSERT INTO public.transaction_entries (transaction_id, account_id, entry_type, amount, description)\r\n        VALUES (v_transaction_id, v_shipping_revenue_acc_id, 'CREDIT', v_shipping_charge, 'Shipping Charged');\r\n    END IF;\r\n\r\n\tIF v_discount_amount > 0 THEN\r\n\t     INSERT INTO public.transaction_entries (transaction_id, account_id, entry_type, amount, description)\r\n\t     VALUES (v_transaction_id, v_sales_discount_acc_id, 'DEBIT', v_discount_amount, 'Sales Discount Applied');\r\n\tEND IF;\r\n\r\n    -- Handle Discount (Skipped for now, assuming grand_total is net)\r\n\r\n    INSERT INTO public.transaction_entries (transaction_id, account_id, entry_type, amount, description)\r\n    VALUES (v_transaction_id, v_ar_cust_acc_id, 'DEBIT', v_grand_total, 'Sale Invoice: ' || v_gen_reference_no);\r\n\r\n    -- 5. Process Immediate Payment (remain the same)\r\n    IF v_paid_amount > 0 AND v_payment_details IS NOT NULL THEN\r\n        RAISE LOG 'create_sale: Processing immediate payment of: %', v_paid_amount;\r\n        FOR v_payment_method, v_payment_amount IN SELECT key, value::text::numeric FROM jsonb_each_text(v_payment_details) WHERE value::text::numeric > 0\r\n        LOOP\r\n             DECLARE\r\n                 v_payment_account_id UUID;\r\n             BEGIN\r\n                 RAISE LOG 'create_sale: Payment Method: %, Amount: %', v_payment_method, v_payment_amount;\r\n                 IF lower(v_payment_method) = 'cash' THEN\r\n                    v_payment_account_id := v_petty_cash_acc_id;\r\n                 ELSE\r\n                    v_payment_account_id := v_cash_in_bank_acc_id;\r\n                 END IF;\r\n\r\n                 INSERT INTO public.transaction_entries (transaction_id, account_id, entry_type, amount, description)\r\n                 VALUES (v_transaction_id, v_payment_account_id, 'DEBIT', v_payment_amount, 'Payment Received for Sale ' || v_gen_reference_no);\r\n\r\n                 INSERT INTO public.transaction_entries (transaction_id, account_id, entry_type, amount, description)\r\n                 VALUES (v_transaction_id, v_ar_cust_acc_id, 'CREDIT', v_payment_amount, 'Payment Received for Sale ' || v_gen_reference_no);\r\n\r\n                 INSERT INTO public.payments (transaction_id, payment_date, amount, payment_method, reference_no, created_by)\r\n                 VALUES (v_transaction_id, v_sale_date, v_payment_amount, v_payment_method, v_gen_reference_no, v_user_id);\r\n             END;\r\n        END LOOP;\r\n        RAISE LOG 'create_sale: Verifying transaction balance after payment';\r\n        PERFORM public.verify_transaction_balance(v_transaction_id);\r\n    ELSE\r\n        RAISE LOG 'create_sale: No immediate payment, verifying sale transaction balance';\r\n        PERFORM public.verify_transaction_balance(v_transaction_id);\r\n    END IF;\r\n\r\n    -- 6. Remove Direct Customer Balance Update (remains the same)\r\n    PERFORM nextval(v_business_id::text || '_sale_invoice'); -- Removed redundant nextval call\r\n    RAISE LOG 'create_sale: Sale creation complete for Sale ID: %', v_sale_id;\r\n\r\n    -- 7. Return Result (Ensure sale_view exists)\r\n    RETURN (SELECT row_to_json(sv) FROM public.sale_view sv WHERE sv.sale_id = v_sale_id);\r\n\r\nEXCEPTION\r\n    WHEN unique_violation THEN\r\n        RAISE LOG 'create_sale: ERROR - Unique constraint violation. Invoice No \\"%\\". Detail: %', v_gen_reference_no, SQLERRM;\r\n        RAISE EXCEPTION 'Failed to create sale: Unique constraint violated. Check Invoice No \\"%\\". Detail: %', v_gen_reference_no, SQLERRM;\r\n    WHEN others THEN\r\n        RAISE LOG 'create_sale: ERROR - General exception: %', SQLERRM;\r\n        RAISE EXCEPTION 'Failed to create sale: %', SQLERRM;\r\nEND;\r\n$function$","CREATE OR REPLACE FUNCTION public.create_sale_return(p_data jsonb)\r\n RETURNS void\r\n LANGUAGE plpgsql\r\nAS $function$\r\nDECLARE\r\n    v_transaction_id uuid;\r\n    v_return_id uuid;\r\n    v_business_id uuid;\r\n    v_sale_id uuid;\r\n    v_main_account_id uuid;\r\n    v_receivable_account_id uuid;\r\n    v_return_date timestamp with time zone;\r\n    v_return_item record;\r\n    v_total_amount numeric := 0;\r\n    v_customer_id uuid;\r\nBEGIN\r\n    -- Extract key values\r\n    v_business_id := (p_data->>'business_id')::uuid;\r\n    v_sale_id := (p_data->>'sale_id')::uuid;\r\n    v_return_date := (p_data->>'return_date')::timestamp with time zone;\r\n    \r\n    -- Get customer_id from sale\r\n    SELECT customer_id INTO v_customer_id\r\n    FROM sales\r\n    WHERE sale_id = v_sale_id;\r\n    \r\n    -- Calculate total amount\r\n    SELECT SUM(quantity * unit_price)::numeric INTO v_total_amount\r\n    FROM jsonb_to_recordset(p_data->'items') \r\n    AS x(quantity numeric, unit_price numeric);\r\n    \r\n    -- Get account IDs\r\n    SELECT account_id INTO v_main_account_id\r\n    FROM accounts \r\n    WHERE business_id = v_business_id AND code = 'TRP';\r\n    \r\n    SELECT account_id INTO v_receivable_account_id\r\n    FROM accounts \r\n    WHERE business_id = v_business_id AND code = 'MOA';\r\n    \r\n    -- Create transaction\r\n    INSERT INTO transactions (\r\n        reference_no,\r\n        transaction_type,\r\n        transaction_date,\r\n        status,\r\n        total_amount,\r\n        paid_amount,\r\n        due_amount,\r\n        business_id,\r\n        metadata\r\n    ) VALUES (\r\n        p_data->>'return_invoice',\r\n        'SALE_RETURN',\r\n        v_return_date,\r\n        'PAID',\r\n        v_total_amount,\r\n        v_total_amount,\r\n        0,\r\n        v_business_id,\r\n        p_data\r\n    ) RETURNING transaction_id INTO v_transaction_id;\r\n    \r\n    -- Create transaction entries (reverse of sale entries)\r\n    INSERT INTO transaction_entries (\r\n        transaction_id,\r\n        account_id,\r\n        entry_type,\r\n        amount,\r\n        description\r\n    ) VALUES\r\n    (v_transaction_id, v_main_account_id, 'CREDIT', v_total_amount, 'Sale return credit'),\r\n    (v_transaction_id, v_receivable_account_id, 'DEBIT', v_total_amount, 'Sale return debit');\r\n    \r\n    -- Create sale return record\r\n    INSERT INTO sale_returns (\r\n        sale_id,\r\n        return_invoice,\r\n        return_date,\r\n        reason,\r\n        notes,\r\n        total_amount,\r\n        transaction_id,\r\n        business_id\r\n    ) VALUES (\r\n        v_sale_id,\r\n        p_data->>'return_invoice',\r\n        v_return_date,\r\n        p_data->>'reason',\r\n        p_data->>'notes',\r\n        v_total_amount,\r\n        v_transaction_id,\r\n        v_business_id\r\n    ) RETURNING return_id INTO v_return_id;\r\n    \r\n    -- Create return items and update inventory\r\n    FOR v_return_item IN \r\n        SELECT \r\n            x.*,\r\n            i.item_type\r\n        FROM jsonb_to_recordset(p_data->'items') \r\n        AS x(item_id uuid, original_item_id uuid, quantity numeric, unit_price numeric)\r\n        JOIN items i ON i.item_id = x.item_id\r\n    LOOP\r\n        -- Insert return item\r\n        INSERT INTO sale_return_items (\r\n            return_id,\r\n            sale_item_id,\r\n            quantity,\r\n            unit_price\r\n        ) VALUES (\r\n            v_return_id,\r\n            v_return_item.original_item_id,\r\n            v_return_item.quantity,\r\n            v_return_item.unit_price\r\n        );\r\n        \r\n        -- Update item inventory if it's a good\r\n        IF v_return_item.item_type = 'goods' THEN\r\n            UPDATE items\r\n            SET \r\n                stock_quantity = CASE \r\n                    WHEN inventory_enabled THEN stock_quantity + v_return_item.quantity \r\n                    ELSE stock_quantity \r\n                END,\r\n                stock_value = CASE \r\n                    WHEN inventory_enabled THEN stock_value + (v_return_item.quantity * v_return_item.unit_price)\r\n                    ELSE stock_value \r\n                END\r\n            WHERE item_id = v_return_item.item_id;\r\n        END IF;\r\n    END LOOP;\r\n    \r\n    -- Create refund payment\r\n    INSERT INTO payments (\r\n        transaction_id,\r\n        payment_date,\r\n        amount,\r\n        payment_method,\r\n        reference_no,\r\n        created_by\r\n    ) VALUES (\r\n        v_transaction_id,\r\n        v_return_date,\r\n        v_total_amount,\r\n        'CASH',  -- You might want to make this configurable\r\n        p_data->>'return_invoice',\r\n        auth.uid()\r\n    );\r\n    \r\n    -- Update sale due amount\r\n    UPDATE sales \r\n    SET due_amount = due_amount - v_total_amount\r\n    WHERE sale_id = v_sale_id;\r\n    \r\n    -- Update customer due amount\r\n    UPDATE business_customers \r\n    SET due = due - v_total_amount\r\n    WHERE business_id = v_business_id \r\n    AND customer_id = v_customer_id;\r\n\r\n\tPERFORM nextval(v_business_id::text || '_sale_return_code');\r\n    \r\nEXCEPTION\r\n    WHEN others THEN\r\n        RAISE EXCEPTION 'Error in create_sale_return: %', SQLERRM;\r\nEND;\r\n$function$","CREATE OR REPLACE FUNCTION public.create_sequences(business_id uuid)\r\n RETURNS void\r\n LANGUAGE plpgsql\r\nAS $function$\r\nDECLARE\r\n    v_base_name text;\r\nBEGIN\r\n    v_base_name := business_id::text;\r\n    \r\n    -- Create sequences for various business documents\r\n    EXECUTE format('CREATE SEQUENCE IF NOT EXISTS %I START 1', v_base_name || '_purchase_invoice');\r\n    EXECUTE format('CREATE SEQUENCE IF NOT EXISTS %I START 1', v_base_name || '_sale_invoice');\r\n    EXECUTE format('CREATE SEQUENCE IF NOT EXISTS %I START 1', v_base_name || '_purchase_return_code');\r\n    EXECUTE format('CREATE SEQUENCE IF NOT EXISTS %I START 1', v_base_name || '_sale_return_code');\r\n    EXECUTE format('CREATE SEQUENCE IF NOT EXISTS %I START 1', v_base_name || '_item_code');\r\n    EXECUTE format('CREATE SEQUENCE IF NOT EXISTS %I START 1', v_base_name || '_employee_code');\r\nEND;\r\n$function$","create or replace view \\"public\\".\\"customer_view\\" as  SELECT c.customer_id,\r\n    c.name,\r\n    u.email,\r\n    u.phone,\r\n    c.image\r\n   FROM (customers c\r\n     JOIN users u ON ((c.customer_id = u.user_id)))","create or replace view \\"public\\".\\"daily_transactions_report\\" as  WITH RECURSIVE dates AS (\r\n         SELECT min(payments.payment_date) AS date,\r\n            max(payments.payment_date) AS max_date\r\n           FROM payments\r\n          WHERE (payments.payment_date IS NOT NULL)\r\n        UNION ALL\r\n         SELECT (dates.date + '1 day'::interval) AS timestamptz,\r\n            dates.max_date\r\n           FROM dates\r\n          WHERE ((dates.date + '1 day'::interval) <= dates.max_date)\r\n        ), daily_payments AS (\r\n         SELECT p.payment_date AS date,\r\n            COALESCE(\r\n                CASE\r\n                    WHEN (s.sale_id IS NOT NULL) THEN bc.name\r\n                    WHEN (sr.return_id IS NOT NULL) THEN bc_return.name\r\n                    WHEN (pur.purchase_id IS NOT NULL) THEN sup.name\r\n                    WHEN (pr.return_id IS NOT NULL) THEN sup_return.name\r\n                    WHEN (inc.income_id IS NOT NULL) THEN 'Income'::text\r\n                    WHEN (exp.expense_id IS NOT NULL) THEN 'Expense'::text\r\n                    ELSE 'Other'::text\r\n                END, 'Walk-in Customer'::text) AS name,\r\n                CASE\r\n                    WHEN (s.sale_id IS NOT NULL) THEN 'Sale Payment'::text\r\n                    WHEN (sr.return_id IS NOT NULL) THEN 'Sale Return'::text\r\n                    WHEN (pur.purchase_id IS NOT NULL) THEN 'Purchase Payment'::text\r\n                    WHEN (pr.return_id IS NOT NULL) THEN 'Purchase Return'::text\r\n                    WHEN (inc.income_id IS NOT NULL) THEN ('Income - '::text || COALESCE(ic.name, 'Other'::text))\r\n                    WHEN (exp.expense_id IS NOT NULL) THEN ('Expense - '::text || COALESCE(ec.name, 'Other'::text))\r\n                    ELSE (t.transaction_type)::text\r\n                END AS type,\r\n            t.total_amount AS total,\r\n                CASE\r\n                    WHEN ((s.sale_id IS NOT NULL) OR (inc.income_id IS NOT NULL) OR (pr.return_id IS NOT NULL)) THEN p.amount\r\n                    ELSE NULL::numeric\r\n                END AS payment_in,\r\n                CASE\r\n                    WHEN ((pur.purchase_id IS NOT NULL) OR (exp.expense_id IS NOT NULL) OR (sr.return_id IS NOT NULL)) THEN p.amount\r\n                    ELSE NULL::numeric\r\n                END AS payment_out,\r\n            p.payment_method,\r\n            t.transaction_id,\r\n            COALESCE(s.business_id, sr.business_id, pur.business_id, pr.business_id, inc.business_id, exp.business_id) AS business_id,\r\n            p.payment_id,\r\n            p.reference_no,\r\n                CASE\r\n                    WHEN (s.sale_id IS NOT NULL) THEN 'sale'::text\r\n                    WHEN (sr.return_id IS NOT NULL) THEN 'sale_return'::text\r\n                    WHEN (pur.purchase_id IS NOT NULL) THEN 'purchase'::text\r\n                    WHEN (pr.return_id IS NOT NULL) THEN 'purchase_return'::text\r\n                    WHEN (inc.income_id IS NOT NULL) THEN 'income'::text\r\n                    WHEN (exp.expense_id IS NOT NULL) THEN 'expense'::text\r\n                    ELSE 'other'::text\r\n                END AS transaction_category\r\n           FROM (((((((((((((((payments p\r\n             JOIN transactions t ON ((t.transaction_id = p.transaction_id)))\r\n             LEFT JOIN sales s ON ((s.transaction_id = t.transaction_id)))\r\n             LEFT JOIN business_customers bc ON (((bc.customer_id = s.customer_id) AND (bc.business_id = s.business_id))))\r\n             LEFT JOIN sale_returns sr ON ((sr.transaction_id = t.transaction_id)))\r\n             LEFT JOIN sales s_return ON ((s_return.sale_id = sr.sale_id)))\r\n             LEFT JOIN business_customers bc_return ON (((bc_return.customer_id = s_return.customer_id) AND (bc_return.business_id = sr.business_id))))\r\n             LEFT JOIN purchases pur ON ((pur.transaction_id = t.transaction_id)))\r\n             LEFT JOIN suppliers sup ON ((sup.supplier_id = pur.supplier_id)))\r\n             LEFT JOIN purchase_returns pr ON ((pr.transaction_id = t.transaction_id)))\r\n             LEFT JOIN purchases p_return ON ((p_return.purchase_id = pr.purchase_id)))\r\n             LEFT JOIN suppliers sup_return ON ((sup_return.supplier_id = p_return.supplier_id)))\r\n             LEFT JOIN incomes inc ON ((inc.transaction_id = t.transaction_id)))\r\n             LEFT JOIN income_categories ic ON ((ic.category_id = inc.income_category_id)))\r\n             LEFT JOIN expenses exp ON ((exp.transaction_id = t.transaction_id)))\r\n             LEFT JOIN expense_categories ec ON ((ec.category_id = exp.expense_category_id)))\r\n          WHERE (p.payment_date IS NOT NULL)\r\n        ), running_balance AS (\r\n         SELECT dp.date,\r\n            dp.name,\r\n            dp.type,\r\n            dp.total,\r\n            dp.payment_in,\r\n            dp.payment_out,\r\n            dp.payment_method,\r\n            dp.reference_no,\r\n            dp.transaction_category,\r\n            dp.business_id,\r\n            dp.payment_id,\r\n            dp.transaction_id,\r\n            sum((COALESCE(dp.payment_in, (0)::numeric) - COALESCE(dp.payment_out, (0)::numeric))) OVER (PARTITION BY dp.business_id ORDER BY dp.date, dp.payment_id) AS balance\r\n           FROM daily_payments dp\r\n          WHERE (dp.date IS NOT NULL)\r\n        )\r\n SELECT running_balance.date,\r\n    running_balance.name,\r\n    running_balance.type,\r\n    running_balance.total,\r\n    running_balance.payment_in,\r\n    running_balance.payment_out,\r\n    running_balance.payment_method,\r\n    running_balance.reference_no,\r\n    running_balance.transaction_category,\r\n    running_balance.business_id,\r\n    running_balance.payment_id,\r\n    running_balance.transaction_id,\r\n    running_balance.balance\r\n   FROM running_balance\r\n  WHERE (running_balance.business_id IS NOT NULL)\r\n  ORDER BY running_balance.date, running_balance.transaction_id, running_balance.payment_id","CREATE OR REPLACE FUNCTION public.delete_stock_adjustment(p_adjustment_id uuid)\r\n RETURNS void\r\n LANGUAGE plpgsql\r\nAS $function$\r\nDECLARE\r\n    v_transaction_id UUID;\r\n    v_business_id UUID;\r\n    v_adjustment_items RECORD;\r\nBEGIN\r\n    -- Get transaction_id and business_id\r\n    SELECT transaction_id, business_id \r\n    INTO v_transaction_id, v_business_id\r\n    FROM stock_adjustments \r\n    WHERE adjustment_id = p_adjustment_id;\r\n\r\n    -- Revert item quantities and values\r\n    FOR v_adjustment_items IN \r\n        SELECT \r\n            sai.item_id,\r\n            sai.previous_quantity,\r\n            sai.quantity_adjusted,\r\n            i.purchase_price\r\n        FROM stock_adjustment_items sai\r\n        JOIN items i ON i.item_id = sai.item_id\r\n        WHERE sai.adjustment_id = p_adjustment_id\r\n    LOOP\r\n        UPDATE items \r\n        SET \r\n            stock_quantity = v_adjustment_items.previous_quantity,\r\n            stock_value = stock_value - (v_adjustment_items.quantity_adjusted * v_adjustment_items.purchase_price)\r\n        WHERE item_id = v_adjustment_items.item_id;\r\n    END LOOP;\r\n\r\n    -- Delete stock adjustment items\r\n    DELETE FROM stock_adjustment_items \r\n    WHERE adjustment_id = p_adjustment_id;\r\n\r\n    -- Delete stock adjustment\r\n    DELETE FROM stock_adjustments \r\n    WHERE adjustment_id = p_adjustment_id;\r\n\r\n    -- Delete transaction entries\r\n    DELETE FROM transaction_entries \r\n    WHERE transaction_id = v_transaction_id;\r\n\r\n    -- Delete transaction\r\n    DELETE FROM transactions \r\n    WHERE transaction_id = v_transaction_id;\r\nEND;\r\n$function$","create or replace view \\"public\\".\\"employee_branches_view\\" as  SELECT e.employee_id,\r\n    e.business_id,\r\n    b.name\r\n   FROM (employee_branch_access e\r\n     JOIN businesses b ON ((e.business_id = b.business_id)))","create or replace view \\"public\\".\\"employee_view\\" as  WITH user_props AS (\r\n         SELECT (replace((((auth.jwt() -> 'user_metadata'::text) -> 'business_id'::text))::text, '\\"'::text, ''::text))::uuid AS business_id\r\n        )\r\n SELECT e.employee_id,\r\n    e.code,\r\n    e.org_id,\r\n    COALESCE(NULLIF(TRIM(BOTH FROM e.name), ''::text), u.name) AS name,\r\n    u.email,\r\n    u.phone,\r\n    e.role,\r\n    e.image,\r\n    e.created_at,\r\n    COALESCE(array_agg(DISTINCT eba.business_id) FILTER (WHERE (eba.business_id IS NOT NULL)), ARRAY[]::uuid[]) AS business_ids,\r\n    COALESCE(array_agg(DISTINCT roe.employee_role_id) FILTER (WHERE (roe.employee_role_id IS NOT NULL)), ARRAY[]::uuid[]) AS employee_role_ids,\r\n    COALESCE(( SELECT json_agg(t.distinct_roles) AS json_agg\r\n           FROM ( SELECT json_build_object('role_id', er_1.employee_role_id, 'role_name', er_1.name, 'business_id', er_1.business_id) AS distinct_roles\r\n                   FROM ( SELECT DISTINCT employee_roles.employee_role_id,\r\n                            employee_roles.name,\r\n                            employee_roles.business_id\r\n                           FROM employee_roles\r\n                          WHERE ((employee_roles.business_id = up.business_id) AND (employee_roles.employee_role_id = ANY (array_agg(roe.employee_role_id))))) er_1) t), '[]'::json) AS employee_roles,\r\n    up.business_id\r\n   FROM (((((employees e\r\n     JOIN users u ON ((e.employee_id = u.user_id)))\r\n     LEFT JOIN employee_branch_access eba ON ((e.employee_id = eba.employee_id)))\r\n     LEFT JOIN roles_of_employees roe ON ((e.employee_id = roe.employee_id)))\r\n     LEFT JOIN employee_roles er ON ((roe.employee_role_id = er.employee_role_id)))\r\n     CROSS JOIN user_props up)\r\n  GROUP BY e.employee_id, e.code, e.org_id, u.name, u.email, u.phone, e.role, u.image, e.created_at, up.business_id","CREATE OR REPLACE FUNCTION public.generate_business_dependencies(business_data jsonb)\r\n RETURNS uuid\r\n LANGUAGE plpgsql\r\nAS $function$\r\nDECLARE\r\n    v_auth_user_id UUID := auth.uid();  -- Get the authenticated user ID\r\n    v_org_id UUID;\r\n\tv_existing_user_id UUID;\r\n    v_business_id UUID;\r\nBEGIN\r\n\r\n\tv_org_id := (business_data->>'org_id')::uuid;\r\n    -- 4. Insert into businesses\r\n    INSERT INTO public.businesses (\r\n        name,\r\n        org_id,\r\n        created_by,\r\n        business_type,\r\n        currency\r\n    ) VALUES (\r\n        business_data->>'name',\r\n        v_org_id,\r\n        v_auth_user_id,\r\n        (business_data->>'business_type')::public.business_types,\r\n        business_data->'currency'\r\n    ) RETURNING business_id INTO v_business_id;\r\n\r\n    -- Add default sale statuses\r\n    INSERT INTO public.statuses (\r\n        business_id,\r\n        name,\r\n        sequence_order,\r\n        is_default,\r\n        type,\r\n\t\tis_editable\r\n    ) VALUES \r\n    (v_business_id, 'Booked', 1, true, 'sale'::status_type, true),\r\n    (v_business_id, 'In Process', 2, false, 'sale'::status_type, true),\r\n    (v_business_id, 'Cancelled', 3, false, 'sale'::status_type, false),\r\n    (v_business_id, 'Completed', 4, false, 'sale'::status_type, false);\r\n\r\n    -- 5. Create the default Account Categories and Chart of Accounts\r\n    --    The block for inserting into account_categories has been removed from here.\r\n    PERFORM public.create_default_chart_of_accounts(v_business_id, v_org_id);\r\n\r\n    -- 4. Insert into branch accesses\r\n    INSERT INTO public.employee_branch_access (\r\n        employee_id,\r\n        business_id\r\n    ) VALUES (\r\n        v_auth_user_id,\r\n        v_business_id\r\n    );\r\n\r\n\tRETURN v_business_id;\r\nEXCEPTION\r\n    WHEN OTHERS THEN\r\n        RAISE EXCEPTION '%', SQLERRM;\r\nEND;\r\n$function$","CREATE OR REPLACE FUNCTION public.get_business_summaries(p_business_id uuid)\r\n RETURNS json\r\n LANGUAGE plpgsql\r\n SECURITY DEFINER\r\nAS $function$\r\nDECLARE\r\n    v_total_sales NUMERIC;\r\n    v_total_purchases NUMERIC;\r\n    v_total_received_sales NUMERIC;\r\n    v_total_customer_dues NUMERIC;\r\n    v_total_supplier_dues NUMERIC;\r\nBEGIN\r\n    -- Get total sales\r\n    SELECT COALESCE(SUM(total_amount), 0)\r\n    INTO v_total_sales\r\n    FROM sales\r\n    WHERE business_id = p_business_id\r\n    AND status_id NOT IN (\r\n        SELECT status_id \r\n        FROM statuses \r\n        WHERE name IN ('VOID', 'CANCELLED')\r\n    );\r\n\r\n    -- Get total purchases\r\n    SELECT COALESCE(SUM(total_amount), 0)\r\n    INTO v_total_purchases\r\n    FROM purchases\r\n    WHERE business_id = p_business_id;\r\n\r\n    -- Get total received payments from sales\r\n    SELECT COALESCE(SUM(paid_amount), 0)\r\n    INTO v_total_received_sales\r\n    FROM sales\r\n    WHERE business_id = p_business_id\r\n    AND status_id NOT IN (\r\n        SELECT status_id \r\n        FROM statuses \r\n        WHERE name IN ('VOID', 'CANCELLED')\r\n    );\r\n\r\n    -- Get total customer dues (using customer_balance)\r\n    SELECT COALESCE(SUM(customer_balance), 0)\r\n    INTO v_total_customer_dues\r\n    FROM business_customers\r\n    WHERE business_id = p_business_id;\r\n\r\n    -- Get total supplier dues (using supplier_balance)\r\n    SELECT COALESCE(SUM(supplier_balance), 0)\r\n    INTO v_total_supplier_dues\r\n    FROM suppliers\r\n    WHERE business_id = p_business_id;\r\n\r\n    -- Return JSON object\r\n    RETURN json_build_object(\r\n        'total_sales', v_total_sales,\r\n        'total_purchases', v_total_purchases,\r\n        'total_received_sales', v_total_received_sales,\r\n        'total_customer_dues', v_total_customer_dues,\r\n        'total_supplier_dues', v_total_supplier_dues\r\n    );\r\nEND;\r\n$function$","CREATE OR REPLACE FUNCTION public.get_chart_of_accounts_tree(p_business_id uuid)\r\n RETURNS jsonb\r\n LANGUAGE plpgsql\r\n STABLE\r\nAS $function$\r\nDECLARE\r\n    v_result jsonb;\r\nBEGIN\r\n    SELECT jsonb_agg(category_obj ORDER BY category_code) -- Order categories by code\r\n    INTO v_result\r\n    FROM (\r\n        SELECT\r\n            jsonb_build_object(\r\n                'category_id', ac.category_id,\r\n                'name', ac.name,\r\n                'code', ac.code,\r\n                'description', ac.description,\r\n                'children', COALESCE(\r\n                    ( -- Subquery to aggregate top-level accounts/groups for this category\r\n                        SELECT jsonb_agg(node ORDER BY account_code)\r\n                        FROM (\r\n                            SELECT\r\n                                public.build_account_node(a.account_id, p_business_id) as node,\r\n                                a.code as account_code\r\n                            FROM public.accounts a\r\n                            WHERE a.business_id = p_business_id\r\n                              AND a.category_id = ac.category_id\r\n                              AND a.parent_account_id IS NULL -- Start with top-level items in the category\r\n                        ) AS top_level_accounts\r\n                        WHERE node IS NOT NULL\r\n                    ),\r\n                    '[]'::jsonb -- Default to empty array if no top-level accounts/groups\r\n                )\r\n            ) AS category_obj,\r\n            ac.code AS category_code\r\n        FROM public.account_categories ac\r\n        WHERE ac.business_id = p_business_id\r\n    ) AS categories_subquery;\r\n\r\n    -- If no categories found for the business, return an empty array\r\n    IF v_result IS NULL THEN\r\n        RETURN '[]'::jsonb;\r\n    END IF;\r\n\r\n    RETURN v_result;\r\nEND;\r\n$function$","CREATE OR REPLACE FUNCTION public.get_current_fiscal_period(p_business_id uuid)\r\n RETURNS jsonb\r\n LANGUAGE plpgsql\r\nAS $function$\r\nDECLARE\r\n    v_start_month INT;\r\n    v_end_month INT;\r\n    v_current_date DATE := NOW()::DATE;\r\n    v_current_year INT := EXTRACT(YEAR FROM v_current_date);\r\n    v_current_month INT := EXTRACT(MONTH FROM v_current_date);\r\n    v_fiscal_start_year INT;\r\n    v_fiscal_end_year INT;\r\n    v_start_date DATE;\r\n    v_end_date DATE;\r\nBEGIN\r\n    -- Get fiscal year details for the business\r\n    SELECT fy.start_month, fy.end_month\r\n    INTO v_start_month, v_end_month\r\n    FROM public.businesses b\r\n    JOIN public.fiscal_years fy ON b.fiscal_id = fy.fiscal_id\r\n    WHERE b.business_id = p_business_id;\r\n\r\n    IF v_start_month IS NULL THEN\r\n        -- Handle case where business or fiscal year is not found or not set\r\n        -- Defaulting to standard calendar year (Jan - Dec)\r\n        v_start_month := 1;\r\n        v_end_month := 12;\r\n        -- Optionally, you could raise an exception or return NULL\r\n        -- RETURN NULL;\r\n        -- RAISE EXCEPTION 'Fiscal year not set for business_id %', p_business_id;\r\n    END IF;\r\n\r\n    -- Determine the start year of the current fiscal period\r\n    IF v_current_month < v_start_month THEN\r\n        v_fiscal_start_year := v_current_year - 1;\r\n    ELSE\r\n        v_fiscal_start_year := v_current_year;\r\n    END IF;\r\n\r\n    -- Determine the end year of the current fiscal period\r\n    IF v_end_month < v_start_month THEN\r\n        v_fiscal_end_year := v_fiscal_start_year + 1;\r\n    ELSE\r\n        v_fiscal_end_year := v_fiscal_start_year;\r\n    END IF;\r\n\r\n    -- Calculate the start date\r\n    v_start_date := MAKE_DATE(v_fiscal_start_year, v_start_month, 1);\r\n\r\n    -- Calculate the end date (last day of the end month)\r\n    v_end_date := (DATE_TRUNC('MONTH', MAKE_DATE(v_fiscal_end_year, v_end_month, 1)) + INTERVAL '1 MONTH' - INTERVAL '1 DAY')::DATE;\r\n\r\n    -- Construct JSON result\r\n    RETURN jsonb_build_object(\r\n        'start_date', v_start_date,\r\n        'end_date', v_end_date\r\n    );\r\nEXCEPTION\r\n    WHEN NO_DATA_FOUND THEN\r\n         -- Handle case where business or fiscal year is not found\r\n         -- Defaulting to standard calendar year (Jan - Dec) or return NULL/error\r\n         RETURN jsonb_build_object(\r\n            'start_date', MAKE_DATE(EXTRACT(YEAR FROM NOW())::INT, 1, 1),\r\n            'end_date', MAKE_DATE(EXTRACT(YEAR FROM NOW())::INT, 12, 31)\r\n         );\r\n         -- RETURN NULL;\r\n    WHEN OTHERS THEN\r\n        -- Log error or handle other exceptions\r\n        RAISE NOTICE 'Error in get_current_fiscal_period for business %: %', p_business_id, SQLERRM;\r\n        RETURN NULL; -- Or re-raise the exception\r\nEND;\r\n$function$","CREATE OR REPLACE FUNCTION public.get_dashboard_data(p_business_id uuid)\r\n RETURNS json\r\n LANGUAGE plpgsql\r\n SECURITY DEFINER\r\nAS $function$\r\nDECLARE\r\n    v_result JSON;\r\n    v_fiscal_year_start DATE;\r\n    v_fiscal_year_end DATE;\r\nBEGIN\r\n    -- Get fiscal year dates\r\n    v_fiscal_year_start := DATE_TRUNC('year', CURRENT_DATE);\r\n    v_fiscal_year_end := (v_fiscal_year_start + INTERVAL '1 year' - INTERVAL '1 day')::DATE;\r\n\r\n    WITH daily_sales AS (\r\n        -- Calculate today's sales\r\n        SELECT COALESCE(SUM(total_amount), 0) as amount\r\n        FROM sales\r\n        WHERE business_id = p_business_id\r\n        AND DATE(sale_date) = CURRENT_DATE\r\n    ),\r\n    yearly_income AS (\r\n        -- Calculate total income for current fiscal year\r\n        SELECT COALESCE(SUM(total_amount), 0) as amount\r\n        FROM sales\r\n        WHERE business_id = p_business_id\r\n        AND sale_date BETWEEN v_fiscal_year_start AND v_fiscal_year_end\r\n    ),\r\n    yearly_expenses AS (\r\n        -- Calculate total expenses for current fiscal year\r\n        SELECT COALESCE(SUM(total_amount), 0) as amount\r\n        FROM purchases\r\n        WHERE business_id = p_business_id\r\n        AND purchase_date BETWEEN v_fiscal_year_start AND v_fiscal_year_end\r\n    ),\r\n    new_customers AS (\r\n        -- Count new customers in last 30 days\r\n        SELECT COUNT(*) as count\r\n        FROM business_customers\r\n        WHERE business_id = p_business_id\r\n        AND created_at >= (CURRENT_DATE - INTERVAL '30 days')\r\n    ),\r\n    top_selling_items AS (\r\n        -- Get top 5 selling items\r\n        SELECT \r\n            i.name,\r\n            COALESCE(SUM(si.quantity), 0) as sold_count\r\n        FROM sale_items si\r\n        JOIN items i ON i.item_id = si.item_id\r\n        JOIN sales s ON s.sale_id = si.sale_id\r\n        WHERE s.business_id = p_business_id\r\n        AND s.sale_date >= (CURRENT_DATE - INTERVAL '30 days')\r\n        GROUP BY i.name\r\n        ORDER BY sold_count DESC\r\n        LIMIT 5\r\n    ),\r\n    low_stock_items AS (\r\n        -- Get items with low stock\r\n        SELECT \r\n            name,\r\n            stock_quantity as stock_left\r\n        FROM items\r\n        WHERE business_id = p_business_id\r\n        AND stock_quantity <= alert_quantity\r\n        ORDER BY stock_quantity ASC\r\n        LIMIT 5\r\n    ),\r\n    category_stats AS (\r\n        -- Calculate item category statistics\r\n        WITH total_sales AS (\r\n            SELECT COALESCE(SUM(si.quantity * si.unit_price), 0) as total_amount\r\n            FROM sale_items si\r\n            JOIN sales s ON s.sale_id = si.sale_id\r\n            WHERE s.business_id = p_business_id\r\n            AND s.sale_date >= (CURRENT_DATE - INTERVAL '30 days')\r\n        )\r\n        SELECT \r\n            c.icon_info as icon_info,\r\n            c.name as category_name,\r\n            ROUND(\r\n                (SUM(si.quantity * si.unit_price) * 100.0 / NULLIF((SELECT total_amount FROM total_sales), 0))::numeric, \r\n                2\r\n            ) as percentage\r\n        FROM sale_items si\r\n        JOIN sales s ON s.sale_id = si.sale_id\r\n        JOIN items i ON i.item_id = si.item_id\r\n        JOIN item_categories c ON c.item_category_id = i.item_category_id\r\n        WHERE s.business_id = p_business_id\r\n        AND s.sale_date >= (CURRENT_DATE - INTERVAL '30 days')\r\n        GROUP BY c.name, c.icon_info\r\n        ORDER BY percentage DESC\r\n        LIMIT 5\r\n    )\r\n    SELECT json_build_object(\r\n        'daily_sales', (SELECT amount FROM daily_sales),\r\n        'total_incomes_current_fiscal_year', (SELECT amount FROM yearly_income),\r\n        'total_expenses_current_fiscal_year', (SELECT amount FROM yearly_expenses),\r\n        'new_customers_past_30_days', (SELECT count FROM new_customers),\r\n        'top_selling_items', (\r\n            SELECT json_agg(\r\n                json_build_object(\r\n                    'name', name,\r\n                    'sold_count', sold_count\r\n                )\r\n            )\r\n            FROM top_selling_items\r\n        ),\r\n        'low_stock_items', (\r\n            SELECT json_agg(\r\n                json_build_object(\r\n                    'name', name,\r\n                    'stock_left', stock_left\r\n                )\r\n            )\r\n            FROM low_stock_items\r\n        ),\r\n        'item_category_statistics', (\r\n            SELECT json_agg(\r\n                json_build_object(\r\n                    'icon_info', icon_info,\r\n                    'category_name', category_name,\r\n                    'percentage', percentage\r\n                )\r\n            )\r\n            FROM category_stats\r\n        )\r\n    ) INTO v_result;\r\n\r\n    RETURN v_result;\r\nEND;\r\n$function$","CREATE OR REPLACE FUNCTION public.get_employee_sales_report(start_date timestamp with time zone DEFAULT NULL::timestamp with time zone, end_date timestamp with time zone DEFAULT NULL::timestamp with time zone, page_number integer DEFAULT 1, page_size integer DEFAULT 10, p_business_id uuid DEFAULT NULL::uuid, employee_name_filter text DEFAULT NULL::text)\r\n RETURNS TABLE(employee_name text, employee_role employee_type, employee_code text, total_items_sold numeric, total_revenue_generated numeric)\r\n LANGUAGE plpgsql\r\nAS $function$\r\nDECLARE\r\n    offset_value integer;\r\nBEGIN\r\n    -- Calculate the offset for pagination\r\n    offset_value := (page_number - 1) * page_size;\r\n\r\n    -- Ensure page_number and page_size are not negative and page_size is not zero\r\n    IF page_number < 1 THEN\r\n        page_number := 1; -- Default to first page if page_number is invalid\r\n    END IF;\r\n    IF page_size < 1 THEN\r\n        page_size := 10; -- Default to 10 items per page if page_size is invalid\r\n    END IF;\r\n\r\n    RETURN QUERY\r\n    SELECT\r\n        ev.name AS employee_name,\r\n        ev.role AS employee_role,\r\n        ev.code AS employee_code,\r\n        COALESCE(SUM(si.quantity), 0) AS total_items_sold,\r\n        COALESCE(SUM(s.total_amount), 0) AS total_revenue_generated\r\n    FROM\r\n        employee_view ev\r\n    LEFT JOIN\r\n        sales s ON s.created_by = ev.employee_id AND s.business_id = p_business_id\r\n    LEFT JOIN\r\n        sale_items si ON si.sale_id = s.sale_id\r\n    WHERE\r\n        (start_date IS NULL OR s.sale_date >= start_date)\r\n        AND (end_date IS NULL OR s.sale_date <= end_date)\r\n        AND (p_business_id IS NULL OR s.business_id = p_business_id)\r\n        AND (employee_name_filter IS NULL OR ev.name ILIKE '%' || employee_name_filter || '%') -- Added employee name filter\r\n    GROUP BY\r\n        ev.employee_id,\r\n        ev.name,\r\n        ev.role,\r\n        ev.code\r\n    ORDER BY\r\n        total_revenue_generated DESC\r\n    LIMIT page_size\r\n    OFFSET offset_value;\r\n\r\nEND;\r\n$function$","CREATE OR REPLACE FUNCTION public.get_next_item_code(business_id uuid)\r\n RETURNS text\r\n LANGUAGE plpgsql\r\nAS $function$\r\nDECLARE\r\n    v_base_name text;\r\n    next_value text;\r\n    formatted_value text;\r\n    sequence_exists boolean;\r\nBEGIN\r\n    v_base_name := business_id::text;\r\n    \r\n    -- Check if sequence exists\r\n    SELECT EXISTS (\r\n        SELECT 1 \r\n        FROM pg_sequences \r\n        WHERE schemaname = 'public' \r\n        AND sequencename = v_base_name || '_item_code'\r\n    ) INTO sequence_exists;\r\n    \r\n    -- Create sequence if it doesn't exist\r\n    IF NOT sequence_exists THEN\r\n        EXECUTE format('CREATE SEQUENCE IF NOT EXISTS public.%I START 1', v_base_name || '_item_code');\r\n    END IF;\r\n    \r\n    -- Get the next value of the item_code sequence without incrementing\r\n        EXECUTE format('SELECT LPAD(CASE \r\n             \t\t\t\tWHEN is_called THEN (last_value + 1)::text \r\n             \t\t\t\tELSE last_value::text \r\n           \t\t\t\tEND, 6, ''0'') \r\n\t\t\t\t\tFROM %I', v_base_name || '_item_code') INTO next_value;\r\n    \r\n    -- Format the value with prefix\r\n    formatted_value := 'ITEM-' || next_value;\r\n    \r\n    RETURN formatted_value;\r\nEND;\r\n$function$","CREATE OR REPLACE FUNCTION public.get_next_purchase_code(business_id uuid)\r\n RETURNS text\r\n LANGUAGE plpgsql\r\nAS $function$\r\nDECLARE\r\n    v_base_name text;\r\n    next_value text;\r\n    formatted_value text;\r\n    sequence_exists boolean;\r\nBEGIN\r\n    v_base_name := business_id::text;\r\n    \r\n    -- Check if sequence exists\r\n    SELECT EXISTS (\r\n        SELECT 1 \r\n        FROM pg_sequences \r\n        WHERE schemaname = 'public' \r\n        AND sequencename = v_base_name || '_purchase_invoice'\r\n    ) INTO sequence_exists;\r\n    \r\n    -- Create sequence if it doesn't exist\r\n    IF NOT sequence_exists THEN\r\n        EXECUTE format('CREATE SEQUENCE IF NOT EXISTS public.%I START 1', v_base_name || '_purchase_invoice');\r\n    END IF;\r\n    \r\n    -- Get the next value of the item_code sequence without incrementing\r\n        EXECUTE format('SELECT LPAD(CASE \r\n             \t\t\t\tWHEN is_called THEN (last_value + 1)::text \r\n             \t\t\t\tELSE last_value::text \r\n           \t\t\t\tEND, 6, ''0'') \r\n\t\t\t\t\tFROM %I', v_base_name || '_purchase_invoice') INTO next_value;\r\n    \r\n    -- Format the value with prefix\r\n    formatted_value := 'PURCHASE-' || next_value;\r\n    \r\n    RETURN formatted_value;\r\nEND;\r\n$function$","CREATE OR REPLACE FUNCTION public.get_next_purchase_return_code(business_id uuid)\r\n RETURNS text\r\n LANGUAGE plpgsql\r\nAS $function$\r\nDECLARE\r\n    v_base_name text;\r\n    next_value text;\r\n    formatted_value text;\r\n    sequence_exists boolean;\r\nBEGIN\r\n    v_base_name := business_id::text;\r\n    \r\n    -- Check if sequence exists\r\n    SELECT EXISTS (\r\n        SELECT 1 \r\n        FROM pg_sequences \r\n        WHERE schemaname = 'public' \r\n        AND sequencename = v_base_name || '_purchase_return_code'\r\n    ) INTO sequence_exists;\r\n    \r\n    -- Create sequence if it doesn't exist\r\n    IF NOT sequence_exists THEN\r\n        EXECUTE format('CREATE SEQUENCE IF NOT EXISTS public.%I START 1', v_base_name || '_purchase_return_code');\r\n    END IF;\r\n    \r\n    -- Get the next value of the item_code sequence without incrementing\r\n        EXECUTE format('SELECT LPAD(CASE \r\n             \t\t\t\tWHEN is_called THEN (last_value + 1)::text \r\n             \t\t\t\tELSE last_value::text \r\n           \t\t\t\tEND, 6, ''0'') \r\n\t\t\t\t\tFROM %I', v_base_name || '_purchase_return_code') INTO next_value;\r\n    \r\n    -- Format the value with prefix\r\n    formatted_value := 'PURCHASE-RETURN-' || next_value;\r\n    \r\n    RETURN formatted_value;\r\nEND;\r\n$function$","CREATE OR REPLACE FUNCTION public.get_next_sale_code(business_id uuid)\r\n RETURNS text\r\n LANGUAGE plpgsql\r\nAS $function$\r\nDECLARE\r\n    v_base_name text;\r\n    next_value text;\r\n    formatted_value text;\r\n    sequence_exists boolean;\r\nBEGIN\r\n    v_base_name := business_id::text;\r\n    \r\n    -- Check if sequence exists\r\n    SELECT EXISTS (\r\n        SELECT 1 \r\n        FROM pg_sequences \r\n        WHERE schemaname = 'public' \r\n        AND sequencename = v_base_name || '_sale_invoice'\r\n    ) INTO sequence_exists;\r\n    \r\n    -- Create sequence if it doesn't exist\r\n    IF NOT sequence_exists THEN\r\n        EXECUTE format('CREATE SEQUENCE IF NOT EXISTS public.%I START 1', v_base_name || '_sale_invoice');\r\n    END IF;\r\n    \r\n    -- Get the next value of the item_code sequence without incrementing\r\n        EXECUTE format('SELECT LPAD(CASE \r\n             \t\t\t\tWHEN is_called THEN (last_value + 1)::text \r\n             \t\t\t\tELSE last_value::text \r\n           \t\t\t\tEND, 6, ''0'') \r\n\t\t\t\t\tFROM %I', v_base_name || '_sale_invoice') INTO next_value;\r\n    \r\n    -- Format the value with prefix\r\n    formatted_value := 'SALE-' || next_value;\r\n    \r\n    RETURN formatted_value;\r\nEND;\r\n$function$","CREATE OR REPLACE FUNCTION public.get_next_sale_return_code(business_id uuid)\r\n RETURNS text\r\n LANGUAGE plpgsql\r\nAS $function$\r\nDECLARE\r\n    v_base_name text;\r\n    next_value text;\r\n    formatted_value text;\r\n    sequence_exists boolean;\r\nBEGIN\r\n    v_base_name := business_id::text;\r\n    \r\n    -- Check if sequence exists\r\n    SELECT EXISTS (\r\n        SELECT 1 \r\n        FROM pg_sequences \r\n        WHERE schemaname = 'public' \r\n        AND sequencename = v_base_name || '_sale_return_code'\r\n    ) INTO sequence_exists;\r\n    \r\n    -- Create sequence if it doesn't exist\r\n    IF NOT sequence_exists THEN\r\n        EXECUTE format('CREATE SEQUENCE IF NOT EXISTS public.%I START 1', v_base_name || '_sale_return_code');\r\n    END IF;\r\n    \r\n    -- Get the next value of the item_code sequence without incrementing\r\n        EXECUTE format('SELECT LPAD(CASE \r\n             \t\t\t\tWHEN is_called THEN (last_value + 1)::text \r\n             \t\t\t\tELSE last_value::text \r\n           \t\t\t\tEND, 6, ''0'') \r\n\t\t\t\t\tFROM %I', v_base_name || '_sale_return_code') INTO next_value;\r\n    \r\n    -- Format the value with prefix\r\n    formatted_value := 'SALE-RETURN-' || next_value;\r\n    \r\n    RETURN formatted_value;\r\nEND;\r\n$function$","CREATE OR REPLACE FUNCTION public.get_or_create_brand(p_business_id uuid, p_brand_name text)\r\n RETURNS uuid\r\n LANGUAGE plpgsql\r\nAS $function$\r\nDECLARE\r\n    v_brand_id uuid;\r\n    v_org_id uuid;\r\nBEGIN\r\n     IF p_brand_name IS NULL OR trim(p_brand_name) = '' THEN\r\n        RETURN NULL;\r\n    END IF;\r\n\r\n    SELECT brand_id INTO v_brand_id\r\n    FROM public.brands\r\n    WHERE business_id = p_business_id AND lower(name) = lower(trim(p_brand_name));\r\n\r\n    IF v_brand_id IS NULL THEN\r\n        SELECT org_id INTO v_org_id FROM public.businesses WHERE business_id = p_business_id;\r\n        IF v_org_id IS NULL THEN RAISE EXCEPTION 'Cannot find org_id for business %', p_business_id; END IF;\r\n\r\n        INSERT INTO public.brands (name, business_id, org_id)\r\n        VALUES (trim(p_brand_name), p_business_id, v_org_id)\r\n        RETURNING brand_id INTO v_brand_id;\r\n    END IF;\r\n\r\n    RETURN v_brand_id;\r\nEND;\r\n$function$","CREATE OR REPLACE FUNCTION public.get_or_create_item_category(p_business_id uuid, p_category_name text)\r\n RETURNS uuid\r\n LANGUAGE plpgsql\r\nAS $function$\r\nDECLARE\r\n    v_category_id uuid;\r\n    v_org_id uuid;\r\nBEGIN\r\n    IF p_category_name IS NULL OR trim(p_category_name) = '' THEN\r\n        RETURN NULL; -- Return NULL if no name provided\r\n    END IF;\r\n\r\n    -- Find existing category by name (case-insensitive recommended)\r\n    SELECT item_category_id INTO v_category_id\r\n    FROM public.item_categories\r\n    WHERE business_id = p_business_id AND lower(name) = lower(trim(p_category_name));\r\n\r\n    -- If not found, create it\r\n    IF v_category_id IS NULL THEN\r\n        -- Need org_id to insert\r\n        SELECT org_id INTO v_org_id FROM public.businesses WHERE business_id = p_business_id;\r\n        IF v_org_id IS NULL THEN RAISE EXCEPTION 'Cannot find org_id for business %', p_business_id; END IF;\r\n\r\n        INSERT INTO public.item_categories (name, business_id, org_id)\r\n        VALUES (trim(p_category_name), p_business_id, v_org_id)\r\n        RETURNING item_category_id INTO v_category_id;\r\n    END IF;\r\n\r\n    RETURN v_category_id;\r\nEND;\r\n$function$","CREATE OR REPLACE FUNCTION public.get_or_create_unit(p_business_id uuid, p_unit_name text, p_unit_short_name text DEFAULT NULL::text)\r\n RETURNS uuid\r\n LANGUAGE plpgsql\r\nAS $function$\r\nDECLARE\r\n    v_unit_id uuid;\r\n    v_org_id uuid;\r\n    v_final_short_name text;\r\nBEGIN\r\n     IF p_unit_name IS NULL OR trim(p_unit_name) = '' THEN\r\n        RETURN NULL;\r\n    END IF;\r\n\r\n    SELECT unit_id INTO v_unit_id\r\n    FROM public.units\r\n    WHERE business_id = p_business_id AND lower(name) = lower(trim(p_unit_name));\r\n\r\n    IF v_unit_id IS NULL THEN\r\n        SELECT org_id INTO v_org_id FROM public.businesses WHERE business_id = p_business_id;\r\n        IF v_org_id IS NULL THEN RAISE EXCEPTION 'Cannot find org_id for business %', p_business_id; END IF;\r\n\r\n        -- Use provided short name or derive from long name\r\n        v_final_short_name := COALESCE(trim(p_unit_short_name), upper(substring(trim(p_unit_name) from 1 for 3)));\r\n\r\n        INSERT INTO public.units (name, short_name, business_id, org_id)\r\n        VALUES (trim(p_unit_name), v_final_short_name, p_business_id, v_org_id)\r\n        RETURNING unit_id INTO v_unit_id;\r\n    END IF;\r\n\r\n    RETURN v_unit_id;\r\nEND;\r\n$function$","CREATE OR REPLACE FUNCTION public.get_party_transaction_summary(party_type text, party_id uuid)\r\n RETURNS json\r\n LANGUAGE plpgsql\r\n SECURITY DEFINER\r\nAS $function$\r\nDECLARE\r\n    v_total NUMERIC;\r\n    v_total_paid NUMERIC;\r\n    v_total_due NUMERIC;\r\nBEGIN\r\n    -- Initialize variables\r\n    v_total := 0;\r\n    v_total_paid := 0;\r\n    v_total_due := 0;\r\n\r\n    -- Calculate summaries based on party type\r\n    IF party_type = 'customer' THEN\r\n        -- Get customer transaction summaries\r\n        SELECT \r\n            COALESCE(SUM(s.total_amount), 0),\r\n            COALESCE(SUM(s.paid_amount), 0),\r\n            COALESCE(SUM(s.due_amount), 0)\r\n        INTO v_total, v_total_paid, v_total_due\r\n        FROM sales s\r\n        WHERE s.customer_id = party_id\r\n        AND s.status_id NOT IN (\r\n            SELECT status_id \r\n            FROM statuses \r\n            WHERE name IN ('VOID', 'CANCELLED')\r\n        );\r\n\r\n        -- Get current due from business_customers\r\n        SELECT COALESCE(due, 0)\r\n        INTO v_total_due\r\n        FROM business_customers\r\n        WHERE customer_id = party_id;\r\n\r\n    ELSIF party_type = 'supplier' THEN\r\n        -- Get supplier transaction summaries\r\n        SELECT \r\n            COALESCE(SUM(p.total_amount), 0),\r\n            COALESCE(SUM(p.paid_amount), 0),\r\n            COALESCE(SUM(p.due_amount), 0)\r\n        INTO v_total, v_total_paid, v_total_due\r\n        FROM purchases p\r\n        WHERE p.supplier_id = party_id;\r\n\r\n        -- Get current due from suppliers\r\n        SELECT COALESCE(due, 0)\r\n        INTO v_total_due\r\n        FROM suppliers\r\n        WHERE supplier_id = party_id;\r\n\r\n    ELSE\r\n        RAISE EXCEPTION 'Invalid party type: %', party_type;\r\n    END IF;\r\n\r\n    -- Return JSON object\r\n    RETURN json_build_object(\r\n        'total', v_total,\r\n        'total_paid', v_total_paid,\r\n        'total_due', v_total_due\r\n    );\r\nEND;\r\n$function$","CREATE OR REPLACE FUNCTION public.get_profit_and_loss(p_business_id uuid, p_start_date date, p_end_date date)\r\n RETURNS jsonb\r\n LANGUAGE plpgsql\r\nAS $function$\r\nDECLARE\r\n    result jsonb;\r\n    v_total_sales NUMERIC := 0;\r\n    v_total_purchases NUMERIC := 0;\r\n    v_total_income_other NUMERIC := 0;\r\n    v_total_expenses NUMERIC := 0;\r\n    v_gross_profit NUMERIC := 0;\r\n    v_net_profit_loss NUMERIC := 0;\r\nBEGIN\r\n    -- Calculate Total Sales (Revenue)\r\n    SELECT COALESCE(SUM(total_amount), 0)\r\n    INTO v_total_sales\r\n    FROM public.transactions\r\n    WHERE business_id = p_business_id\r\n      AND transaction_type = 'SALE'\r\n      AND transaction_date BETWEEN p_start_date AND p_end_date\r\n      AND status <> 'VOID' AND status <> 'CANCELLED' AND status <> 'REVERSED';\r\n\r\n    -- Calculate Total Purchases (COGS)\r\n    SELECT COALESCE(SUM(total_amount), 0)\r\n    INTO v_total_purchases\r\n    FROM public.transactions\r\n    WHERE business_id = p_business_id\r\n      AND transaction_type = 'PURCHASE'\r\n      AND transaction_date BETWEEN p_start_date AND p_end_date\r\n      AND status <> 'VOID' AND status <> 'CANCELLED' AND status <> 'REVERSED';\r\n\r\n    -- Calculate Total Income (Other)\r\n    SELECT COALESCE(SUM(total_amount), 0)\r\n    INTO v_total_income_other\r\n    FROM public.transactions\r\n    WHERE business_id = p_business_id\r\n      AND transaction_type = 'INCOME'\r\n      AND transaction_date BETWEEN p_start_date AND p_end_date\r\n      AND status <> 'VOID' AND status <> 'CANCELLED' AND status <> 'REVERSED';\r\n\r\n    -- Calculate Total Expenses\r\n    SELECT COALESCE(SUM(total_amount), 0)\r\n    INTO v_total_expenses\r\n    FROM public.transactions\r\n    WHERE business_id = p_business_id\r\n      AND transaction_type = 'EXPENSE'\r\n      AND transaction_date BETWEEN p_start_date AND p_end_date\r\n      AND status <> 'VOID' AND status <> 'CANCELLED' AND status <> 'REVERSED';\r\n\r\n    -- Calculate Gross Profit\r\n    v_gross_profit := v_total_sales - v_total_purchases;\r\n\r\n    -- Calculate Net Profit/Loss\r\n    v_net_profit_loss := v_gross_profit + v_total_income_other - v_total_expenses;\r\n\r\n    -- Construct JSON result\r\n    result := jsonb_build_object(\r\n        'total_sales', v_total_sales,\r\n        'total_purchases', v_total_purchases,\r\n        'gross_profit', v_gross_profit,\r\n        'total_income_other', v_total_income_other,\r\n        'total_expenses', v_total_expenses,\r\n        'net_profit_loss', v_net_profit_loss\r\n    );\r\n\r\n    RETURN result;\r\nEND;\r\n$function$","CREATE OR REPLACE FUNCTION public.get_promotional_plan_details(p_country_code character varying)\r\n RETURNS jsonb\r\n LANGUAGE plpgsql\r\nAS $function$\r\nDECLARE\r\n    result_json JSONB;\r\nBEGIN\r\n    WITH PlanPricing AS (\r\n        -- Calculate effective pricing for each active plan based on country\r\n        SELECT\r\n            p.plan_id,\r\n            p.name,\r\n            p.slug,\r\n            p.description,\r\n            p.display_order,\r\n            p.trial_period_days,\r\n            COALESCE(pp.price_monthly, p.default_price_monthly) AS effective_price_monthly,\r\n            COALESCE(pp.price_annual, p.default_price_annual) AS effective_price_annual,\r\n            COALESCE(pp.currency_code, p.default_currency) AS effective_currency\r\n        FROM\r\n            plans p\r\n        LEFT JOIN\r\n            plan_prices pp ON p.plan_id = pp.plan_id\r\n                          AND pp.country_code = p_country_code\r\n                          AND pp.is_active = TRUE\r\n        WHERE\r\n            p.is_active = TRUE\r\n    ),\r\n    PlanFeaturesDetails AS (\r\n        -- Aggregate features into a JSON array for each plan\r\n        SELECT\r\n            p.plan_id,\r\n            jsonb_agg(\r\n                jsonb_build_object(\r\n                    'feature_id', f.feature_id,\r\n                    'feature_name', f.name,\r\n                    'feature_slug', f.slug,\r\n                    'feature_type', f.feature_type,\r\n                    'is_enabled', COALESCE(pf.is_enabled, FALSE),\r\n                    'limit_value', CASE WHEN COALESCE(pf.is_enabled, FALSE) = TRUE THEN pf.limit_value ELSE NULL END\r\n                ) ORDER BY f.feature_id -- Or order by feature display order if you add one\r\n            ) AS features_json\r\n        FROM\r\n            PlanPricing p -- Use the already filtered active plans\r\n        CROSS JOIN\r\n            features f\r\n        LEFT JOIN\r\n            plan_features pf ON p.plan_id = pf.plan_id AND f.feature_id = pf.feature_id\r\n        GROUP BY\r\n            p.plan_id\r\n    )\r\n    -- Final aggregation: build plan objects and aggregate them into a top-level array\r\n    SELECT\r\n        jsonb_agg(\r\n            jsonb_build_object(\r\n                'plan_id', pp.plan_id,\r\n                'plan_name', pp.name,\r\n                'plan_slug', pp.slug,\r\n                'plan_description', pp.description,\r\n                'display_order', pp.display_order,\r\n                'price_monthly', pp.effective_price_monthly,\r\n                'price_annual', pp.effective_price_annual,\r\n                'currency', pp.effective_currency,\r\n                'trial_period_days', pp.trial_period_days,\r\n                'features', COALESCE(pfd.features_json, '[]'::jsonb) -- Use the aggregated features, default to empty array if plan has no features mapped (unlikely with CROSS JOIN approach but safe)\r\n            ) ORDER BY pp.display_order -- Ensure final array is ordered correctly\r\n        )\r\n    INTO result_json -- Store the final aggregated JSON array into the variable\r\n    FROM\r\n        PlanPricing pp\r\n    LEFT JOIN\r\n        PlanFeaturesDetails pfd ON pp.plan_id = pfd.plan_id;\r\n\r\n    -- Return the resulting JSONB object (or an empty JSON array if no active plans found)\r\n    RETURN COALESCE(result_json, '[]'::jsonb);\r\n\r\nEND;\r\n$function$","CREATE OR REPLACE FUNCTION public.get_purchase_summary(p_business_id uuid, p_start_date timestamp with time zone DEFAULT NULL::timestamp with time zone, p_end_date timestamp with time zone DEFAULT NULL::timestamp with time zone)\r\n RETURNS json\r\n LANGUAGE plpgsql\r\nAS $function$\r\nDECLARE\r\n    result JSON;\r\n    v_start_date TIMESTAMP WITH TIME ZONE;\r\n    v_end_date TIMESTAMP WITH TIME ZONE;\r\n    v_fiscal_start_month INTEGER;\r\n    v_fiscal_end_month INTEGER;\r\n    v_current_year INTEGER;\r\nBEGIN\r\n    -- Get fiscal year details for the business\r\n    SELECT \r\n        fy.start_month,\r\n        fy.end_month\r\n    INTO \r\n        v_fiscal_start_month,\r\n        v_fiscal_end_month\r\n    FROM businesses b\r\n    JOIN fiscal_years fy ON b.fiscal_id = fy.fiscal_id\r\n    WHERE b.business_id = p_business_id;\r\n\r\n    -- If dates are not provided, calculate fiscal year dates\r\n    IF p_start_date IS NULL OR p_end_date IS NULL THEN\r\n        v_current_year := EXTRACT(YEAR FROM CURRENT_DATE);\r\n        \r\n        -- If current month is less than fiscal start month, we're in previous year's fiscal year\r\n        IF EXTRACT(MONTH FROM CURRENT_DATE) < v_fiscal_start_month THEN\r\n            v_current_year := v_current_year - 1;\r\n        END IF;\r\n\r\n        v_start_date := make_timestamp(\r\n            v_current_year,\r\n            v_fiscal_start_month,\r\n            1,\r\n            0,\r\n            0,\r\n            0\r\n        );\r\n        \r\n        -- If fiscal end month is less than start month, it means it spans to next year\r\n        IF v_fiscal_end_month < v_fiscal_start_month THEN\r\n            v_current_year := v_current_year + 1;\r\n        END IF;\r\n        \r\n        v_end_date := make_timestamp(\r\n            v_current_year,\r\n            v_fiscal_end_month,\r\n            1,\r\n            0,\r\n            0,\r\n            0\r\n        );\r\n        -- Set to last day of the end month\r\n        v_end_date := (v_end_date + INTERVAL '1 month' - INTERVAL '1 day');\r\n    ELSE\r\n        v_start_date := p_start_date;\r\n        v_end_date := p_end_date;\r\n    END IF;\r\n\r\n    -- Get the purchase summary\r\n    SELECT json_build_object(\r\n        'total_purchase_amount', COALESCE(SUM(p.total_amount), 0),\r\n        'total_purchase_count', COUNT(p.purchase_id),\r\n        'total_paid', COALESCE(SUM(p.paid_amount), 0),\r\n        'total_due', COALESCE(SUM(p.due_amount), 0)\r\n    ) INTO result\r\n    FROM purchases p\r\n    WHERE \r\n        p.business_id = p_business_id\r\n        AND p.created_at >= v_start_date\r\n        AND p.created_at <= v_end_date;\r\n\r\n    RETURN result;\r\nEND;\r\n$function$","CREATE OR REPLACE FUNCTION public.get_role_permissions(role_id uuid DEFAULT NULL::uuid)\r\n RETURNS jsonb\r\n LANGUAGE plpgsql\r\nAS $function$\r\nDECLARE \r\n    v_items JSONB;\r\nBEGIN\r\n    SELECT JSON_AGG(\r\n                JSONB_BUILD_OBJECT(\r\n                    'id', MODULES.MODULE_ID,\r\n                    'created_at', MODULES.CREATED_AT,\r\n                    'name', MODULES.NAME,\r\n                    'description', MODULES.DESCRIPTION,\r\n                    'url', MODULES.URL,\r\n\t\t\t\t\t'sort_order', MODULES.SORT_ORDER,\r\n                    'submenus',\r\n                    COALESCE(\r\n                        (\r\n                            SELECT JSON_AGG(\r\n                                    JSONB_BUILD_OBJECT(\r\n                                        'id', LINKS.LINK_ID,\r\n                                        'link_name', LINKS.NAME,\r\n                                        'url', LINKS.URL,\r\n\t\t\t\t\t\t\t\t\t\t 'sort_order', LINKS.SORT_ORDER,\r\n                                        'permissions', \r\n                                        COALESCE(\r\n                                            (\r\n                                                SELECT JSONB_BUILD_OBJECT(\r\n                                                    'view', P.\\"view\\",\r\n                                                    'add', P.\\"create\\",\r\n                                                    'edit', P.\\"edit\\",\r\n                                                    'delete', P.\\"delete\\",\r\n                                                    'print', P.\\"print\\",\r\n\t\t\t\t\t\t\t\t\t\t\t\t\t'permission_id', p.permission_id\t\t\t\t\t\t\t\t\t\t\t\t\t\r\n                                                )\r\n                                                FROM public.permissions P\r\n                                                WHERE \r\n                                                    P.link_id = LINKS.LINK_ID\r\n                                                    AND\r\n                                                    P.employee_role_id = role_id\r\n\t\t\t\t\t\t\t\t\t\t\t\tLIMIT 1\r\n                                            ),\r\n                                            JSONB_BUILD_OBJECT(\r\n                                                'view', FALSE,\r\n                                                'add', FALSE,\r\n                                                'edit', FALSE,\r\n                                                'delete', FALSE,\r\n                                                'print', FALSE\r\n                                            )\r\n                                        )\r\n                                    )\r\n                                )\r\n                            FROM PUBLIC.LINKS\r\n                            WHERE LINKS.MODULE_ID = MODULES.MODULE_ID\r\n                        ),\r\n                        '[]'::json\r\n                    ),\r\n                    'permissions', \r\n                    COALESCE(\r\n                        (\r\n                            SELECT JSONB_BUILD_OBJECT(\r\n                                'view', P.\\"view\\",\r\n                                'add', P.\\"create\\",\r\n                                'edit', P.\\"edit\\",\r\n                                'delete', P.\\"delete\\",\r\n                                'print', P.\\"print\\",\r\n\t\t\t\t\t\t\t\t'permission_id', p.permission_id\r\n                            )\r\n                            FROM public.permissions P\r\n                            WHERE \r\n                                P.MODULE_ID = MODULES.MODULE_ID\r\n                                AND\r\n                                P.employee_role_id = role_id\r\n\t\t\t\t\t\t\tLIMIT 1\r\n                        ),\r\n                        JSONB_BUILD_OBJECT(\r\n                            'view', FALSE,\r\n                            'add', FALSE,\r\n                            'edit', FALSE,\r\n                            'delete', FALSE,\r\n                            'print', FALSE\r\n                        )\r\n                    )\r\n                )\r\n            ) AS result\r\n    FROM MODULES \r\n    INTO v_items;\r\n    \r\n    RETURN v_items;\r\nEND;\r\n$function$","CREATE OR REPLACE FUNCTION public.get_sales_summary(p_business_id uuid, p_start_date timestamp with time zone DEFAULT NULL::timestamp with time zone, p_end_date timestamp with time zone DEFAULT NULL::timestamp with time zone)\r\n RETURNS json\r\n LANGUAGE plpgsql\r\nAS $function$\r\nDECLARE\r\n    result JSON;\r\n    v_start_date TIMESTAMP WITH TIME ZONE;\r\n    v_end_date TIMESTAMP WITH TIME ZONE;\r\n    v_fiscal_start_month INTEGER;\r\n    v_fiscal_end_month INTEGER;\r\n    v_current_year INTEGER;\r\nBEGIN\r\n    -- Get fiscal year details for the business\r\n    SELECT \r\n        fy.start_month,\r\n        fy.end_month\r\n    INTO \r\n        v_fiscal_start_month,\r\n        v_fiscal_end_month\r\n    FROM businesses b\r\n    JOIN fiscal_years fy ON b.fiscal_id = fy.fiscal_id\r\n    WHERE b.business_id = p_business_id;\r\n\r\n    -- If dates are not provided, calculate fiscal year dates\r\n    IF p_start_date IS NULL OR p_end_date IS NULL THEN\r\n        v_current_year := EXTRACT(YEAR FROM CURRENT_DATE);\r\n        \r\n        -- If current month is less than fiscal start month, we're in previous year's fiscal year\r\n        IF EXTRACT(MONTH FROM CURRENT_DATE) < v_fiscal_start_month THEN\r\n            v_current_year := v_current_year - 1;\r\n        END IF;\r\n\r\n        v_start_date := make_timestamp(\r\n            v_current_year,\r\n            v_fiscal_start_month,\r\n            1,\r\n            0,\r\n            0,\r\n            0\r\n        );\r\n        \r\n        -- If fiscal end month is less than start month, it means it spans to next year\r\n        IF v_fiscal_end_month < v_fiscal_start_month THEN\r\n            v_current_year := v_current_year + 1;\r\n        END IF;\r\n        \r\n        v_end_date := make_timestamp(\r\n            v_current_year,\r\n            v_fiscal_end_month,\r\n            1,\r\n            0,\r\n            0,\r\n            0\r\n        );\r\n        -- Set to last day of the end month\r\n        v_end_date := (v_end_date + INTERVAL '1 month' - INTERVAL '1 day');\r\n    ELSE\r\n        v_start_date := p_start_date;\r\n        v_end_date := p_end_date;\r\n    END IF;\r\n\r\n    -- Get the sales summary\r\n    SELECT json_build_object(\r\n        'total_sales_amount', COALESCE(SUM(s.total_amount), 0),\r\n        'total_sales_count', COUNT(s.sale_id),\r\n        'total_paid', COALESCE(SUM(s.paid_amount), 0),\r\n        'total_due', COALESCE(SUM(s.due_amount), 0)\r\n    ) INTO result\r\n    FROM sales s\r\n    WHERE \r\n        s.business_id = p_business_id\r\n        AND s.created_at >= v_start_date\r\n        AND s.created_at <= v_end_date;\r\n\r\n    RETURN result;\r\nEND;\r\n$function$","CREATE OR REPLACE FUNCTION public.get_sidebar()\r\n RETURNS jsonb\r\n LANGUAGE plpgsql\r\nAS $function$\r\nDECLARE \r\n    V_ITEMS JSONB;\r\n    _uid UUID;\r\nBEGIN\r\n    _uid = auth.uid();\r\n    SELECT \r\n        JSON_AGG(\r\n            JSONB_BUILD_OBJECT(\r\n                'id', MODULES.MODULE_ID,\r\n                'created_at', MODULES.CREATED_AT,\r\n                'name', MODULES.NAME,\r\n                'description', MODULES.DESCRIPTION,\r\n                'url', MODULES.URL,\r\n\t\t\t\t'sort_order', MODULES.SORT_ORDER,\r\n                'submenus',\r\n                COALESCE(\r\n                    (SELECT JSON_AGG(\r\n                        JSONB_BUILD_OBJECT(\r\n                            'id', LINKS.LINK_ID,\r\n                            'link_name', LINKS.NAME,\r\n                            'url', LINKS.URL,\r\n\t\t\t\t\t\t\t'sort_order', LINKS.SORT_ORDER,\r\n                            'permissions',\r\n                            COALESCE(\r\n                                (JSONB_BUILD_OBJECT(\r\n                                    'view', COALESCE((SELECT BOOL_OR(p.view) AS view FROM roles_of_employees ru JOIN permissions p ON ru.employee_role_id = p.employee_role_id WHERE ru.employee_id = _uid AND p.LINK_ID = LINKS.LINK_ID AND p.view IS TRUE),FALSE),\r\n                                    'add', COALESCE((SELECT BOOL_OR(p.create) AS view FROM roles_of_employees ru JOIN permissions p ON ru.employee_role_id = p.employee_role_id WHERE ru.employee_id = _uid AND p.LINK_ID = LINKS.LINK_ID AND p.create IS TRUE),FALSE),\r\n                                    'edit', COALESCE((SELECT BOOL_OR(p.edit) AS view FROM roles_of_employees ru JOIN permissions p ON ru.employee_role_id = p.employee_role_id WHERE ru.employee_id = _uid AND p.LINK_ID = LINKS.LINK_ID AND p.edit IS TRUE),FALSE),\r\n                                    'delete', COALESCE((SELECT BOOL_OR(p.delete) AS view FROM roles_of_employees ru JOIN permissions p ON ru.employee_role_id = p.employee_role_id WHERE ru.employee_id = _uid AND p.LINK_ID = LINKS.LINK_ID AND p.delete IS TRUE),FALSE),\r\n                                    'print', COALESCE((SELECT BOOL_OR(p.print) AS view FROM roles_of_employees ru JOIN permissions p ON ru.employee_role_id = p.employee_role_id WHERE ru.employee_id = _uid AND p.LINK_ID = LINKS.LINK_ID AND p.print IS TRUE),FALSE)\r\n                                )),\r\n                                JSONB_BUILD_OBJECT(\r\n                                    'view', FALSE,\r\n                                    'add', FALSE,\r\n                                    'edit', FALSE,\r\n                                    'delete', FALSE,\r\n                                    'print', FALSE\r\n                                )\r\n                            )\r\n                        )\r\n                    ) FROM PUBLIC.LINKS WHERE LINKS.MODULE_ID = MODULES.MODULE_ID),\r\n                    '[]'::json\r\n                ),\r\n\t\t\t\t'permissions', \r\n                    COALESCE(\r\n                        (\r\n                            JSONB_BUILD_OBJECT(\r\n\t\t\t\t\t\t\t\t'view', COALESCE((SELECT BOOL_OR(p.view) AS view FROM roles_of_employees ru JOIN permissions p ON ru.employee_role_id = p.employee_role_id WHERE ru.employee_id = _uid AND p.MODULE_ID = MODULES.MODULE_ID AND p.view IS TRUE),FALSE),\r\n\t\t\t\t\t\t\t\t'add', COALESCE((SELECT BOOL_OR(p.create) AS view FROM roles_of_employees ru JOIN permissions p ON ru.employee_role_id = p.employee_role_id WHERE ru.employee_id = _uid AND p.MODULE_ID = MODULES.MODULE_ID AND p.create IS TRUE),FALSE),\r\n\t\t\t\t\t\t\t\t'edit', COALESCE((SELECT BOOL_OR(p.edit) AS view FROM roles_of_employees ru JOIN permissions p ON ru.employee_role_id = p.employee_role_id WHERE ru.employee_id = _uid AND p.MODULE_ID = MODULES.MODULE_ID AND p.edit IS TRUE),FALSE),\r\n\t\t\t\t\t\t\t\t'delete', COALESCE((SELECT BOOL_OR(p.delete) AS view FROM roles_of_employees ru JOIN permissions p ON ru.employee_role_id = p.employee_role_id WHERE ru.employee_id = _uid AND p.MODULE_ID = MODULES.MODULE_ID AND p.delete IS TRUE),FALSE),\r\n\t\t\t\t\t\t\t\t'print', COALESCE((SELECT BOOL_OR(p.print) AS view FROM roles_of_employees ru JOIN permissions p ON ru.employee_role_id = p.employee_role_id WHERE ru.employee_id = _uid AND p.MODULE_ID = MODULES.MODULE_ID AND p.print IS TRUE),FALSE)\r\n                            )\r\n                        ),\r\n                        JSONB_BUILD_OBJECT(\r\n                            'view', FALSE,\r\n                            'add', FALSE,\r\n                            'edit', FALSE,\r\n                            'delete', FALSE,\r\n                            'print', FALSE\r\n                        )\r\n                    )\r\n            )\r\n        ) AS RESULT\r\n    FROM MODULES INTO V_ITEMS;\r\n    RETURN V_ITEMS;\r\nEND;\r\n$function$","CREATE OR REPLACE FUNCTION public.get_total_dues_summary(p_business_id uuid, p_start_date timestamp with time zone DEFAULT NULL::timestamp with time zone, p_end_date timestamp with time zone DEFAULT NULL::timestamp with time zone)\r\n RETURNS json\r\n LANGUAGE plpgsql\r\nAS $function$\r\nDECLARE\r\n    result JSON;\r\n    v_start_date TIMESTAMP WITH TIME ZONE;\r\n    v_end_date TIMESTAMP WITH TIME ZONE;\r\n    v_fiscal_start_month INTEGER;\r\n    v_fiscal_end_month INTEGER;\r\n    v_current_year INTEGER;\r\nBEGIN\r\n    -- Get fiscal year details for the business\r\n    SELECT \r\n        fy.start_month,\r\n        fy.end_month\r\n    INTO \r\n        v_fiscal_start_month,\r\n        v_fiscal_end_month\r\n    FROM businesses b\r\n    JOIN fiscal_years fy ON b.fiscal_id = fy.fiscal_id\r\n    WHERE b.business_id = p_business_id;\r\n\r\n    -- If dates are not provided, calculate fiscal year dates\r\n    IF p_start_date IS NULL OR p_end_date IS NULL THEN\r\n        v_current_year := EXTRACT(YEAR FROM CURRENT_DATE);\r\n        \r\n        -- If current month is less than fiscal start month, we're in previous year's fiscal year\r\n        IF EXTRACT(MONTH FROM CURRENT_DATE) < v_fiscal_start_month THEN\r\n            v_current_year := v_current_year - 1;\r\n        END IF;\r\n\r\n        v_start_date := make_timestamp(\r\n            v_current_year,\r\n            v_fiscal_start_month,\r\n            1,\r\n            0,\r\n            0,\r\n            0\r\n        );\r\n        \r\n        -- If fiscal end month is less than start month, it means it spans to next year\r\n        IF v_fiscal_end_month < v_fiscal_start_month THEN\r\n            v_current_year := v_current_year + 1;\r\n        END IF;\r\n        \r\n        v_end_date := make_timestamp(\r\n            v_current_year,\r\n            v_fiscal_end_month,\r\n            1,\r\n            0,\r\n            0,\r\n            0\r\n        );\r\n        -- Set to last day of the end month\r\n        v_end_date := (v_end_date + INTERVAL '1 month' - INTERVAL '1 day');\r\n    ELSE\r\n        v_start_date := p_start_date;\r\n        v_end_date := p_end_date;\r\n    END IF;\r\n\r\n    -- Get the combined dues summary\r\n    WITH sales_dues AS (\r\n        SELECT \r\n            COALESCE(SUM(due_amount), 0) as sales_due,\r\n            COUNT(CASE WHEN due_amount > 0 THEN 1 END) as sales_due_count\r\n        FROM sales\r\n        WHERE \r\n            business_id = p_business_id\r\n            AND created_at >= v_start_date\r\n            AND created_at <= v_end_date\r\n    ),\r\n    purchase_dues AS (\r\n        SELECT \r\n            COALESCE(SUM(due_amount), 0) as purchase_due,\r\n            COUNT(CASE WHEN due_amount > 0 THEN 1 END) as purchase_due_count\r\n        FROM purchases\r\n        WHERE \r\n            business_id = p_business_id\r\n            AND created_at >= v_start_date\r\n            AND created_at <= v_end_date\r\n    )\r\n    SELECT json_build_object(\r\n        'total_sales_due', sd.sales_due,\r\n        'sales_due_count', sd.sales_due_count,\r\n        'total_purchase_due', pd.purchase_due,\r\n        'purchase_due_count', pd.purchase_due_count,\r\n        'total_combined_due', (sd.sales_due + pd.purchase_due),\r\n        'total_due_transactions', (sd.sales_due_count + pd.purchase_due_count),\r\n        'start_date', v_start_date,\r\n        'end_date', v_end_date\r\n    ) INTO result\r\n    FROM sales_dues sd, purchase_dues pd;\r\n\r\n    RETURN result;\r\nEND;\r\n$function$","CREATE OR REPLACE FUNCTION public.handle_purchase_audit()\r\n RETURNS trigger\r\n LANGUAGE plpgsql\r\nAS $function$\r\nDECLARE\r\n    v_timestamp TEXT;\r\nBEGIN\r\n\r\n    -- Format timestamp\r\n    v_timestamp := ' on ' || TO_CHAR(NOW(), 'DD Mon YYYY HH24:MI:SS');\r\n\r\n    -- For purchase table changes\r\n    IF TG_TABLE_NAME = 'purchases' THEN\r\n        IF TG_OP = 'INSERT' THEN\r\n            INSERT INTO purchase_audits (\r\n                purchase_id,\r\n                transaction_id,\r\n                action_type,\r\n                performed_by,\r\n                new_data,\r\n                change_details\r\n            ) VALUES (\r\n                NEW.purchase_id,\r\n                NEW.transaction_id,\r\n                'CREATED',\r\n                auth.uid(),\r\n                row_to_json(NEW),\r\n                'Purchase created with invoice ' || NEW.purchase_invoice || v_timestamp\r\n            );\r\n        ELSIF TG_OP = 'UPDATE' THEN\r\n            -- Check what kind of update occurred\r\n            IF OLD.paid_amount != NEW.paid_amount THEN\r\n                INSERT INTO purchase_audits (\r\n                    purchase_id,\r\n                    transaction_id,\r\n                    action_type,\r\n                    performed_by,\r\n                    old_data,\r\n                    new_data,\r\n                    change_details\r\n                ) VALUES (\r\n                    NEW.purchase_id,\r\n                    NEW.transaction_id,\r\n                    'PAYMENT_ADDED',\r\n                    auth.uid(),\r\n                    jsonb_build_object('paid_amount', OLD.paid_amount, 'due_amount', OLD.due_amount),\r\n                    jsonb_build_object('paid_amount', NEW.paid_amount, 'due_amount', NEW.due_amount),\r\n                    'Payment updated from ' || OLD.paid_amount || ' to ' || NEW.paid_amount || v_timestamp\r\n                );\r\n            END IF;\r\n        END IF;\r\n    END IF;\r\n\r\n    -- For purchase_returns table changes\r\n    IF TG_TABLE_NAME = 'purchase_returns' THEN\r\n        IF TG_OP = 'INSERT' THEN\r\n            INSERT INTO purchase_audits (\r\n                purchase_id,\r\n                transaction_id,\r\n                action_type,\r\n                performed_by,\r\n                new_data,\r\n                change_details\r\n            ) VALUES (\r\n                NEW.purchase_id,\r\n                NEW.transaction_id,\r\n                'RETURN_CREATED',\r\n                auth.uid(),\r\n                row_to_json(NEW),\r\n                'Purchase return created with invoice ' || NEW.return_invoice || ' for amount ' || NEW.total_amount || v_timestamp\r\n            );\r\n        END IF;\r\n    END IF;\r\n\r\n    RETURN NEW;\r\nEND;\r\n$function$","CREATE OR REPLACE FUNCTION public.handle_sale_audit()\r\n RETURNS trigger\r\n LANGUAGE plpgsql\r\nAS $function$\r\nDECLARE\r\n    v_timestamp TEXT;\r\nBEGIN\r\n\r\n    -- Format timestamp\r\n    v_timestamp := ' on ' || TO_CHAR(NOW(), 'DD Mon YYYY HH24:MI:SS');\r\n\r\n    -- For sale table changes\r\n    IF TG_TABLE_NAME = 'sales' THEN\r\n        IF TG_OP = 'INSERT' THEN\r\n            INSERT INTO sale_audits (\r\n                sale_id,\r\n                transaction_id,\r\n                action_type,\r\n                performed_by,\r\n                new_data,\r\n                change_details\r\n            ) VALUES (\r\n                NEW.sale_id,\r\n                NEW.transaction_id,\r\n                'CREATED',\r\n                NEW.created_by,\r\n                row_to_json(NEW),\r\n                'Sale created with invoice ' || NEW.sale_invoice || v_timestamp\r\n            );\r\n        ELSIF TG_OP = 'UPDATE' THEN\r\n            -- Check for payment updates\r\n            IF OLD.paid_amount != NEW.paid_amount THEN\r\n                INSERT INTO sale_audits (\r\n                    sale_id,\r\n                    transaction_id,\r\n                    action_type,\r\n                    performed_by,\r\n                    old_data,\r\n                    new_data,\r\n                    change_details\r\n                ) VALUES (\r\n                    NEW.sale_id,\r\n                    NEW.transaction_id,\r\n                    'PAYMENT_ADDED',\r\n                    NEW.created_by,\r\n                    jsonb_build_object('paid_amount', OLD.paid_amount, 'due_amount', OLD.due_amount),\r\n                    jsonb_build_object('paid_amount', NEW.paid_amount, 'due_amount', NEW.due_amount),\r\n                    'Payment updated from ' || OLD.paid_amount || ' to ' || NEW.paid_amount || v_timestamp\r\n                );\r\n            END IF;\r\n            \r\n            -- Check for status changes\r\n\t\t\tIF OLD.status_id != NEW.status_id THEN\r\n\t\t\t    DECLARE\r\n\t\t\t        old_status_name text;\r\n\t\t\t        new_status_name text;\r\n\t\t\t    BEGIN\r\n\t\t\t        -- Get the status names\r\n\t\t\t        SELECT name INTO old_status_name\r\n\t\t\t        FROM statuses \r\n\t\t\t        WHERE status_id = OLD.status_id;\r\n\t\t\t\r\n\t\t\t        SELECT name INTO new_status_name\r\n\t\t\t        FROM statuses \r\n\t\t\t        WHERE status_id = NEW.status_id;\r\n\t\t\t\r\n\t\t\t        INSERT INTO sale_audits (\r\n\t\t\t            sale_id,\r\n\t\t\t            transaction_id,\r\n\t\t\t            action_type,\r\n\t\t\t            performed_by,\r\n\t\t\t            old_data,\r\n\t\t\t            new_data,\r\n\t\t\t            change_details\r\n\t\t\t        ) VALUES (\r\n\t\t\t            NEW.sale_id,\r\n\t\t\t            NEW.transaction_id,\r\n\t\t\t            'STATUS_CHANGED',\r\n\t\t\t            NEW.created_by,\r\n\t\t\t            jsonb_build_object('status_id', OLD.status_id, 'status_name', old_status_name),\r\n\t\t\t            jsonb_build_object('status_id', NEW.status_id, 'status_name', new_status_name),\r\n\t\t\t            'Status changed from \\"' || COALESCE(old_status_name, 'Unknown') || '\\" to \\"' || COALESCE(new_status_name, 'Unknown') || '\\"'\r\n\t\t\t        );\r\n\t\t\t    END;\r\n\t\t\tEND IF;\r\n\r\n        END IF;\r\n    END IF;\r\n\r\n    -- For sale_returns table changes\r\n    IF TG_TABLE_NAME = 'sale_returns' THEN\r\n        IF TG_OP = 'INSERT' THEN\r\n            INSERT INTO sale_audits (\r\n                sale_id,\r\n                transaction_id,\r\n                action_type,\r\n                performed_by,\r\n                new_data,\r\n                change_details\r\n            ) VALUES (\r\n                NEW.sale_id,\r\n                NEW.transaction_id,\r\n                'RETURN_CREATED',\r\n                NEW.created_by,\r\n                row_to_json(NEW),\r\n                'Sale return created with invoice ' || NEW.return_invoice || ' for amount ' || NEW.total_amount || v_timestamp\r\n            );\r\n        END IF;\r\n    END IF;\r\n\r\n    RETURN NEW;\r\nEND;\r\n$function$","create or replace view \\"public\\".\\"ledger_parties\\" as  WITH customer_transactions AS (\r\n         SELECT c.customer_id AS id,\r\n            bc.business_id,\r\n            sum(s.total_amount) AS total_amount,\r\n            bc.customer_balance AS due_amount\r\n           FROM ((customers c\r\n             JOIN business_customers bc ON ((bc.customer_id = c.customer_id)))\r\n             LEFT JOIN sales s ON ((s.customer_id = c.customer_id)))\r\n          GROUP BY c.customer_id, bc.business_id, bc.customer_balance\r\n        ), supplier_transactions AS (\r\n         SELECT s.supplier_id AS id,\r\n            s.business_id,\r\n            sum(p.total_amount) AS total_amount,\r\n            s.supplier_balance AS due_amount\r\n           FROM (suppliers s\r\n             LEFT JOIN purchases p ON ((p.supplier_id = s.supplier_id)))\r\n          GROUP BY s.supplier_id, s.business_id, s.supplier_balance\r\n        )\r\n SELECT bc.customer_id AS id,\r\n    bc.business_id,\r\n    'customer'::text AS type,\r\n    COALESCE(ct.total_amount, (0)::numeric) AS amount,\r\n    bc.name,\r\n    COALESCE(bc.customer_balance, (0)::numeric) AS due_amount\r\n   FROM (business_customers bc\r\n     LEFT JOIN customer_transactions ct ON (((ct.id = bc.customer_id) AND (ct.business_id = bc.business_id))))\r\nUNION ALL\r\n SELECT s.supplier_id AS id,\r\n    s.business_id,\r\n    'supplier'::text AS type,\r\n    COALESCE(st.total_amount, (0)::numeric) AS amount,\r\n    s.name,\r\n    COALESCE(s.supplier_balance, (0)::numeric) AS due_amount\r\n   FROM (suppliers s\r\n     LEFT JOIN supplier_transactions st ON (((st.id = s.supplier_id) AND (st.business_id = s.business_id))))","CREATE OR REPLACE FUNCTION public.register_business(business_data jsonb)\r\n RETURNS void\r\n LANGUAGE plpgsql\r\nAS $function$\r\nDECLARE\r\n    v_auth_user_id UUID := auth.uid();  -- Get the authenticated user ID\r\n    v_org_id UUID;\r\n    -- Removed category ID variables as they are now handled internally by create_default_chart_of_accounts\r\n\tv_existing_user_id UUID;\r\n    v_business_id UUID;\r\nBEGIN\r\n\r\n    -- Check if user already exists\r\n    SELECT user_id INTO v_existing_user_id\r\n    FROM public.users\r\n    WHERE email = business_data->>'email';\r\n\r\n    IF v_existing_user_id IS NOT NULL THEN\r\n        RAISE EXCEPTION 'User already exists';\r\n    END IF;\r\n\r\n    -- 1. Insert into users table\r\n    INSERT INTO public.users (\r\n        user_id,\r\n        name,\r\n        email,\r\n        phone\r\n    ) VALUES (\r\n        v_auth_user_id,\r\n        business_data->>'name',\r\n        business_data->>'email',\r\n        business_data->>'phone_number'\r\n    );\r\n\r\n    -- 2. Insert into organizations and get org_id\r\n    INSERT INTO public.organizations (\r\n        name\r\n    ) VALUES (\r\n        business_data->>'name'\r\n    ) RETURNING org_id INTO v_org_id;\r\n\r\n    -- Insert into employees\r\n    INSERT INTO public.employees (\r\n        employee_id,\r\n        org_id,\r\n        name,\r\n        role\r\n    ) VALUES (\r\n        v_auth_user_id,\r\n        v_org_id,\r\n        business_data->>'name',\r\n        'admin'\r\n    );\r\n\r\n    -- 3. Insert into roles_of_employees\r\n    INSERT INTO public.roles_of_employees (\r\n        employee_role_id,\r\n        employee_id\r\n    ) VALUES (\r\n        '00000000-0000-0000-0000-000000000000', -- Assuming this is a valid default role ID\r\n        v_auth_user_id\r\n    );\r\n\r\n    -- 4. Insert into businesses\r\n    INSERT INTO public.businesses (\r\n        name,\r\n        org_id,\r\n        created_by,\r\n        business_type,\r\n        currency\r\n    ) VALUES (\r\n        business_data->>'name',\r\n        v_org_id,\r\n        v_auth_user_id,\r\n        (business_data->>'business_type')::public.business_types,\r\n        business_data->'currency'\r\n    ) RETURNING business_id INTO v_business_id;\r\n\r\n    -- Add default sale statuses\r\n    INSERT INTO public.statuses (\r\n        business_id,\r\n        name,\r\n        sequence_order,\r\n        is_default,\r\n        type,\r\n\t\tis_editable\r\n    ) VALUES\r\n    (v_business_id, 'Booked', 1, true, 'sale'::status_type, true),\r\n    (v_business_id, 'In Process', 2, false, 'sale'::status_type, true),\r\n    (v_business_id, 'Cancelled', 3, false, 'sale'::status_type, false),\r\n    (v_business_id, 'Completed', 4, false, 'sale'::status_type, false);\r\n\r\n    -- 5. Create the default Account Categories and Chart of Accounts\r\n    --    The block for inserting into account_categories has been removed from here.\r\n    PERFORM public.create_default_chart_of_accounts(v_business_id, v_org_id);\r\n\r\n    -- 6. Insert into branch accesses (Renumbered step)\r\n    INSERT INTO public.employee_branch_access (\r\n        employee_id,\r\n        business_id\r\n    ) VALUES (\r\n        v_auth_user_id,\r\n        v_business_id\r\n    );\r\n\r\n\tRETURN;\r\nEXCEPTION\r\n    WHEN OTHERS THEN\r\n        -- Consider logging the error or providing more context\r\n        RAISE EXCEPTION 'Error during business registration: %', SQLERRM;\r\n        RETURN; -- Or re-raise\r\nEND;\r\n$function$","create or replace view \\"public\\".\\"reseller_referred_businesses\\" as  SELECT r.reseller_id,\r\n    b.business_id,\r\n    b.name,\r\n    b.contact_email,\r\n    b.contact_phone,\r\n    b.contact_address,\r\n    b.subscription_status,\r\n    b.last_active_at\r\n   FROM (referrals r\r\n     JOIN businesses b ON ((r.business_id = b.business_id)))","CREATE OR REPLACE FUNCTION public.reverse_stock_adjustment(p_original_adjustment_id uuid, p_reversal_date timestamp with time zone DEFAULT now(), p_reason text DEFAULT 'Reversal of stock adjustment'::text)\r\n RETURNS uuid\r\n LANGUAGE plpgsql\r\nAS $function$\r\nDECLARE\r\n    v_original_transaction_id UUID;\r\n    v_original_tran RECORD; -- Holds data from original transactions record\r\n    v_original_adj_item RECORD; -- For looping through original stock_adjustment_items\r\n    v_reversal_transaction_id UUID;\r\n    v_reversal_ref_no TEXT;\r\n    v_user_id UUID := auth.uid();\r\n    v_inventory_account_id UUID;\r\n    v_adjustment_offset_account_id UUID;\r\n    v_inventory_code TEXT := '1030';\r\n    v_adjustment_offset_code TEXT := '6095';\r\n    v_item_cost NUMERIC;\r\n    v_item_name TEXT;\r\n    v_item_adjustment_value NUMERIC;\r\n    v_total_adjustment_abs_value NUMERIC := 0; -- For reversal transaction header\r\n    v_business_id_check UUID; -- To fetch business_id early\r\n\r\nBEGIN\r\n    -- 1. Find original transaction_id and business_id from adjustment_id\r\n    SELECT sa.transaction_id, sa.business_id\r\n    INTO v_original_transaction_id, v_business_id_check -- Fetch business_id early\r\n    FROM public.stock_adjustments sa\r\n    WHERE sa.adjustment_id = p_original_adjustment_id;\r\n\r\n    IF v_original_transaction_id IS NULL THEN\r\n        RAISE EXCEPTION 'Stock Adjustment ID % not found.', p_original_adjustment_id;\r\n    END IF;\r\n\r\n    -- 2. Fetch full original transaction details & perform checks\r\n    SELECT *\r\n    INTO v_original_tran -- <<< Assign v_original_tran HERE\r\n    FROM public.transactions\r\n    WHERE transaction_id = v_original_transaction_id;\r\n\r\n    -- Now perform checks using v_original_tran\r\n    IF v_original_tran.transaction_id IS NULL THEN\r\n         -- This should ideally not happen if the previous check passed, but is a safeguard\r\n         RAISE EXCEPTION 'Original Transaction ID % linked to Adjustment ID % not found in transactions table.', v_original_transaction_id, p_original_adjustment_id;\r\n    END IF;\r\n\r\n    IF v_original_tran.status = 'REVERSED' OR v_original_tran.status = 'CANCELLED' THEN -- Use your chosen status\r\n         RAISE EXCEPTION 'Stock Adjustment (Transaction ID %) has already been reversed or cancelled.', v_original_transaction_id;\r\n    END IF;\r\n    IF v_original_tran.reverses_transaction_id IS NOT NULL THEN\r\n         RAISE EXCEPTION 'Transaction ID % is itself a reversal and cannot be reversed.', v_original_transaction_id;\r\n    END IF;\r\n    -- Add period lock checks if necessary (using v_original_tran.transaction_date)\r\n\r\n    -- 3. Fetch required Account IDs using the business_id from v_original_tran\r\n    SELECT account_id INTO v_inventory_account_id FROM public.accounts WHERE business_id = v_original_tran.business_id AND code = v_inventory_code;\r\n    SELECT account_id INTO v_adjustment_offset_account_id FROM public.accounts WHERE business_id = v_original_tran.business_id AND code = v_adjustment_offset_code;\r\n\r\n    IF v_inventory_account_id IS NULL OR v_adjustment_offset_account_id IS NULL THEN\r\n         RAISE EXCEPTION 'Required accounting accounts (Inventory or Stock Adj. Expense) not found for business %.', v_original_tran.business_id;\r\n    END IF;\r\n\r\n    -- 4. Generate Reference for Reversal\r\n    v_reversal_ref_no := 'REV-' || COALESCE(v_original_tran.reference_no, p_original_adjustment_id::text);\r\n\r\n    -- 5. Calculate total absolute value from original adjustment items for header\r\n    FOR v_original_adj_item IN\r\n        SELECT sai.quantity_adjusted, COALESCE(i.purchase_price, 0) as item_cost\r\n        FROM public.stock_adjustment_items sai\r\n        JOIN public.items i ON sai.item_id = i.item_id\r\n        WHERE sai.adjustment_id = p_original_adjustment_id\r\n    LOOP\r\n        v_total_adjustment_abs_value := v_total_adjustment_abs_value + abs(v_original_adj_item.quantity_adjusted * v_original_adj_item.item_cost);\r\n    END LOOP;\r\n\r\n\r\n    -- 6. Create the new Reversal Transaction Header\r\n    INSERT INTO public.transactions (\r\n        reference_no, transaction_type, transaction_date, status,\r\n        total_amount, paid_amount, due_amount,\r\n        notes, business_id, created_by,\r\n        reverses_transaction_id -- Link back\r\n    ) VALUES (\r\n        v_reversal_ref_no, v_original_tran.transaction_type, p_reversal_date, 'PAID'::public.transaction_status, -- Mark reversal as complete\r\n        v_total_adjustment_abs_value, v_total_adjustment_abs_value, 0,\r\n        'Reversal of Stock Adj ' || v_original_tran.reference_no || '. Reason: ' || p_reason,\r\n        v_original_tran.business_id, v_user_id,\r\n        v_original_transaction_id\r\n    ) RETURNING transaction_id INTO v_reversal_transaction_id;\r\n\r\n    -- 7. Reverse Item Quantities and Create Reversal GL Entries\r\n    FOR v_original_adj_item IN\r\n        SELECT sai.item_id, sai.quantity_adjusted, sai.previous_quantity, i.name as item_name, COALESCE(i.purchase_price, 0) as item_cost\r\n        FROM public.stock_adjustment_items sai\r\n        JOIN public.items i ON sai.item_id = i.item_id\r\n        WHERE sai.adjustment_id = p_original_adjustment_id\r\n    LOOP\r\n        -- Calculate value of this specific item's original adjustment\r\n        v_item_adjustment_value := v_original_adj_item.quantity_adjusted * v_original_adj_item.item_cost;\r\n\r\n        -- Create REVERSED Transaction Entries for this item\r\n        -- If original was INCREASE (Debit Inv, Credit Offset), reversal is DEBIT Offset, CREDIT Inv\r\n        IF v_original_adj_item.quantity_adjusted > 0 THEN\r\n             INSERT INTO public.transaction_entries (transaction_id, account_id, entry_type, amount, description)\r\n             VALUES\r\n                (v_reversal_transaction_id, v_adjustment_offset_account_id, 'DEBIT'::public.entry_type, v_item_adjustment_value, '(Reversal) Stock Increase Adj Offset: ' || v_original_adj_item.item_name),\r\n                (v_reversal_transaction_id, v_inventory_account_id, 'CREDIT'::public.entry_type, v_item_adjustment_value, '(Reversal) Stock Increase Adj: ' || v_original_adj_item.item_name);\r\n        -- If original was DECREASE (Debit Offset, Credit Inv), reversal is DEBIT Inv, CREDIT Offset\r\n        ELSIF v_original_adj_item.quantity_adjusted < 0 THEN\r\n             INSERT INTO public.transaction_entries (transaction_id, account_id, entry_type, amount, description)\r\n             VALUES\r\n                (v_reversal_transaction_id, v_inventory_account_id, 'DEBIT'::public.entry_type, abs(v_item_adjustment_value), '(Reversal) Stock Decrease Adj: ' || v_original_adj_item.item_name),\r\n                (v_reversal_transaction_id, v_adjustment_offset_account_id, 'CREDIT'::public.entry_type, abs(v_item_adjustment_value), '(Reversal) Stock Decrease Adj Offset: ' || v_original_adj_item.item_name);\r\n        END IF;\r\n\r\n        -- Update the item's stock quantity back to its previous state\r\n        UPDATE public.items\r\n        SET stock_quantity = v_original_adj_item.previous_quantity,\r\n            updated_at = now()\r\n        WHERE item_id = v_original_adj_item.item_id;\r\n\r\n    END LOOP;\r\n\r\n    -- 8. Update Status of Original Transaction\r\n    UPDATE public.transactions\r\n    SET status = 'REVERSED'::public.transaction_status, -- Or CANCELLED if you chose that\r\n        updated_at = now()\r\n    WHERE transaction_id = v_original_transaction_id;\r\n\r\n    -- 9. Mark original stock adjustment header as reversed (optional)\r\n    -- UPDATE public.stock_adjustments SET status = 'REVERSED' WHERE adjustment_id = p_original_adjustment_id;\r\n\r\n\r\n    -- 10. Verify balance of the NEW reversal transaction\r\n    PERFORM public.verify_transaction_balance(v_reversal_transaction_id);\r\n\r\n    RAISE NOTICE 'Stock Adjustment (Transaction ID %) reversed by new Transaction ID %.', v_original_transaction_id, v_reversal_transaction_id;\r\n\r\n    RETURN v_reversal_transaction_id;\r\n\r\nEND;\r\n$function$","CREATE OR REPLACE FUNCTION public.reverse_transaction(p_original_transaction_id uuid, p_reversal_date timestamp with time zone DEFAULT now(), p_reason text DEFAULT 'Reversal of original transaction'::text)\r\n RETURNS uuid\r\n LANGUAGE plpgsql\r\nAS $function$\r\nDECLARE\r\n    v_original_tran RECORD;\r\n    v_original_entry RECORD;\r\n    v_reversal_transaction_id UUID;\r\n    v_reversal_ref_no TEXT;\r\n    v_user_id UUID := auth.uid();\r\nBEGIN\r\n    -- 1. Fetch original transaction details\r\n    SELECT *\r\n    INTO v_original_tran\r\n    FROM public.transactions\r\n    WHERE transaction_id = p_original_transaction_id;\r\n\r\n    IF NOT FOUND THEN\r\n        RAISE EXCEPTION 'Original Transaction ID % not found.', p_original_transaction_id;\r\n    END IF;\r\n\r\n    IF v_original_tran.status = 'REVERSED' OR v_original_tran.status = 'CANCELLED' THEN\r\n         RAISE EXCEPTION 'Transaction ID % has already been reversed or cancelled.', p_original_transaction_id;\r\n    END IF;\r\n    IF v_original_tran.reverses_transaction_id IS NOT NULL THEN\r\n         RAISE EXCEPTION 'Transaction ID % is itself a reversal and cannot be reversed.', p_original_transaction_id;\r\n    END IF;\r\n\r\n    -- Add checks for period locking here if applicable (compare v_original_tran.transaction_date)\r\n\r\n    -- 2. Generate Reference for Reversal\r\n    v_reversal_ref_no := 'REV-' || v_original_tran.reference_no;\r\n    -- Ensure uniqueness if needed (e.g., append date/time or check existence)\r\n\r\n    -- 3. Create the new Reversal Transaction Header\r\n    INSERT INTO public.transactions (\r\n        reference_no, transaction_type, transaction_date, status,\r\n        total_amount, paid_amount, due_amount, -- Use negative amounts? Or keep positive and rely on entries? Keep positive for consistency.\r\n        notes, business_id, created_by,\r\n        customer_id, supplier_id, -- Copy related IDs\r\n        metadata, -- Copy metadata if desired\r\n        reverses_transaction_id -- Link back to the original\r\n    ) VALUES (\r\n        v_reversal_ref_no, v_original_tran.transaction_type, p_reversal_date, 'PAID', -- Assume reversal is complete ('PAID')\r\n        v_original_tran.total_amount, v_original_tran.paid_amount, v_original_tran.due_amount, -- Amounts might need review based on reversal meaning\r\n        'Reversal of TXN ' || p_original_transaction_id || '. Reason: ' || p_reason,\r\n        v_original_tran.business_id, v_user_id,\r\n        v_original_tran.customer_id, v_original_tran.supplier_id,\r\n        v_original_tran.metadata,\r\n        p_original_transaction_id\r\n    ) RETURNING transaction_id INTO v_reversal_transaction_id;\r\n\r\n    -- 4. Create Reversed Transaction Entries\r\n    FOR v_original_entry IN\r\n        SELECT * FROM public.transaction_entries WHERE transaction_id = p_original_transaction_id\r\n    LOOP\r\n        INSERT INTO public.transaction_entries (\r\n            transaction_id, account_id, entry_type, amount, description\r\n        ) VALUES (\r\n            v_reversal_transaction_id,\r\n            v_original_entry.account_id,\r\n            -- Flip the entry type\r\n            CASE v_original_entry.entry_type\r\n                WHEN 'DEBIT' THEN 'CREDIT'::public.entry_type\r\n                ELSE 'DEBIT'::public.entry_type\r\n            END,\r\n            v_original_entry.amount, -- Amount stays the same magnitude\r\n            '(Reversal) ' || COALESCE(v_original_entry.description, '')\r\n        );\r\n    END LOOP;\r\n\r\n    -- 5. Update Status of Original Transaction\r\n    UPDATE public.transactions\r\n    SET status = 'REVERSED'::public.transaction_status,\r\n        updated_at = now()\r\n    WHERE transaction_id = p_original_transaction_id;\r\n\r\n    -- 6. Optionally update status on linked income/expense records\r\n    UPDATE public.incomes SET status = 'REVERSED' WHERE transaction_id = p_original_transaction_id;\r\n    UPDATE public.expenses SET status = 'REVERSED' WHERE transaction_id = p_original_transaction_id;\r\n\r\n    -- 7. Verify balance of the NEW reversal transaction\r\n    PERFORM public.verify_transaction_balance(v_reversal_transaction_id);\r\n\r\n    RAISE NOTICE 'Transaction ID % reversed by new Transaction ID %.', p_original_transaction_id, v_reversal_transaction_id;\r\n\r\n    RETURN v_reversal_transaction_id;\r\n\r\nEND;\r\n$function$","CREATE OR REPLACE FUNCTION public.settle_purchase_payment(p_purchase_id uuid, p_amount numeric, p_payment_mode text, p_payment_date timestamp with time zone)\r\n RETURNS uuid\r\n LANGUAGE plpgsql\r\n SECURITY DEFINER\r\nAS $function$\r\nDECLARE\r\n    v_purchase_record     RECORD;\r\n    v_business_id         UUID;\r\n    v_supplier_id         UUID;\r\n    v_transaction_id      UUID;\r\n    v_payment_id          UUID;\r\n    v_payment_account_id  UUID; -- Cash or Bank account ID\r\n    v_payable_account_id  UUID; -- Specific A/P account ID\r\n    v_reference_no        TEXT; -- Reference for the payment itself\r\n    v_user_id             UUID := auth.uid();\r\n\r\n    -- Account Codes\r\n    v_ap_supplier_code    TEXT := '2010';\r\n    v_cash_in_bank_code   TEXT := '1011';\r\n    v_petty_cash_code     TEXT := '1010';\r\n\r\nBEGIN\r\n    -- 1. Get purchase and related transaction details\r\n    SELECT\r\n        p.purchase_id, p.supplier_id, p.business_id, p.purchase_invoice, p.due_amount as current_purchase_due,\r\n        t.transaction_id, t.total_amount as transaction_total, t.paid_amount as transaction_paid, t.status as transaction_status\r\n    INTO v_purchase_record\r\n    FROM public.purchases p\r\n    JOIN public.transactions t ON p.transaction_id = t.transaction_id\r\n    WHERE p.purchase_id = p_purchase_id;\r\n\r\n    IF NOT FOUND THEN\r\n        RAISE EXCEPTION 'Purchase ID % not found.', p_purchase_id;\r\n    END IF;\r\n\r\n    v_business_id := v_purchase_record.business_id;\r\n    v_supplier_id := v_purchase_record.supplier_id;\r\n    v_transaction_id := v_purchase_record.transaction_id;\r\n\r\n    -- 2. Validate payment amount\r\n    -- Ensure payment is positive and not more than what's currently due on the transaction\r\n    IF p_amount <= 0 THEN\r\n         RAISE EXCEPTION 'Payment amount must be positive.';\r\n    END IF;\r\n    -- Use ROUND for safer comparison\r\n    IF ROUND(p_amount, 2) > ROUND(v_purchase_record.transaction_total - v_purchase_record.transaction_paid, 2) THEN\r\n        RAISE EXCEPTION 'Payment amount % exceeds the remaining due amount % for Purchase ID %.',\r\n                        p_amount, (v_purchase_record.transaction_total - v_purchase_record.transaction_paid), p_purchase_id;\r\n    END IF;\r\n    -- Check if already fully paid\r\n    IF v_purchase_record.transaction_status = 'PAID'::public.transaction_status THEN\r\n         RAISE EXCEPTION 'Purchase ID % is already fully paid.', p_purchase_id;\r\n    END IF;\r\n\r\n\r\n    -- 3. Get Account IDs\r\n    SELECT account_id INTO v_payable_account_id FROM public.accounts WHERE business_id = v_business_id AND code = v_ap_supplier_code;\r\n    IF lower(p_payment_mode) = 'cash' THEN\r\n        SELECT account_id INTO v_payment_account_id FROM public.accounts WHERE business_id = v_business_id AND code = v_petty_cash_code;\r\n    ELSE -- Assume Bank, Card, Transfer etc. use the Bank account\r\n        SELECT account_id INTO v_payment_account_id FROM public.accounts WHERE business_id = v_business_id AND code = v_cash_in_bank_code;\r\n    END IF;\r\n\r\n    IF v_payable_account_id IS NULL OR v_payment_account_id IS NULL THEN\r\n        RAISE EXCEPTION 'Required accounts (A/P Supplier or Cash/Bank) not found for business %.', v_business_id;\r\n    END IF;\r\n\r\n    -- 4. Generate Payment Reference Number\r\n    -- Use a distinct reference for the payment itself\r\n    v_reference_no := 'PAY-PUR-' || COALESCE(v_purchase_record.purchase_invoice, p_purchase_id::text) || '-' || upper(substring(gen_random_uuid()::text from 1 for 4));\r\n\r\n    -- 5. Create Payment Record (linking to the original transaction)\r\n    INSERT INTO public.payments (\r\n        transaction_id, payment_date, amount, payment_method, reference_no, created_by\r\n    ) VALUES (\r\n        v_transaction_id, p_payment_date, p_amount, p_payment_mode, v_reference_no, v_user_id\r\n    ) RETURNING payment_id INTO v_payment_id;\r\n\r\n    -- 6. Create Transaction Entries (added to the existing transaction_id)\r\n    -- Debit Accounts Payable (Reducing liability)\r\n    INSERT INTO public.transaction_entries (transaction_id, account_id, entry_type, amount, description)\r\n    VALUES (v_transaction_id, v_payable_account_id, 'DEBIT', p_amount, 'Payment made for Purchase Ref ' || v_purchase_record.purchase_invoice);\r\n\r\n    -- Credit Cash/Bank (Reducing asset)\r\n    INSERT INTO public.transaction_entries (transaction_id, account_id, entry_type, amount, description)\r\n    VALUES (v_transaction_id, v_payment_account_id, 'CREDIT', p_amount, 'Payment made for Purchase Ref ' || v_purchase_record.purchase_invoice);\r\n\r\n    -- 7. Update Purchase Header (Track payment progress)\r\n    UPDATE public.purchases\r\n    SET\r\n        paid_amount = paid_amount + p_amount,\r\n        due_amount = due_amount - p_amount,\r\n        updated_at = now()\r\n    WHERE purchase_id = p_purchase_id;\r\n\r\n    -- 8. Update Transaction Header (Paid amount and Status)\r\n    DECLARE\r\n        v_new_paid_amount NUMERIC;\r\n        v_new_due_amount NUMERIC;\r\n        v_new_status public.transaction_status;\r\n    BEGIN\r\n        v_new_paid_amount := v_purchase_record.transaction_paid + p_amount;\r\n        v_new_due_amount := v_purchase_record.transaction_total - v_new_paid_amount;\r\n\r\n        IF ROUND(v_new_paid_amount, 2) >= ROUND(v_purchase_record.transaction_total, 2) THEN\r\n            v_new_status := 'PAID'::public.transaction_status;\r\n            v_new_due_amount := LEAST(v_new_due_amount, 0); -- Cap at 0 or less if overpaid\r\n        ELSE\r\n            v_new_status := 'PARTIALLY_PAID'::public.transaction_status;\r\n        END IF;\r\n\r\n        UPDATE public.transactions\r\n        SET\r\n            paid_amount = v_new_paid_amount,\r\n            due_amount = v_new_due_amount,\r\n            status = v_new_status,\r\n            updated_at = now()\r\n        WHERE transaction_id = v_transaction_id;\r\n    END;\r\n\r\n    -- 9. Verify Balance (Important AFTER all entries for this operation are done)\r\n    PERFORM public.verify_transaction_balance(v_transaction_id);\r\n\r\n    -- 10. Supplier Balance Update (REMOVED - Handled by Trigger)\r\n    -- The 'trigger_update_supplier_balance' on transaction_entries will fire\r\n    -- due to the Debit entry to the A/P account and update suppliers.supplier_balance.\r\n\r\n    RETURN v_payment_id;\r\n\r\nEXCEPTION\r\n    WHEN others THEN\r\n        RAISE EXCEPTION 'Failed to settle purchase payment: %', SQLERRM;\r\nEND;\r\n$function$","CREATE OR REPLACE FUNCTION public.settle_sale_payment(p_sale_id uuid, p_amount numeric, p_payment_mode text, p_payment_date timestamp with time zone)\r\n RETURNS uuid\r\n LANGUAGE plpgsql\r\n SECURITY DEFINER\r\nAS $function$\r\nDECLARE\r\n    v_sale_record         RECORD;\r\n    v_business_id         UUID;\r\n    v_customer_id         UUID; -- Can be NULL if original sale allowed it\r\n    v_transaction_id      UUID;\r\n    v_payment_id          UUID;\r\n    v_payment_account_id  UUID; -- Cash or Bank account ID\r\n    v_receivable_account_id UUID; -- Specific A/R account ID\r\n    v_reference_no        TEXT; -- Reference for the payment itself\r\n    v_user_id             UUID := auth.uid();\r\n\r\n    -- Account Codes\r\n    v_ar_cust_code        TEXT := '1020';\r\n    v_cash_in_bank_code   TEXT := '1011';\r\n    v_petty_cash_code     TEXT := '1010';\r\n\r\nBEGIN\r\n    -- 1. Get sale and related transaction details\r\n    SELECT\r\n        s.sale_id, s.customer_id, s.business_id, s.sale_invoice, s.due_amount as current_sale_due,\r\n        t.transaction_id, t.total_amount as transaction_total, t.paid_amount as transaction_paid, t.status as transaction_status\r\n    INTO v_sale_record\r\n    FROM public.sales s\r\n    JOIN public.transactions t ON s.transaction_id = t.transaction_id\r\n    WHERE s.sale_id = p_sale_id;\r\n\r\n    IF NOT FOUND THEN\r\n        RAISE EXCEPTION 'Sale ID % not found.', p_sale_id;\r\n    END IF;\r\n\r\n    v_business_id := v_sale_record.business_id;\r\n    v_customer_id := v_sale_record.customer_id; -- Might be NULL\r\n    v_transaction_id := v_sale_record.transaction_id;\r\n\r\n    -- 2. Validate payment amount\r\n    IF p_amount <= 0 THEN\r\n         RAISE EXCEPTION 'Payment amount must be positive.';\r\n    END IF;\r\n    -- Use ROUND for safer comparison\r\n    IF ROUND(p_amount, 2) > ROUND(v_sale_record.transaction_total - v_sale_record.transaction_paid, 2) THEN\r\n        RAISE EXCEPTION 'Payment amount % exceeds the remaining due amount % for Sale ID %.',\r\n                        p_amount, (v_sale_record.transaction_total - v_sale_record.transaction_paid), p_sale_id;\r\n    END IF;\r\n    IF v_sale_record.transaction_status = 'PAID'::public.transaction_status THEN\r\n         RAISE EXCEPTION 'Sale ID % is already fully paid.', p_sale_id;\r\n    END IF;\r\n\r\n\r\n    -- 3. Get Account IDs\r\n    SELECT account_id INTO v_receivable_account_id FROM public.accounts WHERE business_id = v_business_id AND code = v_ar_cust_code;\r\n    IF lower(p_payment_mode) = 'cash' THEN\r\n        SELECT account_id INTO v_payment_account_id FROM public.accounts WHERE business_id = v_business_id AND code = v_petty_cash_code;\r\n    ELSE -- Assume Bank, Card, Transfer etc. use the Bank account\r\n        SELECT account_id INTO v_payment_account_id FROM public.accounts WHERE business_id = v_business_id AND code = v_cash_in_bank_code;\r\n    END IF;\r\n\r\n    IF v_receivable_account_id IS NULL OR v_payment_account_id IS NULL THEN\r\n        RAISE EXCEPTION 'Required accounts (A/R Customer or Cash/Bank) not found for business %.', v_business_id;\r\n    END IF;\r\n\r\n    -- 4. Generate Payment Reference Number\r\n    v_reference_no := 'PAY-SAL-' || COALESCE(v_sale_record.sale_invoice, p_sale_id::text) || '-' || upper(substring(gen_random_uuid()::text from 1 for 4));\r\n\r\n    -- 5. Create Payment Record (linking to the original transaction)\r\n    INSERT INTO public.payments (\r\n        transaction_id, payment_date, amount, payment_method, reference_no, created_by\r\n    ) VALUES (\r\n        v_transaction_id, p_payment_date, p_amount, p_payment_mode, v_reference_no, v_user_id\r\n    ) RETURNING payment_id INTO v_payment_id;\r\n\r\n    -- 6. Create Transaction Entries (added to the existing transaction_id)\r\n    -- Debit Cash/Bank (Asset Increase)\r\n    INSERT INTO public.transaction_entries (transaction_id, account_id, entry_type, amount, description)\r\n    VALUES (v_transaction_id, v_payment_account_id, 'DEBIT', p_amount, 'Payment received for Sale Ref ' || v_sale_record.sale_invoice);\r\n\r\n    -- Credit Accounts Receivable (Reducing Asset)\r\n    INSERT INTO public.transaction_entries (transaction_id, account_id, entry_type, amount, description)\r\n    VALUES (v_transaction_id, v_receivable_account_id, 'CREDIT', p_amount, 'Payment received for Sale Ref ' || v_sale_record.sale_invoice);\r\n\r\n    -- 7. Update Sale Header (Track payment progress)\r\n    UPDATE public.sales\r\n    SET\r\n        paid_amount = paid_amount + p_amount,\r\n        due_amount = due_amount - p_amount,\r\n        updated_at = now()\r\n    WHERE sale_id = p_sale_id;\r\n\r\n    -- 8. Update Transaction Header (Paid amount and Status)\r\n    DECLARE\r\n        v_new_paid_amount NUMERIC;\r\n        v_new_due_amount NUMERIC;\r\n        v_new_status public.transaction_status;\r\n    BEGIN\r\n        v_new_paid_amount := v_sale_record.transaction_paid + p_amount;\r\n        v_new_due_amount := v_sale_record.transaction_total - v_new_paid_amount;\r\n\r\n        IF ROUND(v_new_paid_amount, 2) >= ROUND(v_sale_record.transaction_total, 2) THEN\r\n            v_new_status := 'PAID'::public.transaction_status;\r\n            v_new_due_amount := LEAST(v_new_due_amount, 0); -- Cap at 0 or less\r\n        ELSE\r\n            v_new_status := 'PARTIALLY_PAID'::public.transaction_status;\r\n        END IF;\r\n\r\n        UPDATE public.transactions\r\n        SET\r\n            paid_amount = v_new_paid_amount,\r\n            due_amount = v_new_due_amount,\r\n            status = v_new_status,\r\n            updated_at = now()\r\n        WHERE transaction_id = v_transaction_id;\r\n    END;\r\n\r\n    -- 9. Verify Balance\r\n    PERFORM public.verify_transaction_balance(v_transaction_id);\r\n\r\n    -- 10. Customer Balance Update (REMOVED - Handled by Trigger)\r\n    -- The 'trigger_update_customer_balance' on transaction_entries will fire\r\n    -- due to the Credit entry to the A/R account and update business_customers.customer_balance.\r\n\r\n    RETURN v_payment_id;\r\n\r\nEXCEPTION\r\n    WHEN others THEN\r\n        RAISE EXCEPTION 'Failed to settle sale payment: %', SQLERRM;\r\nEND;\r\n$function$","CREATE OR REPLACE FUNCTION public.trigger_clear_sequences()\r\n RETURNS trigger\r\n LANGUAGE plpgsql\r\nAS $function$\r\nBEGIN\r\n    PERFORM clear_sequences(OLD.business_id);\r\n    RETURN OLD;\r\nEND;\r\n$function$","CREATE OR REPLACE FUNCTION public.trigger_create_sequences()\r\n RETURNS trigger\r\n LANGUAGE plpgsql\r\nAS $function$\r\nBEGIN\r\n    PERFORM create_sequences(NEW.business_id);\r\n    RETURN NEW;\r\nEND;\r\n$function$","CREATE OR REPLACE FUNCTION public.update_account_balance()\r\n RETURNS trigger\r\n LANGUAGE plpgsql\r\nAS $function$\r\nDECLARE\r\n    v_account_id UUID;\r\n    v_amount NUMERIC;\r\n    v_entry_type public.entry_type;\r\n    v_multiplier INTEGER;\r\nBEGIN\r\n    IF TG_OP = 'DELETE' THEN\r\n        v_account_id := OLD.account_id;\r\n        v_amount := OLD.amount;\r\n        v_entry_type := OLD.entry_type;\r\n        v_multiplier := -1; -- Reverse the operation\r\n    ELSE -- INSERT or UPDATE\r\n        v_account_id := NEW.account_id;\r\n        v_amount := NEW.amount;\r\n        v_entry_type := NEW.entry_type;\r\n        v_multiplier := 1;\r\n\r\n        -- If UPDATE, first reverse the OLD amount\r\n        IF TG_OP = 'UPDATE' THEN\r\n             -- Ensure we only update if account_id or amount changed\r\n             IF OLD.account_id != NEW.account_id OR OLD.amount != NEW.amount OR OLD.entry_type != NEW.entry_type THEN\r\n                 UPDATE public.accounts\r\n                 SET balance = balance -\r\n                     CASE\r\n                         WHEN OLD.entry_type = 'DEBIT' THEN OLD.amount\r\n                         ELSE -OLD.amount -- Subtracting a negative credit is adding\r\n                     END\r\n                 WHERE account_id = OLD.account_id;\r\n\r\n                 -- If account ID changed, the NEW account update will handle the addition below.\r\n                 -- If only amount/type changed, we proceed to update the same account with the new value.\r\n             ELSE\r\n                -- If relevant fields didn't change, no balance update needed\r\n                RETURN NEW;\r\n             END IF;\r\n        END IF;\r\n    END IF;\r\n\r\n    -- Apply the change (for INSERT, or the NEW value of UPDATE)\r\n    UPDATE public.accounts\r\n    SET balance = balance +\r\n        (CASE\r\n            WHEN v_entry_type = 'DEBIT' THEN v_amount\r\n            ELSE -v_amount\r\n        END * v_multiplier)\r\n    WHERE account_id = v_account_id;\r\n\r\n    RETURN NEW; -- For INSERT/UPDATE\r\nEND;\r\n$function$","CREATE OR REPLACE FUNCTION public.update_customer_balance_from_entry()\r\n RETURNS trigger\r\n LANGUAGE plpgsql\r\nAS $function$\r\nDECLARE\r\n    v_transaction_id UUID;\r\n    v_account_id UUID;\r\n    v_business_id UUID;\r\n    v_customer_id UUID;\r\n    v_ar_account_id UUID; -- Account ID for Accounts Receivable - Customers (1020)\r\n    v_ap_account_id UUID; -- Account ID for Payables to Customers (2011)\r\n    v_recalculated_balance NUMERIC;\r\nBEGIN\r\n    -- Determine which record (NEW or OLD) contains the relevant info\r\n    IF TG_OP = 'DELETE' THEN\r\n        v_transaction_id := OLD.transaction_id;\r\n        v_account_id := OLD.account_id;\r\n    ELSE -- INSERT or UPDATE\r\n        v_transaction_id := NEW.transaction_id;\r\n        v_account_id := NEW.account_id;\r\n    END IF;\r\n\r\n    -- Get business_id and customer_id from the transaction header\r\n    SELECT t.business_id, t.customer_id\r\n    INTO v_business_id, v_customer_id\r\n    FROM public.transactions t\r\n    WHERE t.transaction_id = v_transaction_id;\r\n\r\n    -- If no business or customer found for the transaction, exit\r\n    IF v_business_id IS NULL OR v_customer_id IS NULL THEN\r\n        RETURN NULL;\r\n    END IF;\r\n\r\n    -- Get the specific AR and AP account IDs for THIS business\r\n    SELECT account_id INTO v_ar_account_id FROM public.accounts WHERE business_id = v_business_id AND code = '1020';\r\n    SELECT account_id INTO v_ap_account_id FROM public.accounts WHERE business_id = v_business_id AND code = '2011';\r\n\r\n    -- Check if the affected account is one we track for customer balances\r\n    IF v_account_id != v_ar_account_id AND v_account_id != v_ap_account_id THEN\r\n        RETURN NULL; -- Not a relevant account, do nothing\r\n    END IF;\r\n\r\n    -- Recalculate the net balance for this customer from transaction_entries\r\n    -- *** LOGIC MODIFIED: Positive = Business Owes Customer, Negative = Customer Owes Business ***\r\n    -- Balance = (Credits to A/P - Debits to A/P) - (Debits to A/R - Credits to A/R)\r\n    SELECT COALESCE(SUM(\r\n               CASE\r\n                   -- Accounts Receivable (Asset - What Customer Owes Us): Debit makes balance more negative, Credit makes balance less negative\r\n                   WHEN te.account_id = v_ar_account_id THEN\r\n                       te.amount * (CASE WHEN te.entry_type = 'DEBIT' THEN -1 ELSE 1 END) -- Flipped Sign\r\n                   -- Accounts Payable (Liability - What Business Owes Customer): Credit makes balance more positive, Debit makes balance less positive\r\n                   WHEN te.account_id = v_ap_account_id THEN\r\n                       te.amount * (CASE WHEN te.entry_type = 'CREDIT' THEN 1 ELSE -1 END) -- Flipped Sign\r\n                   ELSE 0 -- Ignore other accounts\r\n               END\r\n           ), 0)\r\n    INTO v_recalculated_balance\r\n    FROM public.transaction_entries te\r\n    JOIN public.transactions t ON te.transaction_id = t.transaction_id\r\n    WHERE t.business_id = v_business_id\r\n      AND t.customer_id = v_customer_id\r\n      AND te.account_id IN (v_ar_account_id, v_ap_account_id); -- Only consider these two accounts\r\n\r\n    -- Update the business_customers table\r\n    UPDATE public.business_customers bc\r\n    SET customer_balance = v_recalculated_balance,\r\n        updated_at = now() -- Keep track of the update\r\n    WHERE bc.business_id = v_business_id\r\n      AND bc.customer_id = v_customer_id;\r\n\r\n    RETURN NULL; -- Trigger is AFTER, return value is ignored\r\n\r\nEXCEPTION\r\n    WHEN others THEN\r\n        -- Log error or handle appropriately\r\n        RAISE WARNING 'Error in update_customer_balance_from_entry trigger: %', SQLERRM;\r\n        RETURN NULL; -- Prevent trigger failure from blocking the original operation\r\nEND;\r\n$function$","CREATE OR REPLACE FUNCTION public.update_sale(p_sale_json jsonb)\r\n RETURNS jsonb\r\n LANGUAGE plpgsql\r\nAS $function$\r\nDECLARE\r\n    v_transaction_id uuid;\r\n    v_sale_id uuid;\r\n    v_business_id uuid;\r\n    v_customer_id uuid;\r\n    v_main_account_id uuid;\r\n    v_receivable_account_id uuid;\r\n    v_sale_date timestamp with time zone;\r\n    v_sale_item record;\r\n    v_existing_sale record;\r\n    v_old_sale_item record;\r\n    v_status_id uuid;\r\n    v_sale_item_id uuid;\r\n    v_subservice record;\r\nBEGIN\r\n    -- Extract key values\r\n    v_sale_id := (p_sale_json->>'sale_id')::uuid;\r\n    v_business_id := (p_sale_json->>'business_id')::uuid;\r\n    v_customer_id := (p_sale_json->>'customer_id')::uuid;\r\n    \r\n    -- Get existing sale information\r\n    SELECT s.*, t.transaction_id, t.paid_amount, t.reference_no\r\n    INTO v_existing_sale\r\n    FROM sales s\r\n    JOIN transactions t ON t.transaction_id = s.transaction_id\r\n    WHERE s.sale_id = v_sale_id;\r\n    \r\n    IF NOT FOUND THEN\r\n        RAISE EXCEPTION 'Sale not found';\r\n    END IF;\r\n    \r\n    v_transaction_id := v_existing_sale.transaction_id;\r\n    \r\n    -- Get account IDs\r\n    SELECT account_id INTO v_main_account_id\r\n    FROM accounts \r\n    WHERE business_id = v_business_id AND code = 'TRP';\r\n    \r\n    SELECT account_id INTO v_receivable_account_id\r\n    FROM accounts \r\n    WHERE business_id = v_business_id AND code = 'MOA';\r\n    \r\n    -- Revert inventory changes for existing sale items\r\n    FOR v_old_sale_item IN \r\n        SELECT si.*, i.item_type, i.inventory_enabled\r\n        FROM sale_items si\r\n        JOIN items i ON i.item_id = si.item_id\r\n        WHERE si.sale_id = v_sale_id\r\n    LOOP\r\n        IF v_old_sale_item.item_type = 'goods' AND v_old_sale_item.inventory_enabled THEN\r\n            UPDATE items\r\n            SET \r\n                stock_quantity = stock_quantity + v_old_sale_item.quantity,\r\n                stock_value = stock_value + (v_old_sale_item.quantity * v_old_sale_item.unit_price)\r\n            WHERE item_id = v_old_sale_item.item_id;\r\n        END IF;\r\n    END LOOP;\r\n    \r\n    -- Delete existing sale items and subservices\r\n    DELETE FROM sale_item_subservices \r\n    WHERE sale_item_id IN (SELECT sale_item_id FROM sale_items WHERE sale_id = v_sale_id);\r\n    DELETE FROM sale_items WHERE sale_id = v_sale_id;\r\n    \r\n    -- Update transaction\r\n    UPDATE transactions\r\n    SET\r\n        total_amount = (p_sale_json->>'grand_total')::numeric,\r\n        due_amount = (p_sale_json->>'grand_total')::numeric - paid_amount,\r\n        metadata = p_sale_json,\r\n        updated_at = CURRENT_TIMESTAMP\r\n    WHERE transaction_id = v_transaction_id;\r\n    \r\n    -- Update transaction entries\r\n    UPDATE transaction_entries\r\n    SET amount = (p_sale_json->>'grand_total')::numeric\r\n    WHERE transaction_id = v_transaction_id;\r\n    \r\n    -- Update sale record\r\n    UPDATE sales\r\n    SET\r\n        customer_id = v_customer_id,\r\n        subtotal = (p_sale_json->>'subtotal')::numeric,\r\n        discount_amount = (p_sale_json->>'discount_amount')::numeric,\r\n        tax_amount = (p_sale_json->>'tax_total')::numeric,\r\n        shipping_charge = (p_sale_json->>'shipping')::numeric,\r\n        total_amount = (p_sale_json->>'grand_total')::numeric,\r\n        due_amount = (p_sale_json->>'grand_total')::numeric - v_existing_sale.paid_amount,\r\n        metadata = p_sale_json,\r\n        updated_at = CURRENT_TIMESTAMP\r\n    WHERE sale_id = v_sale_id;\r\n    \r\n    -- Create new sale items and update inventory\r\n    FOR v_sale_item IN \r\n        SELECT \r\n            x.*,\r\n            i.item_type,\r\n            i.inventory_enabled,\r\n            x.subservices::jsonb as subservices_data\r\n        FROM jsonb_to_recordset(p_sale_json->'sale_items') \r\n        AS x(item_id uuid, quantity numeric, unit_price numeric, subservices jsonb)\r\n        JOIN items i ON i.item_id = x.item_id::uuid\r\n    LOOP\r\n        -- Insert sale item\r\n        INSERT INTO sale_items (\r\n            sale_id,\r\n            item_id,\r\n            quantity,\r\n            unit_price\r\n        ) VALUES (\r\n            v_sale_id,\r\n            v_sale_item.item_id,\r\n            v_sale_item.quantity,\r\n            v_sale_item.unit_price\r\n        ) RETURNING sale_item_id INTO v_sale_item_id;\r\n        \r\n        -- If item is a service and has subservices, add them\r\n        IF v_sale_item.item_type = 'services' AND \r\n           v_sale_item.subservices_data IS NOT NULL AND \r\n           jsonb_array_length(v_sale_item.subservices_data) > 0 THEN\r\n            \r\n            FOR v_subservice IN \r\n                SELECT * FROM jsonb_to_recordset(v_sale_item.subservices_data)\r\n                AS x(sub_service_id uuid, quantity numeric, additional_price numeric)\r\n            LOOP\r\n                INSERT INTO sale_item_subservices (\r\n                    sale_item_id,\r\n                    sub_service_id,\r\n                    quantity,\r\n                    additional_price\r\n                ) VALUES (\r\n                    v_sale_item_id,\r\n                    v_subservice.sub_service_id,\r\n                    v_subservice.quantity,\r\n                    v_subservice.additional_price\r\n                );\r\n            END LOOP;\r\n        END IF;\r\n        \r\n        -- Update item inventory if enabled (only for goods)\r\n        IF v_sale_item.item_type = 'goods' AND v_sale_item.inventory_enabled THEN\r\n            UPDATE items\r\n            SET \r\n                stock_quantity = stock_quantity - v_sale_item.quantity,\r\n                stock_value = stock_value - (v_sale_item.quantity * v_sale_item.unit_price)\r\n            WHERE item_id = v_sale_item.item_id;\r\n        END IF;\r\n    END LOOP;\r\n    \r\n    -- Update business_customers due amount\r\n    UPDATE business_customers \r\n    SET due = due - v_existing_sale.due_amount + ((p_sale_json->>'grand_total')::numeric - v_existing_sale.paid_amount)\r\n    WHERE business_id = v_business_id \r\n    AND customer_id = v_customer_id;\r\n    \r\n    RETURN (SELECT row_to_json(sale_view)\r\n    FROM sale_view\r\n    WHERE sale_id = v_sale_id);\r\nEXCEPTION\r\n    WHEN others THEN\r\n        RAISE EXCEPTION 'Error in update_sale: %', SQLERRM;\r\nEND;\r\n$function$","CREATE OR REPLACE FUNCTION public.update_supplier_balance_from_entry()\r\n RETURNS trigger\r\n LANGUAGE plpgsql\r\nAS $function$\r\nDECLARE\r\n    v_transaction_id UUID;\r\n    v_account_id UUID;\r\n    v_business_id UUID;\r\n    v_supplier_id UUID;\r\n    v_ap_supp_acc_id UUID; -- Account ID for Accounts Payable - Suppliers (2010)\r\n    v_ar_supp_acc_id UUID; -- Account ID for Receivables from Suppliers (1021)\r\n    v_recalculated_balance NUMERIC;\r\nBEGIN\r\n    -- Determine which record (NEW or OLD) contains the relevant info\r\n    IF TG_OP = 'DELETE' THEN\r\n        v_transaction_id := OLD.transaction_id;\r\n        v_account_id := OLD.account_id;\r\n    ELSE -- INSERT or UPDATE\r\n        v_transaction_id := NEW.transaction_id;\r\n        v_account_id := NEW.account_id;\r\n    END IF;\r\n\r\n    -- Get business_id and supplier_id from the transaction header\r\n    SELECT t.business_id, t.supplier_id\r\n    INTO v_business_id, v_supplier_id\r\n    FROM public.transactions t\r\n    WHERE t.transaction_id = v_transaction_id;\r\n\r\n    -- If no business or supplier found for the transaction, exit\r\n    IF v_business_id IS NULL OR v_supplier_id IS NULL THEN\r\n        RETURN NULL;\r\n    END IF;\r\n\r\n    -- Get the specific AP and AR account IDs for THIS business\r\n    SELECT account_id INTO v_ap_supp_acc_id FROM public.accounts WHERE business_id = v_business_id AND code = '2010';\r\n    SELECT account_id INTO v_ar_supp_acc_id FROM public.accounts WHERE business_id = v_business_id AND code = '1021';\r\n\r\n    -- Check if the affected account is one we track for supplier balances\r\n    IF v_account_id != v_ap_supp_acc_id AND v_account_id != v_ar_supp_acc_id THEN\r\n        RETURN NULL; -- Not a relevant account, do nothing\r\n    END IF;\r\n\r\n    -- Recalculate the net balance for this supplier from transaction_entries\r\n    -- *** LOGIC MODIFIED: Positive = Supplier Owes Business, Negative = Business Owes Supplier ***\r\n    -- Balance = (Debits to A/R - Credits to A/R) - (Credits to A/P - Debits to A/P)\r\n    SELECT COALESCE(SUM(\r\n               CASE\r\n                   -- Accounts Payable (Liability - What Business Owes): Credit makes balance more negative, Debit makes balance less negative\r\n                   WHEN te.account_id = v_ap_supp_acc_id THEN\r\n                       te.amount * (CASE WHEN te.entry_type = 'CREDIT' THEN 1 ELSE -1 END) -- Flipped Sign\r\n                   -- Accounts Receivable (Asset - What Supplier Owes): Debit makes balance more positive, Credit makes balance less positive\r\n                   WHEN te.account_id = v_ar_supp_acc_id THEN\r\n                       te.amount * (CASE WHEN te.entry_type = 'DEBIT' THEN -1 ELSE 1 END) -- Flipped Sign\r\n                   ELSE 0 -- Ignore other accounts\r\n               END\r\n           ), 0)\r\n    INTO v_recalculated_balance\r\n    FROM public.transaction_entries te\r\n    JOIN public.transactions t ON te.transaction_id = t.transaction_id\r\n    WHERE t.business_id = v_business_id\r\n      AND t.supplier_id = v_supplier_id\r\n      AND te.account_id IN (v_ap_supp_acc_id, v_ar_supp_acc_id); -- Only consider these two accounts\r\n\r\n    -- Update the suppliers table\r\n    UPDATE public.suppliers s\r\n    SET supplier_balance = v_recalculated_balance,\r\n        updated_at = now() -- Keep track of the update\r\n    WHERE s.supplier_id = v_supplier_id;\r\n\r\n    RETURN NULL; -- Trigger is AFTER, return value is ignored\r\n\r\nEXCEPTION\r\n    WHEN others THEN\r\n        RAISE WARNING 'Error in update_supplier_balance_from_entry trigger: %', SQLERRM;\r\n        RETURN NULL;\r\nEND;\r\n$function$","CREATE OR REPLACE FUNCTION public.upsert_business_customer(p_customer_data jsonb)\r\n RETURNS void\r\n LANGUAGE plpgsql\r\nAS $function$\r\nDECLARE\r\n    -- Input Data\r\n    v_business_id UUID := p_customer_data->>'business_id';\r\n    v_customer_id UUID := p_customer_data->>'customer_id';\r\n    v_name TEXT := p_customer_data->>'name';\r\n    v_image TEXT := p_customer_data->>'image';\r\n    v_address TEXT := p_customer_data->>'address';\r\n    v_opening_balance NUMERIC := COALESCE((p_customer_data->>'customer_balance')::numeric, 0); -- Default to 0\r\n    v_opening_balance_date TIMESTAMPTZ := now();\r\n\r\n    -- Internal Variables\r\n    v_user_id UUID := COALESCE(auth.uid(), v_customer_id); -- Assuming Supabase auth\r\n    v_upsert_result RECORD;\r\n    v_is_insert BOOLEAN := FALSE;\r\n    v_transaction_id UUID;\r\n    v_ref_no TEXT;\r\n\r\n    -- Account IDs\r\n    v_ar_cust_acc_id UUID;   -- Accounts Receivable - Customers (1020)\r\n    v_ap_cust_acc_id UUID;   -- Payables to Customers (2011)\r\n    v_ob_equity_acc_id UUID; -- Opening Balance Equity (3900)\r\n\r\n    -- Account Codes\r\n    v_ar_cust_code TEXT := '1020';\r\n    v_ap_cust_code TEXT := '2011';\r\n    v_ob_equity_code TEXT := '3900';\r\nBEGIN\r\n    -- Validate required inputs\r\n    IF v_business_id IS NULL OR v_customer_id IS NULL OR v_name IS NULL THEN\r\n        RAISE EXCEPTION 'business_id, customer_id, and name are required.';\r\n    END IF;\r\n\r\n    -- Perform Upsert using INSERT ON CONFLICT\r\n    WITH upsert AS (\r\n        INSERT INTO public.business_customers (\r\n            business_id, customer_id, name, image, address, customer_balance, created_at, updated_at\r\n        ) VALUES (\r\n            v_business_id, v_customer_id, v_name, v_image, v_address, v_opening_balance, now(), now()\r\n        )\r\n        ON CONFLICT (business_id, customer_id) DO UPDATE SET\r\n            name = EXCLUDED.name,\r\n            image = EXCLUDED.image,\r\n            address = EXCLUDED.address,\r\n            updated_at = now()\r\n            -- DO NOT update customer_balance here on conflict!\r\n        RETURNING xmax -- xmax = 0 for INSERT, non-zero for UPDATE\r\n    )\r\n    SELECT xmax INTO v_upsert_result FROM upsert;\r\n\r\n    -- Check if an INSERT occurred (xmax = 0 indicates INSERT)\r\n    IF v_upsert_result.xmax = 0 THEN\r\n        v_is_insert := TRUE;\r\n    END IF;\r\n\r\n    -- If it was an INSERT AND an opening balance was provided and is non-zero\r\n    IF v_is_insert AND v_opening_balance != 0 THEN\r\n\r\n        -- Fetch required account IDs for the business\r\n        SELECT account_id INTO v_ar_cust_acc_id FROM public.accounts WHERE business_id = v_business_id AND code = v_ar_cust_code;\r\n        SELECT account_id INTO v_ap_cust_acc_id FROM public.accounts WHERE business_id = v_business_id AND code = v_ap_cust_code;\r\n        SELECT account_id INTO v_ob_equity_acc_id FROM public.accounts WHERE business_id = v_business_id AND code = v_ob_equity_code;\r\n\r\n        -- Validate that accounts exist\r\n        IF v_ob_equity_acc_id IS NULL THEN\r\n             RAISE EXCEPTION 'Opening Balance Equity account (Code: %) not found for business %.', v_ob_equity_code, v_business_id;\r\n        END IF;\r\n        IF v_opening_balance > 0 AND v_ar_cust_acc_id IS NULL THEN\r\n             RAISE EXCEPTION 'Accounts Receivable - Customers account (Code: %) not found for business %.', v_ar_cust_code, v_business_id;\r\n        END IF;\r\n         IF v_opening_balance < 0 AND v_ap_cust_acc_id IS NULL THEN\r\n             RAISE EXCEPTION 'Payables to Customers account (Code: %) not found for business %.', v_ap_cust_code, v_business_id;\r\n        END IF;\r\n\r\n        -- Generate a unique reference number for the opening balance transaction\r\n        v_ref_no := 'OB-CUST-' || v_customer_id::text || '-' || to_char(v_opening_balance_date, 'YYYYMMDD');\r\n\r\n        -- Create the Transaction Header\r\n        INSERT INTO public.transactions (\r\n            reference_no, transaction_type, transaction_date, status,\r\n            total_amount, paid_amount, due_amount, -- Amounts represent the magnitude of the balance being set up\r\n            notes, business_id, created_by, customer_id -- Link to customer\r\n        ) VALUES (\r\n            v_ref_no, 'CUSTOMER_OPENING_BALANCE'::public.transaction_type, v_opening_balance_date, 'PAID'::public.transaction_status, -- Mark as PAID/Complete\r\n            abs(v_opening_balance), abs(v_opening_balance), 0,\r\n            'Opening balance setup for customer ' || v_name, v_business_id, v_user_id, v_customer_id\r\n        ) RETURNING transaction_id INTO v_transaction_id;\r\n\r\n        -- Create Transaction Entries based on balance sign\r\n        IF v_opening_balance < 0 THEN\r\n            -- Customer owes Business: Debit A/R, Credit OB Equity\r\n            INSERT INTO public.transaction_entries (transaction_id, account_id, entry_type, amount, description)\r\n            VALUES\r\n                (v_transaction_id, v_ar_cust_acc_id, 'DEBIT'::public.entry_type, v_opening_balance, 'Opening balance receivable'),\r\n                (v_transaction_id, v_ob_equity_acc_id, 'CREDIT'::public.entry_type, v_opening_balance, 'Opening balance equity offset');\r\n        ELSE -- v_opening_balance < 0\r\n            -- Business owes Customer: Debit OB Equity, Credit A/P\r\n            INSERT INTO public.transaction_entries (transaction_id, account_id, entry_type, amount, description)\r\n            VALUES\r\n                (v_transaction_id, v_ob_equity_acc_id, 'DEBIT'::public.entry_type, abs(v_opening_balance), 'Opening balance equity offset'),\r\n                (v_transaction_id, v_ap_cust_acc_id, 'CREDIT'::public.entry_type, abs(v_opening_balance), 'Opening balance payable');\r\n        END IF;\r\n\r\n        -- Verify the balance of the opening balance transaction itself\r\n        PERFORM public.verify_transaction_balance(v_transaction_id);\r\n\r\n        -- Note: The trigger `trigger_update_customer_balance` on `transaction_entries`\r\n        -- should fire automatically due to the inserts above and correctly set the\r\n        -- `customer_balance` in `business_customers` based on these new entries.\r\n        -- The initial insert into business_customers already set the balance,\r\n        -- but the trigger recalculating based on GL entries ensures consistency.\r\n\r\n    END IF; -- End of opening balance handling\r\n\r\n    RETURN; -- Function returns void\r\n\r\nEXCEPTION\r\n    WHEN unique_violation THEN\r\n        -- This might occur if the generated reference_no collides, though unlikely.\r\n        RAISE EXCEPTION 'Failed to upsert customer OB: Unique constraint violated. Check reference number \\"%\\". Detail: %', v_ref_no, SQLERRM;\r\n    WHEN others THEN\r\n        -- Catch potential errors like account not found or balance verification failure\r\n        RAISE EXCEPTION 'Failed to upsert business customer: %', v_user_id;\r\nEND;\r\n$function$","CREATE OR REPLACE FUNCTION public.upsert_employee_role(employee_role_json jsonb)\r\n RETURNS void\r\n LANGUAGE plpgsql\r\nAS $function$\r\nDECLARE\r\n    v_employee_role_id UUID;\r\n    v_permission JSONB;\r\n    v_submenu JSONB;\r\nBEGIN\r\n    -- Check if employee_role_id is provided\r\n    IF (employee_role_json->>'employee_role_id') IS NOT NULL THEN\r\n        v_employee_role_id := (employee_role_json->>'employee_role_id')::UUID;\r\n        \r\n        -- Update existing employee role\r\n        UPDATE public.employee_roles\r\n        SET \r\n            name = COALESCE(employee_role_json->>'name', name),\r\n            description = COALESCE(employee_role_json->>'description', description)\r\n        WHERE employee_role_id = v_employee_role_id;\r\n    ELSE\r\n        -- Insert new employee role\r\n        INSERT INTO public.employee_roles (name, description, editable, business_id)\r\n        VALUES (employee_role_json->>'name', employee_role_json->>'description', true, (employee_role_json->>'business_id')::uuid)\r\n        RETURNING employee_role_id INTO v_employee_role_id;\r\n    END IF;\r\n\r\n    -- Delete existing permissions for this role\r\n    DELETE FROM public.permissions WHERE employee_role_id = v_employee_role_id;\r\n\r\n    -- Insert new permissions\r\n    FOR v_permission IN SELECT * FROM jsonb_array_elements(employee_role_json->'permissions')\r\n    LOOP\r\n        -- Insert main module permission\r\n        INSERT INTO public.permissions (employee_role_id, module_id, view, \\"create\\", edit, delete, print)\r\n        VALUES (\r\n            v_employee_role_id,\r\n            (v_permission->>'id')::bigint,\r\n            (v_permission->'permissions'->>'view')::boolean,\r\n            (v_permission->'permissions'->>'add')::boolean,\r\n            (v_permission->'permissions'->>'edit')::boolean,\r\n            (v_permission->'permissions'->>'delete')::boolean,\r\n            (v_permission->'permissions'->>'print')::boolean\r\n        );\r\n\r\n        -- Insert submenu permissions\r\n        FOR v_submenu IN SELECT * FROM jsonb_array_elements(v_permission->'submenus')\r\n        LOOP\r\n            INSERT INTO public.permissions (employee_role_id, module_id, link_id, view, \\"create\\", edit, delete, print)\r\n            VALUES (\r\n                v_employee_role_id,\r\n                (v_permission->>'id')::bigint,\r\n                (v_submenu->>'id')::bigint,\r\n                (v_submenu->'permissions'->>'view')::boolean,\r\n                (v_submenu->'permissions'->>'add')::boolean,\r\n                (v_submenu->'permissions'->>'edit')::boolean,\r\n                (v_submenu->'permissions'->>'delete')::boolean,\r\n                (v_submenu->'permissions'->>'print')::boolean\r\n            );\r\n        END LOOP;\r\n    END LOOP;\r\nEND;\r\n$function$","CREATE OR REPLACE FUNCTION public.upsert_expense(p_expense_data jsonb)\r\n RETURNS uuid\r\n LANGUAGE plpgsql\r\nAS $function$\r\nDECLARE\r\n    v_expense_id UUID := p_expense_data->>'expense_id';\r\n    v_transaction_id UUID;\r\n    v_business_id UUID := p_expense_data->>'business_id';\r\n    v_user_id UUID := auth.uid(); -- Assuming you use Supabase auth\r\n    v_date TIMESTAMPTZ := (p_expense_data->>'date')::timestamptz;\r\n    v_amount NUMERIC := (p_expense_data->>'amount')::numeric;\r\n    v_expense_account_id UUID; -- Determined based on default\r\n    v_payment_account_id UUID; -- Determined based on payment_type\r\n    v_expense_for TEXT := p_expense_data->>'expense_for';\r\n    v_payment_type public.payment_type := (p_expense_data->>'payment_type')::public.payment_type;\r\n    v_note TEXT := p_expense_data->>'note';\r\n    v_reference_number TEXT := p_expense_data->>'reference_number';\r\n    v_expense_category_id UUID := (p_expense_data->>'expense_category_id')::uuid; -- Optional link to expense_categories table\r\n    v_existing_txn_id UUID;\r\n    v_ref_no TEXT;\r\n    v_default_expense_code TEXT := '6090'; -- Code for 'General Expense'\r\n    v_petty_cash_code TEXT := '1010';    -- Code for 'Petty Cash'\r\n    v_cash_in_bank_code TEXT := '1011';  -- Code for 'Cash in Bank'\r\nBEGIN\r\n    -- Validate required fields from JSON\r\n    IF v_business_id IS NULL OR v_date IS NULL OR v_amount IS NULL OR v_amount <= 0 OR v_expense_for IS NULL OR v_payment_type IS NULL THEN\r\n        RAISE EXCEPTION 'Missing required expense data: business_id, date, amount > 0, expense_for, payment_type are required.';\r\n    END IF;\r\n\r\n    -- Fetch the default expense account ID\r\n    SELECT account_id INTO v_expense_account_id\r\n    FROM public.accounts\r\n    WHERE business_id = v_business_id AND code = v_default_expense_code AND is_group = FALSE;\r\n\r\n    IF v_expense_account_id IS NULL THEN\r\n        RAISE EXCEPTION 'Default expense account (Code: %) not found for business_id %.', v_default_expense_code, v_business_id;\r\n    END IF;\r\n\r\n    -- Determine the payment account ID based on payment_type\r\n    IF v_payment_type = 'cash' THEN -- Adjust type names if needed\r\n        SELECT account_id INTO v_payment_account_id\r\n        FROM public.accounts\r\n        WHERE business_id = v_business_id AND code = v_petty_cash_code AND is_group = FALSE;\r\n\r\n        IF v_payment_account_id IS NULL THEN\r\n            RAISE EXCEPTION 'Petty Cash account (Code: %) not found for business_id %.', v_petty_cash_code, v_business_id;\r\n        END IF;\r\n    ELSE -- Assume Bank, Card, Transfer, Other map to Cash in Bank\r\n        SELECT account_id INTO v_payment_account_id\r\n        FROM public.accounts\r\n        WHERE business_id = v_business_id AND code = v_cash_in_bank_code AND is_group = FALSE;\r\n\r\n        IF v_payment_account_id IS NULL THEN\r\n            RAISE EXCEPTION 'Cash in Bank account (Code: %) not found for business_id %.', v_cash_in_bank_code, v_business_id;\r\n        END IF;\r\n    END IF;\r\n\r\n    -- Generate a reference number if not provided (example logic)\r\n    IF v_reference_number IS NULL OR v_reference_number = '' THEN\r\n         v_ref_no := 'EXP-' || to_char(v_date, 'YYYYMMDD') || '-' || upper(substring(gen_random_uuid()::text from 1 for 6));\r\n    ELSE\r\n        v_ref_no := v_reference_number;\r\n    END IF;\r\n\r\n    IF v_expense_id IS NOT NULL THEN\r\n        -- ======== UPDATE PATH ========\r\n        SELECT transaction_id INTO v_existing_txn_id\r\n        FROM public.expenses\r\n        WHERE expense_id = v_expense_id AND business_id = v_business_id;\r\n\r\n        IF v_existing_txn_id IS NULL THEN\r\n            RAISE EXCEPTION 'Expense with ID % not found for business %.', v_expense_id, v_business_id;\r\n        END IF;\r\n\r\n        v_transaction_id := v_existing_txn_id;\r\n\r\n        -- Update Transaction Header (assuming immediate payment)\r\n        UPDATE public.transactions\r\n        SET\r\n            reference_no = v_ref_no,\r\n            transaction_date = v_date,\r\n            total_amount = v_amount,\r\n            paid_amount = v_amount,\r\n            due_amount = 0,\r\n            status = 'PAID'::public.transaction_status,\r\n            notes = v_note,\r\n            updated_at = now()\r\n        WHERE transaction_id = v_transaction_id\r\n          AND business_id = v_business_id;\r\n\r\n        -- Check potential unique violation on reference_no if it changed\r\n        IF NOT FOUND AND v_reference_number IS NOT NULL THEN\r\n             PERFORM 1 FROM public.transactions\r\n             WHERE reference_no = v_ref_no\r\n               AND business_id = v_business_id\r\n               AND transaction_id != v_transaction_id;\r\n             IF FOUND THEN\r\n                 RAISE EXCEPTION 'Reference number \\"%\\" already exists for another transaction in this business.', v_ref_no;\r\n             END IF;\r\n             RAISE EXCEPTION 'Failed to update transaction header for ID %.', v_transaction_id;\r\n        END IF;\r\n\r\n        -- Update Expense Details\r\n        UPDATE public.expenses\r\n        SET\r\n            date = v_date,\r\n            payment_type = v_payment_type,\r\n            expense_for = v_expense_for,\r\n            amount = v_amount,\r\n            note = v_note,\r\n            reference_number = v_ref_no,\r\n            expense_category_id = v_expense_category_id\r\n        WHERE expense_id = v_expense_id;\r\n\r\n        -- Recreate Transaction Entries (Delete old, Insert new using fetched account IDs)\r\n        DELETE FROM public.transaction_entries WHERE transaction_id = v_transaction_id;\r\n\r\n        INSERT INTO public.transaction_entries (transaction_id, account_id, entry_type, amount, description)\r\n        VALUES\r\n            (v_transaction_id, v_expense_account_id, 'DEBIT'::public.entry_type, v_amount, v_expense_for),\r\n            (v_transaction_id, v_payment_account_id, 'CREDIT'::public.entry_type, v_amount, 'Payment for ' || v_expense_for);\r\n\r\n    ELSE\r\n        -- ======== INSERT PATH ========\r\n        -- Create Transaction Header (assuming immediate payment)\r\n        INSERT INTO public.transactions (\r\n            reference_no, transaction_type, transaction_date, status,\r\n            total_amount, paid_amount, due_amount, notes, business_id, created_by\r\n        ) VALUES (\r\n            v_ref_no, 'EXPENSE'::public.transaction_type, v_date, 'PAID'::public.transaction_status,\r\n            v_amount, v_amount, 0, v_note, v_business_id, v_user_id\r\n        ) RETURNING transaction_id INTO v_transaction_id;\r\n\r\n        -- Create Expense Record\r\n        INSERT INTO public.expenses (\r\n            date, payment_type, expense_for, amount, note, reference_number,\r\n            business_id, expense_category_id, transaction_id\r\n        ) VALUES (\r\n            v_date, v_payment_type, v_expense_for, v_amount, v_note, v_ref_no,\r\n            v_business_id, v_expense_category_id, v_transaction_id\r\n        ) RETURNING expense_id INTO v_expense_id;\r\n\r\n        -- Create Transaction Entries (using fetched account IDs)\r\n        INSERT INTO public.transaction_entries (transaction_id, account_id, entry_type, amount, description)\r\n        VALUES\r\n            (v_transaction_id, v_expense_account_id, 'DEBIT'::public.entry_type, v_amount, v_expense_for),\r\n            (v_transaction_id, v_payment_account_id, 'CREDIT'::public.entry_type, v_amount, 'Payment for ' || v_expense_for);\r\n\r\n    END IF;\r\n\r\n    -- ============ FINAL VALIDATION STEP ============\r\n    -- This ensures balance AFTER all entries for this expense are created/updated\r\n    PERFORM public.verify_transaction_balance(v_transaction_id);\r\n    -- ==============================================\r\n\r\n    RETURN v_expense_id;\r\n\r\nEXCEPTION\r\n    WHEN unique_violation THEN\r\n        RAISE EXCEPTION 'Failed to upsert expense: Unique constraint violated. Check reference number \\"%\\". Detail: %', v_ref_no, SQLERRM;\r\n    WHEN others THEN\r\n        RAISE EXCEPTION 'Failed to upsert expense: %', SQLERRM;\r\nEND;\r\n$function$","CREATE OR REPLACE FUNCTION public.upsert_income(p_income_data jsonb)\r\n RETURNS uuid\r\n LANGUAGE plpgsql\r\nAS $function$\r\nDECLARE\r\n    v_income_id UUID := p_income_data->>'income_id';\r\n    v_transaction_id UUID;\r\n    v_business_id UUID := p_income_data->>'business_id';\r\n    v_user_id UUID := auth.uid(); -- Assuming you use Supabase auth\r\n    v_date TIMESTAMPTZ := (p_income_data->>'date')::timestamptz;\r\n    v_amount NUMERIC := (p_income_data->>'amount')::numeric;\r\n    v_income_account_id UUID; -- Default Income Account\r\n    v_asset_account_id UUID;  -- Account where money is received (Cash/Bank)\r\n    v_income_for TEXT := p_income_data->>'income_for';\r\n    v_payment_type public.payment_type := (p_income_data->>'payment_type')::public.payment_type;\r\n    v_note TEXT := p_income_data->>'note';\r\n    v_reference_number TEXT := p_income_data->>'reference_number';\r\n    v_income_category_id UUID := (p_income_data->>'income_category_id')::uuid; -- Optional link to income_categories table\r\n    v_existing_txn_id UUID;\r\n    v_ref_no TEXT;\r\n    v_default_income_code TEXT := '4030'; -- Code for 'Income from Other Sources'\r\n    v_petty_cash_code TEXT := '1010';     -- Code for 'Petty Cash'\r\n    v_cash_in_bank_code TEXT := '1011';   -- Code for 'Cash in Bank'\r\nBEGIN\r\n    -- Validate required fields from JSON\r\n    IF v_business_id IS NULL OR v_date IS NULL OR v_amount IS NULL OR v_amount <= 0 OR v_income_for IS NULL OR v_payment_type IS NULL THEN\r\n        RAISE EXCEPTION 'Missing required income data: business_id, date, amount > 0, income_for, payment_type are required.';\r\n    END IF;\r\n\r\n    -- Fetch the default income account ID\r\n    SELECT account_id INTO v_income_account_id\r\n    FROM public.accounts\r\n    WHERE business_id = v_business_id AND code = v_default_income_code AND is_group = FALSE;\r\n\r\n    IF v_income_account_id IS NULL THEN\r\n        RAISE EXCEPTION 'Default income account (Code: %) not found for business_id %.', v_default_income_code, v_business_id;\r\n    END IF;\r\n\r\n    -- Determine the asset account ID based on payment_type\r\n    IF v_payment_type = 'cash' THEN -- Adjust type names if needed\r\n        SELECT account_id INTO v_asset_account_id\r\n        FROM public.accounts\r\n        WHERE business_id = v_business_id AND code = v_petty_cash_code AND is_group = FALSE;\r\n\r\n        IF v_asset_account_id IS NULL THEN\r\n            RAISE EXCEPTION 'Petty Cash account (Code: %) not found for business_id %.', v_petty_cash_code, v_business_id;\r\n        END IF;\r\n    ELSE -- Assume Bank, Card, Transfer, Other map to Cash in Bank\r\n        SELECT account_id INTO v_asset_account_id\r\n        FROM public.accounts\r\n        WHERE business_id = v_business_id AND code = v_cash_in_bank_code AND is_group = FALSE;\r\n\r\n        IF v_asset_account_id IS NULL THEN\r\n            RAISE EXCEPTION 'Cash in Bank account (Code: %) not found for business_id %.', v_cash_in_bank_code, v_business_id;\r\n        END IF;\r\n    END IF;\r\n\r\n    -- Generate a reference number if not provided (example logic)\r\n    IF v_reference_number IS NULL OR v_reference_number = '' THEN\r\n         v_ref_no := 'INC-' || to_char(v_date, 'YYYYMMDD') || '-' || upper(substring(gen_random_uuid()::text from 1 for 6));\r\n    ELSE\r\n        v_ref_no := v_reference_number;\r\n    END IF;\r\n\r\n    IF v_income_id IS NOT NULL THEN\r\n        -- ======== UPDATE PATH ========\r\n        SELECT transaction_id INTO v_existing_txn_id\r\n        FROM public.incomes\r\n        WHERE income_id = v_income_id AND business_id = v_business_id;\r\n\r\n        IF v_existing_txn_id IS NULL THEN\r\n            RAISE EXCEPTION 'Income with ID % not found for business %.', v_income_id, v_business_id;\r\n        END IF;\r\n\r\n        v_transaction_id := v_existing_txn_id;\r\n\r\n        -- Update Transaction Header (assuming immediate receipt)\r\n        UPDATE public.transactions\r\n        SET\r\n            reference_no = v_ref_no,\r\n            transaction_date = v_date,\r\n            total_amount = v_amount,\r\n            paid_amount = v_amount, -- Income is 'paid' immediately in this model\r\n            due_amount = 0,         -- No amount is 'due' to be received\r\n            status = 'PAID'::public.transaction_status, -- Or maybe 'RECEIVED'? Using PAID for consistency\r\n            notes = v_note,\r\n            updated_at = now()\r\n            -- transaction_type and created_by are not updated\r\n        WHERE transaction_id = v_transaction_id\r\n          AND business_id = v_business_id;\r\n\r\n        -- Check potential unique violation on reference_no if it changed\r\n        IF NOT FOUND AND v_reference_number IS NOT NULL THEN\r\n             PERFORM 1 FROM public.transactions\r\n             WHERE reference_no = v_ref_no\r\n               AND business_id = v_business_id\r\n               AND transaction_id != v_transaction_id;\r\n             IF FOUND THEN\r\n                 RAISE EXCEPTION 'Reference number \\"%\\" already exists for another transaction in this business.', v_ref_no;\r\n             END IF;\r\n             RAISE EXCEPTION 'Failed to update transaction header for ID %.', v_transaction_id;\r\n        END IF;\r\n\r\n        -- Update Income Details\r\n        UPDATE public.incomes\r\n        SET\r\n            date = v_date,\r\n            payment_type = v_payment_type,\r\n            income_for = v_income_for,\r\n            amount = v_amount,\r\n            note = v_note,\r\n            reference_number = v_ref_no,\r\n            income_category_id = v_income_category_id\r\n        WHERE income_id = v_income_id;\r\n\r\n        -- Recreate Transaction Entries (Delete old, Insert new using fetched account IDs)\r\n        DELETE FROM public.transaction_entries WHERE transaction_id = v_transaction_id;\r\n\r\n        INSERT INTO public.transaction_entries (transaction_id, account_id, entry_type, amount, description)\r\n        VALUES\r\n            -- Income received increases Asset (Debit)\r\n            (v_transaction_id, v_asset_account_id, 'DEBIT'::public.entry_type, v_amount, 'Received income for ' || v_income_for),\r\n            -- Income increases Revenue/Equity (Credit)\r\n            (v_transaction_id, v_income_account_id, 'CREDIT'::public.entry_type, v_amount, v_income_for);\r\n\r\n    ELSE\r\n        -- ======== INSERT PATH ========\r\n        -- Create Transaction Header (assuming immediate receipt)\r\n        INSERT INTO public.transactions (\r\n            reference_no, transaction_type, transaction_date, status,\r\n            total_amount, paid_amount, due_amount, notes, business_id, created_by\r\n        ) VALUES (\r\n            v_ref_no, 'INCOME'::public.transaction_type, v_date, 'PAID'::public.transaction_status, -- Or maybe 'RECEIVED'?\r\n            v_amount, v_amount, 0, v_note, v_business_id, v_user_id\r\n        ) RETURNING transaction_id INTO v_transaction_id;\r\n\r\n        -- Create Income Record\r\n        INSERT INTO public.incomes (\r\n            date, payment_type, income_for, amount, note, reference_number,\r\n            business_id, income_category_id, transaction_id\r\n        ) VALUES (\r\n            v_date, v_payment_type, v_income_for, v_amount, v_note, v_ref_no,\r\n            v_business_id, v_income_category_id, v_transaction_id\r\n        ) RETURNING income_id INTO v_income_id;\r\n\r\n        -- Create Transaction Entries (using fetched account IDs)\r\n        INSERT INTO public.transaction_entries (transaction_id, account_id, entry_type, amount, description)\r\n        VALUES\r\n            -- Income received increases Asset (Debit)\r\n            (v_transaction_id, v_asset_account_id, 'DEBIT'::public.entry_type, v_amount, 'Received income for ' || v_income_for),\r\n            -- Income increases Revenue/Equity (Credit)\r\n            (v_transaction_id, v_income_account_id, 'CREDIT'::public.entry_type, v_amount, v_income_for);\r\n\r\n    END IF;\r\n\r\n    -- ============ FINAL VALIDATION STEP ============\r\n    PERFORM public.verify_transaction_balance(v_transaction_id);\r\n    -- ==============================================\r\n\r\n    RETURN v_income_id;\r\n\r\nEXCEPTION\r\n    WHEN unique_violation THEN\r\n        RAISE EXCEPTION 'Failed to upsert income: Unique constraint violated. Check reference number \\"%\\". Detail: %', v_ref_no, SQLERRM;\r\n    WHEN others THEN\r\n        IF SQLERRM LIKE 'Double-entry imbalance for transaction %' THEN\r\n             RAISE EXCEPTION '%', SQLERRM; -- Re-raise the specific balance error\r\n        ELSE\r\n             RAISE EXCEPTION 'Failed to upsert income: %', SQLERRM; -- Raise other errors\r\n        END IF;\r\nEND;\r\n$function$","CREATE OR REPLACE FUNCTION public.upsert_item(item_json jsonb)\r\n RETURNS uuid\r\n LANGUAGE plpgsql\r\nAS $function$\r\nDECLARE\r\n    -- Input Extraction\r\n    v_item_id_in              UUID := (item_json->>'item_id')::uuid;\r\n    v_business_id           UUID := (item_json->>'business_id')::uuid;\r\n    v_org_id                UUID := (item_json->>'org_id')::uuid;\r\n    v_name                  TEXT := item_json->>'name';\r\n    v_item_type             public.item_type := (item_json->>'item_type')::public.item_type;\r\n    v_item_category_id      UUID := (item_json->>'item_category_id')::uuid;\r\n    v_brand_id              UUID := (item_json->>'brand_id')::uuid;\r\n    v_tax_id                UUID := (item_json->>'tax_id')::uuid;\r\n    v_preferred_vendor_id   UUID := (item_json->>'preferred_vendor_id')::uuid;\r\n    v_item_code             TEXT := item_json->>'item_code'; -- Use provided code or generate below\r\n    v_unit_id               UUID := (item_json->>'unit_id')::uuid;\r\n    v_sale_price            NUMERIC := COALESCE((item_json->>'sale_price')::numeric, 0);\r\n    v_purchase_price        NUMERIC := COALESCE((item_json->>'purchase_price')::numeric, 0);\r\n    v_is_returnable         BOOLEAN := COALESCE((item_json->>'is_returnable')::boolean, false);\r\n    v_alert_quantity        NUMERIC := COALESCE((item_json->>'alert_quantity')::numeric, 0);\r\n    v_rich_text             JSONB := item_json->'rich_text';\r\n    v_sales_enabled         BOOLEAN := COALESCE((item_json->>'sales_enabled')::boolean, true);\r\n    v_purchase_enabled      BOOLEAN := COALESCE((item_json->>'purchase_enabled')::boolean, true);\r\n    v_inventory_enabled     BOOLEAN := COALESCE((item_json->>'inventory_enabled')::boolean, true);\r\n    v_opening_stock_qty     NUMERIC := COALESCE((item_json->>'opening_stock_qty')::numeric, 0); -- Renamed JSON key for clarity\r\n    v_opening_stock_value   NUMERIC := COALESCE((item_json->>'opening_stock_value')::numeric, 0); -- Renamed JSON key for clarity\r\n\r\n    -- Arrays\r\n    v_serial_nos            TEXT[];\r\n    v_images                JSONB[];\r\n\r\n    -- Internal Vars\r\n    v_item_id_out           UUID;\r\n    v_is_insert             BOOLEAN := FALSE;\r\n    v_transaction_id        UUID;\r\n    v_ob_ref_no             TEXT;\r\n    v_user_id               UUID := auth.uid(); -- Assuming Supabase auth\r\n\r\n    -- Account IDs & Codes\r\n    v_inventory_account_id  UUID;\r\n    v_ob_equity_account_id  UUID;\r\n    v_inventory_code        TEXT := '1030'; -- Standard Inventory Account Code\r\n    v_ob_equity_code        TEXT := '3900'; -- Standard Opening Balance Equity Code\r\n\r\nBEGIN\r\n    -- Extract arrays\r\n    SELECT array_agg(value::text) INTO v_serial_nos FROM jsonb_array_elements_text(COALESCE(item_json->'serial_nos', '[]'::jsonb));\r\n    SELECT array_agg(value::jsonb) INTO v_images FROM jsonb_array_elements(COALESCE(item_json->'images', '[]'::jsonb)); -- Fixed array aggregation for JSONB\r\n\r\n-- Check if item_code is provided and if it has changed\r\nIF v_item_code IS NULL THEN\r\n    -- Generate item_code if not provided (using a sequence per business is robust)\r\n    SELECT get_next_item_code(v_business_id) INTO v_item_code;\r\n    RAISE WARNING 'Item code not provided, generated: %', v_item_code;\r\nEND IF;\r\n\r\n-- Check uniqueness of item_code only if it's being changed (i.e., it's different from the original item code)\r\nIF v_item_code != (SELECT item_code FROM public.items WHERE item_id = v_item_id_in AND business_id = v_business_id) THEN\r\n    PERFORM 1 FROM public.items WHERE business_id = v_business_id AND item_code = v_item_code;\r\n    IF FOUND THEN\r\n        RAISE EXCEPTION 'Item code % already exists for business %.', v_item_code, v_business_id;\r\n    END IF;\r\nEND IF;\r\n    -- ==== INSERT or UPDATE ====\r\n    IF v_item_id_in IS NULL THEN\r\n        -- ======== INSERT PATH ========\r\n        v_is_insert := TRUE;\r\n\r\n        INSERT INTO public.items (\r\n            name, item_type, item_code, item_category_id, brand_id, unit_id,\r\n            sales_enabled, purchase_enabled, inventory_enabled, is_returnable,\r\n            sale_price, purchase_price, alert_quantity, preferred_vendor_id,\r\n            tax_id, images, serial_nos, rich_text,\r\n            business_id, org_id,\r\n            -- Set initial stock based on opening values\r\n            stock_quantity, stock_value,\r\n            opening_stock_qty, opening_stock_value,\r\n            created_at, updated_at\r\n            -- branch_variant_id defaults in table definition\r\n        ) VALUES (\r\n            v_name, v_item_type, v_item_code, v_item_category_id, v_brand_id, v_unit_id,\r\n            v_sales_enabled, v_purchase_enabled, v_inventory_enabled, v_is_returnable,\r\n            v_sale_price, v_purchase_price, v_alert_quantity, v_preferred_vendor_id,\r\n            v_tax_id, v_images, v_serial_nos, v_rich_text,\r\n            v_business_id, v_org_id,\r\n            -- Initial stock IS the opening stock\r\n            v_opening_stock_qty, v_opening_stock_value,\r\n            v_opening_stock_qty, v_opening_stock_value,\r\n            now(), now()\r\n        )\r\n        RETURNING item_id INTO v_item_id_out;\r\n\r\n        -- Handle subservices on insert\r\n        IF v_item_type = 'services' AND item_json->'sub_services' IS NOT NULL THEN\r\n            WITH sub_services AS (\r\n                SELECT * FROM jsonb_array_elements(item_json->'sub_services')\r\n            )\r\n            INSERT INTO public.subservices (service_id, name, additional_price)\r\n            SELECT\r\n                v_item_id_out,\r\n                sub_services.value->>'name',\r\n                (sub_services.value->>'additional_price')::numeric\r\n            FROM sub_services;\r\n            -- WHERE sub_services.value->>'sub_service_id' IS NULL; -- Not needed on initial insert\r\n        END IF;\r\n\t\tPERFORM nextval(v_business_id::text || '_item_code'); -- Removed redundant nextval call\r\n    ELSE\r\n        -- ======== UPDATE PATH ========\r\n        v_item_id_out := v_item_id_in;\r\n        v_is_insert := FALSE;\r\n\r\n        UPDATE public.items SET\r\n            name = v_name,\r\n            item_code = v_item_code, -- Allow item code update? Maybe only if unique constraint allows.\r\n            item_category_id = v_item_category_id,\r\n            brand_id = v_brand_id,\r\n            unit_id = v_unit_id,\r\n            sales_enabled = v_sales_enabled,\r\n            purchase_enabled = v_purchase_enabled,\r\n            inventory_enabled = v_inventory_enabled,\r\n            is_returnable = v_is_returnable,\r\n            sale_price = v_sale_price,\r\n            purchase_price = v_purchase_price,\r\n            alert_quantity = v_alert_quantity,\r\n            preferred_vendor_id = v_preferred_vendor_id,\r\n            tax_id = v_tax_id,\r\n            images = v_images,\r\n            serial_nos = v_serial_nos,\r\n            rich_text = v_rich_text,\r\n            updated_at = now()\r\n            -- DO NOT UPDATE opening_stock_qty, opening_stock_value, stock_quantity, stock_value here.\r\n            -- Stock changes happen via Purchase, Sale, Adjustment transactions.\r\n        WHERE item_id = v_item_id_out\r\n          AND business_id = v_business_id;\r\n\r\n        IF NOT FOUND THEN\r\n            RAISE EXCEPTION 'Item ID % not found for business %.', v_item_id_out, v_business_id;\r\n        END IF;\r\n\r\n        -- Handle subservice updates\r\n        IF v_item_type = 'services' AND item_json->'sub_services' IS NOT NULL THEN\r\n             -- Delete sub-services not in the new list\r\n            DELETE FROM public.subservices s\r\n            WHERE s.service_id = v_item_id_out\r\n            AND NOT EXISTS (\r\n                SELECT 1\r\n                FROM jsonb_array_elements(item_json->'sub_services') elem\r\n                WHERE elem->>'sub_service_id' IS NOT NULL AND (elem->>'sub_service_id')::uuid = s.sub_service_id\r\n            );\r\n\r\n            -- Insert new sub-services (those without an ID in the input)\r\n            WITH sub_services AS (\r\n                SELECT * FROM jsonb_array_elements(item_json->'sub_services')\r\n                WHERE value->>'sub_service_id' IS NULL\r\n            )\r\n            INSERT INTO public.subservices (service_id, name, additional_price)\r\n            SELECT\r\n                v_item_id_out,\r\n                sub_services.value->>'name',\r\n                (sub_services.value->>'additional_price')::numeric\r\n            FROM sub_services;\r\n\r\n            -- Update existing sub-services (those with an ID in the input)\r\n            UPDATE public.subservices s\r\n            SET\r\n                name = sub.name,\r\n                additional_price = sub.additional_price\r\n            FROM (\r\n                SELECT\r\n                    (elem->>'sub_service_id')::uuid as sub_service_id,\r\n                    elem->>'name' as name,\r\n                    (elem->>'additional_price')::numeric as additional_price\r\n                FROM jsonb_array_elements(item_json->'sub_services') elem\r\n                WHERE elem->>'sub_service_id' IS NOT NULL\r\n            ) sub\r\n            WHERE s.sub_service_id = sub.sub_service_id\r\n            AND s.service_id = v_item_id_out;\r\n        END IF;\r\n\r\n    END IF; -- End INSERT/UPDATE Check\r\n\r\n    -- ==== OPENING BALANCE ACCOUNTING (INSERT ONLY) ====\r\n    IF v_is_insert AND v_inventory_enabled AND v_opening_stock_value != 0 THEN\r\n\r\n        -- Fetch required account IDs for the business\r\n        SELECT account_id INTO v_inventory_account_id FROM public.accounts WHERE business_id = v_business_id AND code = v_inventory_code;\r\n        SELECT account_id INTO v_ob_equity_account_id FROM public.accounts WHERE business_id = v_business_id AND code = v_ob_equity_code;\r\n\r\n        -- Validate that accounts exist\r\n        IF v_inventory_account_id IS NULL THEN\r\n             RAISE EXCEPTION 'Inventory account (Code: %) not found for business %.', v_inventory_code, v_business_id;\r\n        END IF;\r\n        IF v_ob_equity_account_id IS NULL THEN\r\n             RAISE EXCEPTION 'Opening Balance Equity account (Code: %) not found for business %.', v_ob_equity_code, v_business_id;\r\n        END IF;\r\n\r\n        -- Generate a unique reference number for the opening balance transaction\r\n        v_ob_ref_no := 'OB-ITEM-' || v_item_id_out::text; -- Simple reference\r\n\r\n        -- Create the Transaction Header\r\n        INSERT INTO public.transactions (\r\n            reference_no, transaction_type, transaction_date, status,\r\n            total_amount, paid_amount, due_amount,\r\n            notes, business_id, created_by,\r\n            item_id -- Link to item\r\n        ) VALUES (\r\n            v_ob_ref_no, 'OPENING_STOCK'::public.transaction_type, now(), 'PAID'::public.transaction_status, -- Mark as PAID/Complete\r\n            abs(v_opening_stock_value), abs(v_opening_stock_value), 0, -- OB is self-balancing\r\n            'Opening stock value for item ' || v_name || ' (' || v_item_code || ')', v_business_id, v_user_id,\r\n            v_item_id_out\r\n        ) RETURNING transaction_id INTO v_transaction_id;\r\n\r\n        -- Create Correct Transaction Entries\r\n        -- Debit Inventory (Asset Increase), Credit OB Equity (Offset)\r\n        INSERT INTO public.transaction_entries (transaction_id, account_id, entry_type, amount, description)\r\n        VALUES\r\n            (v_transaction_id, v_inventory_account_id, 'DEBIT'::public.entry_type, v_opening_stock_value, 'Opening stock value'),\r\n            (v_transaction_id, v_ob_equity_account_id, 'CREDIT'::public.entry_type, v_opening_stock_value, 'Opening balance equity offset');\r\n\r\n        -- Verify the balance of the opening balance transaction itself\r\n        PERFORM public.verify_transaction_balance(v_transaction_id);\r\n\r\n    END IF; -- End Opening Balance Accounting\r\n\r\n    RETURN v_item_id_out;\r\n\r\nEXCEPTION\r\n    WHEN unique_violation THEN\r\n        -- Could be item_code constraint or generated OB reference_no collision\r\n        RAISE EXCEPTION 'Failed to upsert item: Unique constraint violated. Check item code \\"%\\". Detail: %', v_item_code, SQLERRM;\r\n    WHEN others THEN\r\n        RAISE EXCEPTION 'Failed to upsert item: %', SQLERRM;\r\nEND;\r\n$function$","CREATE OR REPLACE FUNCTION public.upsert_supplier(p_supplier_data jsonb)\r\n RETURNS uuid\r\n LANGUAGE plpgsql\r\nAS $function$\r\nDECLARE\r\n    -- Input Data\r\n    v_supplier_id UUID := p_supplier_data->>'supplier_id';\r\n    v_business_id UUID := p_supplier_data->>'business_id';\r\n    v_org_id UUID := p_supplier_data->>'org_id';\r\n    v_name TEXT := p_supplier_data->>'name';\r\n    v_email TEXT := p_supplier_data->>'email';\r\n    v_phone TEXT := p_supplier_data->>'phone';\r\n    v_address TEXT := p_supplier_data->>'address';\r\n    v_gst_number TEXT := p_supplier_data->>'gst_number';\r\n    v_image TEXT := p_supplier_data->>'image';\r\n    -- Input opening_balance uses the new convention: >0 Supplier Owes Us, <0 We Owe Supplier\r\n    v_opening_balance NUMERIC := COALESCE((p_supplier_data->>'supplier_balance')::numeric, 0);\r\n    v_opening_balance_date TIMESTAMPTZ := now();\r\n\r\n    -- Internal Variables\r\n    v_user_id UUID := auth.uid();\r\n    v_is_insert BOOLEAN := FALSE;\r\n    v_transaction_id UUID;\r\n    v_ref_no TEXT;\r\n    v_result_supplier_id UUID;\r\n\r\n    -- Account IDs\r\n    v_ap_supp_acc_id UUID;   -- Accounts Payable - Suppliers (2010)\r\n    v_ar_supp_acc_id UUID;   -- Receivables from Suppliers (1021)\r\n    v_ob_equity_acc_id UUID; -- Opening Balance Equity (3900)\r\n\r\n    -- Account Codes\r\n    v_ap_supp_code TEXT := '2010';\r\n    v_ar_supp_code TEXT := '1021';\r\n    v_ob_equity_code TEXT := '3900';\r\nBEGIN\r\n    -- Validate required inputs\r\n    IF v_business_id IS NULL OR v_org_id IS NULL OR v_name IS NULL OR v_phone IS NULL THEN\r\n        RAISE EXCEPTION 'business_id, org_id, name, and phone are required.';\r\n    END IF;\r\n\r\n    -- Handle INSERT or UPDATE\r\n    IF v_supplier_id IS NULL THEN\r\n        -- ======== INSERT PATH ========\r\n        v_is_insert := TRUE;\r\n        INSERT INTO public.suppliers (\r\n            supplier_id, name, email, phone, address, gst_number,\r\n            business_id, org_id, image, created_at, updated_at,\r\n            supplier_balance -- Start balance at 0, trigger will adjust if OB applied\r\n        ) VALUES (\r\n            gen_random_uuid(), v_name, v_email, v_phone, v_address, v_gst_number,\r\n            v_business_id, v_org_id, v_image, now(), now(),\r\n            0\r\n        ) RETURNING suppliers.supplier_id INTO v_result_supplier_id;\r\n    ELSE\r\n        -- ======== UPDATE PATH ========\r\n        v_is_insert := FALSE;\r\n        UPDATE public.suppliers\r\n        SET\r\n            name = v_name,\r\n            email = v_email,\r\n            phone = v_phone,\r\n            address = v_address,\r\n            gst_number = v_gst_number,\r\n            image = v_image,\r\n            updated_at = now()\r\n        WHERE supplier_id = v_supplier_id\r\n          AND business_id = v_business_id\r\n        RETURNING suppliers.supplier_id INTO v_result_supplier_id;\r\n\r\n        IF NOT FOUND THEN\r\n            RAISE EXCEPTION 'Supplier with ID % not found for business %.', v_supplier_id, v_business_id;\r\n        END IF;\r\n    END IF;\r\n\r\n\r\n    -- If it was an INSERT AND an opening balance was provided and is non-zero\r\n    IF v_is_insert AND v_opening_balance != 0 THEN\r\n\r\n        -- Fetch required account IDs\r\n        SELECT account_id INTO v_ap_supp_acc_id FROM public.accounts WHERE business_id = v_business_id AND code = v_ap_supp_code;\r\n        SELECT account_id INTO v_ar_supp_acc_id FROM public.accounts WHERE business_id = v_business_id AND code = v_ar_supp_code;\r\n        SELECT account_id INTO v_ob_equity_acc_id FROM public.accounts WHERE business_id = v_business_id AND code = v_ob_equity_code;\r\n\r\n        -- Validate that accounts exist\r\n        IF v_ob_equity_acc_id IS NULL THEN\r\n             RAISE EXCEPTION 'Opening Balance Equity account (Code: %) not found for business %.', v_ob_equity_code, v_business_id;\r\n        END IF;\r\n        -- Positive OB: Supplier owes Business -> Need A/R Account\r\n        IF v_opening_balance > 0 AND v_ar_supp_acc_id IS NULL THEN\r\n             RAISE EXCEPTION 'Receivables from Suppliers account (Code: %) not found for business %.', v_ar_supp_code, v_business_id;\r\n        END IF;\r\n        -- Negative OB: Business owes Supplier -> Need A/P Account\r\n         IF v_opening_balance < 0 AND v_ap_supp_acc_id IS NULL THEN\r\n             RAISE EXCEPTION 'Accounts Payable - Suppliers account (Code: %) not found for business %.', v_ap_supp_code, v_business_id;\r\n        END IF;\r\n\r\n        -- Generate a unique reference number\r\n        v_ref_no := 'OB-SUPP-' || v_result_supplier_id::text || '-' || to_char(v_opening_balance_date, 'YYYYMMDD');\r\n\r\n        -- Create the Transaction Header\r\n        INSERT INTO public.transactions (\r\n            reference_no, transaction_type, transaction_date, status,\r\n            total_amount, paid_amount, due_amount,\r\n            notes, business_id, created_by, supplier_id -- Link to supplier\r\n        ) VALUES (\r\n            v_ref_no, 'SUPPLIER_OPENING_BALANCE'::public.transaction_type, v_opening_balance_date, 'PAID'::public.transaction_status,\r\n            abs(v_opening_balance), abs(v_opening_balance), 0,\r\n            'Opening balance setup for supplier ' || v_name, v_business_id, v_user_id, v_result_supplier_id\r\n        ) RETURNING transaction_id INTO v_transaction_id;\r\n\r\n        -- *** MODIFIED GL ENTRIES FOR OPENING BALANCE ***\r\n        IF v_opening_balance < 0 THEN\r\n            -- Positive OB means Supplier Owes Business (Asset): Debit A/R, Credit OB Equity\r\n            INSERT INTO public.transaction_entries (transaction_id, account_id, entry_type, amount, description)\r\n            VALUES\r\n                (v_transaction_id, v_ar_supp_acc_id, 'DEBIT'::public.entry_type, v_opening_balance, 'Opening balance receivable from supplier'),\r\n                (v_transaction_id, v_ob_equity_acc_id, 'CREDIT'::public.entry_type, v_opening_balance, 'Opening balance equity offset');\r\n        ELSE -- v_opening_balance < 0\r\n            -- Negative OB means Business Owes Supplier (Liability): Debit OB Equity, Credit A/P\r\n            INSERT INTO public.transaction_entries (transaction_id, account_id, entry_type, amount, description)\r\n            VALUES\r\n                (v_transaction_id, v_ob_equity_acc_id, 'DEBIT'::public.entry_type, abs(v_opening_balance), 'Opening balance equity offset'),\r\n                (v_transaction_id, v_ap_supp_acc_id, 'CREDIT'::public.entry_type, abs(v_opening_balance), 'Opening balance payable to supplier');\r\n        END IF;\r\n\r\n        -- Verify the balance of the opening balance transaction itself\r\n        PERFORM public.verify_transaction_balance(v_transaction_id);\r\n\r\n        -- The trigger trigger_update_supplier_balance will update suppliers.supplier_balance\r\n\r\n    END IF; -- End of opening balance handling\r\n\r\n    RETURN v_result_supplier_id;\r\n\r\nEXCEPTION\r\n    WHEN unique_violation THEN\r\n        RAISE EXCEPTION 'Failed to upsert supplier OB: Unique constraint violated. Detail: %', SQLERRM;\r\n    WHEN others THEN\r\n        RAISE EXCEPTION 'Failed to upsert supplier: %', SQLERRM;\r\nEND;\r\n$function$","create or replace view \\"public\\".\\"v_purchase_return_items\\" as  SELECT pri.return_item_id,\r\n    pri.return_id,\r\n    pri.purchase_item_id,\r\n    pri.quantity AS return_quantity,\r\n    pri.unit_price AS return_unit_price,\r\n    pri.total_price AS return_total_price,\r\n    pi.item_id,\r\n    i.name AS item_name,\r\n    i.item_code,\r\n    pi.quantity AS original_quantity,\r\n    pi.unit_price AS original_unit_price,\r\n    pi.total_price AS original_total_price,\r\n    pri.created_at,\r\n    pri.updated_at\r\n   FROM ((purchase_return_items pri\r\n     JOIN purchase_items pi ON ((pri.purchase_item_id = pi.purchase_item_id)))\r\n     JOIN items i ON ((pi.item_id = i.item_id)))","create or replace view \\"public\\".\\"v_purchase_returns\\" as  SELECT pr.return_id,\r\n    pr.purchase_id,\r\n    pr.return_invoice,\r\n    pr.return_date,\r\n    pr.reason,\r\n    pr.notes,\r\n    pr.total_amount AS return_amount,\r\n    pr.transaction_id,\r\n    pr.business_id,\r\n    pr.created_by,\r\n    pr.created_at,\r\n    pr.updated_at,\r\n    p.invoice_no AS purchase_invoice,\r\n    p.purchase_date,\r\n    p.total_amount AS original_purchase_amount,\r\n    (row_to_json(s.*))::jsonb AS supplier,\r\n    t.reference_no AS transaction_reference,\r\n    t.status AS transaction_status,\r\n    t.total_amount AS transaction_amount,\r\n    t.paid_amount AS transaction_paid_amount,\r\n    t.due_amount AS transaction_due_amount,\r\n    e.name AS created_by_name,\r\n    ( SELECT jsonb_agg(jsonb_build_object('return_item_id', pri.return_item_id, 'item_id', i.item_id, 'item_name', i.name, 'item_code', i.item_code, 'return_quantity', pri.quantity, 'return_unit_price', pri.unit_price, 'return_total_price', pri.total_price, 'original_quantity', pi.quantity, 'original_unit_price', pi.unit_price, 'original_total_price', pi.total_price)) AS jsonb_agg\r\n           FROM ((purchase_return_items pri\r\n             JOIN purchase_items pi ON ((pri.purchase_item_id = pi.purchase_item_id)))\r\n             JOIN items i ON ((pi.item_id = i.item_id)))\r\n          WHERE (pri.return_id = pr.return_id)) AS return_items,\r\n    ( SELECT jsonb_agg(jsonb_build_object('entry_id', te.entry_id, 'account_id', te.account_id, 'account_name', a.name, 'entry_type', te.entry_type, 'amount', te.amount, 'description', te.description)) AS jsonb_agg\r\n           FROM (transaction_entries te\r\n             JOIN accounts a ON ((te.account_id = a.account_id)))\r\n          WHERE (te.transaction_id = pr.transaction_id)) AS accounting_entries\r\n   FROM ((((purchase_returns pr\r\n     JOIN purchases p ON ((pr.purchase_id = p.purchase_id)))\r\n     JOIN transactions t ON ((pr.transaction_id = t.transaction_id)))\r\n     JOIN employees e ON ((pr.created_by = e.employee_id)))\r\n     LEFT JOIN suppliers s ON ((p.supplier_id = s.supplier_id)))","create or replace view \\"public\\".\\"v_purchase_returns_summary\\" as  SELECT pr.business_id,\r\n    date_trunc('day'::text, pr.return_date) AS return_date,\r\n    count(*) AS total_returns,\r\n    sum(pr.total_amount) AS total_return_amount,\r\n    count(DISTINCT p.supplier_id) AS unique_suppliers,\r\n    jsonb_agg(jsonb_build_object('return_invoice', pr.return_invoice, 'amount', pr.total_amount, 'supplier', s.name, 'reason', pr.reason)) AS returns_list\r\n   FROM ((purchase_returns pr\r\n     JOIN purchases p ON ((pr.purchase_id = p.purchase_id)))\r\n     LEFT JOIN suppliers s ON ((p.supplier_id = s.supplier_id)))\r\n  GROUP BY pr.business_id, (date_trunc('day'::text, pr.return_date))","create or replace view \\"public\\".\\"v_sale_return_items\\" as  SELECT sri.return_item_id,\r\n    sri.return_id,\r\n    sri.sale_item_id,\r\n    sri.quantity AS return_quantity,\r\n    sri.unit_price AS return_unit_price,\r\n    sri.total_price AS return_total_price,\r\n    si.item_id,\r\n    i.name AS item_name,\r\n    i.item_code,\r\n    si.quantity AS original_quantity,\r\n    si.unit_price AS original_unit_price,\r\n    si.total_price AS original_total_price,\r\n    sri.created_at,\r\n    sri.updated_at\r\n   FROM ((sale_return_items sri\r\n     JOIN sale_items si ON ((sri.sale_item_id = si.sale_item_id)))\r\n     JOIN items i ON ((si.item_id = i.item_id)))","create or replace view \\"public\\".\\"v_sale_returns\\" as  SELECT sr.return_id,\r\n    sr.sale_id,\r\n    sr.return_invoice,\r\n    sr.return_date,\r\n    sr.reason,\r\n    sr.notes,\r\n    sr.total_amount AS return_amount,\r\n    sr.transaction_id,\r\n    sr.business_id,\r\n    sr.created_by,\r\n    sr.created_at,\r\n    sr.updated_at,\r\n    s.sale_invoice,\r\n    s.sale_date,\r\n    s.total_amount AS original_sale_amount,\r\n    (row_to_json(c.*))::jsonb AS customer,\r\n    t.reference_no AS transaction_reference,\r\n    t.status AS transaction_status,\r\n    t.total_amount AS transaction_amount,\r\n    t.paid_amount AS transaction_paid_amount,\r\n    t.due_amount AS transaction_due_amount,\r\n    e.name AS created_by_name,\r\n    ( SELECT jsonb_agg(jsonb_build_object('return_item_id', sri.return_item_id, 'item_id', i.item_id, 'item_name', i.name, 'item_code', i.item_code, 'return_quantity', sri.quantity, 'return_unit_price', sri.unit_price, 'return_total_price', sri.total_price, 'original_quantity', si.quantity, 'original_unit_price', si.unit_price, 'original_total_price', si.total_price)) AS jsonb_agg\r\n           FROM ((sale_return_items sri\r\n             JOIN sale_items si ON ((sri.sale_item_id = si.sale_item_id)))\r\n             JOIN items i ON ((si.item_id = i.item_id)))\r\n          WHERE (sri.return_id = sr.return_id)) AS return_items,\r\n    ( SELECT jsonb_agg(jsonb_build_object('entry_id', te.entry_id, 'account_id', te.account_id, 'account_name', a.name, 'entry_type', te.entry_type, 'amount', te.amount, 'description', te.description)) AS jsonb_agg\r\n           FROM (transaction_entries te\r\n             JOIN accounts a ON ((te.account_id = a.account_id)))\r\n          WHERE (te.transaction_id = sr.transaction_id)) AS accounting_entries\r\n   FROM ((((sale_returns sr\r\n     JOIN sales s ON ((sr.sale_id = s.sale_id)))\r\n     JOIN transactions t ON ((sr.transaction_id = t.transaction_id)))\r\n     JOIN employees e ON ((sr.created_by = e.employee_id)))\r\n     LEFT JOIN business_customer_view c ON ((s.customer_id = c.customer_id)))","create or replace view \\"public\\".\\"v_sale_returns_summary\\" as  SELECT sr.business_id,\r\n    date_trunc('day'::text, sr.return_date) AS return_date,\r\n    count(*) AS total_returns,\r\n    sum(sr.total_amount) AS total_return_amount,\r\n    count(DISTINCT s.customer_id) AS unique_customers,\r\n    jsonb_agg(jsonb_build_object('return_invoice', sr.return_invoice, 'amount', sr.total_amount, 'customer', c.name, 'reason', sr.reason)) AS returns_list\r\n   FROM ((sale_returns sr\r\n     JOIN sales s ON ((sr.sale_id = s.sale_id)))\r\n     LEFT JOIN customers c ON ((s.customer_id = c.customer_id)))\r\n  GROUP BY sr.business_id, (date_trunc('day'::text, sr.return_date))","CREATE OR REPLACE FUNCTION public.verify_transaction_balance(p_transaction_id uuid)\r\n RETURNS void\r\n LANGUAGE plpgsql\r\nAS $function$\r\nDECLARE\r\n    v_debit_total NUMERIC := 0;\r\n    v_credit_total NUMERIC := 0;\r\nBEGIN\r\n    -- Calculate totals for the given transaction ID based on current state within the transaction\r\n    SELECT\r\n        COALESCE(SUM(CASE WHEN entry_type = 'DEBIT' THEN amount ELSE 0 END), 0),\r\n        COALESCE(SUM(CASE WHEN entry_type = 'CREDIT' THEN amount ELSE 0 END), 0)\r\n    INTO v_debit_total, v_credit_total\r\n    FROM public.transaction_entries\r\n    WHERE transaction_id = p_transaction_id;\r\n\r\n    -- Using a small tolerance might be wise if you ever use floating-point types,\r\n    -- but with NUMERIC, direct comparison should be fine.\r\n    -- IF abs(v_debit_total - v_credit_total) > 0.0001 THEN -- Example with tolerance\r\n    IF v_debit_total != v_credit_total THEN\r\n        RAISE EXCEPTION 'Double-entry imbalance for transaction %: Debits (%) do not equal Credits (%).',\r\n            p_transaction_id, v_debit_total, v_credit_total;\r\n    END IF;\r\n\r\n    -- If balanced, simply return\r\nEND;\r\n$function$","CREATE OR REPLACE FUNCTION public.verify_user_password(password text)\r\n RETURNS boolean\r\n LANGUAGE plpgsql\r\n SECURITY DEFINER\r\n SET search_path TO 'public', 'extensions'\r\nAS $function$\r\nBEGIN\r\n  RETURN EXISTS (\r\n    SELECT id \r\n    FROM auth.users \r\n    WHERE id = auth.uid() AND encrypted_password = crypt(password::text, auth.users.encrypted_password)\r\n  );\r\nEND;\r\n$function$","create or replace view \\"public\\".\\"vw_daily_transactions_report_v2\\" as  WITH transaction_details AS (\r\n         SELECT t.transaction_id,\r\n            t.transaction_date,\r\n            t.transaction_type,\r\n            t.total_amount,\r\n            t.business_id,\r\n            t.reference_no AS transaction_ref_no,\r\n            COALESCE(\r\n                CASE\r\n                    WHEN (t.transaction_type = 'SALE'::transaction_type) THEN bc.name\r\n                    WHEN (t.transaction_type = 'SALE_RETURN'::transaction_type) THEN bc_return.name\r\n                    WHEN (t.transaction_type = 'PURCHASE'::transaction_type) THEN sup.name\r\n                    WHEN (t.transaction_type = 'PURCHASE_RETURN'::transaction_type) THEN sup_return.name\r\n                    WHEN (t.transaction_type = 'INCOME'::transaction_type) THEN COALESCE(inc.income_for, 'Income'::text)\r\n                    WHEN (t.transaction_type = 'EXPENSE'::transaction_type) THEN COALESCE(exp.expense_for, 'Expense'::text)\r\n                    WHEN (t.transaction_type = 'STOCK_ADJUSTMENT'::transaction_type) THEN 'Stock Adjustment'::text\r\n                    WHEN (t.transaction_type = 'CUSTOMER_OPENING_BALANCE'::transaction_type) THEN 'Opening Balance - Customer'::text\r\n                    WHEN (t.transaction_type = 'SUPPLIER_OPENING_BALANCE'::transaction_type) THEN 'Opening Balance - Supplier'::text\r\n                    WHEN (t.transaction_type = 'OPENING_STOCK'::transaction_type) THEN 'Opening Balance - Item Stock'::text\r\n                    ELSE 'Other Transaction'::text\r\n                END, 'Walk-in'::text) AS name,\r\n                CASE\r\n                    WHEN (t.transaction_type = 'SALE'::transaction_type) THEN 'Sale'::text\r\n                    WHEN (t.transaction_type = 'SALE_RETURN'::transaction_type) THEN 'Sale Return'::text\r\n                    WHEN (t.transaction_type = 'PURCHASE'::transaction_type) THEN 'Purchase'::text\r\n                    WHEN (t.transaction_type = 'PURCHASE_RETURN'::transaction_type) THEN 'Purchase Return'::text\r\n                    WHEN (t.transaction_type = 'INCOME'::transaction_type) THEN ('Income - '::text || COALESCE(ic.name, inc.income_for, 'Other'::text))\r\n                    WHEN (t.transaction_type = 'EXPENSE'::transaction_type) THEN ('Expense - '::text || COALESCE(ec.name, exp.expense_for, 'Other'::text))\r\n                    WHEN (t.transaction_type = 'STOCK_ADJUSTMENT'::transaction_type) THEN 'Stock Adjustment'::text\r\n                    WHEN (t.transaction_type = ANY (ARRAY['CUSTOMER_OPENING_BALANCE'::transaction_type, 'SUPPLIER_OPENING_BALANCE'::transaction_type, 'OPENING_STOCK'::transaction_type])) THEN 'Opening Balance Setup'::text\r\n                    ELSE initcap(replace((t.transaction_type)::text, '_'::text, ' '::text))\r\n                END AS type,\r\n            lower((t.transaction_type)::text) AS transaction_category,\r\n            p.payment_id,\r\n            p.payment_date,\r\n            p.amount AS payment_amount,\r\n            p.payment_method,\r\n            p.reference_no AS payment_ref_no\r\n           FROM (((((((((((((((transactions t\r\n             LEFT JOIN payments p ON ((t.transaction_id = p.transaction_id)))\r\n             LEFT JOIN sales s ON (((s.transaction_id = t.transaction_id) AND (t.transaction_type = 'SALE'::transaction_type))))\r\n             LEFT JOIN business_customers bc ON (((bc.customer_id = s.customer_id) AND (bc.business_id = t.business_id))))\r\n             LEFT JOIN sale_returns sr ON (((sr.transaction_id = t.transaction_id) AND (t.transaction_type = 'SALE_RETURN'::transaction_type))))\r\n             LEFT JOIN sales s_return ON ((s_return.sale_id = sr.sale_id)))\r\n             LEFT JOIN business_customers bc_return ON (((bc_return.customer_id = s_return.customer_id) AND (bc_return.business_id = t.business_id))))\r\n             LEFT JOIN purchases pur ON (((pur.transaction_id = t.transaction_id) AND (t.transaction_type = 'PURCHASE'::transaction_type))))\r\n             LEFT JOIN suppliers sup ON ((sup.supplier_id = pur.supplier_id)))\r\n             LEFT JOIN purchase_returns pr ON (((pr.transaction_id = t.transaction_id) AND (t.transaction_type = 'PURCHASE_RETURN'::transaction_type))))\r\n             LEFT JOIN purchases p_return ON ((p_return.purchase_id = pr.purchase_id)))\r\n             LEFT JOIN suppliers sup_return ON ((sup_return.supplier_id = p_return.supplier_id)))\r\n             LEFT JOIN incomes inc ON (((inc.transaction_id = t.transaction_id) AND (t.transaction_type = 'INCOME'::transaction_type))))\r\n             LEFT JOIN income_categories ic ON ((ic.category_id = inc.income_category_id)))\r\n             LEFT JOIN expenses exp ON (((exp.transaction_id = t.transaction_id) AND (t.transaction_type = 'EXPENSE'::transaction_type))))\r\n             LEFT JOIN expense_categories ec ON ((ec.category_id = exp.expense_category_id)))\r\n          WHERE ((t.status IS DISTINCT FROM 'REVERSED'::transaction_status) AND (t.status IS DISTINCT FROM 'CANCELLED'::transaction_status))\r\n        ), daily_movements AS (\r\n         SELECT COALESCE(td.payment_date, td.transaction_date) AS date,\r\n            td.name,\r\n            td.type,\r\n            td.total_amount AS transaction_total,\r\n                CASE\r\n                    WHEN ((td.payment_id IS NOT NULL) AND (td.transaction_category = ANY (ARRAY['sale'::text, 'income'::text, 'purchase_return'::text]))) THEN td.payment_amount\r\n                    ELSE NULL::numeric\r\n                END AS payment_in,\r\n                CASE\r\n                    WHEN ((td.payment_id IS NOT NULL) AND (td.transaction_category = ANY (ARRAY['purchase'::text, 'expense'::text, 'sale_return'::text]))) THEN td.payment_amount\r\n                    ELSE NULL::numeric\r\n                END AS payment_out,\r\n            td.payment_method,\r\n            td.payment_id,\r\n            td.transaction_id,\r\n            COALESCE(td.payment_ref_no, td.transaction_ref_no) AS reference_no,\r\n            td.transaction_category,\r\n            td.business_id\r\n           FROM transaction_details td\r\n        ), running_balance AS (\r\n         SELECT dm.date,\r\n            dm.name,\r\n            dm.type,\r\n            dm.transaction_total,\r\n            dm.payment_in,\r\n            dm.payment_out,\r\n            dm.payment_method,\r\n            dm.reference_no,\r\n            dm.transaction_category,\r\n            dm.business_id,\r\n            dm.payment_id,\r\n            dm.transaction_id,\r\n            sum((COALESCE(dm.payment_in, (0)::numeric) - COALESCE(dm.payment_out, (0)::numeric))) OVER (PARTITION BY dm.business_id ORDER BY dm.date, dm.transaction_id, dm.payment_id) AS balance\r\n           FROM daily_movements dm\r\n        )\r\n SELECT rb.date,\r\n    rb.name,\r\n    rb.type,\r\n    rb.transaction_total,\r\n    rb.payment_in,\r\n    rb.payment_out,\r\n    rb.payment_method,\r\n    rb.reference_no,\r\n    rb.transaction_category,\r\n    rb.business_id,\r\n    rb.payment_id,\r\n    rb.transaction_id,\r\n    rb.balance\r\n   FROM running_balance rb\r\n  WHERE (rb.business_id IS NOT NULL)\r\n  ORDER BY rb.date, rb.transaction_id, rb.payment_id","create or replace view \\"public\\".\\"vw_items\\" as  WITH custom_fields_agg AS (\r\n         SELECT cfv.item_id,\r\n            jsonb_object_agg(cfd.field_name, jsonb_build_object('value', cfv.field_value, 'type', cfd.field_type, 'required', COALESCE(((cfd.validation_rules ->> 'required'::text))::boolean, false))) AS custom_fields\r\n           FROM (item_custom_field_values cfv\r\n             JOIN item_custom_field_definitions cfd ON ((cfd.field_id = cfv.field_id)))\r\n          GROUP BY cfv.item_id\r\n        ), sub_services_agg AS (\r\n         SELECT s_1.service_id AS item_id,\r\n            jsonb_agg(jsonb_build_object('sub_service_id', s_1.sub_service_id, 'name', s_1.name, 'additional_price', s_1.additional_price)) AS sub_services\r\n           FROM subservices s_1\r\n          GROUP BY s_1.service_id\r\n        )\r\n SELECT i.item_id,\r\n    i.name,\r\n    i.item_type,\r\n    i.item_code,\r\n    i.sales_enabled,\r\n    i.purchase_enabled,\r\n    i.retail_price,\r\n    i.sale_price,\r\n    i.purchase_price,\r\n    i.stock_value,\r\n    i.stock_quantity,\r\n    i.alert_quantity,\r\n    i.inventory_enabled,\r\n    i.quantity,\r\n        CASE\r\n            WHEN (i.stock_quantity > i.alert_quantity) THEN 'In Stock'::text\r\n            WHEN (i.stock_quantity = (0)::numeric) THEN 'Out of Stock'::text\r\n            ELSE 'Low Stock'::text\r\n        END AS stock_status,\r\n        CASE\r\n            WHEN (ic.item_category_id IS NOT NULL) THEN jsonb_build_object('item_category_id', ic.item_category_id, 'name', ic.name, 'description', ic.description, 'business_id', ic.business_id, 'org_id', ic.org_id, 'created_at', ic.created_at, 'icon_info', ic.icon_info)\r\n            ELSE NULL::jsonb\r\n        END AS item_category,\r\n        CASE\r\n            WHEN (b.brand_id IS NOT NULL) THEN jsonb_build_object('brand_id', b.brand_id, 'name', b.name, 'description', b.description, 'org_id', b.org_id, 'business_id', b.business_id, 'created_at', b.created_at)\r\n            ELSE NULL::jsonb\r\n        END AS brand,\r\n        CASE\r\n            WHEN (u.unit_id IS NOT NULL) THEN jsonb_build_object('unit_id', u.unit_id, 'name', u.name, 'short_name', u.short_name, 'business_id', u.business_id, 'org_id', u.org_id, 'created_at', u.created_at)\r\n            ELSE NULL::jsonb\r\n        END AS unit,\r\n        CASE\r\n            WHEN (t.tax_id IS NOT NULL) THEN jsonb_build_object('tax_id', t.tax_id, 'name', t.name, 'rate', t.rate, 'org_id', t.org_id, 'business_id', t.business_id, 'created_at', t.created_at)\r\n            ELSE NULL::jsonb\r\n        END AS tax,\r\n        CASE\r\n            WHEN (s.supplier_id IS NOT NULL) THEN jsonb_build_object('supplier_id', s.supplier_id, 'name', s.name, 'email', s.email, 'phone', s.phone, 'address', s.address, 'gst_number', s.gst_number, 'business_id', s.business_id, 'org_id', s.org_id, 'supplier_balance', s.supplier_balance, 'created_at', s.created_at)\r\n            ELSE NULL::jsonb\r\n        END AS preferred_vendor,\r\n    i.business_id,\r\n    i.org_id,\r\n    i.is_returnable,\r\n    i.serial_nos,\r\n    i.rich_text,\r\n    i.images,\r\n    i.branch_variant_id,\r\n    COALESCE(cfa.custom_fields, '{}'::jsonb) AS custom_fields,\r\n    COALESCE(ssa.sub_services, '[]'::jsonb) AS sub_services,\r\n    i.created_at,\r\n    (EXISTS ( SELECT 1\r\n           FROM item_custom_field_values cfv2\r\n          WHERE (cfv2.item_id = i.item_id))) AS has_custom_fields,\r\n    i.opening_stock_qty,\r\n    i.opening_stock_value,\r\n    i.item_category_id,\r\n    i.is_active\r\n   FROM (((((((items i\r\n     LEFT JOIN item_categories ic ON ((i.item_category_id = ic.item_category_id)))\r\n     LEFT JOIN brands b ON ((i.brand_id = b.brand_id)))\r\n     LEFT JOIN units u ON ((i.unit_id = u.unit_id)))\r\n     LEFT JOIN taxes t ON ((i.tax_id = t.tax_id)))\r\n     LEFT JOIN suppliers s ON ((i.preferred_vendor_id = s.supplier_id)))\r\n     LEFT JOIN custom_fields_agg cfa ON ((i.item_id = cfa.item_id)))\r\n     LEFT JOIN sub_services_agg ssa ON ((i.item_id = ssa.item_id)))","create or replace view \\"public\\".\\"vw_stock_adjustments\\" as  WITH adjustment_items_agg AS (\r\n         SELECT sai.adjustment_id,\r\n            jsonb_agg(jsonb_build_object('adjustment_item_id', sai.adjustment_item_id, 'item_id', sai.item_id, 'item', to_jsonb(vw_i.*), 'quantity_adjusted', sai.quantity_adjusted, 'previous_quantity', sai.previous_quantity, 'new_quantity', sai.new_quantity, 'created_at', sai.created_at)) AS adjusted_items\r\n           FROM (stock_adjustment_items sai\r\n             JOIN vw_items vw_i ON ((sai.item_id = vw_i.item_id)))\r\n          GROUP BY sai.adjustment_id\r\n        )\r\n SELECT sa.adjustment_id,\r\n    sa.reason,\r\n    sa.reference,\r\n    sa.performed_at,\r\n    sa.performed_by,\r\n    emp.name AS performed_user,\r\n    sa.business_id,\r\n    sa.org_id,\r\n    adjustment_items_agg.adjusted_items\r\n   FROM (((stock_adjustments sa\r\n     JOIN transactions t ON ((sa.transaction_id = t.transaction_id)))\r\n     LEFT JOIN adjustment_items_agg ON ((sa.adjustment_id = adjustment_items_agg.adjustment_id)))\r\n     LEFT JOIN employee_view emp ON ((sa.performed_by = emp.employee_id)))\r\n  WHERE (t.status IS DISTINCT FROM 'REVERSED'::transaction_status)\r\n  ORDER BY sa.performed_at DESC","create or replace view \\"public\\".\\"purchase_view\\" as  SELECT p.purchase_id,\r\n    p.purchase_invoice,\r\n    p.invoice_no,\r\n    p.supplier_id,\r\n    p.purchase_date,\r\n    p.transaction_id,\r\n    p.subtotal,\r\n    p.discount_amount,\r\n    p.tax_amount,\r\n    p.shipping_charge,\r\n    p.total_amount,\r\n    p.paid_amount,\r\n    p.due_amount,\r\n    p.business_id,\r\n    p.created_by,\r\n    p.notes,\r\n    p.attachment_url,\r\n    p.metadata,\r\n    p.created_at,\r\n    p.updated_at,\r\n    (row_to_json(s.*))::jsonb AS supplier,\r\n    (row_to_json(t.*))::jsonb AS transaction,\r\n    (( SELECT json_agg(json_build_object('entry', row_to_json(te.*), 'account', row_to_json(a.*))) AS json_agg\r\n           FROM (transaction_entries te\r\n             LEFT JOIN accounts a ON ((te.account_id = a.account_id)))\r\n          WHERE (te.transaction_id = t.transaction_id)))::jsonb AS transaction_entries,\r\n    (( SELECT json_agg(row_to_json(pe.*)) AS json_agg\r\n           FROM payments pe\r\n          WHERE (pe.transaction_id = t.transaction_id)))::jsonb AS payments,\r\n    (( SELECT json_agg(((row_to_json(pi.*))::jsonb || jsonb_build_object('item', row_to_json(i.*)))) AS json_agg\r\n           FROM (purchase_items pi\r\n             JOIN vw_items i ON ((pi.item_id = i.item_id)))\r\n          WHERE (pi.purchase_id = p.purchase_id)))::jsonb AS purchase_items,\r\n    (row_to_json(emp.*))::jsonb AS employee\r\n   FROM (((purchases p\r\n     LEFT JOIN transactions t ON ((p.transaction_id = t.transaction_id)))\r\n     LEFT JOIN suppliers s ON ((p.supplier_id = s.supplier_id)))\r\n     LEFT JOIN employee_view emp ON ((p.created_by = emp.employee_id)))","create or replace view \\"public\\".\\"sale_view\\" as  SELECT DISTINCT ON (s.sale_id) s.sale_id,\r\n    s.sale_invoice,\r\n    s.customer_id,\r\n    s.sale_date,\r\n    s.transaction_id,\r\n    s.subtotal,\r\n    s.discount_amount,\r\n    s.tax_amount,\r\n    s.shipping_charge,\r\n    s.total_amount,\r\n    s.paid_amount,\r\n    s.due_amount,\r\n    s.business_id,\r\n    s.created_by,\r\n    s.notes,\r\n    s.attachment_url,\r\n    s.metadata,\r\n    s.created_at,\r\n    s.updated_at,\r\n    (row_to_json(c.*))::jsonb AS customer,\r\n    (row_to_json(t.*))::jsonb AS transaction,\r\n    ( SELECT (json_agg(json_build_object('entry', row_to_json(te.*), 'account', row_to_json(a.*))))::jsonb AS json_agg\r\n           FROM (transaction_entries te\r\n             LEFT JOIN accounts a ON ((te.account_id = a.account_id)))\r\n          WHERE (te.transaction_id = t.transaction_id)) AS transaction_entries,\r\n    ( SELECT (COALESCE(json_agg(row_to_json(pe.*)), '[]'::json))::jsonb AS \\"coalesce\\"\r\n           FROM payments pe\r\n          WHERE (pe.transaction_id = t.transaction_id)) AS payments,\r\n    ( SELECT (json_agg(json_build_object('sale_item_id', si.sale_item_id, 'item_id', si.item_id, 'quantity', si.quantity, 'unit_price', si.unit_price, 'total_price', si.total_price, 'subservices', ( SELECT COALESCE(json_agg(json_build_object('sale_item_subservice_id', sis.sale_item_subservice_id, 'sub_service_id', sis.sub_service_id, 'quantity', sis.quantity, 'additional_price', sis.additional_price, 'total_additional_price', sis.total_additional_price)), '[]'::json) AS \\"coalesce\\"\r\n                   FROM sale_item_subservices sis\r\n                  WHERE (sis.sale_item_id = si.sale_item_id)), 'item', row_to_json(i.*))))::jsonb AS json_agg\r\n           FROM (sale_items si\r\n             JOIN vw_items i ON ((si.item_id = i.item_id)))\r\n          WHERE (si.sale_id = s.sale_id)) AS sale_items,\r\n    (row_to_json(emp.*))::jsonb AS employee,\r\n    s.order_mode,\r\n    s.status_id,\r\n    (row_to_json(st.*))::jsonb AS status,\r\n    (row_to_json(b.*))::jsonb AS business\r\n   FROM (((((sales s\r\n     LEFT JOIN transactions t ON ((s.transaction_id = t.transaction_id)))\r\n     LEFT JOIN statuses st ON ((s.status_id = st.status_id)))\r\n     LEFT JOIN businesses b ON ((b.business_id = s.business_id)))\r\n     LEFT JOIN business_customer_view c ON ((s.customer_id = c.customer_id)))\r\n     LEFT JOIN employee_view emp ON ((s.created_by = emp.employee_id)))\r\n  ORDER BY s.sale_id","create or replace view \\"public\\".\\"sales_purchases_due_report\\" as  WITH sales_dues AS (\r\n         SELECT s.sale_date AS date,\r\n            COALESCE(s.sale_invoice, ''::text) AS invoice_no,\r\n            s.payments,\r\n            s.total_amount,\r\n            s.due_amount,\r\n            s.transaction_id,\r\n            'sale'::text AS transaction_type,\r\n            s.business_id,\r\n            bc.name AS party_name\r\n           FROM (sale_view s\r\n             LEFT JOIN business_customers bc ON (((bc.customer_id = s.customer_id) AND (bc.business_id = s.business_id))))\r\n          WHERE ((s.due_amount > (0)::numeric) AND (NOT (s.status_id IN ( SELECT statuses.status_id\r\n                   FROM statuses\r\n                  WHERE (statuses.name = ANY (ARRAY['VOID'::text, 'CANCELLED'::text]))))))\r\n        ), purchase_dues AS (\r\n         SELECT p.purchase_date AS date,\r\n            COALESCE(p.purchase_invoice, ''::text) AS invoice_no,\r\n            p.payments,\r\n            p.total_amount,\r\n            p.due_amount,\r\n            p.transaction_id,\r\n            'purchase'::text AS transaction_type,\r\n            p.business_id,\r\n            s.name AS party_name\r\n           FROM (purchase_view p\r\n             LEFT JOIN suppliers s ON ((s.supplier_id = p.supplier_id)))\r\n          WHERE (p.due_amount > (0)::numeric)\r\n        )\r\n SELECT sales_dues.date,\r\n    sales_dues.invoice_no,\r\n    sales_dues.payments,\r\n    sales_dues.total_amount,\r\n    sales_dues.due_amount,\r\n    sales_dues.transaction_id,\r\n    sales_dues.transaction_type,\r\n    sales_dues.business_id,\r\n    sales_dues.party_name\r\n   FROM sales_dues\r\nUNION ALL\r\n SELECT purchase_dues.date,\r\n    purchase_dues.invoice_no,\r\n    purchase_dues.payments,\r\n    purchase_dues.total_amount,\r\n    purchase_dues.due_amount,\r\n    purchase_dues.transaction_id,\r\n    purchase_dues.transaction_type,\r\n    purchase_dues.business_id,\r\n    purchase_dues.party_name\r\n   FROM purchase_dues","grant delete on table \\"public\\".\\"account_categories\\" to \\"anon\\"","grant insert on table \\"public\\".\\"account_categories\\" to \\"anon\\"","grant references on table \\"public\\".\\"account_categories\\" to \\"anon\\"","grant select on table \\"public\\".\\"account_categories\\" to \\"anon\\"","grant trigger on table \\"public\\".\\"account_categories\\" to \\"anon\\"","grant truncate on table \\"public\\".\\"account_categories\\" to \\"anon\\"","grant update on table \\"public\\".\\"account_categories\\" to \\"anon\\"","grant delete on table \\"public\\".\\"account_categories\\" to \\"authenticated\\"","grant insert on table \\"public\\".\\"account_categories\\" to \\"authenticated\\"","grant references on table \\"public\\".\\"account_categories\\" to \\"authenticated\\"","grant select on table \\"public\\".\\"account_categories\\" to \\"authenticated\\"","grant trigger on table \\"public\\".\\"account_categories\\" to \\"authenticated\\"","grant truncate on table \\"public\\".\\"account_categories\\" to \\"authenticated\\"","grant update on table \\"public\\".\\"account_categories\\" to \\"authenticated\\"","grant delete on table \\"public\\".\\"account_categories\\" to \\"service_role\\"","grant insert on table \\"public\\".\\"account_categories\\" to \\"service_role\\"","grant references on table \\"public\\".\\"account_categories\\" to \\"service_role\\"","grant select on table \\"public\\".\\"account_categories\\" to \\"service_role\\"","grant trigger on table \\"public\\".\\"account_categories\\" to \\"service_role\\"","grant truncate on table \\"public\\".\\"account_categories\\" to \\"service_role\\"","grant update on table \\"public\\".\\"account_categories\\" to \\"service_role\\"","grant dele