R EACH ROW EXECUTE FUNCTION update_customer_balance_from_entry()","CREATE TRIGGER trigger_update_supplier_balance AFTER INSERT OR DELETE OR UPDATE ON public.transaction_entries FOR EACH ROW EXECUTE FUNCTION update_supplier_balance_from_entry()","CREATE TRIGGER update_account_balance_trigger AFTER INSERT OR DELETE OR UPDATE ON public.transaction_entries FOR EACH ROW EXECUTE FUNCTION update_account_balance()"}	remote_schema
20250425043821	{"set check_function_bodies = off","CREATE OR REPLACE FUNCTION public.get_party_transaction_summary(party_type text, party_id uuid)\r\n RETURNS json\r\n LANGUAGE plpgsql\r\n SECURITY DEFINER\r\nAS $function$\r\nDECLARE\r\n    v_total NUMERIC;\r\n    v_total_paid NUMERIC;\r\n    v_total_due NUMERIC;\r\nBEGIN\r\n    -- Initialize variables\r\n    v_total := 0;\r\n    v_total_paid := 0;\r\n    v_total_due := 0;\r\n\r\n    -- Calculate summaries based on party type\r\n    IF party_type = 'customer' THEN\r\n        -- Get customer transaction summaries\r\n        SELECT \r\n            COALESCE(SUM(s.total_amount), 0),\r\n            COALESCE(SUM(s.paid_amount), 0),\r\n            COALESCE(SUM(s.due_amount), 0)\r\n        INTO v_total, v_total_paid, v_total_due\r\n        FROM sales s\r\n        WHERE s.customer_id = party_id\r\n        AND s.status_id NOT IN (\r\n            SELECT status_id \r\n            FROM statuses \r\n            WHERE name IN ('VOID', 'CANCELLED')\r\n        );\r\n\r\n        -- Get current due from business_customers\r\n        SELECT COALESCE(customer_balance, 0)\r\n        INTO v_total_due\r\n        FROM business_customers\r\n        WHERE customer_id = party_id;\r\n\r\n    ELSIF party_type = 'supplier' THEN\r\n        -- Get supplier transaction summaries\r\n        SELECT \r\n            COALESCE(SUM(p.total_amount), 0),\r\n            COALESCE(SUM(p.paid_amount), 0),\r\n            COALESCE(SUM(p.due_amount), 0)\r\n        INTO v_total, v_total_paid, v_total_due\r\n        FROM purchases p\r\n        WHERE p.supplier_id = party_id;\r\n\r\n        -- Get current due from suppliers\r\n        SELECT COALESCE(supplier_balance, 0)\r\n        INTO v_total_due\r\n        FROM suppliers\r\n        WHERE supplier_id = party_id;\r\n\r\n    ELSE\r\n        RAISE EXCEPTION 'Invalid party type: %', party_type;\r\n    END IF;\r\n\r\n    -- Return JSON object\r\n    RETURN json_build_object(\r\n        'total', v_total,\r\n        'total_paid', v_total_paid,\r\n        'total_due', v_total_due\r\n    );\r\nEND;\r\n$function$"}	remote_schema
