-- Name: FUNCTION set_graphql_placeholder(); Type: COMMENT; Schema: extensions; Owner: supabase_admin
--

COMMENT ON FUNCTION extensions.set_graphql_placeholder() IS 'Reintroduces placeholder function for graphql_public.graphql';


--
-- TOC entry 1040 (class 1255 OID 16386)
-- Name: get_auth(text); Type: FUNCTION; Schema: pgbouncer; Owner: supabase_admin
--

CREATE FUNCTION pgbouncer.get_auth(p_usename text) RETURNS TABLE(username text, password text)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $_$
  BEGIN
      RAISE DEBUG 'PgBouncer auth request: %', p_usename;

      RETURN QUERY
      SELECT
          rolname::text,
          CASE WHEN rolvaliduntil < now()
              THEN null
              ELSE rolpassword::text
          END
      FROM pg_authid
      WHERE rolname=$1 and rolcanlogin;
  END;
  $_$;


ALTER FUNCTION pgbouncer.get_auth(p_usename text) OWNER TO supabase_admin;

--
-- TOC entry 1008 (class 1255 OID 264589)
-- Name: adjust_stock(jsonb, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.adjust_stock(p_adjustment_json jsonb, p_business_id uuid, p_org_id uuid) RETURNS uuid
    LANGUAGE plpgsql
    AS $$
DECLARE
    -- Input Data
    v_reference               TEXT := p_adjustment_json->>'reference_number'; -- User-provided reference
    v_reason                  TEXT := p_adjustment_json->>'reason';
    v_adjusted_date           TIMESTAMPTZ := COALESCE((p_adjustment_json->>'adjusted_date')::timestamptz, now());
    v_adjusted_items          JSONB := p_adjustment_json->'adjusted_items';

    -- Internal Vars
    v_transaction_id          UUID;
    v_adjustment_id           UUID := gen_random_uuid(); -- PK for stock_adjustments table
    v_item_adjustment_value   NUMERIC;
    v_total_adjustment_abs_value NUMERIC := 0; -- Sum of absolute value changes for transaction header
    v_item_data               RECORD; -- For looping through JSON array
    v_item_cost               NUMERIC; -- Cost of the item being adjusted
    v_user_id                 UUID := auth.uid();

    -- Account IDs & Codes
    v_inventory_account_id    UUID;
    v_adjustment_offset_account_id UUID; -- Account to balance inventory change
    v_inventory_code          TEXT := '1030';
    v_adjustment_offset_code  TEXT := '6095'; -- Stock Adjustment Expense

BEGIN
    -- Validate Inputs
    IF p_business_id IS NULL OR p_org_id IS NULL THEN
        RAISE EXCEPTION 'Business ID and Org ID cannot be null.';
    END IF;
    IF v_adjusted_items IS NULL OR jsonb_array_length(v_adjusted_items) = 0 THEN
        RAISE EXCEPTION 'adjusted_items array cannot be null or empty.';
    END IF;
    -- Add more validation for fields inside v_adjusted_items if needed

    -- Fetch required account IDs for the business
    SELECT account_id INTO v_inventory_account_id FROM public.accounts WHERE business_id = p_business_id AND code = v_inventory_code;
    SELECT account_id INTO v_adjustment_offset_account_id FROM public.accounts WHERE business_id = p_business_id AND code = v_adjustment_offset_code;

    IF v_inventory_account_id IS NULL THEN
         RAISE EXCEPTION 'Inventory account (Code: %) not found for business %.', v_inventory_code, p_business_id;
    END IF;
    IF v_adjustment_offset_account_id IS NULL THEN
         RAISE EXCEPTION 'Stock Adjustment Expense account (Code: %) not found for business %.', v_adjustment_offset_code, p_business_id;
    END IF;

    -- Ensure reference number is not empty, generate if needed
    IF v_reference IS NULL OR v_reference = '' THEN
        v_reference := 'ADJ-' || to_char(v_adjusted_date, 'YYYYMMDD') || '-' || upper(substring(gen_random_uuid()::text from 1 for 6));
    END IF;

    -- Calculate total absolute adjustment value for the transaction header
    FOR v_item_data IN SELECT * FROM jsonb_array_elements(v_adjusted_items)
    LOOP
        -- Fetch item cost (using purchase_price as placeholder, replace if you have better cost data)
        SELECT COALESCE(i.purchase_price, 0) INTO v_item_cost
        FROM public.items i
        WHERE i.item_id = (v_item_data.value->>'item_id')::uuid
          AND i.business_id = p_business_id; -- Ensure item belongs to the business

        IF NOT FOUND THEN
             RAISE EXCEPTION 'Item ID % not found for business %.', (v_item_data.value->>'item_id')::uuid, p_business_id;
        END IF;

        v_item_adjustment_value := (v_item_data.value->>'adjusted_quantity')::numeric * v_item_cost;
        v_total_adjustment_abs_value := v_total_adjustment_abs_value + abs(v_item_adjustment_value);
    END LOOP;

    -- Create the Transaction Header
        reference_no, transaction_type, transaction_date, status,
        total_amount, paid_amount, due_amount, -- Total amount reflects the magnitude of value adjusted
        notes, business_id, created_by
    ) VALUES (
        v_reference, 'STOCK_ADJUSTMENT'::public.transaction_type, v_adjusted_date, 'PAID'::public.transaction_status, -- Adjustment is complete
        v_total_adjustment_abs_value, v_total_adjustment_abs_value, 0,
        'Stock Adjustment: ' || COALESCE(v_reason,'No reason provided.'), p_business_id, v_user_id
    ) RETURNING transaction_id INTO v_transaction_id;

    -- Create stock adjustment header record
        adjustment_id, reason, reference, performed_at, performed_by,
        business_id, org_id, transaction_id
    ) VALUES (
        v_adjustment_id, v_reason, v_reference, v_adjusted_date, v_user_id,
        p_business_id, p_org_id, v_transaction_id
    );

    -- Loop through items again to update stock and create GL entries
    FOR v_item_data IN SELECT * FROM jsonb_array_elements(v_adjusted_items)
    LOOP
        DECLARE
            v_item_id           UUID := (v_item_data.value->>'item_id')::uuid;
            v_adjusted_quantity NUMERIC := (v_item_data.value->>'adjusted_quantity')::numeric;
            v_current_quantity  NUMERIC := (v_item_data.value->>'current_quantity')::numeric; -- From input JSON
            v_new_quantity      NUMERIC := (v_item_data.value->>'new_quantity')::numeric;     -- From input JSON
            v_item_name         TEXT;
        BEGIN
            -- Fetch item cost and name again
            SELECT COALESCE(i.purchase_price, 0), i.name INTO v_item_cost, v_item_name
            FROM public.items i
            WHERE i.item_id = v_item_id AND i.business_id = p_business_id;
            -- We know item exists from previous loop/check

            v_item_adjustment_value := v_adjusted_quantity * v_item_cost;

            -- Create Balanced Transaction Entries for THIS item
            IF v_adjusted_quantity > 0 THEN
                -- Increase Inventory: Debit Inventory, Credit Offset Account
            ELSIF v_adjusted_quantity < 0 THEN
                -- Decrease Inventory: Debit Offset Account, Credit Inventory
            END IF;
            -- If v_adjusted_quantity is 0, no GL entries needed for this item.

            -- Create stock adjustment item detail record
                adjustment_id, item_id, quantity_adjusted, previous_quantity, new_quantity
            ) VALUES (
                v_adjustment_id, v_item_id, v_adjusted_quantity, v_current_quantity, v_new_quantity
            );

            -- Update item's stock quantity ONLY
            UPDATE public.items
            SET stock_quantity = v_new_quantity, -- Trusting the input JSON for new quantity
                updated_at = now()
                -- DO NOT update stock_value here. It should reflect cost based on purchases/production.
                -- The GL entry correctly reflects the value change in the Inventory account.
            WHERE item_id = v_item_id
              AND business_id = p_business_id;
        END;
    END LOOP;

    -- Verify the overall transaction balance
    PERFORM public.verify_transaction_balance(v_transaction_id);

    RETURN v_transaction_id;

EXCEPTION
    WHEN unique_violation THEN
        RAISE EXCEPTION 'Failed to adjust stock: Unique constraint violated. Check reference number "%". Detail: %', v_reference, SQLERRM;
    WHEN others THEN
        RAISE EXCEPTION 'Failed to adjust stock: %', SQLERRM;
END;
$$;


ALTER FUNCTION public.adjust_stock(p_adjustment_json jsonb, p_business_id uuid, p_org_id uuid) OWNER TO postgres;

--
-- TOC entry 1009 (class 1255 OID 264591)
-- Name: archive_customer(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.archive_customer(p_customer_id uuid, p_business_id uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_customer_balance NUMERIC;
BEGIN
    -- 1. Check the balance for this customer specifically within the given business
    SELECT bc.customer_balance
    INTO v_customer_balance
    FROM public.business_customers bc
    WHERE bc.customer_id = p_customer_id
      AND bc.business_id = p_business_id;

    -- If the relationship doesn't exist for this business, we might allow archiving the central record,
    -- or raise an error depending on requirements. Here, we proceed if no specific balance exists.
    -- If a balance DOES exist, it MUST be zero.
    IF v_customer_balance IS NOT NULL AND v_customer_balance != 0 THEN
        RAISE EXCEPTION 'Cannot archive customer ID % for business ID %: Outstanding balance of % exists. Please settle or write off the balance first.',
            p_customer_id, p_business_id, v_customer_balance;
    END IF;

    -- 2. Check balances across ALL businesses (stricter check - optional)
    -- If you want to prevent archiving a central customer if they have a balance with ANY business:
    /*
    PERFORM 1
    FROM public.business_customers bc
    WHERE bc.customer_id = p_customer_id
      AND bc.customer_balance != 0;

    IF FOUND THEN
         RAISE EXCEPTION 'Cannot archive customer ID %: Outstanding balance exists with one or more businesses.', p_customer_id;
    END IF;
    */

    -- 3. Mark the central customer record as inactive
    UPDATE public.business_customers
    SET is_active = FALSE
    WHERE customer_id = p_customer_id;

    IF NOT FOUND THEN
        RAISE WARNING 'Customer ID % not found in central customers table.', p_customer_id;
    END IF;

    -- Note: No direct GL entries are made here. Archiving is an administrative action.
    -- The financial settlement must happen via separate transactions (payments, write-offs).

END;
$$;


ALTER FUNCTION public.archive_customer(p_customer_id uuid, p_business_id uuid) OWNER TO postgres;

--
-- TOC entry 1016 (class 1255 OID 264592)
-- Name: archive_item(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.archive_item(p_item_id uuid, p_business_id uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_stock_quantity NUMERIC;
    v_transaction_exists BOOLEAN := FALSE;
BEGIN
    -- 1. Check if the item exists for the given business
    SELECT stock_quantity INTO v_stock_quantity
    FROM public.items i
    WHERE i.item_id = p_item_id
      AND i.business_id = p_business_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Item ID % not found for business ID %.', p_item_id, p_business_id;
    END IF;

    -- 2. Check for existing transactions linked to this item
    -- We look beyond just the Opening Stock transaction. Any transaction linked
    -- via the optional transactions.item_id or potentially via transaction_entries
    -- if item details are stored there (less ideal) indicates usage.
    -- This example primarily checks transactions.item_id.
    SELECT EXISTS (
        SELECT 1
        FROM public.transactions t
        WHERE t.business_id = p_business_id
          AND t.item_id = p_item_id
          AND t.transaction_type != 'OPENING_STOCK' -- Exclude the OB transaction itself
    ) INTO v_transaction_exists;

    -- Alternatively, or additionally, you might need to check line item tables
    -- if items are linked there instead of directly on the transaction header.
    -- Example (assuming a 'sale_items' table):
    /*
    IF NOT v_transaction_exists THEN
        SELECT EXISTS (
            SELECT 1 FROM public.sale_items si -- Replace with your actual line item table(s)
            JOIN public.sales s ON si.sale_id = s.sale_id -- Join to get business_id if needed
            WHERE si.item_id = p_item_id
              AND s.business_id = p_business_id -- Ensure check is scoped to the business
        ) INTO v_transaction_exists;
    END IF;
    -- Add similar checks for purchase line items, adjustment line items etc.
    */

    IF v_transaction_exists THEN
        RAISE EXCEPTION 'Cannot archive item ID %: Item has associated transaction history (e.g., sales, purchases, adjustments).', p_item_id;
    END IF;

    -- 3. Check for current stock quantity (optional but recommended for inventory items)
    -- This prevents archiving items that physically exist in inventory.
    -- Adjust this check based on whether v_stock_quantity could be null for non-inventory items.
    IF v_stock_quantity IS NOT NULL AND v_stock_quantity != 0 THEN
        RAISE EXCEPTION 'Cannot archive item ID %: Item has a current stock quantity of %. Please perform a stock adjustment first.',
            p_item_id, v_stock_quantity;
    END IF;

    -- 4. Mark the item as inactive
    UPDATE public.items
    SET is_active = FALSE,
        updated_at = now()
    WHERE item_id = p_item_id
      AND business_id = p_business_id; -- Redundant check but safe

    RAISE NOTICE 'Item ID % successfully archived.', p_item_id;

    -- Note: Archiving does not typically create GL entries.
    -- If stock quantity was non-zero and needed adjustment before archiving,
    -- that adjustment transaction would create the necessary GL entries
    -- (e.g., Dr Stock Adjustment Expense, Cr Inventory).

END;
$$;


ALTER FUNCTION public.archive_item(p_item_id uuid, p_business_id uuid) OWNER TO postgres;

--
-- TOC entry 994 (class 1255 OID 264593)
-- Name: archive_supplier(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.archive_supplier(p_supplier_id uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_supplier_balance NUMERIC;
BEGIN
    -- 1. Check the supplier's balance
    SELECT s.supplier_balance
    INTO v_supplier_balance
    FROM public.suppliers s
    WHERE s.supplier_id = p_supplier_id;

    IF NOT FOUND THEN
         RAISE EXCEPTION 'Supplier ID % not found.', p_supplier_id;
    END IF;

    IF v_supplier_balance != 0 THEN
        RAISE EXCEPTION 'Cannot archive supplier ID %: Outstanding balance of % exists. Please settle the balance first.',
            p_supplier_id, v_supplier_balance;
    END IF;

    -- 2. Mark the supplier record as inactive
    UPDATE public.suppliers
    SET is_active = FALSE,
        updated_at = now() -- Also update timestamp
    WHERE supplier_id = p_supplier_id;

    -- Note: No GL entries made here. Financial settlement happens via other transactions.

END;
$$;


ALTER FUNCTION public.archive_supplier(p_supplier_id uuid) OWNER TO postgres;

--
-- TOC entry 1017 (class 1255 OID 264594)
-- Name: build_account_node(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.build_account_node(_account_id uuid, _business_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
    v_account record;
    v_children jsonb := '[]'::jsonb; -- Default to empty array for children
BEGIN
    -- Fetch the details of the current account
    SELECT
        account_id,
        name,
        code,
        description,
        balance,
        is_group,
        parent_account_id,
        category_id
    INTO v_account
    FROM public.accounts a
    WHERE a.account_id = _account_id
      AND a.business_id = _business_id; -- Ensure it belongs to the correct business

    -- If account not found for the business, return NULL
    IF NOT FOUND THEN
        RETURN NULL;
    END IF;

    -- If the current account is a group, find its children recursively
    IF v_account.is_group THEN
        SELECT jsonb_agg(child_node ORDER BY child_code) -- Order children by code for consistency
        INTO v_children
        FROM (
            SELECT public.build_account_node(a.account_id, _business_id) as child_node, a.code as child_code
            FROM public.accounts a
            WHERE a.parent_account_id = _account_id
              AND a.business_id = _business_id -- Ensure children belong to the same business
        ) AS children_subquery
        WHERE child_node IS NOT NULL; -- Exclude potential NULLs if a child wasn't found (shouldn't happen with FKs)

        -- If no children found, jsonb_agg returns NULL, default back to empty array
        IF v_children IS NULL THEN
            v_children := '[]'::jsonb;
        END IF;
    END IF;

    -- Build the JSON object for the current account
    RETURN jsonb_build_object(
        'account_id', v_account.account_id,
        'name', v_account.name,
        'code', v_account.code,
        'description', v_account.description,
        'balance', v_account.balance,
        'is_group', v_account.is_group,
        'parent_account_id', v_account.parent_account_id, -- Included for reference, though structure shows hierarchy
        'category_id', v_account.category_id,             -- Included for reference
        'children', v_children                            -- Add the children array (empty if not a group or no children)
    );
END;
$$;


ALTER FUNCTION public.build_account_node(_account_id uuid, _business_id uuid) OWNER TO postgres;

--
-- TOC entry 995 (class 1255 OID 264595)
-- Name: bulk_import_items(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.bulk_import_items(p_import_data jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    -- Input Params
    v_items_array        JSONB := p_import_data->'p_items';
    v_business_id      UUID := (p_import_data->>'p_business_id')::uuid;
    v_skip_duplicates  BOOLEAN := COALESCE((p_import_data->>'p_skip_duplicates')::boolean, true); -- Default to skipping

    -- Loop Vars
    item_data          JSONB;
    v_item_name        TEXT;
    v_category_name    TEXT;
    v_brand_name       TEXT;
    v_unit_name        TEXT;
    v_item_code        TEXT; -- From "Item Code/Barcode"
    v_sale_price       NUMERIC;
    v_retail_price     NUMERIC; -- Use if needed, otherwise default
    v_purchase_price   NUMERIC;
    v_opening_qty      NUMERIC; -- Assuming opening qty/value might be in import
    v_opening_value    NUMERIC;

    -- Resolved IDs
    v_item_category_id UUID;
    v_brand_id         UUID;
    v_unit_id          UUID;
    v_existing_item_id UUID;
    v_item_id_out      UUID; -- For newly inserted item

    -- Accounting Vars (only for new items with opening stock)
    v_transaction_id        UUID;
    v_ob_ref_no             TEXT;
    v_inventory_account_id  UUID;
    v_ob_equity_account_id  UUID;
    v_inventory_code        TEXT := '1030';
    v_ob_equity_code        TEXT := '3900';

    -- Internal State
    v_org_id           UUID;
    v_user_id          UUID := auth.uid();
    v_processed_count  INTEGER := 0;
    v_inserted_count   INTEGER := 0;
    v_updated_count    INTEGER := 0;
    v_skipped_count    INTEGER := 0;
    v_error_count      INTEGER := 0;
    v_errors           TEXT[] := '{}';

BEGIN
    -- Validate top-level inputs
    IF v_business_id IS NULL THEN
        RAISE EXCEPTION 'p_business_id is required.';
    END IF;
    IF v_items_array IS NULL OR jsonb_typeof(v_items_array) != 'array' OR jsonb_array_length(v_items_array) = 0 THEN
        RAISE EXCEPTION 'p_items array is required and cannot be empty.';
    END IF;

    -- Get Org ID once
    SELECT org_id INTO v_org_id FROM public.businesses WHERE business_id = v_business_id;
    IF v_org_id IS NULL THEN
        RAISE EXCEPTION 'Cannot find org_id for business %', v_business_id;
    END IF;

    -- Fetch account IDs once if needed for opening stock
    SELECT account_id INTO v_inventory_account_id FROM public.accounts WHERE business_id = v_business_id AND code = v_inventory_code;
    SELECT account_id INTO v_ob_equity_account_id FROM public.accounts WHERE business_id = v_business_id AND code = v_ob_equity_code;
    -- Add validation checks if needed later inside the loop if OB exists

    -- Loop through each item in the input array
    FOR item_data IN SELECT * FROM jsonb_array_elements(v_items_array)
    LOOP
        BEGIN -- Start block for individual item processing and error handling
            v_processed_count := v_processed_count + 1;
            v_existing_item_id := NULL; -- Reset for each iteration
            v_item_id_out := NULL;

            -- Extract data for the current item (Use ->> for text)
            v_item_name := trim(item_data->>'Item Name');
            v_category_name := item_data->>'Category'; -- Pass NULL if key doesn't exist
            v_brand_name := item_data->>'Brand';
            v_unit_name := item_data->>'Item Unit';
            v_item_code := item_data->>'Item Code/Barcode'; -- Can be NULL or text/number
            v_sale_price := COALESCE((item_data->>'Sale Price')::numeric, 0);
            v_retail_price := COALESCE((item_data->>'Retail Price')::numeric, v_sale_price); -- Default retail to sale price
            v_purchase_price := COALESCE((item_data->>'Purchase Price')::numeric, 0);
            -- Handle potential opening stock - adjust keys if different in your import
            v_opening_qty := COALESCE((item_data->>'Opening Stock Qty')::numeric, 0);
            v_opening_value := COALESCE((item_data->>'Opening Stock Value')::numeric, 0);

            -- Basic Validation for required item fields
            IF v_item_name IS NULL OR v_item_name = '' THEN
                RAISE EXCEPTION 'Item Name is required.';
            END IF;

            -- Resolve foreign keys using helper functions
            v_item_category_id := public.get_or_create_item_category(v_business_id, v_category_name);
            v_brand_id := public.get_or_create_brand(v_business_id, v_brand_name);
            v_unit_id := public.get_or_create_unit(v_business_id, v_unit_name); -- Assumes unit name is unique identifier

            -- Check if item already exists by NAME for this business
            SELECT item_id INTO v_existing_item_id
            FROM public.items
            WHERE business_id = v_business_id AND lower(name) = lower(v_item_name);

            -- Handle duplicates based on flag
            IF v_existing_item_id IS NOT NULL THEN
                IF v_skip_duplicates THEN
                    RAISE WARNING 'Skipping duplicate item (name): "%"', v_item_name;
                    v_skipped_count := v_skipped_count + 1;
                    CONTINUE; -- Go to the next item in the loop
                ELSE
                    -- UPDATE existing item
                    UPDATE public.items SET
                        -- Update relevant fields from import data
                        item_category_id = COALESCE(v_item_category_id, item_category_id),
                        brand_id = COALESCE(v_brand_id, brand_id),
                        unit_id = COALESCE(v_unit_id, unit_id),
                        item_code = COALESCE(v_item_code, item_code), -- Update code if provided
                        sale_price = v_sale_price,
                        purchase_price = v_purchase_price,
                        -- Add other updatable fields as needed (retail_price, etc.)
                        updated_at = now()
                    WHERE item_id = v_existing_item_id;
                    v_updated_count := v_updated_count + 1;
                    -- DO NOT process opening stock on update
                END IF;
            ELSE
                -- INSERT new item
                 -- Check unique item code constraint before attempting insert
                IF v_item_code IS NOT NULL THEN
                    PERFORM 1 FROM public.items WHERE business_id = v_business_id AND item_code = v_item_code;
                    IF FOUND THEN
                        IF v_skip_duplicates THEN
                           RAISE WARNING 'Skipping item "%": Item Code "%" already exists.', v_item_name, v_item_code;
                           v_skipped_count := v_skipped_count + 1;
                           CONTINUE;
                        ELSE
                            RAISE EXCEPTION 'Item Code "%" already exists for item "%". Cannot insert.', v_item_code, v_item_name;
                        END IF;
                    END IF;
                END IF;

                    name, item_type, item_code, item_category_id, brand_id, unit_id,
                    sales_enabled, purchase_enabled, inventory_enabled, is_returnable, -- Assuming defaults
                    sale_price, purchase_price, alert_quantity, -- Assuming default alert qty
                    business_id, org_id,
                    stock_quantity, stock_value, -- Initial stock is opening stock
                    opening_stock_qty, opening_stock_value,
                    created_at, updated_at
                ) VALUES (
                    v_item_name, 'goods'::public.item_type, v_item_code, v_item_category_id, v_brand_id, v_unit_id,
                    true, true, true, false, -- Sensible defaults
                    v_sale_price, v_purchase_price, 0, -- Default alert quantity
                    v_business_id, v_org_id,
                    v_opening_qty, v_opening_value,
                    v_opening_qty, v_opening_value,
                    now(), now()
                )
                RETURNING item_id INTO v_item_id_out;
                v_inserted_count := v_inserted_count + 1;

                -- Handle Opening Stock Accounting (Only if INSERTED and value > 0)
                IF v_opening_value != 0 THEN
                    -- Validate required accounts fetched earlier
                    IF v_inventory_account_id IS NULL OR v_ob_equity_account_id IS NULL THEN
                        RAISE EXCEPTION 'Cannot process opening stock for "%": Required accounts (Inventory/OB Equity) missing.', v_item_name;
                    END IF;

                    v_ob_ref_no := 'OB-ITEM-' || v_item_id_out::text;

                        reference_no, transaction_type, transaction_date, status,
                        total_amount, paid_amount, due_amount,
                        notes, business_id, created_by, item_id
                    ) VALUES (
                        v_ob_ref_no, 'OPENING_STOCK'::public.transaction_type, now(), 'PAID'::public.transaction_status,
                        abs(v_opening_value), abs(v_opening_value), 0,
                        'Opening stock value for item ' || v_item_name || ' (' || COALESCE(v_item_code,'N/A') || ')', v_business_id, v_user_id, v_item_id_out
                    ) RETURNING transaction_id INTO v_transaction_id;


                    PERFORM public.verify_transaction_balance(v_transaction_id);
                END IF; -- End opening stock handling

            END IF; -- End INSERT/UPDATE logic

        EXCEPTION
            WHEN unique_violation THEN
                 v_error_count := v_error_count + 1;
                 v_errors := array_append(v_errors, format('Item "%s": Failed due to unique constraint violation (Name or Code?). Detail: %s', COALESCE(v_item_name, 'N/A'), SQLERRM));
                 RAISE WARNING 'Unique violation for Item "%": %', COALESCE(v_item_name, 'N/A'), SQLERRM;
            WHEN others THEN
                 v_error_count := v_error_count + 1;
                 v_errors := array_append(v_errors, format('Item "%s": Failed with error: %s', COALESCE(v_item_name, 'N/A'), SQLERRM));
                 RAISE WARNING 'Error processing Item "%": %', COALESCE(v_item_name, 'N/A'), SQLERRM;
        END; -- End block for individual item

    END LOOP; -- End loop through items array

    RETURN jsonb_build_object(
        'processed_count', v_processed_count,
        'inserted_count', v_inserted_count,
        'updated_count', v_updated_count,
        'skipped_count', v_skipped_count,
        'error_count', v_error_count,
        'errors', v_errors
    );

END;
$$;


ALTER FUNCTION public.bulk_import_items(p_import_data jsonb) OWNER TO postgres;

--
-- TOC entry 992 (class 1255 OID 264597)
-- Name: clear_sequences(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.clear_sequences(business_id uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_base_name text;
BEGIN
    v_base_name := business_id::text;

    -- Drop sequences if they exist in the public schema
    EXECUTE format('DROP SEQUENCE IF EXISTS public.%I', v_base_name || '_purchase_invoice');
    EXECUTE format('DROP SEQUENCE IF EXISTS public.%I', v_base_name || '_sale_invoice');
    EXECUTE format('DROP SEQUENCE IF EXISTS public.%I', v_base_name || '_purchase_return_code');
    EXECUTE format('DROP SEQUENCE IF EXISTS public.%I', v_base_name || '_sale_return_code');
    EXECUTE format('DROP SEQUENCE IF EXISTS public.%I', v_base_name || '_item_code');
    EXECUTE format('DROP SEQUENCE IF EXISTS public.%I', v_base_name || '_employee_code');
END;
$$;


ALTER FUNCTION public.clear_sequences(business_id uuid) OWNER TO postgres;

