--
-- TOC entry 993 (class 1255 OID 264600)
-- Name: create_purchase(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.create_purchase(p_purchase_json jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    -- Input Data Parsed
    v_business_id         UUID := (p_purchase_json->>'business_id')::uuid;
    v_supplier_id         UUID := (p_purchase_json->>'supplier_id')::uuid;
    v_user_provided_inv_no TEXT := p_purchase_json->>'purchase_invoice'; -- User's invoice #
    v_purchase_date       TIMESTAMPTZ := COALESCE((p_purchase_json->>'purchase_date')::timestamptz, now());
    v_notes               TEXT := p_purchase_json->>'notes';
    v_attachment_url      TEXT := p_purchase_json->>'attachment';
    v_subtotal            NUMERIC := COALESCE((p_purchase_json->>'subtotal')::numeric, 0); -- Sum of item lines before discounts/tax/shipping
    v_discount_amount     NUMERIC := COALESCE((p_purchase_json->>'discount_amount')::numeric, 0);
    v_shipping_charge     NUMERIC := COALESCE((p_purchase_json->>'shipping')::numeric, 0);
    v_tax_amount          NUMERIC := COALESCE((p_purchase_json->>'tax_amount')::numeric, 0); -- Assuming tax is calculated correctly client-side
    v_grand_total         NUMERIC := COALESCE((p_purchase_json->>'grand_total')::numeric, 0); -- Final amount payable
    v_paid_amount         NUMERIC := COALESCE((p_purchase_json->>'paid_amount')::numeric, 0); -- Amount paid immediately
    v_due_amount          NUMERIC := COALESCE((p_purchase_json->>'balance')::numeric, 0); -- Amount remaining
    v_purchase_items      JSONB := p_purchase_json->'purchase_items';
    v_payment_details     JSONB := p_purchase_json->'payment_details'; -- e.g., {"cash": 100, "bank": 100}

    -- Internal Vars
    v_transaction_id      UUID;
    v_purchase_id         UUID;
    v_gen_reference_no    TEXT; -- Our internal reference
    v_status              public.transaction_status;
    v_user_id             UUID := auth.uid();
    v_item_total_value    NUMERIC := 0;
    v_payment_id          UUID;
    v_purchase_item_data  RECORD;
    v_payment_method      TEXT;
    v_payment_amount      NUMERIC;
    v_calculated_due_amount NUMERIC; -- Use this for insertion

    -- Account IDs & Codes
    v_inventory_acc_id         UUID;
    v_ap_supplier_acc_id       UUID;
    v_shipping_exp_acc_id      UUID;
    v_cash_in_bank_acc_id      UUID; -- Default payment source/destination
    v_petty_cash_acc_id        UUID; -- For 'cash' payments
    v_purchase_discount_acc_id UUID; -- <<< Corrected: Was missing previously

    v_inventory_code           TEXT := '1030';
    v_ap_supplier_code         TEXT := '2010';
    v_shipping_exp_code        TEXT := '5040'; -- Or '6096' if you prefer OpEx
    v_cash_in_bank_code        TEXT := '1011';
    v_petty_cash_code          TEXT := '1010';
    v_purchase_discount_code   TEXT := '5030';

BEGIN
    -- Debug logging: Function entry
    RAISE LOG 'create_purchase: Starting function execution with business_id: %, supplier_id: %', v_business_id, v_supplier_id;
    RAISE LOG 'create_purchase: Purchase details - date: %, subtotal: %, discount: %, shipping: %, tax: %, grand_total: %, paid: %, due: %',
        v_purchase_date, v_subtotal, v_discount_amount, v_shipping_charge, v_tax_amount, v_grand_total, v_paid_amount, v_due_amount;
    RAISE LOG 'create_purchase: Items count: %, Payment details: %', 
        CASE WHEN v_purchase_items IS NULL THEN 0 ELSE jsonb_array_length(v_purchase_items) END, v_payment_details;

    -- Validate Inputs
    IF v_business_id IS NULL OR v_supplier_id IS NULL OR v_purchase_items IS NULL OR jsonb_array_length(v_purchase_items) = 0 THEN
        RAISE LOG 'create_purchase: Validation failed - Missing required fields';
        RAISE EXCEPTION 'business_id, supplier_id, and at least one purchase_item are required.';
    END IF;
    -- Basic validation of amounts (e.g., grand_total should roughly match components)
    IF abs(v_subtotal - v_discount_amount + v_shipping_charge + v_tax_amount - v_grand_total) > 0.01 THEN
         RAISE LOG 'create_purchase: Grand total (%) does not match sum of components (Sub:%, Disc:%, Ship:%, Tax:%)',
             v_grand_total, v_subtotal, v_discount_amount, v_shipping_charge, v_tax_amount;
         RAISE WARNING 'Grand total % does not match sum of components (Sub:%, Disc:%, Ship:%, Tax:%). Check input JSON.',
           v_grand_total, v_subtotal, v_discount_amount, v_shipping_charge, v_tax_amount;
    END IF;
    -- Validation: Check relationship allowing negative due_amount
    IF abs(v_grand_total - (v_paid_amount + v_due_amount)) > 0.01 THEN
        RAISE LOG 'create_purchase: Balance validation failed - GT:%, Paid:%, Due:%', 
            v_grand_total, v_paid_amount, v_due_amount;
        RAISE EXCEPTION 'Relationship Grand Total = Paid Amount + Due Amount violated. GT:%, Paid:%, Due:%. Check input JSON.',
            v_grand_total, v_paid_amount, v_due_amount;
    END IF;

    -- Fetch Account IDs
    RAISE LOG 'create_purchase: Fetching account IDs for business_id: %', v_business_id;
    SELECT account_id INTO v_inventory_acc_id FROM public.accounts WHERE business_id = v_business_id AND code = v_inventory_code;
    SELECT account_id INTO v_ap_supplier_acc_id FROM public.accounts WHERE business_id = v_business_id AND code = v_ap_supplier_code;
    SELECT account_id INTO v_shipping_exp_acc_id FROM public.accounts WHERE business_id = v_business_id AND code = v_shipping_exp_code;
    SELECT account_id INTO v_cash_in_bank_acc_id FROM public.accounts WHERE business_id = v_business_id AND code = v_cash_in_bank_code;
    SELECT account_id INTO v_petty_cash_acc_id FROM public.accounts WHERE business_id = v_business_id AND code = v_petty_cash_code;
    SELECT account_id INTO v_purchase_discount_acc_id FROM public.accounts WHERE business_id = v_business_id AND code = v_purchase_discount_code; -- <<< Added Fetch

    -- Debug account IDs
    RAISE LOG 'create_purchase: Account IDs - Inventory: %, AP: %, Shipping: %, Bank: %, Cash: %, Discount: %',
        v_inventory_acc_id, v_ap_supplier_acc_id, v_shipping_exp_acc_id, 
        v_cash_in_bank_acc_id, v_petty_cash_acc_id, v_purchase_discount_acc_id;

    -- Check ALL required accounts
    IF v_inventory_acc_id IS NULL OR v_ap_supplier_acc_id IS NULL OR v_shipping_exp_acc_id IS NULL
       OR v_cash_in_bank_acc_id IS NULL OR v_petty_cash_acc_id IS NULL OR v_purchase_discount_acc_id IS NULL THEN -- <<< Added Check
        RAISE LOG 'create_purchase: Missing required account(s) for business_id: %', v_business_id;
        RAISE EXCEPTION 'One or more required accounts (Inventory, A/P-Supplier, Shipping Exp, Cash, Bank, Purchase Discount) not found for business %.', v_business_id;
    END IF;

    -- Generate Internal Reference Number
    SELECT public.get_next_purchase_code(v_business_id)
    INTO v_gen_reference_no;
    RAISE LOG 'create_purchase: Generated reference number: %', v_gen_reference_no;

    -- *** CORRECTED Status and Due Amount Calculation ***
    v_calculated_due_amount := v_grand_total - v_paid_amount;

    IF ROUND(v_paid_amount, 2) >= ROUND(v_grand_total, 2) THEN
        v_status := 'PAID'::public.transaction_status;
        v_calculated_due_amount := LEAST(v_calculated_due_amount, 0);
    ELSIF v_paid_amount > 0 THEN
        v_status := 'PARTIALLY_PAID'::public.transaction_status;
    ELSE
        v_status := 'PENDING'::public.transaction_status;
    END IF;

    -- 1. Create Purchase Transaction Header
    RAISE LOG 'create_purchase: Creating transaction header with reference: %', v_gen_reference_no;
        reference_no, transaction_type, transaction_date, status,
        total_amount, paid_amount, due_amount,
        notes, business_id, created_by, supplier_id
    ) VALUES (
        v_gen_reference_no, 'PURCHASE'::public.transaction_type, v_purchase_date, v_status,
        v_grand_total, v_paid_amount, v_due_amount,
        v_notes, v_business_id, v_user_id, v_supplier_id
    ) RETURNING transaction_id INTO v_transaction_id;
    RAISE LOG 'create_purchase: Created transaction ID: %', v_transaction_id;

    -- 2. Create Purchase Header Record
    RAISE LOG 'create_purchase: Creating purchase header record';
        purchase_id, invoice_no, supplier_id, purchase_date, transaction_id,
        subtotal, discount_amount, tax_amount, shipping_charge, total_amount,
        paid_amount, due_amount, business_id, created_by, notes,
        attachment_url, purchase_invoice,
        created_at, updated_at
    ) VALUES (
        gen_random_uuid(), v_gen_reference_no, v_supplier_id, v_purchase_date, v_transaction_id,
        v_subtotal, v_discount_amount, v_tax_amount, v_shipping_charge, v_grand_total,
        v_paid_amount, v_due_amount, v_business_id, v_user_id, v_notes,
        v_attachment_url, v_user_provided_inv_no,
        now(), now()
    ) RETURNING purchases.purchase_id INTO v_purchase_id;
    RAISE LOG 'create_purchase: Created purchase ID: %', v_purchase_id;

    -- 3. Process Purchase Items and Initial GL Entries
    RAISE LOG 'create_purchase: Processing purchase items, count: %', jsonb_array_length(v_purchase_items);
    FOR v_purchase_item_data IN SELECT * FROM jsonb_to_recordset(v_purchase_items) AS x(item_id uuid, quantity numeric, unit_price numeric)
    LOOP
        DECLARE
            v_item_id UUID := v_purchase_item_data.item_id;
            v_quantity NUMERIC := v_purchase_item_data.quantity;
            v_unit_price NUMERIC := v_purchase_item_data.unit_price;
            v_line_total NUMERIC := v_quantity * v_unit_price;
            v_inventory_enabled BOOLEAN;
        BEGIN
            RAISE LOG 'create_purchase: Processing item ID: %, quantity: %, unit_price: %, line_total: %', 
                v_item_id, v_quantity, v_unit_price, v_line_total;

            VALUES (v_purchase_id, v_item_id, v_quantity, v_unit_price);

            SELECT i.inventory_enabled INTO v_inventory_enabled
            FROM public.items i
            WHERE i.item_id = v_item_id AND i.business_id = v_business_id;

            IF FOUND AND v_inventory_enabled THEN
                RAISE LOG 'create_purchase: Item % is inventory enabled, updating stock', v_item_id;
                UPDATE public.items
                SET stock_quantity = stock_quantity + v_quantity,
                    updated_at = now()
                WHERE item_id = v_item_id;

                -- Create GL Entry: Debit Inventory
                VALUES (v_transaction_id, v_inventory_acc_id, 'DEBIT', v_line_total, 'Purchase: Item ' || v_item_id::text);

                v_item_total_value := v_item_total_value + v_line_total;
                RAISE LOG 'create_purchase: Updated item_total_value to: %', v_item_total_value;
            ELSE
                RAISE LOG 'create_purchase: WARNING - Item % not found or inventory not enabled', v_item_id;
                RAISE WARNING 'Item % not found or inventory not enabled; cost not posted to Inventory GL.', v_item_id;
                v_item_total_value := v_item_total_value + v_line_total;
                    VALUES (v_transaction_id, v_inventory_acc_id, 'DEBIT', v_line_total, 'Purchase: Non-inventory Item ' || v_item_id::text);
            END IF;
        END;
    END LOOP;

    -- 4. Create Remaining Purchase GL Entries (Shipping, Discount Offset)
    RAISE LOG 'create_purchase: Creating additional GL entries';

    -- Debit Shipping Costs
    IF v_shipping_charge > 0 THEN
        RAISE LOG 'create_purchase: Adding shipping GL entry for amount: %', v_shipping_charge;
        VALUES (v_transaction_id, v_shipping_exp_acc_id, 'DEBIT', v_shipping_charge, 'Purchase: Shipping');
    END IF;

    -- Handle Discount (Reduce the Credit to A/P)
    IF v_discount_amount > 0 THEN
        RAISE LOG 'create_purchase: Adding discount GL entry for amount: %', v_discount_amount;
        VALUES (v_transaction_id, v_purchase_discount_acc_id, 'CREDIT', v_discount_amount, 'Purchase: Discount Received');
    END IF;

    -- Handle Tax (If needed, add Dr Tax Asset/Expense entry here.)

    -- 5. Create Payment and Payable Entries (CORRECTED LOGIC)
    IF ROUND(v_paid_amount, 2) >= ROUND(v_grand_total, 2) THEN
        -- Fully paid: DR Inventory, CR Cash/Bank/Petty Cash (NO AP)
        FOR v_payment_method, v_payment_amount IN SELECT key, value::text::numeric FROM jsonb_each_text(v_payment_details) WHERE value::text::numeric > 0
        LOOP
            DECLARE
                v_payment_account_id UUID;
            BEGIN
                IF lower(v_payment_method) = 'cash' THEN
                    v_payment_account_id := v_petty_cash_acc_id;
                ELSE
                    v_payment_account_id := v_cash_in_bank_acc_id;
                END IF;
                VALUES (v_transaction_id, v_payment_account_id, 'CREDIT', v_payment_amount, 'Payment for Purchase Ref ' || v_gen_reference_no);

                -- Create Payment Record
                    transaction_id, payment_date, amount, payment_method, reference_no, created_by
                ) VALUES (
                    v_transaction_id, v_purchase_date, v_payment_amount, v_payment_method, v_gen_reference_no, v_user_id
                );
            END;
        END LOOP;
    ELSE
        -- Not fully paid: Credit AP for due, Credit Cash/Bank/Petty Cash for paid
        IF v_due_amount > 0 THEN
            VALUES (v_transaction_id, v_ap_supplier_acc_id, 'CREDIT', v_due_amount, 'Purchase: Payable to Supplier ' || v_supplier_id::text);
        END IF;
        IF v_paid_amount > 0 THEN
            FOR v_payment_method, v_payment_amount IN SELECT key, value::text::numeric FROM jsonb_each_text(v_payment_details) WHERE value::text::numeric > 0
            LOOP
                DECLARE
                    v_payment_account_id UUID;
                BEGIN
                    IF lower(v_payment_method) = 'cash' THEN
                        v_payment_account_id := v_petty_cash_acc_id;
                    ELSE
                        v_payment_account_id := v_cash_in_bank_acc_id;
                    END IF;
                    VALUES (v_transaction_id, v_payment_account_id, 'CREDIT', v_payment_amount, 'Payment for Purchase Ref ' || v_gen_reference_no);

                    -- Create Payment Record
                        transaction_id, payment_date, amount, payment_method, reference_no, created_by
                    ) VALUES (
                        v_transaction_id, v_purchase_date, v_payment_amount, v_payment_method, v_gen_reference_no, v_user_id
                    );
                END;
            END LOOP;
            -- Debit AP for paid amount
            VALUES (v_transaction_id, v_ap_supplier_acc_id, 'DEBIT', v_paid_amount, 'Payment for Purchase Ref ' || v_gen_reference_no);
        END IF;
    END IF;

    -- 6. Verify Transaction Balance
    RAISE LOG 'create_purchase: Verifying transaction balance';
    PERFORM public.verify_transaction_balance(v_transaction_id);

    -- 7. Remove Direct Supplier Update (remains the same)
    RAISE LOG 'create_purchase: Purchase processing completed successfully';

    -- 8. Return Result
    PERFORM nextval(v_business_id::text || '_purchase_invoice');
    RAISE LOG 'create_purchase: Returning purchase data for purchase_id: %', v_purchase_id;
    RETURN (SELECT row_to_json(purchase_view)
    FROM purchase_view
    WHERE purchase_id = v_purchase_id);

EXCEPTION
    WHEN unique_violation THEN
        RAISE LOG 'create_purchase: ERROR - Unique violation with invoice no "%" or reference no "%"', v_user_provided_inv_no, v_gen_reference_no;
        RAISE EXCEPTION 'Failed to create purchase: Unique constraint violated. Check Invoice No "%" or Reference No "%". Detail: %',
        v_user_provided_inv_no, v_gen_reference_no, SQLERRM;
    WHEN others THEN
        RAISE LOG 'create_purchase: ERROR - General exception: %', SQLERRM;
        RAISE EXCEPTION 'Failed to create purchase: %', SQLERRM;
END;
$$;


ALTER FUNCTION public.create_purchase(p_purchase_json jsonb) OWNER TO postgres;

--
-- TOC entry 749 (class 1255 OID 286498)
-- Name: create_purchase_return(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.create_purchase_return(p_data jsonb) RETURNS uuid
    LANGUAGE plpgsql
    AS $$
DECLARE
    -- Input Data
    v_business_id         UUID := (p_data->>'business_id')::uuid;
    v_purchase_id         UUID := (p_data->>'purchase_id')::uuid; -- ID of the original purchase
    v_return_date         TIMESTAMPTZ := COALESCE((p_data->>'return_date')::timestamptz, now());
    v_return_invoice      TEXT := p_data->>'return_invoice'; -- Ref number for the return doc
    v_reason              TEXT := p_data->>'reason';
    v_notes               TEXT := p_data->>'notes';
    v_return_items        JSONB := p_data->'items'; -- Array of items being returned

    -- Internal Vars
    v_transaction_id      UUID;
    v_return_id           UUID; -- PK for purchase_returns table
    v_supplier_id         UUID;
    v_user_id             UUID := auth.uid();
    v_total_return_value  NUMERIC := 0;
    v_return_item_data    RECORD; -- For looping

    -- Account IDs & Codes
    v_ap_supplier_acc_id      UUID;
    v_pur_ret_allow_acc_id    UUID; -- Purchase Returns & Allowances account

    v_ap_supplier_code        TEXT := '2010';
    v_pur_ret_allow_code      TEXT := '5041'; -- <<< New Account Code

BEGIN
    -- Validate Inputs
    IF v_business_id IS NULL OR v_purchase_id IS NULL OR v_return_items IS NULL OR jsonb_array_length(v_return_items) = 0 THEN
        RAISE EXCEPTION 'business_id, purchase_id, and at least one return item are required.';
    END IF;
    IF v_return_invoice IS NULL OR trim(v_return_invoice) = '' THEN
        -- Generate if needed, or make mandatory
        v_return_invoice := 'PRTN-' || to_char(v_return_date, 'YYYYMMDD') || '-' || upper(substring(gen_random_uuid()::text from 1 for 6));
        RAISE WARNING 'Return invoice reference not provided, generated: %', v_return_invoice;
    END IF;

    -- Get Supplier ID from the original purchase
    SELECT p.supplier_id INTO v_supplier_id
    FROM public.purchases p
    WHERE p.purchase_id = v_purchase_id AND p.business_id = v_business_id;

    IF v_supplier_id IS NULL THEN
        RAISE EXCEPTION 'Original Purchase ID % not found for business %.', v_purchase_id, v_business_id;
    END IF;

    -- Fetch Account IDs
    SELECT account_id INTO v_ap_supplier_acc_id FROM public.accounts WHERE business_id = v_business_id AND code = v_ap_supplier_code;
    SELECT account_id INTO v_pur_ret_allow_acc_id FROM public.accounts WHERE business_id = v_business_id AND code = v_pur_ret_allow_code;

    IF v_ap_supplier_acc_id IS NULL THEN
        RAISE EXCEPTION 'Accounts Payable - Suppliers account (Code: %) not found for business %.', v_ap_supplier_code, v_business_id;
    END IF;
    IF v_pur_ret_allow_acc_id IS NULL THEN
        RAISE EXCEPTION 'Purchase Returns and Allowances account (Code: %) not found for business %.', v_pur_ret_allow_code, v_business_id;
    END IF;

    -- Calculate total return value from items *at their original purchase unit price*
    -- Assumes input JSON 'items' has 'purchase_item_id' (from original purchase) and 'quantity' being returned
    SELECT COALESCE(SUM(ri.quantity * pi.unit_price), 0)
    INTO v_total_return_value
    FROM jsonb_to_recordset(v_return_items) AS ri(purchase_item_id uuid, quantity numeric) -- Adjust keys if needed
    JOIN public.purchase_items pi ON pi.purchase_item_id = ri.purchase_item_id
    WHERE pi.purchase_id = v_purchase_id; -- Ensure items belong to original purchase

    IF v_total_return_value <= 0 THEN
        RAISE EXCEPTION 'Return items invalid or total return value is zero or less.';
    END IF;


    -- Create Transaction Header for the Return
    -- Status is PAID because the liability adjustment is complete. No money necessarily changed hands yet.
    -- paid_amount = 0 initially. due_amount = 0 initially.
        reference_no, transaction_type, transaction_date, status,
        total_amount, paid_amount, due_amount,
        notes, business_id, created_by, supplier_id
    ) VALUES (
        v_return_invoice, 'PURCHASE_RETURN'::public.transaction_type, v_return_date, 'PAID'::public.transaction_status,
        v_total_return_value, 0, 0, -- Initially no payment/refund applied to this return transaction itself
        'Purchase Return: ' || COALESCE(v_reason, ''), v_business_id, v_user_id, v_supplier_id
    ) RETURNING transaction_id INTO v_transaction_id;

    -- Create Correct Transaction Entries
    -- Debit A/P (Reduce liability to supplier)
    -- Credit Purchase Returns & Allowances (Reduce cost of purchases)

    -- Verify balance of this return transaction
    PERFORM public.verify_transaction_balance(v_transaction_id);

    -- Create Purchase Return Header Record
        return_id, -- Add return_id if it's the primary key
        purchase_id, return_invoice, return_date, reason, notes,
        total_amount, transaction_id, business_id, created_by
    ) VALUES (
        gen_random_uuid(), -- Assuming default PK generation
        v_purchase_id, v_return_invoice, v_return_date, v_reason, v_notes,
        v_total_return_value, v_transaction_id, v_business_id, v_user_id
    ) RETURNING purchase_returns.return_id INTO v_return_id; -- Ensure PK column name is correct

    -- Create Return Item Details and Update Stock Quantity
    FOR v_return_item_data IN
        SELECT
            ri.item_id,
            ri.purchase_item_id, -- Link to original purchase item line
            ri.quantity,
            pi.unit_price, -- Use original unit price for value calculation consistency
            i.inventory_enabled
        FROM jsonb_to_recordset(v_return_items) AS ri(item_id uuid, purchase_item_id uuid, quantity numeric) -- Adjust keys if needed
        JOIN public.purchase_items pi ON pi.purchase_item_id = ri.purchase_item_id AND pi.item_id = ri.item_id -- Ensure item matches
        JOIN public.items i ON i.item_id = ri.item_id
        WHERE pi.purchase_id = v_purchase_id -- Ensure item belongs to original purchase
    LOOP
        -- Insert return item detail
            return_id, purchase_item_id, quantity, unit_price -- Store original unit price for reference
        ) VALUES (
            v_return_id,
            v_return_item_data.purchase_item_id,
            v_return_item_data.quantity,
            v_return_item_data.unit_price
        );

        -- Update item inventory quantity if applicable
        IF v_return_item_data.inventory_enabled THEN
            UPDATE public.items
            SET stock_quantity = stock_quantity - v_return_item_data.quantity,
                updated_at = now()
                -- DO NOT update stock_value here. The GL entry handles value.
            WHERE item_id = v_return_item_data.item_id;
        END IF;
    END LOOP;

    -- NO automatic payment creation here. A refund received is a separate event.
    -- NO direct updates to purchase.due_amount or supplier.supplier_balance. Triggers handle this.
    -- NO redundant nextval call.

    RAISE NOTICE 'Purchase Return created successfully. Transaction ID: %', v_transaction_id;
    RETURN v_transaction_id; -- Return the transaction ID of the return

EXCEPTION
    WHEN others THEN
        RAISE EXCEPTION 'Error creating purchase return: %', SQLERRM;
END;
$$;


ALTER FUNCTION public.create_purchase_return(p_data jsonb) OWNER TO postgres;

--
-- TOC entry 997 (class 1255 OID 264603)
-- Name: create_sale(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.create_sale(p_sale_json jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    -- Input Data Parsed (Minimal + Optional Overrides)
    v_business_id         UUID := (p_sale_json->>'business_id')::uuid;
    v_customer_id         UUID := (p_sale_json->>'customer_id')::uuid; -- Nullable
    v_sale_date           TIMESTAMPTZ := COALESCE((p_sale_json->>'sale_date')::timestamptz, now());
    v_notes               TEXT := p_sale_json->>'notes';
    v_attachment_url      TEXT := p_sale_json->>'attachment';
    v_platform		      TEXT := COALESCE(p_sale_json->>'platform', 'Duxbe');
    v_discount_amount     NUMERIC := COALESCE((p_sale_json->>'discount_amount')::numeric, 0); -- Input override
    v_shipping_charge     NUMERIC := COALESCE((p_sale_json->>'shipping')::numeric, 0);       -- Input override
    v_paid_amount         NUMERIC := COALESCE((p_sale_json->>'paid_amount')::numeric, 0);   -- Input
    v_sale_items          JSONB := p_sale_json->'sale_items';                               -- Required input
    v_payment_details     JSONB := p_sale_json->'payment_details';                         -- Input (optional if paid_amount=0)
    v_order_mode          BOOLEAN := COALESCE((p_sale_json->>'order_mode')::boolean, false); -- Input
    v_user_id             UUID := COALESCE((p_sale_json->>'employee_id')::uuid, auth.uid()); -- Prefer employee_id if passed

    -- Internal Calculated Totals
    v_calc_subtotal       NUMERIC := 0;
    v_calc_tax_total      NUMERIC := 0;
    v_calc_grand_total    NUMERIC := 0;
    v_calculated_due_amount NUMERIC;

    -- Internal Vars
    v_transaction_id      UUID;
    v_sale_id             UUID;
    v_status_id           UUID;
    v_gen_reference_no    TEXT; -- Our internal invoice number
    v_status              public.transaction_status;
    v_sale_item_data      RECORD;
    v_subservice_data     RECORD;
    v_payment_method      TEXT;
    v_payment_amount      NUMERIC;
    v_total_cogs_value    NUMERIC := 0;
    v_total_revenue_value NUMERIC := 0;
    v_sale_item_id_gen    UUID;

    -- Account IDs & Codes
    v_ar_cust_acc_id           UUID;
    v_sales_goods_acc_id       UUID;
    v_sales_services_acc_id    UUID;
    v_tax_payable_acc_id       UUID;
    v_shipping_revenue_acc_id  UUID;
    v_inventory_acc_id         UUID;
    v_cogs_acc_id              UUID;
    v_cash_in_bank_acc_id      UUID;
    v_petty_cash_acc_id        UUID;
    v_sales_discount_acc_id    UUID;

    v_sales_discount_code      TEXT := '4900';
    v_ar_cust_code             TEXT := '1020';
    v_sales_goods_code         TEXT := '4010';
    v_sales_services_code      TEXT := '4020';
    v_tax_payable_code         TEXT := '2020';
    v_shipping_revenue_code    TEXT := '4040';
    v_inventory_code           TEXT := '1030';
    v_cogs_code                TEXT := '5015';
    v_cash_in_bank_code        TEXT := '1011';
    v_petty_cash_code          TEXT := '1010';

BEGIN
    RAISE LOG 'create_sale: Starting function execution for business_id: %', v_business_id;

    -- Validate Core Inputs
    IF v_business_id IS NULL OR v_sale_items IS NULL OR jsonb_array_length(v_sale_items) = 0 THEN
        RAISE EXCEPTION 'business_id and at least one sale_item are required.';
    END IF;
    -- Remove the validation check that compared input totals, as we calculate them now.

    -- Get default status ID for sales
    SELECT status_id INTO v_status_id
    FROM public.statuses
    WHERE business_id = v_business_id AND is_default = true AND type = 'sale'::public.status_type
    LIMIT 1;
    IF v_status_id IS NULL THEN
        RAISE EXCEPTION 'Default sale status not found for business ID: %', v_business_id;
    END IF;

    -- Fetch Account IDs (same as before, including conditional fetching)
    RAISE LOG 'create_sale: Fetching accounts for business: %', v_business_id;
    SELECT account_id INTO v_ar_cust_acc_id FROM public.accounts WHERE business_id = v_business_id AND code = v_ar_cust_code;
    SELECT account_id INTO v_sales_goods_acc_id FROM public.accounts WHERE business_id = v_business_id AND code = v_sales_goods_code;
    SELECT account_id INTO v_sales_services_acc_id FROM public.accounts WHERE business_id = v_business_id AND code = v_sales_services_code;
    SELECT account_id INTO v_tax_payable_acc_id FROM public.accounts WHERE business_id = v_business_id AND code = v_tax_payable_code;
    SELECT account_id INTO v_inventory_acc_id FROM public.accounts WHERE business_id = v_business_id AND code = v_inventory_code;
    SELECT account_id INTO v_cogs_acc_id FROM public.accounts WHERE business_id = v_business_id AND code = v_cogs_code;
    SELECT account_id INTO v_cash_in_bank_acc_id FROM public.accounts WHERE business_id = v_business_id AND code = v_cash_in_bank_code;
    SELECT account_id INTO v_petty_cash_acc_id FROM public.accounts WHERE business_id = v_business_id AND code = v_petty_cash_code;

    IF v_shipping_charge > 0 THEN
        SELECT account_id INTO v_shipping_revenue_acc_id FROM public.accounts WHERE business_id = v_business_id AND code = v_shipping_revenue_code;
        IF v_shipping_revenue_acc_id IS NULL THEN
             RAISE EXCEPTION 'Shipping Revenue account (Code: %) not found for business %.', v_shipping_revenue_code, v_business_id;
        END IF;
    END IF;

    IF v_discount_amount > 0 THEN
        SELECT account_id INTO v_sales_discount_acc_id FROM public.accounts WHERE business_id = v_business_id AND code = v_sales_discount_code;
        IF v_sales_discount_acc_id IS NULL THEN
             RAISE EXCEPTION 'Sales Discount account (Code: %) not found for business %.', v_sales_discount_code, v_business_id;
        END IF;
    END IF;

    -- Check required core accounts exist
    IF v_ar_cust_acc_id IS NULL OR v_sales_goods_acc_id IS NULL OR v_sales_services_acc_id IS NULL OR v_tax_payable_acc_id IS NULL
       OR v_inventory_acc_id IS NULL OR v_cogs_acc_id IS NULL OR v_cash_in_bank_acc_id IS NULL OR v_petty_cash_acc_id IS NULL THEN
        RAISE EXCEPTION 'One or more required core accounts (A/R, Sales, Tax, Inventory, COGS, Cash, Bank) not found for business %.', v_business_id;
    END IF;

    -- Generate Internal Invoice Number
    SELECT public.get_next_sale_code(v_business_id) INTO v_gen_reference_no;
    RAISE LOG 'create_sale: Using Invoice No: %', v_gen_reference_no;

    -- 3. Process Sale Items, Calculate Totals, Inventory, COGS, and Revenue GL Entries
    RAISE LOG 'create_sale: Processing sale items and calculating totals...';
    FOR v_sale_item_data IN
        SELECT
            x.item_id,
            x.quantity,
            x.unit_price, -- Expecting unit_price from input JSON per item
            x.subservices,
            i.item_type,
            i.inventory_enabled,
            COALESCE(i.purchase_price, 0) as item_cost,
            i.name as item_name,
            i.tax_id -- Fetch tax_id from item
        FROM jsonb_to_recordset(v_sale_items)
            AS x(item_id uuid, quantity numeric, unit_price numeric, subservices jsonb)
        JOIN public.items i ON i.item_id = x.item_id
        WHERE i.business_id = v_business_id
    LOOP
        DECLARE
            v_item_id               UUID := v_sale_item_data.item_id;
            v_quantity              NUMERIC := v_sale_item_data.quantity;
            v_unit_price            NUMERIC := v_sale_item_data.unit_price;
            v_line_subtotal_item    NUMERIC := v_quantity * v_unit_price;
            v_item_type             public.item_type := v_sale_item_data.item_type;
            v_inventory_enabled     BOOLEAN := v_sale_item_data.inventory_enabled;
            v_item_cost             NUMERIC := v_sale_item_data.item_cost;
            v_cogs_amount           NUMERIC := 0;
            v_revenue_account_id    UUID;
            v_item_name             TEXT := v_sale_item_data.item_name;
            v_tax_id                UUID := v_sale_item_data.tax_id;
            v_tax_rate              DOUBLE PRECISION := 0;
            v_line_tax_item         NUMERIC := 0;
            v_line_subtotal_subs    NUMERIC := 0; -- Subtotal from subservices for this line
            v_line_tax_subs         NUMERIC := 0; -- Tax from subservices for this line
        BEGIN
            RAISE LOG 'create_sale: Processing Item ID: %, Name: %, Qty: %, Price: %', v_item_id, v_item_name, v_quantity, v_unit_price;

            -- ** Calculate Item Contribution **
            v_calc_subtotal := v_calc_subtotal + v_line_subtotal_item;

            -- Fetch Tax Rate for the item
            IF v_tax_id IS NOT NULL THEN
                SELECT COALESCE(t.rate, 0) INTO v_tax_rate
                FROM public.taxes t
                WHERE t.tax_id = v_tax_id AND t.business_id = v_business_id; -- Ensure tax belongs to the business
                RAISE LOG 'create_sale: Tax ID: %, Fetched Rate: %', v_tax_id, v_tax_rate;
            ELSE
                 RAISE LOG 'create_sale: No Tax ID for item %', v_item_id;
            END IF;

            -- Calculate Tax for the main item part
            v_line_tax_item := v_line_subtotal_item * (v_tax_rate / 100.0);
            v_calc_tax_total := v_calc_tax_total + v_line_tax_item;

            -- Determine Revenue Account for main item/service
            IF v_item_type = 'goods' THEN
                v_revenue_account_id := v_sales_goods_acc_id;
            ELSIF v_item_type = 'services' THEN
                v_revenue_account_id := v_sales_services_acc_id;
            ELSE
                RAISE WARNING 'Unknown item_type "%" for item %; defaulting revenue to Sales of Goods.', v_item_type, v_item_id;
                v_revenue_account_id := v_sales_goods_acc_id;
            END IF;

            -- ** Hold GL Entries until Sale Header is created **
            -- We'll create GL entries after the loop using calculated totals

            -- Handle Subservices (Calculation and Link Table)
            IF v_item_type = 'services' AND v_sale_item_data.subservices IS NOT NULL AND jsonb_array_length(v_sale_item_data.subservices) > 0 THEN
                RAISE LOG 'create_sale: Processing subservices for item: %', v_item_id;
                FOR v_subservice_data IN
                    SELECT
                       (x->>'sub_service_id')::uuid as sub_service_id,
                       COALESCE((x->>'quantity')::numeric, 1) as quantity, -- Default quantity 1 if not provided
                       COALESCE((x->>'additional_price')::numeric, 0) as additional_price,
                       ss.name as sub_service_name
                    FROM jsonb_array_elements(v_sale_item_data.subservices) x
                    LEFT JOIN public.subservices ss ON ss.sub_service_id = (x->>'sub_service_id')::uuid
                       AND ss.service_id = v_item_id -- Ensure subservice belongs to the service
                LOOP
                    DECLARE
                        v_sub_line_total NUMERIC;
                        v_sub_line_tax   NUMERIC;
                    BEGIN
                        -- ** Calculate Subservice Contribution **
                        v_sub_line_total := v_subservice_data.quantity * v_subservice_data.additional_price;
                        v_line_subtotal_subs := v_line_subtotal_subs + v_sub_line_total; -- Accumulate subservice subtotal for this line item
                        v_calc_subtotal := v_calc_subtotal + v_sub_line_total; -- Add to overall subtotal

                        -- Calculate Tax for the subservice (using main item's tax rate)
                        v_sub_line_tax := v_sub_line_total * (v_tax_rate / 100.0);
                        v_line_tax_subs := v_line_tax_subs + v_sub_line_tax; -- Accumulate subservice tax for this line item
                        v_calc_tax_total := v_calc_tax_total + v_sub_line_tax; -- Add to overall tax total

                        RAISE LOG 'create_sale: Subservice: % Qty: % Price: % Subtotal: % Tax: %',
                                   v_subservice_data.sub_service_name, v_subservice_data.quantity, v_subservice_data.additional_price, v_sub_line_total, v_sub_line_tax;

                        -- ** Hold Subservice Link insert until Sale Item is created **
                    END;
                END LOOP;
            END IF;

            -- Handle Inventory and COGS for Goods (Calculation only for now)
            IF v_item_type = 'goods' AND v_inventory_enabled THEN
                RAISE LOG 'create_sale: Calculating COGS for Item: %, Cost: %', v_item_id, v_item_cost;
                v_cogs_amount := v_quantity * v_item_cost;
                v_total_cogs_value := v_total_cogs_value + v_cogs_amount;
                -- ** Inventory Update and GL entries happen later **
            END IF;

             -- ** Total Revenue for this line (Item + Subservices) for potential later logging/validation **
            v_total_revenue_value := v_total_revenue_value + v_line_subtotal_item + v_line_subtotal_subs;

        END; -- End of inner block for item processing
    END LOOP; -- End of sale item loop

    RAISE LOG 'create_sale: Item processing complete. Calculated Totals - Pre-Adjustment: Subtotal: %, Tax: %', v_calc_subtotal, v_calc_tax_total;
    RAISE LOG 'create_sale: Total COGS Calculated: %, Total Revenue Calculated: %', v_total_cogs_value, v_total_revenue_value;

    -- ** Calculate Final Grand Total **
    v_calc_grand_total := v_calc_subtotal - v_discount_amount + v_shipping_charge + v_calc_tax_total;
	

-- ** MODIFIED SECTION: Calculate Status and Due Amount **
v_calculated_due_amount := v_calc_grand_total - v_paid_amount; -- This will be <= 0 if paid_amount >= grand_total

IF ROUND(v_paid_amount, 2) >= ROUND(v_calc_grand_total, 2) THEN -- Paid in full or overpaid
    v_status := 'PAID'::public.transaction_status;
    IF v_customer_id IS NOT NULL THEN
        -- Known customer: invoice is considered settled, due amount is 0.
        -- Any overpayment becomes an implicit credit to their account balance.
        v_calculated_due_amount := 0;
    ELSE
        -- Walking customer (v_customer_id IS NULL): due amount reflects change to be given back.
        -- v_calculated_due_amount is already (v_calc_grand_total - v_paid_amount), which will be <= 0.
        -- No change needed to v_calculated_due_amount here for walking customer overpayment.
    END IF;
ELSIF v_paid_amount > 0 THEN -- Partially paid
    v_status := 'PARTIALLY_PAID'::public.transaction_status;
    -- v_calculated_due_amount is (v_calc_grand_total - v_paid_amount), which will be > 0. Correct.
ELSE -- Not paid at all (paid_amount is 0 or was NULL and coalesced to 0)
    v_status := 'PENDING'::public.transaction_status; -- Or 'UNPAID'
    -- v_calculated_due_amount is v_calc_grand_total (since v_paid_amount is 0). Correct.
END IF;
-- ** END OF MODIFIED SECTION **

RAISE LOG 'create_sale: Final Calculated Totals - Subtotal: %, Tax: %, Shipping: %, Discount: %, Grand Total: %',
           v_calc_subtotal, v_calc_tax_total, v_shipping_charge, v_discount_amount, v_calc_grand_total;
RAISE LOG 'create_sale: Calculated Status: %, Due Amount: % (Customer ID: %)', v_status, v_calculated_due_amount, v_customer_id;
    -- 1. Create Sale Transaction Header (Using Calculated Totals)
    RAISE LOG 'create_sale: Creating transaction header';
        reference_no, transaction_type, transaction_date, status,
        total_amount, paid_amount, due_amount, -- Use calculated grand_total and due_amount
        notes, business_id, created_by, customer_id
    ) VALUES (
        v_gen_reference_no, 'SALE'::public.transaction_type, v_sale_date, v_status,
        v_calc_grand_total, v_paid_amount, v_calculated_due_amount,
        v_notes, v_business_id, v_user_id, v_customer_id
    ) RETURNING transaction_id INTO v_transaction_id;
    RAISE LOG 'create_sale: Created Transaction ID: %', v_transaction_id;

    -- 2. Create Sale Header Record (Using Calculated Totals)
    RAISE LOG 'create_sale: Creating sale header record';
        sale_id, customer_id, sale_date, transaction_id,
        subtotal, discount_amount, tax_amount, shipping_charge, total_amount, -- Use calculated totals
        paid_amount, due_amount, business_id, created_by, notes, platform,
        attachment_url, sale_invoice, status_id, order_mode, metadata,
        created_at, updated_at
    ) VALUES (
        gen_random_uuid(), v_customer_id, v_sale_date, v_transaction_id,
        v_calc_subtotal, v_discount_amount, v_calc_tax_total, v_shipping_charge, v_calc_grand_total,
        v_paid_amount, v_calculated_due_amount, v_business_id, v_user_id, v_notes, v_platform,
        v_attachment_url, v_gen_reference_no, v_status_id, v_order_mode, p_sale_json->'metadata', -- Keep metadata if provided
        now(), now()
    ) RETURNING sales.sale_id INTO v_sale_id;
    RAISE LOG 'create_sale: Created Sale ID: %', v_sale_id;

    -- 3b. NOW Insert Sale Items, Subservice Links, Update Inventory, and Create Line-Specific GL Entries
    RAISE LOG 'create_sale: Inserting sale items, subservices, updating inventory, and creating line GL entries';
    FOR v_sale_item_data IN
       SELECT
            x.item_id,
            x.quantity,
            x.unit_price,
            x.subservices,
            i.item_type,
            i.inventory_enabled,
            COALESCE(i.purchase_price, 0) as item_cost,
            i.name as item_name,
            i.tax_id -- Re-fetch tax_id for consistency if needed, or rely on previous loop's data
        FROM jsonb_to_recordset(v_sale_items)
            AS x(item_id uuid, quantity numeric, unit_price numeric, subservices jsonb)
        JOIN public.items i ON i.item_id = x.item_id
        WHERE i.business_id = v_business_id
    LOOP
        DECLARE
            v_item_id               UUID := v_sale_item_data.item_id;
            v_quantity              NUMERIC := v_sale_item_data.quantity;
            v_unit_price            NUMERIC := v_sale_item_data.unit_price;
            v_line_subtotal_item    NUMERIC := v_quantity * v_unit_price;
            v_item_type             public.item_type := v_sale_item_data.item_type;
            v_inventory_enabled     BOOLEAN := v_sale_item_data.inventory_enabled;
            v_item_cost             NUMERIC := v_sale_item_data.item_cost;
            v_cogs_amount           NUMERIC := 0;
            v_revenue_account_id    UUID;
            v_item_name             TEXT := v_sale_item_data.item_name;
            v_current_sale_item_id  UUID; -- To link subservices
        BEGIN
             RAISE LOG 'create_sale: Processing line item again for DB inserts: Item ID %', v_item_id;

             -- Insert Sale Item Line
            VALUES (v_sale_id, v_item_id, v_quantity, v_unit_price, now(), now())
            RETURNING sale_item_id INTO v_current_sale_item_id;

            -- Determine Revenue Account again
            IF v_item_type = 'goods' THEN
                v_revenue_account_id := v_sales_goods_acc_id;
            ELSIF v_item_type = 'services' THEN
                v_revenue_account_id := v_sales_services_acc_id;
            ELSE
                v_revenue_account_id := v_sales_goods_acc_id; -- Default
            END IF;

            -- Create GL Entry: Credit Sales Revenue for main item/service price
            IF v_line_subtotal_item > 0 THEN -- Avoid zero entries
               VALUES (v_transaction_id, v_revenue_account_id, 'CREDIT', v_line_subtotal_item, 'Sale: Item ' || v_item_name);
            END IF;

            -- Handle Subservices (Insert links AND Add GL Credit)
            IF v_item_type = 'services' AND v_sale_item_data.subservices IS NOT NULL AND jsonb_array_length(v_sale_item_data.subservices) > 0 THEN
                FOR v_subservice_data IN
                    SELECT
                       (x->>'sub_service_id')::uuid as sub_service_id,
                       COALESCE((x->>'quantity')::numeric, 1) as quantity,
                       COALESCE((x->>'additional_price')::numeric, 0) as additional_price,
                       ss.name as sub_service_name
                    FROM jsonb_array_elements(v_sale_item_data.subservices) x
                    LEFT JOIN public.subservices ss ON ss.sub_service_id = (x->>'sub_service_id')::uuid
                       AND ss.service_id = v_item_id
                LOOP
                    DECLARE
                        v_sub_line_total NUMERIC;
                    BEGIN
                        v_sub_line_total := v_subservice_data.quantity * v_subservice_data.additional_price;

                        IF v_subservice_data.sub_service_id IS NOT NULL THEN
                           -- Insert link record
                           VALUES (v_current_sale_item_id, v_subservice_data.sub_service_id, v_subservice_data.quantity, v_subservice_data.additional_price, now(), now());

                           -- Add GL CREDIT FOR SUBSERVICE REVENUE
                           IF v_sub_line_total > 0 THEN
                              VALUES (v_transaction_id, v_sales_services_acc_id, 'CREDIT', v_sub_line_total, 'Sale: Subservice ' || COALESCE(v_subservice_data.sub_service_name,'Unknown') || ' for ' || v_item_name);
                           END IF;
                        ELSE
                            RAISE WARNING 'create_sale: Subservice ID missing or subservice not found for item % in input JSON: %', v_item_id, x;
                        END IF;

                    END;
                END LOOP;
            END IF;

            -- Handle Inventory and COGS for Goods (DB Update and GL Entries)
            IF v_item_type = 'goods' AND v_inventory_enabled THEN
                RAISE LOG 'create_sale: Updating Inventory and creating COGS GL for Item: %', v_item_id;
                UPDATE public.items
                SET stock_quantity = stock_quantity - v_quantity,
                    updated_at = now()
                WHERE item_id = v_item_id;

                v_cogs_amount := v_quantity * v_item_cost;

                IF v_cogs_amount > 0 THEN
                    VALUES (v_transaction_id, v_cogs_acc_id, 'DEBIT', v_cogs_amount, 'COGS for Sale: ' || v_item_name);

                    VALUES (v_transaction_id, v_inventory_acc_id, 'CREDIT', v_cogs_amount, 'Inventory Sold: ' || v_item_name);
                END IF;
            END IF;
        END; -- End inner block
    END LOOP; -- End second item loop

    -- 4. Create Remaining Sale GL Entries (Tax, Shipping, Discount, AR)
    RAISE LOG 'create_sale: Creating summary Tax/Shipping/Discount/AR entries';
    IF v_calc_tax_total > 0 THEN
        VALUES (v_transaction_id, v_tax_payable_acc_id, 'CREDIT', v_calc_tax_total, 'Sales Tax');
    END IF;

    IF v_shipping_charge > 0 THEN
        VALUES (v_transaction_id, v_shipping_revenue_acc_id, 'CREDIT', v_shipping_charge, 'Shipping Charged');
    END IF;

    IF v_discount_amount > 0 THEN
         VALUES (v_transaction_id, v_sales_discount_acc_id, 'DEBIT', v_discount_amount, 'Sales Discount Applied');
    END IF;

    -- A/R Debit for the Grand Total
    IF v_calc_grand_total > 0 THEN
        VALUES (v_transaction_id, v_ar_cust_acc_id, 'DEBIT', v_calc_grand_total, 'Sale Invoice: ' || v_gen_reference_no);
    END IF;

    -- 5. Process Immediate Payment (If any)
    IF v_paid_amount > 0 AND v_payment_details IS NOT NULL THEN
        RAISE LOG 'create_sale: Processing immediate payment of: %', v_paid_amount;
        DECLARE
            v_total_payment_processed NUMERIC := 0;
        BEGIN
            FOR v_payment_method, v_payment_amount IN SELECT key, value::text::numeric FROM jsonb_each_text(v_payment_details) WHERE value::text::numeric > 0
            LOOP
                 DECLARE
                     v_payment_account_id UUID;
                 BEGIN
                     RAISE LOG 'create_sale: Payment Method: %, Amount: %', v_payment_method, v_payment_amount;
                     v_total_payment_processed := v_total_payment_processed + v_payment_amount;

                     IF lower(v_payment_method) = 'cash' THEN
                        v_payment_account_id := v_petty_cash_acc_id;
                     ELSE -- Assume 'card', 'bank', 'wallet' etc. go to bank account for simplicity
                        v_payment_account_id := v_cash_in_bank_acc_id;
                     END IF;

                     -- GL Entry: Debit Cash/Bank
                     VALUES (v_transaction_id, v_payment_account_id, 'DEBIT', v_payment_amount, 'Payment Received for Sale ' || v_gen_reference_no || ' (' || v_payment_method || ')');

                     -- GL Entry: Credit A/R
                     VALUES (v_transaction_id, v_ar_cust_acc_id, 'CREDIT', v_payment_amount, 'Payment Received for Sale ' || v_gen_reference_no);

                     -- Create Payment Record
                     VALUES (v_transaction_id, v_sale_date, v_payment_amount, v_payment_method, v_gen_reference_no, v_user_id);
                 END;
            END LOOP;

            -- Optional: Check if total processed payment matches v_paid_amount from input
            IF abs(v_total_payment_processed - v_paid_amount) > 0.01 THEN
                 RAISE WARNING 'create_sale: Total amount in payment_details (%) does not match paid_amount (%) provided in input JSON.', v_total_payment_processed, v_paid_amount;
                 -- Consider whether to raise an error here or just proceed. Proceeding for now.
            END IF;

            RAISE LOG 'create_sale: Verifying transaction balance after payment';
            PERFORM public.verify_transaction_balance(v_transaction_id); -- Assumes this function exists and works
        END;
    ELSE
        RAISE LOG 'create_sale: No immediate payment, verifying sale transaction balance';
        PERFORM public.verify_transaction_balance(v_transaction_id); -- Assumes this function exists and works
    END IF;

    -- 6. Increment Invoice Counter Sequence
    PERFORM nextval(v_business_id::text || '_sale_invoice');
    RAISE LOG 'create_sale: Sale creation complete for Sale ID: %', v_sale_id;

    -- 7. Return Result (Ensure sale_view exists and includes calculated fields)
    RETURN (SELECT row_to_json(sv) FROM public.sale_view sv WHERE sv.sale_id = v_sale_id);

EXCEPTION
    WHEN unique_violation THEN
        RAISE LOG 'create_sale: ERROR - Unique constraint violation. Invoice No "%". Detail: %', v_gen_reference_no, SQLERRM;
        RAISE EXCEPTION 'Failed to create sale: Unique constraint violated. Check Invoice No "%". Detail: %', v_gen_reference_no, SQLERRM;
    WHEN others THEN
        -- Log the error and the input JSON for debugging
        RAISE LOG 'create_sale: ERROR - General exception: %. SQL State: %. Input JSON: %', SQLERRM, SQLSTATE, p_sale_json;
        RAISE EXCEPTION 'Failed to create sale: %. SQL State: %', SQLERRM, SQLSTATE; -- Re-raise the exception
END;
$$;


ALTER FUNCTION public.create_sale(p_sale_json jsonb) OWNER TO postgres;

--
-- TOC entry 750 (class 1255 OID 286507)
-- Name: create_sale_return(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.create_sale_return(p_data jsonb) RETURNS uuid
    LANGUAGE plpgsql
    AS $$
DECLARE
    -- Input Data
    v_business_id         UUID := (p_data->>'business_id')::uuid;
    v_sale_id             UUID := (p_data->>'sale_id')::uuid; -- ID of the original sale
    v_return_date         TIMESTAMPTZ := COALESCE((p_data->>'return_date')::timestamptz, now());
    v_return_invoice      TEXT := p_data->>'return_invoice'; -- Ref number for the return doc
    v_reason              TEXT := p_data->>'reason';
    v_notes               TEXT := p_data->>'notes';
    v_return_items        JSONB := p_data->'items'; -- Array of items being returned

    -- Internal Vars
    v_transaction_id      UUID;
    v_return_id           UUID; -- PK for sale_returns table
    v_customer_id         UUID;
    v_user_id             UUID := auth.uid();
    v_total_return_sale_value NUMERIC := 0;
    v_total_return_cost_value NUMERIC := 0;
    v_return_item_data    RECORD; -- For looping

    -- Account IDs & Codes
    v_ar_customer_acc_id      UUID;
    v_sales_ret_allow_acc_id  UUID; -- Sales Returns & Allowances account
    v_inventory_acc_id        UUID;
    v_cogs_acc_id             UUID; -- Cost of Goods Sold account

    v_ar_customer_code        TEXT := '1020';
    v_sales_ret_allow_code    TEXT := '4910'; -- <<< New Account Code
    v_inventory_code          TEXT := '1030';
    v_cogs_code               TEXT := '5015';

BEGIN
    -- Validate Inputs
    IF v_business_id IS NULL OR v_sale_id IS NULL OR v_return_items IS NULL OR jsonb_array_length(v_return_items) = 0 THEN
        RAISE EXCEPTION 'business_id, sale_id, and at least one return item are required.';
    END IF;
    IF v_return_invoice IS NULL OR trim(v_return_invoice) = '' THEN
        v_return_invoice := 'SRTN-' || to_char(v_return_date, 'YYYYMMDD') || '-' || upper(substring(gen_random_uuid()::text from 1 for 6));
        RAISE WARNING 'Return invoice reference not provided, generated: %', v_return_invoice;
    END IF;

    -- Get Customer ID from the original sale
    SELECT s.customer_id INTO v_customer_id
    FROM public.sales s -- Assuming 'sales' is your sales header table
    WHERE s.sale_id = v_sale_id AND s.business_id = v_business_id;

    IF v_customer_id IS NULL THEN
        RAISE EXCEPTION 'Original Sale ID % not found for business %.', v_sale_id, v_business_id;
    END IF;

    -- Fetch Account IDs
    SELECT account_id INTO v_ar_customer_acc_id FROM public.accounts WHERE business_id = v_business_id AND code = v_ar_customer_code;
    SELECT account_id INTO v_sales_ret_allow_acc_id FROM public.accounts WHERE business_id = v_business_id AND code = v_sales_ret_allow_code;
    SELECT account_id INTO v_inventory_acc_id FROM public.accounts WHERE business_id = v_business_id AND code = v_inventory_code;
    SELECT account_id INTO v_cogs_acc_id FROM public.accounts WHERE business_id = v_business_id AND code = v_cogs_code;

    IF v_ar_customer_acc_id IS NULL THEN
        RAISE EXCEPTION 'Accounts Receivable - Customers account (Code: %) not found for business %.', v_ar_customer_code, v_business_id;
    END IF;
    IF v_sales_ret_allow_acc_id IS NULL THEN
        RAISE EXCEPTION 'Sales Returns and Allowances account (Code: %) not found for business %.', v_sales_ret_allow_code, v_business_id;
    END IF;
    IF v_inventory_acc_id IS NULL THEN
        RAISE EXCEPTION 'Inventory account (Code: %) not found for business %.', v_inventory_code, v_business_id;
    END IF;
     IF v_cogs_acc_id IS NULL THEN
        RAISE EXCEPTION 'Cost of Goods Sold account (Code: %) not found for business %.', v_cogs_code, v_business_id;
    END IF;

    -- Calculate total return value at SALE PRICE and COST
    -- Assumes input JSON 'items' has 'sale_item_id' (from original sale) and 'quantity' returned
    -- Also fetches item cost (using purchase_price as proxy - review this assumption)
    SELECT
        COALESCE(SUM(ri.quantity * si.unit_price), 0),
        COALESCE(SUM(ri.quantity * COALESCE(i.purchase_price, 0)), 0) -- Using current purchase_price as cost proxy
    INTO
        v_total_return_sale_value,
        v_total_return_cost_value
    FROM jsonb_to_recordset(v_return_items) AS ri(sale_item_id uuid, quantity numeric) -- Adjust keys if needed
    JOIN public.sale_items si ON si.sale_item_id = ri.sale_item_id -- Assuming 'sale_items' table
    JOIN public.items i ON i.item_id = si.item_id -- Get item cost proxy
    WHERE si.sale_id = v_sale_id; -- Ensure items belong to original sale

    IF v_total_return_sale_value <= 0 THEN
        RAISE EXCEPTION 'Return items invalid or total return sale value is zero or less.';
    END IF;

    -- Create Transaction Header for the Return
    -- Status is PAID (A/R adjustment complete). paid/due are 0 for this transaction.
        reference_no, transaction_type, transaction_date, status,
        total_amount, paid_amount, due_amount,
        notes, business_id, created_by, customer_id -- Link customer
    ) VALUES (
        v_return_invoice, 'SALE_RETURN'::public.transaction_type, v_return_date, 'PAID'::public.transaction_status,
        v_total_return_sale_value, 0, 0,
        'Sale Return: ' || COALESCE(v_reason, ''), v_business_id, v_user_id, v_customer_id
    ) RETURNING transaction_id INTO v_transaction_id;

    -- Create Correct Transaction Entries
    -- 1. Reverse Revenue/Receivable (@ Sale Price)

    -- 2. Reverse COGS/Inventory (@ Cost Price) - Only if cost value > 0
    IF v_total_return_cost_value > 0 THEN
    ELSE
         RAISE WARNING 'Sale Return %: Cost of returned items is zero or could not be determined; COGS reversal entries skipped.', v_return_invoice;
    END IF;


    -- Verify balance of this return transaction
    PERFORM public.verify_transaction_balance(v_transaction_id);

    -- Create Sale Return Header Record
        return_id, -- Assuming PK is 'return_id' and defaults or gen_random_uuid() is used
        sale_id, return_invoice, return_date, reason, notes,
        total_amount, transaction_id, business_id, created_by -- Use correct column name for user id
    ) VALUES (
        gen_random_uuid(), -- Assuming default PK generation
        v_sale_id, v_return_invoice, v_return_date, v_reason, v_notes,
        v_total_return_sale_value, v_transaction_id, v_business_id, v_user_id
    ) RETURNING sale_returns.return_id INTO v_return_id; -- Ensure PK column name is correct

    -- Create Return Item Details and Update Stock Quantity
    FOR v_return_item_data IN
        SELECT
            ri.item_id,
            ri.sale_item_id, -- Link to original sale item line
            ri.quantity,
            si.unit_price, -- Original sale unit price
            i.inventory_enabled
        FROM jsonb_to_recordset(v_return_items) AS ri(item_id uuid, sale_item_id uuid, quantity numeric) -- Adjust keys if needed
        JOIN public.sale_items si ON si.sale_item_id = ri.sale_item_id AND si.item_id = ri.item_id -- Ensure item matches
        JOIN public.items i ON i.item_id = ri.item_id
        WHERE si.sale_id = v_sale_id -- Ensure item belongs to original sale
    LOOP
        -- Insert return item detail
            return_id, sale_item_id, quantity, unit_price
        ) VALUES (
            v_return_id,
            v_return_item_data.sale_item_id,
            v_return_item_data.quantity,
            v_return_item_data.unit_price -- Store original sale price for reference
        );

        -- Update item inventory quantity if applicable
        IF v_return_item_data.inventory_enabled THEN
            UPDATE public.items
            SET stock_quantity = stock_quantity + v_return_item_data.quantity, -- ADDING back to stock
                updated_at = now()
                -- DO NOT update stock_value here. GL entry handles value.
            WHERE item_id = v_return_item_data.item_id;
        END IF;
    END LOOP;

    -- NO automatic payment creation here. Issuing a refund is separate.
    -- NO direct updates to sale.due_amount or business_customers.customer_balance. Triggers handle this.
    -- NO redundant nextval call.

    RAISE NOTICE 'Sale Return created successfully. Transaction ID: %', v_transaction_id;
    RETURN v_transaction_id; -- Return the transaction ID of the return

EXCEPTION
    WHEN others THEN
        RAISE EXCEPTION 'Error creating sale return: %', SQLERRM;
END;
$$;


ALTER FUNCTION public.create_sale_return(p_data jsonb) OWNER TO postgres;

--
-- TOC entry 999 (class 1255 OID 264606)
-- Name: create_sequences(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.create_sequences(business_id uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_base_name text;
BEGIN
    v_base_name := business_id::text;
    
    -- Create sequences for various business documents
    EXECUTE format('CREATE SEQUENCE IF NOT EXISTS %I START 1', v_base_name || '_purchase_invoice');
    EXECUTE format('CREATE SEQUENCE IF NOT EXISTS %I START 1', v_base_name || '_sale_invoice');
    EXECUTE format('CREATE SEQUENCE IF NOT EXISTS %I START 1', v_base_name || '_purchase_return_code');
    EXECUTE format('CREATE SEQUENCE IF NOT EXISTS %I START 1', v_base_name || '_sale_return_code');
    EXECUTE format('CREATE SEQUENCE IF NOT EXISTS %I START 1', v_base_name || '_item_code');
    EXECUTE format('CREATE SEQUENCE IF NOT EXISTS %I START 1', v_base_name || '_employee_code');
END;
$$;


ALTER FUNCTION public.create_sequences(business_id uuid) OWNER TO postgres;

--
-- TOC entry 998 (class 1255 OID 264607)
-- Name: delete_stock_adjustment(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.delete_stock_adjustment(p_adjustment_id uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_transaction_id UUID;
    v_business_id UUID;
    v_adjustment_items RECORD;
BEGIN
    -- Get transaction_id and business_id
    SELECT transaction_id, business_id 
    INTO v_transaction_id, v_business_id
    FROM stock_adjustments 
    WHERE adjustment_id = p_adjustment_id;

    -- Revert item quantities and values
    FOR v_adjustment_items IN 
        SELECT 
            sai.item_id,
            sai.previous_quantity,
            sai.quantity_adjusted,
            i.purchase_price
        FROM stock_adjustment_items sai
        JOIN items i ON i.item_id = sai.item_id
        WHERE sai.adjustment_id = p_adjustment_id
    LOOP
        UPDATE items 
        SET 
            stock_quantity = v_adjustment_items.previous_quantity,
            stock_value = stock_value - (v_adjustment_items.quantity_adjusted * v_adjustment_items.purchase_price)
        WHERE item_id = v_adjustment_items.item_id;
    END LOOP;

    -- Delete stock adjustment items
    DELETE FROM stock_adjustment_items 
    WHERE adjustment_id = p_adjustment_id;

    -- Delete stock adjustment
    DELETE FROM stock_adjustments 
    WHERE adjustment_id = p_adjustment_id;

    -- Delete transaction entries
    DELETE FROM transaction_entries 
    WHERE transaction_id = v_transaction_id;

    -- Delete transaction
    DELETE FROM transactions 
    WHERE transaction_id = v_transaction_id;
END;
$$;


ALTER FUNCTION public.delete_stock_adjustment(p_adjustment_id uuid) OWNER TO postgres;

--
-- TOC entry 769 (class 1255 OID 311718)
-- Name: find_missing_default_accounts(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.find_missing_default_accounts() RETURNS TABLE(business_id_missing uuid, business_name_missing text, missing_item_type text, missing_category_code text, missing_category_name_expected text, missing_account_code text, missing_account_name_expected text, is_group_expected boolean)
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Define the expected default chart of accounts structure
    -- This should mirror what create_default_chart_of_accounts does
    RETURN QUERY
    WITH expected_categories (category_code, category_name) AS (
        VALUES
            ('AST', 'ASSETS'),
            ('LBT', 'LIABILITIES'),
            ('EQT', 'EQUITIES'),
            ('RVN', 'REVENUES'),
            ('COS', 'COST OF SALES'),
            ('OPE', 'OPERATING EXPENSES')
    ),
    expected_accounts (
        category_code_ref, account_name, account_code, is_group, parent_account_code_ref
    ) AS (
        VALUES
        -- Assets
        ('AST', 'Current Assets', '1000', TRUE, NULL),
        ('AST', 'Fixed Assets', '1100', TRUE, NULL),
        ('AST', 'Petty Cash', '1010', FALSE, '1000'),
        ('AST', 'Cash in Bank', '1011', FALSE, '1000'),
        ('AST', 'Accounts Receivable - Customers', '1020', FALSE, '1000'),
        ('AST', 'Receivables from Suppliers', '1021', FALSE, '1000'),
        ('AST', 'Inventory', '1030', FALSE, '1000'),
        ('AST', 'Land', '1110', FALSE, '1100'),
        ('AST', 'Buildings', '1120', FALSE, '1100'),
        ('AST', 'Equipment', '1130', FALSE, '1100'),
        -- Liabilities
        ('LBT', 'Current Liabilities', '2000', TRUE, NULL),
        ('LBT', 'Accounts Payable - Suppliers', '2010', FALSE, '2000'),
        ('LBT', 'Payables to Customers', '2011', FALSE, '2000'),
        ('LBT', 'Sales Tax Payable', '2020', FALSE, '2000'),
        -- Equities
        ('EQT', 'Retained Earnings', '3000', FALSE, NULL), -- is_system = TRUE
        ('EQT', 'Opening Balance Equity', '3900', FALSE, NULL), -- is_system = TRUE
        -- Revenues
        ('RVN', 'Sales Revenue', '4000', TRUE, NULL),
        ('RVN', 'Sales of Goods', '4010', FALSE, '4000'),
        ('RVN', 'Sales of Services', '4020', FALSE, '4000'),
        ('RVN', 'Income from Other Sources', '4030', FALSE, NULL),
        ('RVN', 'Shipping Revenue', '4040', FALSE, NULL),
        ('RVN', 'Sales Discount', '4900', FALSE, NULL),
        ('RVN', 'Sales Returns and Allowances', '4910', FALSE, NULL),
        -- Cost of Sales
        ('COS', 'Cost of Sales', '5000', TRUE, NULL),
        ('COS', 'Direct Materials', '5010', FALSE, '5000'),
        ('COS', 'Direct Labor', '5020', FALSE, '5000'),
        ('COS', 'Purchase Discount', '5030', FALSE, '5000'),
        ('COS', 'Shipping Costs (Purchases)', '5040', FALSE, '5000'),
        ('COS', 'Cost of Goods Sold', '5015', FALSE, '5000'),
        ('COS', 'Purchase Returns and Allowances', '5041', FALSE, '5000'),
        -- Operating Expenses
        ('OPE', 'Selling, General, and Administrative Expenses', '6000', TRUE, NULL),
        ('OPE', 'General Expense', '6090', FALSE, '6000'),
        ('OPE', 'Stock Adjustment Expense', '6095', FALSE, '6000')
    ),
    all_businesses AS (
        -- Assuming you have a table listing all businesses
        -- Replace with `SELECT DISTINCT business_id AS id, 'N/A'::TEXT AS name FROM public.account_categories`
        -- or `SELECT DISTINCT business_id AS id, 'N/A'::TEXT AS name FROM public.accounts`
        -- if you don't have a separate businesses table, but this is less ideal.
        SELECT b.business_id, b.name FROM public.businesses b
    )
    -- First, check for missing categories
    SELECT
        ab.business_id AS business_id_missing,
        ab.name AS business_name_missing,
        'Category'::TEXT AS missing_item_type,
        ec.category_code AS missing_category_code,
        ec.category_name AS missing_category_name_expected,
        NULL::TEXT AS missing_account_code,
        NULL::TEXT AS missing_account_name_expected,
        NULL::BOOLEAN AS is_group_expected
    FROM
        all_businesses ab
    CROSS JOIN
        expected_categories ec
    LEFT JOIN
        public.account_categories ac_actual
        ON ac_actual.business_id = ab.business_id AND ac_actual.code = ec.category_code
    WHERE
        ac_actual.category_id IS NULL

    UNION ALL

    -- Then, check for missing accounts (only for businesses that have the category)
    SELECT
        ab.business_id AS business_id_missing,
        ab.name AS business_name_missing,
        'Account'::TEXT AS missing_item_type,
        ea.category_code_ref AS missing_category_code,
        ec.category_name AS missing_category_name_expected,
        ea.account_code AS missing_account_code,
        ea.account_name AS missing_account_name_expected,
        ea.is_group AS is_group_expected
    FROM
        all_businesses ab
    CROSS JOIN
        expected_accounts ea
    JOIN
        expected_categories ec ON ec.category_code = ea.category_code_ref -- To get category name
    JOIN
        public.account_categories ac_actual -- Category must exist for this business
        ON ac_actual.business_id = ab.business_id AND ac_actual.code = ea.category_code_ref
    LEFT JOIN
        public.accounts pa_parent -- Find parent account if applicable
        ON pa_parent.business_id = ab.business_id
        AND pa_parent.code = ea.parent_account_code_ref
        AND pa_parent.category_id = ac_actual.category_id -- Parent must be in the same category for this check
    LEFT JOIN
        public.accounts acc_actual
        ON acc_actual.business_id = ab.business_id
        AND acc_actual.code = ea.account_code
        AND acc_actual.category_id = ac_actual.category_id
        AND acc_actual.is_group = ea.is_group
        AND (
            (ea.parent_account_code_ref IS NULL AND acc_actual.parent_account_id IS NULL) OR
            (ea.parent_account_code_ref IS NOT NULL AND acc_actual.parent_account_id = pa_parent.account_id)
        )
    WHERE
        acc_actual.account_id IS NULL
        -- AND (ea.parent_account_code_ref IS NULL OR pa_parent.account_id IS NOT NULL) -- Ensure parent exists if expected
        -- The above line for parent check might be too strict if a missing parent is already reported.
        -- The primary check is for the account itself. If its parent is missing, it's a separate issue
        -- that makes this account's creation more complex, but this account is still "missing".

    ORDER BY
        business_id_missing, missing_item_type, missing_category_code, missing_account_code;
-- SELECT * FROM public.find_missing_default_accounts();

END;
$$;


ALTER FUNCTION public.find_missing_default_accounts() OWNER TO postgres;

--
-- TOC entry 1018 (class 1255 OID 264608)
-- Name: generate_business_dependencies(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.generate_business_dependencies(business_data jsonb) RETURNS uuid
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_auth_user_id UUID := auth.uid();  -- Get the authenticated user ID
    v_org_id UUID;
	v_existing_user_id UUID;
    v_business_id UUID;
BEGIN

	v_org_id := (business_data->>'org_id')::uuid;
    -- 4. Insert into businesses
        name,
        org_id,
        created_by,
        business_type,
        currency
    ) VALUES (
        business_data->>'name',
        v_org_id,
        v_auth_user_id,
        (business_data->>'business_type')::public.business_types,
        business_data->'currency'
    ) RETURNING business_id INTO v_business_id;

    -- Add default sale statuses
        business_id,
        name,
        sequence_order,
        is_default,
        type,
		is_editable
    ) VALUES 
    (v_business_id, 'Booked', 1, true, 'sale'::status_type, true),
    (v_business_id, 'In Process', 2, false, 'sale'::status_type, true),
    (v_business_id, 'Cancelled', 3, false, 'sale'::status_type, false),
    (v_business_id, 'Completed', 4, false, 'sale'::status_type, false);

    -- 5. Create the default Account Categories and Chart of Accounts
    --    The block for inserting into account_categories has been removed from here.
    PERFORM public.create_default_chart_of_accounts(v_business_id, v_org_id);

    -- 4. Insert into branch accesses
        employee_id,
        business_id
    ) VALUES (
        v_auth_user_id,
        v_business_id
    );

	RETURN v_business_id;
EXCEPTION
    WHEN OTHERS THEN
        RAISE EXCEPTION '%', SQLERRM;
END;
$$;


ALTER FUNCTION public.generate_business_dependencies(business_data jsonb) OWNER TO postgres;

--
-- TOC entry 1041 (class 1255 OID 264609)
-- Name: get_business_summaries(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_business_summaries(p_business_id uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_total_sales NUMERIC;
    v_total_purchases NUMERIC;
    v_total_received_sales NUMERIC;
    v_total_customer_dues NUMERIC;
    v_total_supplier_dues NUMERIC;
BEGIN
    -- Get total sales
    SELECT COALESCE(SUM(total_amount), 0)
    INTO v_total_sales
    FROM sales
    WHERE business_id = p_business_id
    AND status_id NOT IN (
        SELECT status_id 
        FROM statuses 
        WHERE name IN ('VOID', 'CANCELLED')
    );

    -- Get total purchases
    SELECT COALESCE(SUM(total_amount), 0)
    INTO v_total_purchases
    FROM purchases
    WHERE business_id = p_business_id;

    -- Get total received payments from sales
    SELECT COALESCE(SUM(paid_amount), 0)
    INTO v_total_received_sales
    FROM sales
    WHERE business_id = p_business_id
    AND status_id NOT IN (
        SELECT status_id 
        FROM statuses 
        WHERE name IN ('VOID', 'CANCELLED')
    );

    -- Get total customer dues (using customer_balance)
    SELECT COALESCE(SUM(customer_balance), 0)
    INTO v_total_customer_dues
    FROM business_customers
    WHERE business_id = p_business_id;

    -- Get total supplier dues (using supplier_balance)
    SELECT COALESCE(SUM(supplier_balance), 0)
    INTO v_total_supplier_dues
    FROM suppliers
    WHERE business_id = p_business_id;

    -- Return JSON object
    RETURN json_build_object(
        'total_sales', v_total_sales,
        'total_purchases', v_total_purchases,
        'total_received_sales', v_total_received_sales,
        'total_customer_dues', v_total_customer_dues,
        'total_supplier_dues', v_total_supplier_dues
    );
END;
$$;


ALTER FUNCTION public.get_business_summaries(p_business_id uuid) OWNER TO postgres;

--
-- TOC entry 1019 (class 1255 OID 264610)
-- Name: get_chart_of_accounts_tree(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_chart_of_accounts_tree(p_business_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
    v_result jsonb;
BEGIN
    SELECT jsonb_agg(category_obj ORDER BY category_code) -- Order categories by code
    INTO v_result
    FROM (
        SELECT
            jsonb_build_object(
                'category_id', ac.category_id,
                'name', ac.name,
                'code', ac.code,
                'description', ac.description,
                'children', COALESCE(
                    ( -- Subquery to aggregate top-level accounts/groups for this category
                        SELECT jsonb_agg(node ORDER BY account_code)
                        FROM (
                            SELECT
                                public.build_account_node(a.account_id, p_business_id) as node,
                                a.code as account_code
                            FROM public.accounts a
                            WHERE a.business_id = p_business_id
                              AND a.category_id = ac.category_id
                              AND a.parent_account_id IS NULL -- Start with top-level items in the category
                        ) AS top_level_accounts
                        WHERE node IS NOT NULL
                    ),
                    '[]'::jsonb -- Default to empty array if no top-level accounts/groups
                )
            ) AS category_obj,
            ac.code AS category_code
        FROM public.account_categories ac
        WHERE ac.business_id = p_business_id
    ) AS categories_subquery;

    -- If no categories found for the business, return an empty array
    IF v_result IS NULL THEN
        RETURN '[]'::jsonb;
    END IF;

    RETURN v_result;
END;
$$;


ALTER FUNCTION public.get_chart_of_accounts_tree(p_business_id uuid) OWNER TO postgres;

--
-- TOC entry 774 (class 1255 OID 276329)
-- Name: get_current_fiscal_period(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_current_fiscal_period(p_business_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_start_month INT;
    v_end_month INT;
    v_current_date DATE := NOW()::DATE;
    v_current_year INT := EXTRACT(YEAR FROM v_current_date);
    v_current_month INT := EXTRACT(MONTH FROM v_current_date);
    v_fiscal_start_year INT;
    v_fiscal_end_year INT;
    v_start_date DATE;
    v_end_date DATE;
BEGIN
    -- Get fiscal year details for the business
    SELECT fy.start_month, fy.end_month
    INTO v_start_month, v_end_month
    FROM public.businesses b
    JOIN public.fiscal_years fy ON b.fiscal_id = fy.fiscal_id
    WHERE b.business_id = p_business_id;

    IF v_start_month IS NULL THEN
        -- Handle case where business or fiscal year is not found or not set
        -- Defaulting to standard calendar year (Jan - Dec)
        v_start_month := 1;
        v_end_month := 12;
        -- Optionally, you could raise an exception or return NULL
        -- RETURN NULL;
        -- RAISE EXCEPTION 'Fiscal year not set for business_id %', p_business_id;
    END IF;

    -- Determine the start year of the current fiscal period
    IF v_current_month < v_start_month THEN
        v_fiscal_start_year := v_current_year - 1;
    ELSE
        v_fiscal_start_year := v_current_year;
    END IF;

    -- Determine the end year of the current fiscal period
    IF v_end_month < v_start_month THEN
        v_fiscal_end_year := v_fiscal_start_year + 1;
    ELSE
        v_fiscal_end_year := v_fiscal_start_year;
    END IF;

    -- Calculate the start date
    v_start_date := MAKE_DATE(v_fiscal_start_year, v_start_month, 1);

    -- Calculate the end date (last day of the end month)
    v_end_date := (DATE_TRUNC('MONTH', MAKE_DATE(v_fiscal_end_year, v_end_month, 1)) + INTERVAL '1 MONTH' - INTERVAL '1 DAY')::DATE;

    -- Construct JSON result
    RETURN jsonb_build_object(
        'start_date', v_start_date,
        'end_date', v_end_date
    );
EXCEPTION
    WHEN NO_DATA_FOUND THEN
         -- Handle case where business or fiscal year is not found
         -- Defaulting to standard calendar year (Jan - Dec) or return NULL/error
         RETURN jsonb_build_object(
            'start_date', MAKE_DATE(EXTRACT(YEAR FROM NOW())::INT, 1, 1),
            'end_date', MAKE_DATE(EXTRACT(YEAR FROM NOW())::INT, 12, 31)
         );
         -- RETURN NULL;
    WHEN OTHERS THEN
        -- Log error or handle other exceptions
        RAISE NOTICE 'Error in get_current_fiscal_period for business %: %', p_business_id, SQLERRM;
        RETURN NULL; -- Or re-raise the exception
END;
$$;


ALTER FUNCTION public.get_current_fiscal_period(p_business_id uuid) OWNER TO postgres;

--
-- TOC entry 1042 (class 1255 OID 264611)
-- Name: get_dashboard_data(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_dashboard_data(p_business_id uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_result JSON;
    v_fiscal_year_start DATE;
    v_fiscal_year_end DATE;
BEGIN
    -- Get fiscal year dates
    v_fiscal_year_start := DATE_TRUNC('year', CURRENT_DATE);
    v_fiscal_year_end := (v_fiscal_year_start + INTERVAL '1 year' - INTERVAL '1 day')::DATE;

    WITH daily_sales AS (
        -- Calculate today's sales
        SELECT COALESCE(SUM(total_amount), 0) as amount
        FROM sales
        WHERE business_id = p_business_id
        AND DATE(sale_date) = CURRENT_DATE
    ),
    yearly_income AS (
        -- Calculate total income for current fiscal year
        SELECT COALESCE(SUM(total_amount), 0) as amount
        FROM sales
        WHERE business_id = p_business_id
        AND sale_date BETWEEN v_fiscal_year_start AND v_fiscal_year_end
    ),
    yearly_expenses AS (
        -- Calculate total expenses for current fiscal year
        SELECT COALESCE(SUM(total_amount), 0) as amount
        FROM purchases
        WHERE business_id = p_business_id
        AND purchase_date BETWEEN v_fiscal_year_start AND v_fiscal_year_end
    ),
    new_customers AS (
        -- Count new customers in last 30 days
        SELECT COUNT(*) as count
        FROM business_customers
        WHERE business_id = p_business_id
        AND created_at >= (CURRENT_DATE - INTERVAL '30 days')
    ),
    top_selling_items AS (
        -- Get top 5 selling items
        SELECT 
            i.name,
            COALESCE(SUM(si.quantity), 0) as sold_count
        FROM sale_items si
        JOIN items i ON i.item_id = si.item_id
        JOIN sales s ON s.sale_id = si.sale_id
        WHERE s.business_id = p_business_id
		AND is_active = true 
        AND s.sale_date >= (CURRENT_DATE - INTERVAL '30 days')
        GROUP BY i.name
        ORDER BY sold_count DESC
        LIMIT 5
    ),
    low_stock_items AS (
        -- Get items with low stock
        SELECT 
            name,
            stock_quantity as stock_left
        FROM items
        WHERE business_id = p_business_id
		AND is_active = true
        AND stock_quantity <= alert_quantity
		AND item_type = 'goods'::public.item_type
        ORDER BY stock_quantity ASC
        LIMIT 5
    ),
    category_stats AS (
        -- Calculate item category statistics
        WITH total_sales AS (
            SELECT COALESCE(SUM(si.quantity * si.unit_price), 0) as total_amount
            FROM sale_items si
            JOIN sales s ON s.sale_id = si.sale_id
            WHERE s.business_id = p_business_id
            AND s.sale_date >= (CURRENT_DATE - INTERVAL '30 days')
        )
        SELECT 
            c.icon_info as icon_info,
            c.name as category_name,
            ROUND(
                (SUM(si.quantity * si.unit_price) * 100.0 / NULLIF((SELECT total_amount FROM total_sales), 0))::numeric, 
                2
            ) as percentage
        FROM sale_items si
        JOIN sales s ON s.sale_id = si.sale_id
        JOIN items i ON i.item_id = si.item_id
        JOIN item_categories c ON c.item_category_id = i.item_category_id
        WHERE s.business_id = p_business_id
        AND s.sale_date >= (CURRENT_DATE - INTERVAL '30 days')
        GROUP BY c.name, c.icon_info
        ORDER BY percentage DESC
        LIMIT 5
    )
    SELECT json_build_object(
        'daily_sales', (SELECT amount FROM daily_sales),
        'total_incomes_current_fiscal_year', (SELECT amount FROM yearly_income),
        'total_expenses_current_fiscal_year', (SELECT amount FROM yearly_expenses),
        'new_customers_past_30_days', (SELECT count FROM new_customers),
        'top_selling_items', (
            SELECT json_agg(
                json_build_object(
                    'name', name,
                    'sold_count', sold_count
                )
            )
            FROM top_selling_items
        ),
        'low_stock_items', (
            SELECT json_agg(
                json_build_object(
                    'name', name,
                    'stock_left', stock_left
                )
            )
            FROM low_stock_items
        ),
        'item_category_statistics', (
            SELECT json_agg(
                json_build_object(
                    'icon_info', icon_info,
                    'category_name', category_name,
                    'percentage', percentage
                )
            )
            FROM category_stats
        )
    ) INTO v_result;

    RETURN v_result;
END;
$$;


ALTER FUNCTION public.get_dashboard_data(p_business_id uuid) OWNER TO postgres;

--
-- TOC entry 1034 (class 1255 OID 266169)
-- Name: get_employee_sales_report(timestamp with time zone, timestamp with time zone, integer, integer, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_employee_sales_report(start_date timestamp with time zone DEFAULT NULL::timestamp with time zone, end_date timestamp with time zone DEFAULT NULL::timestamp with time zone, page_number integer DEFAULT 1, page_size integer DEFAULT 10, p_business_id uuid DEFAULT NULL::uuid, employee_name_filter text DEFAULT NULL::text) RETURNS TABLE(employee_name text, employee_role public.employee_type, employee_code text, total_items_sold numeric, total_revenue_generated numeric)
    LANGUAGE plpgsql
    AS $$
DECLARE
    offset_value integer;
BEGIN
    -- Calculate the offset for pagination
    offset_value := (page_number - 1) * page_size;

    -- Ensure page_number and page_size are not negative and page_size is not zero
    IF page_number < 1 THEN
        page_number := 1; -- Default to first page if page_number is invalid
    END IF;
    IF page_size < 1 THEN
        page_size := 10; -- Default to 10 items per page if page_size is invalid
    END IF;

    RETURN QUERY
    SELECT
        ev.name AS employee_name,
        ev.role AS employee_role,
        ev.code AS employee_code,
        COALESCE(SUM(si.quantity), 0) AS total_items_sold,
        COALESCE(SUM(s.total_amount), 0) AS total_revenue_generated
    FROM
        employee_view ev
    LEFT JOIN
        sales s ON s.created_by = ev.employee_id AND s.business_id = p_business_id
    LEFT JOIN
        sale_items si ON si.sale_id = s.sale_id
    WHERE
        (start_date IS NULL OR s.sale_date >= start_date)
        AND (end_date IS NULL OR s.sale_date <= end_date)
        AND (p_business_id IS NULL OR s.business_id = p_business_id)
        AND (employee_name_filter IS NULL OR ev.name ILIKE '%' || employee_name_filter || '%') -- Added employee name filter
    GROUP BY
        ev.employee_id,
        ev.name,
        ev.role,
        ev.code
    ORDER BY
        total_revenue_generated DESC
    LIMIT page_size
    OFFSET offset_value;

END;
$$;


ALTER FUNCTION public.get_employee_sales_report(start_date timestamp with time zone, end_date timestamp with time zone, page_number integer, page_size integer, p_business_id uuid, employee_name_filter text) OWNER TO postgres;

--
-- TOC entry 1039 (class 1255 OID 264613)
-- Name: get_next_item_code(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_next_item_code(business_id uuid) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_base_name text;
    next_value text;
    formatted_value text;
    sequence_exists boolean;
BEGIN
    v_base_name := business_id::text;
    
    -- Check if sequence exists
    SELECT EXISTS (
        SELECT 1 
        FROM pg_sequences 
        WHERE schemaname = 'public' 
        AND sequencename = v_base_name || '_item_code'
    ) INTO sequence_exists;
    
    -- Create sequence if it doesn't exist
    IF NOT sequence_exists THEN
        EXECUTE format('CREATE SEQUENCE IF NOT EXISTS public.%I START 1', v_base_name || '_item_code');
    END IF;
    
    -- Get the next value of the item_code sequence without incrementing
        EXECUTE format('SELECT LPAD(CASE 
             				WHEN is_called THEN (last_value + 1)::text 
             				ELSE last_value::text 
           				END, 6, ''0'') 
					FROM %I', v_base_name || '_item_code') INTO next_value;
    
    -- Format the value with prefix
    formatted_value := 'ITEM-' || next_value;
    
    RETURN formatted_value;
END;
$$;


