--
-- TOC entry 1024 (class 1255 OID 264626)
-- Name: get_total_dues_summary(uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_total_dues_summary(p_business_id uuid, p_start_date timestamp with time zone DEFAULT NULL::timestamp with time zone, p_end_date timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    result JSON;
    v_start_date TIMESTAMP WITH TIME ZONE;
    v_end_date TIMESTAMP WITH TIME ZONE;
    v_fiscal_start_month INTEGER;
    v_fiscal_end_month INTEGER;
    v_current_year INTEGER;
BEGIN
    -- Get fiscal year details for the business
    SELECT 
        fy.start_month,
        fy.end_month
    INTO 
        v_fiscal_start_month,
        v_fiscal_end_month
    FROM businesses b
    JOIN fiscal_years fy ON b.fiscal_id = fy.fiscal_id
    WHERE b.business_id = p_business_id;

    -- If dates are not provided, calculate fiscal year dates
    IF p_start_date IS NULL OR p_end_date IS NULL THEN
        v_current_year := EXTRACT(YEAR FROM CURRENT_DATE);
        
        -- If current month is less than fiscal start month, we're in previous year's fiscal year
        IF EXTRACT(MONTH FROM CURRENT_DATE) < v_fiscal_start_month THEN
            v_current_year := v_current_year - 1;
        END IF;

        v_start_date := make_timestamp(
            v_current_year,
            v_fiscal_start_month,
            1,
            0,
            0,
            0
        );
        
        -- If fiscal end month is less than start month, it means it spans to next year
        IF v_fiscal_end_month < v_fiscal_start_month THEN
            v_current_year := v_current_year + 1;
        END IF;
        
        v_end_date := make_timestamp(
            v_current_year,
            v_fiscal_end_month,
            1,
            0,
            0,
            0
        );
        -- Set to last day of the end month
        v_end_date := (v_end_date + INTERVAL '1 month' - INTERVAL '1 day');
    ELSE
        v_start_date := p_start_date;
        v_end_date := p_end_date;
    END IF;

    -- Get the combined dues summary
    WITH sales_dues AS (
        SELECT 
            COALESCE(SUM(due_amount), 0) as sales_due,
            COUNT(CASE WHEN due_amount > 0 THEN 1 END) as sales_due_count
        FROM sales
        WHERE 
            business_id = p_business_id
            AND created_at >= v_start_date
            AND created_at <= v_end_date
    ),
    purchase_dues AS (
        SELECT 
            COALESCE(SUM(due_amount), 0) as purchase_due,
            COUNT(CASE WHEN due_amount > 0 THEN 1 END) as purchase_due_count
        FROM purchases
        WHERE 
            business_id = p_business_id
            AND created_at >= v_start_date
            AND created_at <= v_end_date
    )
    SELECT json_build_object(
        'total_sales_due', sd.sales_due,
        'sales_due_count', sd.sales_due_count,
        'total_purchase_due', pd.purchase_due,
        'purchase_due_count', pd.purchase_due_count,
        'total_combined_due', (sd.sales_due + pd.purchase_due),
        'total_due_transactions', (sd.sales_due_count + pd.purchase_due_count),
        'start_date', v_start_date,
        'end_date', v_end_date
    ) INTO result
    FROM sales_dues sd, purchase_dues pd;

    RETURN result;
END;
$$;


ALTER FUNCTION public.get_total_dues_summary(p_business_id uuid, p_start_date timestamp with time zone, p_end_date timestamp with time zone) OWNER TO postgres;

--
-- TOC entry 1025 (class 1255 OID 264627)
-- Name: handle_purchase_audit(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.handle_purchase_audit() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_timestamp TEXT;
BEGIN

    -- Format timestamp
    v_timestamp := ' on ' || TO_CHAR(NOW(), 'DD Mon YYYY HH24:MI:SS');

    -- For purchase table changes
    IF TG_TABLE_NAME = 'purchases' THEN
        IF TG_OP = 'INSERT' THEN
                purchase_id,
                transaction_id,
                action_type,
                performed_by,
                new_data,
                change_details
            ) VALUES (
                NEW.purchase_id,
                NEW.transaction_id,
                'CREATED',
                auth.uid(),
                row_to_json(NEW),
                'Purchase created with invoice ' || NEW.purchase_invoice || v_timestamp
            );
        ELSIF TG_OP = 'UPDATE' THEN
            -- Check what kind of update occurred
            IF OLD.paid_amount != NEW.paid_amount THEN
                    purchase_id,
                    transaction_id,
                    action_type,
                    performed_by,
                    old_data,
                    new_data,
                    change_details
                ) VALUES (
                    NEW.purchase_id,
                    NEW.transaction_id,
                    'PAYMENT_ADDED',
                    auth.uid(),
                    jsonb_build_object('paid_amount', OLD.paid_amount, 'due_amount', OLD.due_amount),
                    jsonb_build_object('paid_amount', NEW.paid_amount, 'due_amount', NEW.due_amount),
                    'Payment updated from ' || OLD.paid_amount || ' to ' || NEW.paid_amount || v_timestamp
                );
            END IF;
        END IF;
    END IF;

    -- For purchase_returns table changes
    IF TG_TABLE_NAME = 'purchase_returns' THEN
        IF TG_OP = 'INSERT' THEN
                purchase_id,
                transaction_id,
                action_type,
                performed_by,
                new_data,
                change_details
            ) VALUES (
                NEW.purchase_id,
                NEW.transaction_id,
                'RETURN_CREATED',
                auth.uid(),
                row_to_json(NEW),
                'Purchase return created with invoice ' || NEW.return_invoice || ' for amount ' || NEW.total_amount || v_timestamp
            );
        END IF;
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION public.handle_purchase_audit() OWNER TO postgres;

--
-- TOC entry 1026 (class 1255 OID 264628)
-- Name: handle_sale_audit(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.handle_sale_audit() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_timestamp TEXT;
BEGIN

    -- Format timestamp
    v_timestamp := ' on ' || TO_CHAR(NOW(), 'DD Mon YYYY HH24:MI:SS');

    -- For sale table changes
    IF TG_TABLE_NAME = 'sales' THEN
        IF TG_OP = 'INSERT' THEN
                sale_id,
                transaction_id,
                action_type,
                performed_by,
                new_data,
                change_details
            ) VALUES (
                NEW.sale_id,
                NEW.transaction_id,
                'CREATED',
                NEW.created_by,
                row_to_json(NEW),
                'Sale created with invoice ' || NEW.sale_invoice || v_timestamp
            );
        ELSIF TG_OP = 'UPDATE' THEN
            -- Check for payment updates
            IF OLD.paid_amount != NEW.paid_amount THEN
                    sale_id,
                    transaction_id,
                    action_type,
                    performed_by,
                    old_data,
                    new_data,
                    change_details
                ) VALUES (
                    NEW.sale_id,
                    NEW.transaction_id,
                    'PAYMENT_ADDED',
                    NEW.created_by,
                    jsonb_build_object('paid_amount', OLD.paid_amount, 'due_amount', OLD.due_amount),
                    jsonb_build_object('paid_amount', NEW.paid_amount, 'due_amount', NEW.due_amount),
                    'Payment updated from ' || OLD.paid_amount || ' to ' || NEW.paid_amount || v_timestamp
                );
            END IF;
            
            -- Check for status changes
			IF OLD.status_id != NEW.status_id THEN
			    DECLARE
			        old_status_name text;
			        new_status_name text;
			    BEGIN
			        -- Get the status names
			        SELECT name INTO old_status_name
			        FROM statuses 
			        WHERE status_id = OLD.status_id;
			
			        SELECT name INTO new_status_name
			        FROM statuses 
			        WHERE status_id = NEW.status_id;
			
			            sale_id,
			            transaction_id,
			            action_type,
			            performed_by,
			            old_data,
			            new_data,
			            change_details
			        ) VALUES (
			            NEW.sale_id,
			            NEW.transaction_id,
			            'STATUS_CHANGED',
			            NEW.created_by,
			            jsonb_build_object('status_id', OLD.status_id, 'status_name', old_status_name),
			            jsonb_build_object('status_id', NEW.status_id, 'status_name', new_status_name),
			            'Status changed from "' || COALESCE(old_status_name, 'Unknown') || '" to "' || COALESCE(new_status_name, 'Unknown') || '"'
			        );
			    END;
			END IF;

        END IF;
    END IF;

    -- For sale_returns table changes
    IF TG_TABLE_NAME = 'sale_returns' THEN
        IF TG_OP = 'INSERT' THEN
                sale_id,
                transaction_id,
                action_type,
                performed_by,
                new_data,
                change_details
            ) VALUES (
                NEW.sale_id,
                NEW.transaction_id,
                'RETURN_CREATED',
                NEW.created_by,
                row_to_json(NEW),
                'Sale return created with invoice ' || NEW.return_invoice || ' for amount ' || NEW.total_amount || v_timestamp
            );
        END IF;
    END IF;

    RETURN NEW;
END;
$$;


