--
-- TOC entry 1030 (class 1255 OID 264640)
-- Name: update_account_balance(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.update_account_balance() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_account_id UUID;
    v_amount NUMERIC;
    v_entry_type public.entry_type;
    v_multiplier INTEGER;
BEGIN
    IF TG_OP = 'DELETE' THEN
        v_account_id := OLD.account_id;
        v_amount := OLD.amount;
        v_entry_type := OLD.entry_type;
        v_multiplier := -1; -- Reverse the operation
    ELSE -- INSERT or UPDATE
        v_account_id := NEW.account_id;
        v_amount := NEW.amount;
        v_entry_type := NEW.entry_type;
        v_multiplier := 1;

        -- If UPDATE, first reverse the OLD amount
        IF TG_OP = 'UPDATE' THEN
             -- Ensure we only update if account_id or amount changed
             IF OLD.account_id != NEW.account_id OR OLD.amount != NEW.amount OR OLD.entry_type != NEW.entry_type THEN
                 UPDATE public.accounts
                 SET balance = balance -
                     CASE
                         WHEN OLD.entry_type = 'DEBIT' THEN OLD.amount
                         ELSE -OLD.amount -- Subtracting a negative credit is adding
                     END
                 WHERE account_id = OLD.account_id;

                 -- If account ID changed, the NEW account update will handle the addition below.
                 -- If only amount/type changed, we proceed to update the same account with the new value.
             ELSE
                -- If relevant fields didn't change, no balance update needed
                RETURN NEW;
             END IF;
        END IF;
    END IF;

    -- Apply the change (for INSERT, or the NEW value of UPDATE)
    UPDATE public.accounts
    SET balance = balance +
        (CASE
            WHEN v_entry_type = 'DEBIT' THEN v_amount
            ELSE -v_amount
        END * v_multiplier)
    WHERE account_id = v_account_id;

    RETURN NEW; -- For INSERT/UPDATE
END;
$$;


ALTER FUNCTION public.update_account_balance() OWNER TO postgres;

--
-- TOC entry 1031 (class 1255 OID 264641)
-- Name: update_customer_balance_from_entry(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.update_customer_balance_from_entry() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_transaction_id UUID;
    v_account_id UUID;
    v_business_id UUID;
    v_customer_id UUID;
    v_ar_account_id UUID; -- Account ID for Accounts Receivable - Customers (1020)
    v_ap_account_id UUID; -- Account ID for Payables to Customers (2011)
    v_recalculated_balance NUMERIC;
BEGIN
    -- Determine which record (NEW or OLD) contains the relevant info
    IF TG_OP = 'DELETE' THEN
        v_transaction_id := OLD.transaction_id;
        v_account_id := OLD.account_id;
    ELSE -- INSERT or UPDATE
        v_transaction_id := NEW.transaction_id;
        v_account_id := NEW.account_id;
    END IF;

    -- Get business_id and customer_id from the transaction header
    SELECT t.business_id, t.customer_id
    INTO v_business_id, v_customer_id
    FROM public.transactions t
    WHERE t.transaction_id = v_transaction_id;

    -- If no business or customer found for the transaction, exit
    IF v_business_id IS NULL OR v_customer_id IS NULL THEN
        RETURN NULL;
    END IF;

    -- Get the specific AR and AP account IDs for THIS business
    SELECT account_id INTO v_ar_account_id FROM public.accounts WHERE business_id = v_business_id AND code = '1020';
    SELECT account_id INTO v_ap_account_id FROM public.accounts WHERE business_id = v_business_id AND code = '2011';

    -- Check if the affected account is one we track for customer balances
    IF v_account_id != v_ar_account_id AND v_account_id != v_ap_account_id THEN
        RETURN NULL; -- Not a relevant account, do nothing
    END IF;

    -- Recalculate the net balance for this customer from transaction_entries
    -- *** LOGIC MODIFIED: Positive = Business Owes Customer, Negative = Customer Owes Business ***
    -- Balance = (Credits to A/P - Debits to A/P) - (Debits to A/R - Credits to A/R)
    SELECT COALESCE(SUM(
               CASE
                   -- Accounts Receivable (Asset - What Customer Owes Us): Debit makes balance more negative, Credit makes balance less negative
                   WHEN te.account_id = v_ar_account_id THEN
                       te.amount * (CASE WHEN te.entry_type = 'DEBIT' THEN -1 ELSE 1 END) -- Flipped Sign
                   -- Accounts Payable (Liability - What Business Owes Customer): Credit makes balance more positive, Debit makes balance less positive
                   WHEN te.account_id = v_ap_account_id THEN
                       te.amount * (CASE WHEN te.entry_type = 'CREDIT' THEN 1 ELSE -1 END) -- Flipped Sign
                   ELSE 0 -- Ignore other accounts
               END
           ), 0)
    INTO v_recalculated_balance
    FROM public.transaction_entries te
    JOIN public.transactions t ON te.transaction_id = t.transaction_id
    WHERE t.business_id = v_business_id
      AND t.customer_id = v_customer_id
      AND te.account_id IN (v_ar_account_id, v_ap_account_id); -- Only consider these two accounts

    -- Update the business_customers table
    UPDATE public.business_customers bc
    SET customer_balance = v_recalculated_balance,
        updated_at = now() -- Keep track of the update
    WHERE bc.business_id = v_business_id
      AND bc.customer_id = v_customer_id;

    RETURN NULL; -- Trigger is AFTER, return value is ignored

EXCEPTION
    WHEN others THEN
        -- Log error or handle appropriately
        RAISE WARNING 'Error in update_customer_balance_from_entry trigger: %', SQLERRM;
        RETURN NULL; -- Prevent trigger failure from blocking the original operation
END;
$$;


ALTER FUNCTION public.update_customer_balance_from_entry() OWNER TO postgres;

--
-- TOC entry 1032 (class 1255 OID 264642)
-- Name: update_sale(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.update_sale(p_sale_json jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_transaction_id uuid;
    v_sale_id uuid;
    v_business_id uuid;
    v_customer_id uuid;
    v_main_account_id uuid;
    v_receivable_account_id uuid;
    v_sale_date timestamp with time zone;
    v_sale_item record;
    v_existing_sale record;
    v_old_sale_item record;
    v_status_id uuid;
    v_sale_item_id uuid;
    v_subservice record;
BEGIN
    -- Extract key values
    v_sale_id := (p_sale_json->>'sale_id')::uuid;
    v_business_id := (p_sale_json->>'business_id')::uuid;
    v_customer_id := (p_sale_json->>'customer_id')::uuid;
    
    -- Get existing sale information
    SELECT s.*, t.transaction_id, t.paid_amount, t.reference_no
    INTO v_existing_sale
    FROM sales s
    JOIN transactions t ON t.transaction_id = s.transaction_id
    WHERE s.sale_id = v_sale_id;
    
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Sale not found';
    END IF;
    
    v_transaction_id := v_existing_sale.transaction_id;
    
    -- Get account IDs
    SELECT account_id INTO v_main_account_id
    FROM accounts 
    WHERE business_id = v_business_id AND code = 'TRP';
    
    SELECT account_id INTO v_receivable_account_id
    FROM accounts 
    WHERE business_id = v_business_id AND code = 'MOA';
    
    -- Revert inventory changes for existing sale items
    FOR v_old_sale_item IN 
        SELECT si.*, i.item_type, i.inventory_enabled
        FROM sale_items si
        JOIN items i ON i.item_id = si.item_id
        WHERE si.sale_id = v_sale_id
    LOOP
        IF v_old_sale_item.item_type = 'goods' AND v_old_sale_item.inventory_enabled THEN
            UPDATE items
            SET 
                stock_quantity = stock_quantity + v_old_sale_item.quantity,
                stock_value = stock_value + (v_old_sale_item.quantity * v_old_sale_item.unit_price)
            WHERE item_id = v_old_sale_item.item_id;
        END IF;
    END LOOP;
    
    -- Delete existing sale items and subservices
    DELETE FROM sale_item_subservices 
    WHERE sale_item_id IN (SELECT sale_item_id FROM sale_items WHERE sale_id = v_sale_id);
    DELETE FROM sale_items WHERE sale_id = v_sale_id;
    
    -- Update transaction
    UPDATE transactions
    SET
        total_amount = (p_sale_json->>'grand_total')::numeric,
        due_amount = (p_sale_json->>'grand_total')::numeric - paid_amount,
        metadata = p_sale_json,
        updated_at = CURRENT_TIMESTAMP
    WHERE transaction_id = v_transaction_id;
    
    -- Update transaction entries
    UPDATE transaction_entries
    SET amount = (p_sale_json->>'grand_total')::numeric
    WHERE transaction_id = v_transaction_id;
    
    -- Update sale record
    UPDATE sales
    SET
        customer_id = v_customer_id,
        subtotal = (p_sale_json->>'subtotal')::numeric,
        discount_amount = (p_sale_json->>'discount_amount')::numeric,
        tax_amount = (p_sale_json->>'tax_total')::numeric,
        shipping_charge = (p_sale_json->>'shipping')::numeric,
        total_amount = (p_sale_json->>'grand_total')::numeric,
        due_amount = (p_sale_json->>'grand_total')::numeric - v_existing_sale.paid_amount,
        metadata = p_sale_json,
        updated_at = CURRENT_TIMESTAMP
    WHERE sale_id = v_sale_id;
    
    -- Create new sale items and update inventory
    FOR v_sale_item IN 
        SELECT 
            x.*,
            i.item_type,
            i.inventory_enabled,
            x.subservices::jsonb as subservices_data
        FROM jsonb_to_recordset(p_sale_json->'sale_items') 
        AS x(item_id uuid, quantity numeric, unit_price numeric, subservices jsonb)
        JOIN items i ON i.item_id = x.item_id::uuid
    LOOP
        -- Insert sale item
            sale_id,
            item_id,
            quantity,
            unit_price
        ) VALUES (
            v_sale_id,
            v_sale_item.item_id,
            v_sale_item.quantity,
            v_sale_item.unit_price
        ) RETURNING sale_item_id INTO v_sale_item_id;
        
        -- If item is a service and has subservices, add them
        IF v_sale_item.item_type = 'services' AND 
           v_sale_item.subservices_data IS NOT NULL AND 
           jsonb_array_length(v_sale_item.subservices_data) > 0 THEN
            
            FOR v_subservice IN 
                SELECT * FROM jsonb_to_recordset(v_sale_item.subservices_data)
                AS x(sub_service_id uuid, quantity numeric, additional_price numeric)
            LOOP
                    sale_item_id,
                    sub_service_id,
                    quantity,
                    additional_price
                ) VALUES (
                    v_sale_item_id,
                    v_subservice.sub_service_id,
                    v_subservice.quantity,
                    v_subservice.additional_price
                );
            END LOOP;
        END IF;
        
        -- Update item inventory if enabled (only for goods)
        IF v_sale_item.item_type = 'goods' AND v_sale_item.inventory_enabled THEN
            UPDATE items
            SET 
                stock_quantity = stock_quantity - v_sale_item.quantity,
                stock_value = stock_value - (v_sale_item.quantity * v_sale_item.unit_price)
            WHERE item_id = v_sale_item.item_id;
        END IF;
    END LOOP;
    
    -- Update business_customers due amount
    UPDATE business_customers 
    SET due = due - v_existing_sale.due_amount + ((p_sale_json->>'grand_total')::numeric - v_existing_sale.paid_amount)
    WHERE business_id = v_business_id 
    AND customer_id = v_customer_id;
    
    RETURN (SELECT row_to_json(sale_view)
    FROM sale_view
    WHERE sale_id = v_sale_id);
EXCEPTION
    WHEN others THEN
        RAISE EXCEPTION 'Error in update_sale: %', SQLERRM;
END;
$$;


ALTER FUNCTION public.update_sale(p_sale_json jsonb) OWNER TO postgres;

--
-- TOC entry 1007 (class 1255 OID 264643)
-- Name: update_supplier_balance_from_entry(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.update_supplier_balance_from_entry() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_transaction_id UUID;
    v_account_id UUID;
    v_business_id UUID;
    v_supplier_id UUID;
    v_ap_supp_acc_id UUID; -- Account ID for Accounts Payable - Suppliers (2010)
    v_ar_supp_acc_id UUID; -- Account ID for Receivables from Suppliers (1021)
    v_recalculated_balance NUMERIC;
BEGIN
    -- Determine which record (NEW or OLD) contains the relevant info
    IF TG_OP = 'DELETE' THEN
        v_transaction_id := OLD.transaction_id;
        v_account_id := OLD.account_id;
    ELSE -- INSERT or UPDATE
        v_transaction_id := NEW.transaction_id;
        v_account_id := NEW.account_id;
    END IF;

    -- Get business_id and supplier_id from the transaction header
    SELECT t.business_id, t.supplier_id
    INTO v_business_id, v_supplier_id
    FROM public.transactions t
    WHERE t.transaction_id = v_transaction_id;

    -- If no business or supplier found for the transaction, exit
    IF v_business_id IS NULL OR v_supplier_id IS NULL THEN
        RETURN NULL;
    END IF;

    -- Get the specific AP and AR account IDs for THIS business
    SELECT account_id INTO v_ap_supp_acc_id FROM public.accounts WHERE business_id = v_business_id AND code = '2010';
    SELECT account_id INTO v_ar_supp_acc_id FROM public.accounts WHERE business_id = v_business_id AND code = '1021';

    -- Check if the affected account is one we track for supplier balances
    IF v_account_id != v_ap_supp_acc_id AND v_account_id != v_ar_supp_acc_id THEN
        RETURN NULL; -- Not a relevant account, do nothing
    END IF;

    -- Recalculate the net balance for this supplier from transaction_entries
    -- *** LOGIC MODIFIED: Positive = Supplier Owes Business, Negative = Business Owes Supplier ***
    -- Balance = (Debits to A/R - Credits to A/R) - (Credits to A/P - Debits to A/P)
    SELECT COALESCE(SUM(
               CASE
                   -- Accounts Payable (Liability - What Business Owes): Credit makes balance more negative, Debit makes balance less negative
                   WHEN te.account_id = v_ap_supp_acc_id THEN
                       te.amount * (CASE WHEN te.entry_type = 'CREDIT' THEN 1 ELSE -1 END) -- Flipped Sign
                   -- Accounts Receivable (Asset - What Supplier Owes): Debit makes balance more positive, Credit makes balance less positive
                   WHEN te.account_id = v_ar_supp_acc_id THEN
                       te.amount * (CASE WHEN te.entry_type = 'DEBIT' THEN -1 ELSE 1 END) -- Flipped Sign
                   ELSE 0 -- Ignore other accounts
               END
           ), 0)
    INTO v_recalculated_balance
    FROM public.transaction_entries te
    JOIN public.transactions t ON te.transaction_id = t.transaction_id
    WHERE t.business_id = v_business_id
      AND t.supplier_id = v_supplier_id
      AND te.account_id IN (v_ap_supp_acc_id, v_ar_supp_acc_id); -- Only consider these two accounts

    -- Update the suppliers table
    UPDATE public.suppliers s
    SET supplier_balance = v_recalculated_balance,
        updated_at = now() -- Keep track of the update
    WHERE s.supplier_id = v_supplier_id;

    RETURN NULL; -- Trigger is AFTER, return value is ignored

EXCEPTION
    WHEN others THEN
        RAISE WARNING 'Error in update_supplier_balance_from_entry trigger: %', SQLERRM;
        RETURN NULL;
END;
$$;


ALTER FUNCTION public.update_supplier_balance_from_entry() OWNER TO postgres;

--
-- TOC entry 1014 (class 1255 OID 264644)
-- Name: upsert_business_customer(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.upsert_business_customer(p_customer_data jsonb) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    -- Input Data
    v_business_id UUID := p_customer_data->>'business_id';
    v_customer_id UUID := p_customer_data->>'customer_id';
    v_name TEXT := p_customer_data->>'name';
    v_image TEXT := p_customer_data->>'image';
    v_address TEXT := p_customer_data->>'address';
    v_opening_balance NUMERIC := COALESCE((p_customer_data->>'customer_balance')::numeric, 0); -- Default to 0
    v_opening_balance_date TIMESTAMPTZ := now();

    -- Internal Variables
    v_user_id UUID := COALESCE(auth.uid(), v_customer_id); -- Assuming Supabase auth
    v_upsert_result RECORD;
    v_is_insert BOOLEAN := FALSE;
    v_transaction_id UUID;
    v_ref_no TEXT;

    -- Account IDs
    v_ar_cust_acc_id UUID;   -- Accounts Receivable - Customers (1020)
    v_ap_cust_acc_id UUID;   -- Payables to Customers (2011)
    v_ob_equity_acc_id UUID; -- Opening Balance Equity (3900)

    -- Account Codes
    v_ar_cust_code TEXT := '1020';
    v_ap_cust_code TEXT := '2011';
    v_ob_equity_code TEXT := '3900';
BEGIN
    -- Validate required inputs
    IF v_business_id IS NULL OR v_customer_id IS NULL OR v_name IS NULL THEN
        RAISE EXCEPTION 'business_id, customer_id, and name are required.';
    END IF;

    -- Perform Upsert using INSERT ON CONFLICT
    WITH upsert AS (
            business_id, customer_id, name, image, address, customer_balance, created_at, updated_at
        ) VALUES (
            v_business_id, v_customer_id, v_name, v_image, v_address, v_opening_balance, now(), now()
        )
        ON CONFLICT (business_id, customer_id) DO UPDATE SET
            name = EXCLUDED.name,
            image = EXCLUDED.image,
            address = EXCLUDED.address,
            updated_at = now()
            -- DO NOT update customer_balance here on conflict!
        RETURNING xmax -- xmax = 0 for INSERT, non-zero for UPDATE
    )
    SELECT xmax INTO v_upsert_result FROM upsert;

    -- Check if an INSERT occurred (xmax = 0 indicates INSERT)
    IF v_upsert_result.xmax = 0 THEN
        v_is_insert := TRUE;
    END IF;

    -- If it was an INSERT AND an opening balance was provided and is non-zero
    IF v_is_insert AND v_opening_balance != 0 THEN

        -- Fetch required account IDs for the business
        SELECT account_id INTO v_ar_cust_acc_id FROM public.accounts WHERE business_id = v_business_id AND code = v_ar_cust_code;
        SELECT account_id INTO v_ap_cust_acc_id FROM public.accounts WHERE business_id = v_business_id AND code = v_ap_cust_code;
        SELECT account_id INTO v_ob_equity_acc_id FROM public.accounts WHERE business_id = v_business_id AND code = v_ob_equity_code;

        -- Validate that accounts exist
        IF v_ob_equity_acc_id IS NULL THEN
             RAISE EXCEPTION 'Opening Balance Equity account (Code: %) not found for business %.', v_ob_equity_code, v_business_id;
        END IF;
        IF v_opening_balance > 0 AND v_ar_cust_acc_id IS NULL THEN
             RAISE EXCEPTION 'Accounts Receivable - Customers account (Code: %) not found for business %.', v_ar_cust_code, v_business_id;
        END IF;
         IF v_opening_balance < 0 AND v_ap_cust_acc_id IS NULL THEN
             RAISE EXCEPTION 'Payables to Customers account (Code: %) not found for business %.', v_ap_cust_code, v_business_id;
        END IF;

        -- Generate a unique reference number for the opening balance transaction
        v_ref_no := 'OB-CUST-' || v_customer_id::text || '-' || to_char(v_opening_balance_date, 'YYYYMMDD');

        -- Create the Transaction Header
            reference_no, transaction_type, transaction_date, status,
            total_amount, paid_amount, due_amount, -- Amounts represent the magnitude of the balance being set up
            notes, business_id, created_by, customer_id -- Link to customer
        ) VALUES (
            v_ref_no, 'CUSTOMER_OPENING_BALANCE'::public.transaction_type, v_opening_balance_date, 'PAID'::public.transaction_status, -- Mark as PAID/Complete
            abs(v_opening_balance), abs(v_opening_balance), 0,
            'Opening balance setup for customer ' || v_name, v_business_id, v_user_id, v_customer_id
        ) RETURNING transaction_id INTO v_transaction_id;

        -- Create Transaction Entries based on balance sign
        IF v_opening_balance < 0 THEN
            -- Customer owes Business: Debit A/R, Credit OB Equity
        ELSE -- v_opening_balance < 0
            -- Business owes Customer: Debit OB Equity, Credit A/P
        END IF;

        -- Verify the balance of the opening balance transaction itself
        PERFORM public.verify_transaction_balance(v_transaction_id);

        -- Note: The trigger `trigger_update_customer_balance` on `transaction_entries`
        -- should fire automatically due to the inserts above and correctly set the
        -- `customer_balance` in `business_customers` based on these new entries.
        -- The initial insert into business_customers already set the balance,
        -- but the trigger recalculating based on GL entries ensures consistency.

    END IF; -- End of opening balance handling

    RETURN; -- Function returns void

EXCEPTION
    WHEN unique_violation THEN
        -- This might occur if the generated reference_no collides, though unlikely.
        RAISE EXCEPTION 'Failed to upsert customer OB: Unique constraint violated. Check reference number "%". Detail: %', v_ref_no, SQLERRM;
    WHEN others THEN
        -- Catch potential errors like account not found or balance verification failure
        RAISE EXCEPTION 'Failed to upsert business customer: %', v_user_id;
END;
$$;


ALTER FUNCTION public.upsert_business_customer(p_customer_data jsonb) OWNER TO postgres;

--
-- TOC entry 1033 (class 1255 OID 264646)
-- Name: upsert_employee_role(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.upsert_employee_role(employee_role_json jsonb) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_employee_role_id UUID;
    v_permission JSONB;
    v_submenu JSONB;
BEGIN
    -- Check if employee_role_id is provided
    IF (employee_role_json->>'employee_role_id') IS NOT NULL THEN
        v_employee_role_id := (employee_role_json->>'employee_role_id')::UUID;
        
        -- Update existing employee role
        UPDATE public.employee_roles
        SET 
            name = COALESCE(employee_role_json->>'name', name),
            description = COALESCE(employee_role_json->>'description', description)
        WHERE employee_role_id = v_employee_role_id;
    ELSE
        -- Insert new employee role
        VALUES (employee_role_json->>'name', employee_role_json->>'description', true, (employee_role_json->>'business_id')::uuid)
        RETURNING employee_role_id INTO v_employee_role_id;
    END IF;

    -- Delete existing permissions for this role
    DELETE FROM public.permissions WHERE employee_role_id = v_employee_role_id;

    -- Insert new permissions
    FOR v_permission IN SELECT * FROM jsonb_array_elements(employee_role_json->'permissions')
    LOOP
        -- Insert main module permission
        VALUES (
            v_employee_role_id,
            (v_permission->>'id')::bigint,
            (v_permission->'permissions'->>'view')::boolean,
            (v_permission->'permissions'->>'add')::boolean,
            (v_permission->'permissions'->>'edit')::boolean,
            (v_permission->'permissions'->>'delete')::boolean,
            (v_permission->'permissions'->>'print')::boolean
        );

        -- Insert submenu permissions
        FOR v_submenu IN SELECT * FROM jsonb_array_elements(v_permission->'submenus')
        LOOP
            VALUES (
                v_employee_role_id,
                (v_permission->>'id')::bigint,
                (v_submenu->>'id')::bigint,
                (v_submenu->'permissions'->>'view')::boolean,
                (v_submenu->'permissions'->>'add')::boolean,
                (v_submenu->'permissions'->>'edit')::boolean,
                (v_submenu->'permissions'->>'delete')::boolean,
                (v_submenu->'permissions'->>'print')::boolean
            );
        END LOOP;
    END LOOP;
END;
$$;


ALTER FUNCTION public.upsert_employee_role(employee_role_json jsonb) OWNER TO postgres;

--
-- TOC entry 1010 (class 1255 OID 264647)
-- Name: upsert_expense(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.upsert_expense(p_expense_data jsonb) RETURNS uuid
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_expense_id UUID := p_expense_data->>'expense_id';
    v_transaction_id UUID;
    v_business_id UUID := p_expense_data->>'business_id';
    v_user_id UUID := auth.uid(); -- Assuming you use Supabase auth
    v_date TIMESTAMPTZ := (p_expense_data->>'date')::timestamptz;
    v_amount NUMERIC := (p_expense_data->>'amount')::numeric;
    v_expense_account_id UUID; -- Determined based on default
    v_payment_account_id UUID; -- Determined based on payment_type
    v_expense_for TEXT := p_expense_data->>'expense_for';
    v_payment_type public.payment_type := (p_expense_data->>'payment_type')::public.payment_type;
    v_note TEXT := p_expense_data->>'note';
    v_reference_number TEXT := p_expense_data->>'reference_number';
    v_expense_category_id UUID := (p_expense_data->>'expense_category_id')::uuid; -- Optional link to expense_categories table
    v_existing_txn_id UUID;
    v_ref_no TEXT;
    v_default_expense_code TEXT := '6090'; -- Code for 'General Expense'
    v_petty_cash_code TEXT := '1010';    -- Code for 'Petty Cash'
    v_cash_in_bank_code TEXT := '1011';  -- Code for 'Cash in Bank'
BEGIN
    -- Validate required fields from JSON
    IF v_business_id IS NULL OR v_date IS NULL OR v_amount IS NULL OR v_amount <= 0 OR v_expense_for IS NULL OR v_payment_type IS NULL THEN
        RAISE EXCEPTION 'Missing required expense data: business_id, date, amount > 0, expense_for, payment_type are required.';
    END IF;

    -- Fetch the default expense account ID
    SELECT account_id INTO v_expense_account_id
    FROM public.accounts
    WHERE business_id = v_business_id AND code = v_default_expense_code AND is_group = FALSE;

    IF v_expense_account_id IS NULL THEN
        RAISE EXCEPTION 'Default expense account (Code: %) not found for business_id %.', v_default_expense_code, v_business_id;
    END IF;

    -- Determine the payment account ID based on payment_type
    IF v_payment_type = 'cash' THEN -- Adjust type names if needed
        SELECT account_id INTO v_payment_account_id
        FROM public.accounts
        WHERE business_id = v_business_id AND code = v_petty_cash_code AND is_group = FALSE;

        IF v_payment_account_id IS NULL THEN
            RAISE EXCEPTION 'Petty Cash account (Code: %) not found for business_id %.', v_petty_cash_code, v_business_id;
        END IF;
    ELSE -- Assume Bank, Card, Transfer, Other map to Cash in Bank
        SELECT account_id INTO v_payment_account_id
        FROM public.accounts
        WHERE business_id = v_business_id AND code = v_cash_in_bank_code AND is_group = FALSE;

        IF v_payment_account_id IS NULL THEN
            RAISE EXCEPTION 'Cash in Bank account (Code: %) not found for business_id %.', v_cash_in_bank_code, v_business_id;
        END IF;
    END IF;

    -- Generate a reference number if not provided (example logic)
    IF v_reference_number IS NULL OR v_reference_number = '' THEN
         v_ref_no := 'EXP-' || to_char(v_date, 'YYYYMMDD') || '-' || upper(substring(gen_random_uuid()::text from 1 for 6));
    ELSE
        v_ref_no := v_reference_number;
    END IF;

    IF v_expense_id IS NOT NULL THEN
        -- ======== UPDATE PATH ========
        SELECT transaction_id INTO v_existing_txn_id
        FROM public.expenses
        WHERE expense_id = v_expense_id AND business_id = v_business_id;

        IF v_existing_txn_id IS NULL THEN
            RAISE EXCEPTION 'Expense with ID % not found for business %.', v_expense_id, v_business_id;
        END IF;

        v_transaction_id := v_existing_txn_id;

        -- Update Transaction Header (assuming immediate payment)
        UPDATE public.transactions
        SET
            reference_no = v_ref_no,
            transaction_date = v_date,
            total_amount = v_amount,
            paid_amount = v_amount,
            due_amount = 0,
            status = 'PAID'::public.transaction_status,
            notes = v_note,
            updated_at = now()
        WHERE transaction_id = v_transaction_id
          AND business_id = v_business_id;

        -- Check potential unique violation on reference_no if it changed
        IF NOT FOUND AND v_reference_number IS NOT NULL THEN
             PERFORM 1 FROM public.transactions
             WHERE reference_no = v_ref_no
               AND business_id = v_business_id
               AND transaction_id != v_transaction_id;
             IF FOUND THEN
                 RAISE EXCEPTION 'Reference number "%" already exists for another transaction in this business.', v_ref_no;
             END IF;
             RAISE EXCEPTION 'Failed to update transaction header for ID %.', v_transaction_id;
        END IF;

        -- Update Expense Details
        UPDATE public.expenses
        SET
            date = v_date,
            payment_type = v_payment_type,
            expense_for = v_expense_for,
            amount = v_amount,
            note = v_note,
            reference_number = v_ref_no,
            expense_category_id = v_expense_category_id
        WHERE expense_id = v_expense_id;

        -- Recreate Transaction Entries (Delete old, Insert new using fetched account IDs)
        DELETE FROM public.transaction_entries WHERE transaction_id = v_transaction_id;


    ELSE
        -- ======== INSERT PATH ========
        -- Create Transaction Header (assuming immediate payment)
            reference_no, transaction_type, transaction_date, status,
            total_amount, paid_amount, due_amount, notes, business_id, created_by
        ) VALUES (
            v_ref_no, 'EXPENSE'::public.transaction_type, v_date, 'PAID'::public.transaction_status,
            v_amount, v_amount, 0, v_note, v_business_id, v_user_id
        ) RETURNING transaction_id INTO v_transaction_id;

        -- Create Expense Record
            date, payment_type, expense_for, amount, note, reference_number,
            business_id, expense_category_id, transaction_id
        ) VALUES (
            v_date, v_payment_type, v_expense_for, v_amount, v_note, v_ref_no,
            v_business_id, v_expense_category_id, v_transaction_id
        ) RETURNING expense_id INTO v_expense_id;

        -- Create Transaction Entries (using fetched account IDs)

    END IF;

    -- ============ FINAL VALIDATION STEP ============
    -- This ensures balance AFTER all entries for this expense are created/updated
    PERFORM public.verify_transaction_balance(v_transaction_id);
    -- ==============================================

    RETURN v_expense_id;

EXCEPTION
    WHEN unique_violation THEN
        RAISE EXCEPTION 'Failed to upsert expense: Unique constraint violated. Check reference number "%". Detail: %', v_ref_no, SQLERRM;
    WHEN others THEN
        RAISE EXCEPTION 'Failed to upsert expense: %', SQLERRM;
END;
$$;


ALTER FUNCTION public.upsert_expense(p_expense_data jsonb) OWNER TO postgres;

--
-- TOC entry 1012 (class 1255 OID 264649)
-- Name: upsert_income(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.upsert_income(p_income_data jsonb) RETURNS uuid
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_income_id UUID := p_income_data->>'income_id';
    v_transaction_id UUID;
    v_business_id UUID := p_income_data->>'business_id';
    v_user_id UUID := auth.uid(); -- Assuming you use Supabase auth
    v_date TIMESTAMPTZ := (p_income_data->>'date')::timestamptz;
    v_amount NUMERIC := (p_income_data->>'amount')::numeric;
    v_income_account_id UUID; -- Default Income Account
    v_asset_account_id UUID;  -- Account where money is received (Cash/Bank)
    v_income_for TEXT := p_income_data->>'income_for';
    v_payment_type public.payment_type := (p_income_data->>'payment_type')::public.payment_type;
    v_note TEXT := p_income_data->>'note';
    v_reference_number TEXT := p_income_data->>'reference_number';
    v_income_category_id UUID := (p_income_data->>'income_category_id')::uuid; -- Optional link to income_categories table
    v_existing_txn_id UUID;
    v_ref_no TEXT;
    v_default_income_code TEXT := '4030'; -- Code for 'Income from Other Sources'
    v_petty_cash_code TEXT := '1010';     -- Code for 'Petty Cash'
    v_cash_in_bank_code TEXT := '1011';   -- Code for 'Cash in Bank'
BEGIN
    -- Validate required fields from JSON
    IF v_business_id IS NULL OR v_date IS NULL OR v_amount IS NULL OR v_amount <= 0 OR v_income_for IS NULL OR v_payment_type IS NULL THEN
        RAISE EXCEPTION 'Missing required income data: business_id, date, amount > 0, income_for, payment_type are required.';
    END IF;

    -- Fetch the default income account ID
    SELECT account_id INTO v_income_account_id
    FROM public.accounts
    WHERE business_id = v_business_id AND code = v_default_income_code AND is_group = FALSE;

    IF v_income_account_id IS NULL THEN
        RAISE EXCEPTION 'Default income account (Code: %) not found for business_id %.', v_default_income_code, v_business_id;
    END IF;

    -- Determine the asset account ID based on payment_type
    IF v_payment_type = 'cash' THEN -- Adjust type names if needed
        SELECT account_id INTO v_asset_account_id
        FROM public.accounts
        WHERE business_id = v_business_id AND code = v_petty_cash_code AND is_group = FALSE;

        IF v_asset_account_id IS NULL THEN
            RAISE EXCEPTION 'Petty Cash account (Code: %) not found for business_id %.', v_petty_cash_code, v_business_id;
        END IF;
    ELSE -- Assume Bank, Card, Transfer, Other map to Cash in Bank
        SELECT account_id INTO v_asset_account_id
        FROM public.accounts
        WHERE business_id = v_business_id AND code = v_cash_in_bank_code AND is_group = FALSE;

        IF v_asset_account_id IS NULL THEN
            RAISE EXCEPTION 'Cash in Bank account (Code: %) not found for business_id %.', v_cash_in_bank_code, v_business_id;
        END IF;
    END IF;

    -- Generate a reference number if not provided (example logic)
    IF v_reference_number IS NULL OR v_reference_number = '' THEN
         v_ref_no := 'INC-' || to_char(v_date, 'YYYYMMDD') || '-' || upper(substring(gen_random_uuid()::text from 1 for 6));
    ELSE
        v_ref_no := v_reference_number;
    END IF;

    IF v_income_id IS NOT NULL THEN
        -- ======== UPDATE PATH ========
        SELECT transaction_id INTO v_existing_txn_id
        FROM public.incomes
        WHERE income_id = v_income_id AND business_id = v_business_id;

        IF v_existing_txn_id IS NULL THEN
            RAISE EXCEPTION 'Income with ID % not found for business %.', v_income_id, v_business_id;
        END IF;

        v_transaction_id := v_existing_txn_id;

        -- Update Transaction Header (assuming immediate receipt)
        UPDATE public.transactions
        SET
            reference_no = v_ref_no,
            transaction_date = v_date,
            total_amount = v_amount,
            paid_amount = v_amount, -- Income is 'paid' immediately in this model
            due_amount = 0,         -- No amount is 'due' to be received
            status = 'PAID'::public.transaction_status, -- Or maybe 'RECEIVED'? Using PAID for consistency
            notes = v_note,
            updated_at = now()
            -- transaction_type and created_by are not updated
        WHERE transaction_id = v_transaction_id
          AND business_id = v_business_id;

        -- Check potential unique violation on reference_no if it changed
        IF NOT FOUND AND v_reference_number IS NOT NULL THEN
             PERFORM 1 FROM public.transactions
             WHERE reference_no = v_ref_no
               AND business_id = v_business_id
               AND transaction_id != v_transaction_id;
             IF FOUND THEN
                 RAISE EXCEPTION 'Reference number "%" already exists for another transaction in this business.', v_ref_no;
             END IF;
             RAISE EXCEPTION 'Failed to update transaction header for ID %.', v_transaction_id;
        END IF;

        -- Update Income Details
        UPDATE public.incomes
        SET
            date = v_date,
            payment_type = v_payment_type,
            income_for = v_income_for,
            amount = v_amount,
            note = v_note,
            reference_number = v_ref_no,
            income_category_id = v_income_category_id
        WHERE income_id = v_income_id;

        -- Recreate Transaction Entries (Delete old, Insert new using fetched account IDs)
        DELETE FROM public.transaction_entries WHERE transaction_id = v_transaction_id;

            -- Income received increases Asset (Debit)
            (v_transaction_id, v_asset_account_id, 'DEBIT'::public.entry_type, v_amount, 'Received income for ' || v_income_for),
            -- Income increases Revenue/Equity (Credit)
            (v_transaction_id, v_income_account_id, 'CREDIT'::public.entry_type, v_amount, v_income_for);

    ELSE
        -- ======== INSERT PATH ========
        -- Create Transaction Header (assuming immediate receipt)
            reference_no, transaction_type, transaction_date, status,
            total_amount, paid_amount, due_amount, notes, business_id, created_by
        ) VALUES (
            v_ref_no, 'INCOME'::public.transaction_type, v_date, 'PAID'::public.transaction_status, -- Or maybe 'RECEIVED'?
            v_amount, v_amount, 0, v_note, v_business_id, v_user_id
        ) RETURNING transaction_id INTO v_transaction_id;

        -- Create Income Record
            date, payment_type, income_for, amount, note, reference_number,
            business_id, income_category_id, transaction_id
        ) VALUES (
            v_date, v_payment_type, v_income_for, v_amount, v_note, v_ref_no,
            v_business_id, v_income_category_id, v_transaction_id
        ) RETURNING income_id INTO v_income_id;

        -- Create Transaction Entries (using fetched account IDs)
            -- Income received increases Asset (Debit)
            (v_transaction_id, v_asset_account_id, 'DEBIT'::public.entry_type, v_amount, 'Received income for ' || v_income_for),
            -- Income increases Revenue/Equity (Credit)
            (v_transaction_id, v_income_account_id, 'CREDIT'::public.entry_type, v_amount, v_income_for);

    END IF;

    -- ============ FINAL VALIDATION STEP ============
    PERFORM public.verify_transaction_balance(v_transaction_id);
    -- ==============================================

    RETURN v_income_id;

EXCEPTION
    WHEN unique_violation THEN
        RAISE EXCEPTION 'Failed to upsert income: Unique constraint violated. Check reference number "%". Detail: %', v_ref_no, SQLERRM;
    WHEN others THEN
        IF SQLERRM LIKE 'Double-entry imbalance for transaction %' THEN
             RAISE EXCEPTION '%', SQLERRM; -- Re-raise the specific balance error
        ELSE
             RAISE EXCEPTION 'Failed to upsert income: %', SQLERRM; -- Raise other errors
        END IF;
END;
$$;


ALTER FUNCTION public.upsert_income(p_income_data jsonb) OWNER TO postgres;

--
-- TOC entry 1013 (class 1255 OID 264651)
-- Name: upsert_item(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.upsert_item(item_json jsonb) RETURNS uuid
    LANGUAGE plpgsql
    AS $$
DECLARE
    -- Input Extraction
    v_item_id_in              UUID := (item_json->>'item_id')::uuid;
    v_business_id           UUID := (item_json->>'business_id')::uuid;
    v_org_id                UUID := (item_json->>'org_id')::uuid;
    v_name                  TEXT := item_json->>'name';
    v_item_type             public.item_type := (item_json->>'item_type')::public.item_type;
    v_item_category_id      UUID := (item_json->>'item_category_id')::uuid;
    v_brand_id              UUID := (item_json->>'brand_id')::uuid;
    v_tax_id                UUID := (item_json->>'tax_id')::uuid;
    v_preferred_vendor_id   UUID := (item_json->>'preferred_vendor_id')::uuid;
    v_item_code             TEXT := item_json->>'item_code'; -- Use provided code or generate below
    v_unit_id               UUID := (item_json->>'unit_id')::uuid;
    v_sale_price            NUMERIC := COALESCE((item_json->>'sale_price')::numeric, 0);
    v_retail_price          NUMERIC := COALESCE((item_json->>'retail_price')::numeric, 0);
    v_purchase_price        NUMERIC := COALESCE((item_json->>'purchase_price')::numeric, 0);
    v_is_returnable         BOOLEAN := COALESCE((item_json->>'is_returnable')::boolean, false);
    v_alert_quantity        NUMERIC := COALESCE((item_json->>'alert_quantity')::numeric, 0);
    v_quantity              NUMERIC := COALESCE((item_json->>'quantity')::numeric, 0);
    v_rich_text             JSONB := item_json->'rich_text';
    v_sales_enabled         BOOLEAN := COALESCE((item_json->>'sales_enabled')::boolean, true);
    v_purchase_enabled      BOOLEAN := COALESCE((item_json->>'purchase_enabled')::boolean, true);
    v_inventory_enabled     BOOLEAN := COALESCE((item_json->>'inventory_enabled')::boolean, true);
    v_opening_stock_qty     NUMERIC := COALESCE((item_json->>'opening_stock_qty')::numeric, 0); -- Renamed JSON key for clarity
    v_opening_stock_value   NUMERIC := COALESCE((item_json->>'opening_stock_value')::numeric, 0); -- Renamed JSON key for clarity

    -- Arrays
    v_serial_nos            TEXT[];
    v_images                JSONB[];

    -- Internal Vars
    v_item_id_out           UUID;
    v_is_insert             BOOLEAN := FALSE;
    v_transaction_id        UUID;
    v_ob_ref_no             TEXT;
    v_user_id               UUID := auth.uid(); -- Assuming Supabase auth

    -- Account IDs & Codes
    v_inventory_account_id  UUID;
    v_ob_equity_account_id  UUID;
    v_inventory_code        TEXT := '1030'; -- Standard Inventory Account Code
    v_ob_equity_code        TEXT := '3900'; -- Standard Opening Balance Equity Code

BEGIN
    -- Extract arrays
    SELECT array_agg(value::text) INTO v_serial_nos FROM jsonb_array_elements_text(COALESCE(item_json->'serial_nos', '[]'::jsonb));
    SELECT array_agg(value::jsonb) INTO v_images FROM jsonb_array_elements(COALESCE(item_json->'images', '[]'::jsonb)); -- Fixed array aggregation for JSONB

-- Check if item_code is provided and if it has changed
IF v_item_code IS NULL THEN
    -- Generate item_code if not provided (using a sequence per business is robust)
    SELECT get_next_item_code(v_business_id) INTO v_item_code;
    RAISE WARNING 'Item code not provided, generated: %', v_item_code;
END IF;

-- Check uniqueness of item_code only if it's being changed (i.e., it's different from the original item code)
IF v_item_code != (SELECT item_code FROM public.items WHERE item_id = v_item_id_in AND business_id = v_business_id) THEN
    PERFORM 1 FROM public.items WHERE business_id = v_business_id AND item_code = v_item_code;
    IF FOUND THEN
        RAISE EXCEPTION 'Item code % already exists for business %.', v_item_code, v_business_id;
    END IF;
END IF;
    -- ==== INSERT or UPDATE ====
    IF v_item_id_in IS NULL THEN
        -- ======== INSERT PATH ========
        v_is_insert := TRUE;

            name, item_type, item_code, item_category_id, brand_id, unit_id,
            sales_enabled, purchase_enabled, inventory_enabled, is_returnable,
            sale_price, retail_price, purchase_price, alert_quantity, preferred_vendor_id,
            tax_id, images, serial_nos, rich_text, quantity,
            business_id, org_id,
            -- Set initial stock based on opening values
            stock_quantity, stock_value,
            opening_stock_qty, opening_stock_value,
            created_at, updated_at
            -- branch_variant_id defaults in table definition
        ) VALUES (
            v_name, v_item_type, v_item_code, v_item_category_id, v_brand_id, v_unit_id,
            v_sales_enabled, v_purchase_enabled, v_inventory_enabled, v_is_returnable,
            v_sale_price, v_retail_price, v_purchase_price, v_alert_quantity, v_preferred_vendor_id,
            v_tax_id, v_images, v_serial_nos, v_rich_text, v_quantity,
            v_business_id, v_org_id,
            -- Initial stock IS the opening stock
            v_opening_stock_qty, v_opening_stock_value,
            v_opening_stock_qty, v_opening_stock_value,
            now(), now()
        )
        RETURNING item_id INTO v_item_id_out;

        -- Handle subservices on insert
        IF v_item_type = 'services' AND item_json->'sub_services' IS NOT NULL THEN
            WITH sub_services AS (
                SELECT * FROM jsonb_array_elements(item_json->'sub_services')
            )
            SELECT
                v_item_id_out,
                sub_services.value->>'name',
                (sub_services.value->>'additional_price')::numeric
            FROM sub_services;
            -- WHERE sub_services.value->>'sub_service_id' IS NULL; -- Not needed on initial insert
        END IF;
		PERFORM nextval(v_business_id::text || '_item_code'); -- Removed redundant nextval call
    ELSE
        -- ======== UPDATE PATH ========
        v_item_id_out := v_item_id_in;
        v_is_insert := FALSE;

        UPDATE public.items SET
            name = v_name,
            item_code = v_item_code, -- Allow item code update? Maybe only if unique constraint allows.
            item_category_id = v_item_category_id,
            brand_id = v_brand_id,
            unit_id = v_unit_id,
            sales_enabled = v_sales_enabled,
            purchase_enabled = v_purchase_enabled,
            inventory_enabled = v_inventory_enabled,
            is_returnable = v_is_returnable,
            sale_price = v_sale_price,
            retail_price = v_retail_price,
            purchase_price = v_purchase_price,
            alert_quantity = v_alert_quantity,
			quantity = v_quantity,
            preferred_vendor_id = v_preferred_vendor_id,
            tax_id = v_tax_id,
            images = v_images,
            serial_nos = v_serial_nos,
            rich_text = v_rich_text,
            updated_at = now()
            -- DO NOT UPDATE opening_stock_qty, opening_stock_value, stock_quantity, stock_value here.
            -- Stock changes happen via Purchase, Sale, Adjustment transactions.
        WHERE item_id = v_item_id_out
          AND business_id = v_business_id;

        IF NOT FOUND THEN
            RAISE EXCEPTION 'Item ID % not found for business %.', v_item_id_out, v_business_id;
        END IF;

        -- Handle subservice updates
        IF v_item_type = 'services' AND item_json->'sub_services' IS NOT NULL THEN
             -- Delete sub-services not in the new list
            DELETE FROM public.subservices s
            WHERE s.service_id = v_item_id_out
            AND NOT EXISTS (
                SELECT 1
                FROM jsonb_array_elements(item_json->'sub_services') elem
                WHERE elem->>'sub_service_id' IS NOT NULL AND (elem->>'sub_service_id')::uuid = s.sub_service_id
            );

            -- Insert new sub-services (those without an ID in the input)
            WITH sub_services AS (
                SELECT * FROM jsonb_array_elements(item_json->'sub_services')
                WHERE value->>'sub_service_id' IS NULL
            )
            SELECT
                v_item_id_out,
                sub_services.value->>'name',
                (sub_services.value->>'additional_price')::numeric
            FROM sub_services;

            -- Update existing sub-services (those with an ID in the input)
            UPDATE public.subservices s
            SET
                name = sub.name,
                additional_price = sub.additional_price
            FROM (
                SELECT
                    (elem->>'sub_service_id')::uuid as sub_service_id,
                    elem->>'name' as name,
                    (elem->>'additional_price')::numeric as additional_price
                FROM jsonb_array_elements(item_json->'sub_services') elem
                WHERE elem->>'sub_service_id' IS NOT NULL
            ) sub
            WHERE s.sub_service_id = sub.sub_service_id
            AND s.service_id = v_item_id_out;
        END IF;

    END IF; -- End INSERT/UPDATE Check

    -- ==== OPENING BALANCE ACCOUNTING (INSERT ONLY) ====
    IF v_is_insert AND v_inventory_enabled AND v_opening_stock_value != 0 THEN

        -- Fetch required account IDs for the business
        SELECT account_id INTO v_inventory_account_id FROM public.accounts WHERE business_id = v_business_id AND code = v_inventory_code;
        SELECT account_id INTO v_ob_equity_account_id FROM public.accounts WHERE business_id = v_business_id AND code = v_ob_equity_code;

        -- Validate that accounts exist
        IF v_inventory_account_id IS NULL THEN
             RAISE EXCEPTION 'Inventory account (Code: %) not found for business %.', v_inventory_code, v_business_id;
        END IF;
        IF v_ob_equity_account_id IS NULL THEN
             RAISE EXCEPTION 'Opening Balance Equity account (Code: %) not found for business %.', v_ob_equity_code, v_business_id;
        END IF;

        -- Generate a unique reference number for the opening balance transaction
        v_ob_ref_no := 'OB-ITEM-' || v_item_id_out::text; -- Simple reference

        -- Create the Transaction Header
            reference_no, transaction_type, transaction_date, status,
            total_amount, paid_amount, due_amount,
            notes, business_id, created_by,
            item_id -- Link to item
        ) VALUES (
            v_ob_ref_no, 'OPENING_STOCK'::public.transaction_type, now(), 'PAID'::public.transaction_status, -- Mark as PAID/Complete
            abs(v_opening_stock_value), abs(v_opening_stock_value), 0, -- OB is self-balancing
            'Opening stock value for item ' || v_name || ' (' || v_item_code || ')', v_business_id, v_user_id,
            v_item_id_out
        ) RETURNING transaction_id INTO v_transaction_id;

        -- Create Correct Transaction Entries
        -- Debit Inventory (Asset Increase), Credit OB Equity (Offset)

        -- Verify the balance of the opening balance transaction itself
        PERFORM public.verify_transaction_balance(v_transaction_id);

    END IF; -- End Opening Balance Accounting

    RETURN v_item_id_out;

EXCEPTION
    WHEN unique_violation THEN
        -- Could be item_code constraint or generated OB reference_no collision
        RAISE EXCEPTION 'Failed to upsert item: Unique constraint violated. Check item code "%". Detail: %', v_item_code, SQLERRM;
    WHEN others THEN
        RAISE EXCEPTION 'Failed to upsert item: %', SQLERRM;
END;
$$;


ALTER FUNCTION public.upsert_item(item_json jsonb) OWNER TO postgres;

--
-- TOC entry 1015 (class 1255 OID 264653)
-- Name: upsert_supplier(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.upsert_supplier(p_supplier_data jsonb) RETURNS uuid
    LANGUAGE plpgsql
    AS $$
DECLARE
    -- Input Data
    v_supplier_id UUID := p_supplier_data->>'supplier_id';
    v_business_id UUID := p_supplier_data->>'business_id';
    v_org_id UUID := p_supplier_data->>'org_id';
    v_name TEXT := p_supplier_data->>'name';
    v_email TEXT := p_supplier_data->>'email';
    v_phone TEXT := p_supplier_data->>'phone';
    v_address TEXT := p_supplier_data->>'address';
    v_gst_number TEXT := p_supplier_data->>'gst_number';
    v_image TEXT := p_supplier_data->>'image';
    -- Input opening_balance uses the new convention: >0 Supplier Owes Us, <0 We Owe Supplier
    v_opening_balance NUMERIC := COALESCE((p_supplier_data->>'supplier_balance')::numeric, 0);
    v_opening_balance_date TIMESTAMPTZ := now();

    -- Internal Variables
    v_user_id UUID := auth.uid();
    v_is_insert BOOLEAN := FALSE;
    v_transaction_id UUID;
    v_ref_no TEXT;
    v_result_supplier_id UUID;

    -- Account IDs
    v_ap_supp_acc_id UUID;   -- Accounts Payable - Suppliers (2010)
    v_ar_supp_acc_id UUID;   -- Receivables from Suppliers (1021)
    v_ob_equity_acc_id UUID; -- Opening Balance Equity (3900)

    -- Account Codes
    v_ap_supp_code TEXT := '2010';
    v_ar_supp_code TEXT := '1021';
    v_ob_equity_code TEXT := '3900';
BEGIN
    -- Validate required inputs
    IF v_business_id IS NULL OR v_org_id IS NULL OR v_name IS NULL OR v_phone IS NULL THEN
        RAISE EXCEPTION 'business_id, org_id, name, and phone are required.';
    END IF;

    -- Handle INSERT or UPDATE
    IF v_supplier_id IS NULL THEN
        -- ======== INSERT PATH ========
        v_is_insert := TRUE;
            supplier_id, name, email, phone, address, gst_number,
            business_id, org_id, image, created_at, updated_at,
            supplier_balance -- Start balance at 0, trigger will adjust if OB applied
        ) VALUES (
            gen_random_uuid(), v_name, v_email, v_phone, v_address, v_gst_number,
            v_business_id, v_org_id, v_image, now(), now(),
            0
        ) RETURNING suppliers.supplier_id INTO v_result_supplier_id;
    ELSE
        -- ======== UPDATE PATH ========
        v_is_insert := FALSE;
        UPDATE public.suppliers
        SET
            name = v_name,
            email = v_email,
            phone = v_phone,
            address = v_address,
            gst_number = v_gst_number,
            image = v_image,
            updated_at = now()
        WHERE supplier_id = v_supplier_id
          AND business_id = v_business_id
        RETURNING suppliers.supplier_id INTO v_result_supplier_id;

        IF NOT FOUND THEN
            RAISE EXCEPTION 'Supplier with ID % not found for business %.', v_supplier_id, v_business_id;
        END IF;
    END IF;


    -- If it was an INSERT AND an opening balance was provided and is non-zero
    IF v_is_insert AND v_opening_balance != 0 THEN

        -- Fetch required account IDs
        SELECT account_id INTO v_ap_supp_acc_id FROM public.accounts WHERE business_id = v_business_id AND code = v_ap_supp_code;
        SELECT account_id INTO v_ar_supp_acc_id FROM public.accounts WHERE business_id = v_business_id AND code = v_ar_supp_code;
        SELECT account_id INTO v_ob_equity_acc_id FROM public.accounts WHERE business_id = v_business_id AND code = v_ob_equity_code;

        -- Validate that accounts exist
        IF v_ob_equity_acc_id IS NULL THEN
             RAISE EXCEPTION 'Opening Balance Equity account (Code: %) not found for business %.', v_ob_equity_code, v_business_id;
        END IF;
        -- Positive OB: Supplier owes Business -> Need A/R Account
        IF v_opening_balance > 0 AND v_ar_supp_acc_id IS NULL THEN
             RAISE EXCEPTION 'Receivables from Suppliers account (Code: %) not found for business %.', v_ar_supp_code, v_business_id;
        END IF;
        -- Negative OB: Business owes Supplier -> Need A/P Account
         IF v_opening_balance < 0 AND v_ap_supp_acc_id IS NULL THEN
             RAISE EXCEPTION 'Accounts Payable - Suppliers account (Code: %) not found for business %.', v_ap_supp_code, v_business_id;
        END IF;

        -- Generate a unique reference number
        v_ref_no := 'OB-SUPP-' || v_result_supplier_id::text || '-' || to_char(v_opening_balance_date, 'YYYYMMDD');

        -- Create the Transaction Header
            reference_no, transaction_type, transaction_date, status,
            total_amount, paid_amount, due_amount,
            notes, business_id, created_by, supplier_id -- Link to supplier
        ) VALUES (
            v_ref_no, 'SUPPLIER_OPENING_BALANCE'::public.transaction_type, v_opening_balance_date, 'PAID'::public.transaction_status,
            abs(v_opening_balance), abs(v_opening_balance), 0,
            'Opening balance setup for supplier ' || v_name, v_business_id, v_user_id, v_result_supplier_id
        ) RETURNING transaction_id INTO v_transaction_id;

        -- *** MODIFIED GL ENTRIES FOR OPENING BALANCE ***
        IF v_opening_balance < 0 THEN
            -- Positive OB means Supplier Owes Business (Asset): Debit A/R, Credit OB Equity
        ELSE -- v_opening_balance < 0
            -- Negative OB means Business Owes Supplier (Liability): Debit OB Equity, Credit A/P
        END IF;

        -- Verify the balance of the opening balance transaction itself
        PERFORM public.verify_transaction_balance(v_transaction_id);

        -- The trigger trigger_update_supplier_balance will update suppliers.supplier_balance

    END IF; -- End of opening balance handling

    RETURN v_result_supplier_id;

EXCEPTION
    WHEN unique_violation THEN
        RAISE EXCEPTION 'Failed to upsert supplier OB: Unique constraint violated. Detail: %', SQLERRM;
    WHEN others THEN
        RAISE EXCEPTION 'Failed to upsert supplier: %', SQLERRM;
END;
$$;


ALTER FUNCTION public.upsert_supplier(p_supplier_data jsonb) OWNER TO postgres;

--
-- TOC entry 1011 (class 1255 OID 264655)
-- Name: verify_transaction_balance(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.verify_transaction_balance(p_transaction_id uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_debit_total NUMERIC := 0;
    v_credit_total NUMERIC := 0;
BEGIN
    -- Calculate totals for the given transaction ID based on current state within the transaction
    SELECT
        COALESCE(SUM(CASE WHEN entry_type = 'DEBIT' THEN amount ELSE 0 END), 0),
        COALESCE(SUM(CASE WHEN entry_type = 'CREDIT' THEN amount ELSE 0 END), 0)
    INTO v_debit_total, v_credit_total
    FROM public.transaction_entries
    WHERE transaction_id = p_transaction_id;

    -- Using a small tolerance might be wise if you ever use floating-point types,
    -- but with NUMERIC, direct comparison should be fine.
    -- IF abs(v_debit_total - v_credit_total) > 0.0001 THEN -- Example with tolerance
    IF v_debit_total != v_credit_total THEN
        RAISE EXCEPTION 'Double-entry imbalance for transaction %: Debits (%) do not equal Credits (%).',
            p_transaction_id, v_debit_total, v_credit_total;
    END IF;

    -- If balanced, simply return
END;
$$;


ALTER FUNCTION public.verify_transaction_balance(p_transaction_id uuid) OWNER TO postgres;

--
-- TOC entry 787 (class 1255 OID 276332)
-- Name: verify_user_password(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.verify_user_password(password text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
  RETURN EXISTS (
    SELECT id 
    FROM auth.users 
    WHERE id = auth.uid() AND encrypted_password = crypt(password::text, auth.users.encrypted_password)
  );
END;
$$;


ALTER FUNCTION public.verify_user_password(password text) OWNER TO postgres;

--
-- TOC entry 1059 (class 1255 OID 29061)
-- Name: apply_rls(jsonb, integer); Type: FUNCTION; Schema: realtime; Owner: supabase_admin
--

CREATE FUNCTION realtime.apply_rls(wal jsonb, max_record_bytes integer DEFAULT (1024 * 1024)) RETURNS SETOF realtime.wal_rls
    LANGUAGE plpgsql
    AS $$
declare
-- Regclass of the table e.g. public.notes
entity_ regclass = (quote_ident(wal ->> 'schema') || '.' || quote_ident(wal ->> 'table'))::regclass;

-- I, U, D, T: insert, update ...
action realtime.action = (
    case wal ->> 'action'
        when 'I' then 'INSERT'
        when 'U' then 'UPDATE'
        when 'D' then 'DELETE'
        else 'ERROR'
    end
);

-- Is row level security enabled for the table
is_rls_enabled bool = relrowsecurity from pg_class where oid = entity_;

subscriptions realtime.subscription[] = array_agg(subs)
    from
        realtime.subscription subs
    where
        subs.entity = entity_;

-- Subscription vars
roles regrole[] = array_agg(distinct us.claims_role::text)
    from
        unnest(subscriptions) us;

working_role regrole;
claimed_role regrole;
claims jsonb;

subscription_id uuid;
subscription_has_access bool;
visible_to_subscription_ids uuid[] = '{}';

-- structured info for wal's columns
columns realtime.wal_column[];
-- previous identity values for update/delete
old_columns realtime.wal_column[];

error_record_exceeds_max_size boolean = octet_length(wal::text) > max_record_bytes;

-- Primary jsonb output for record
output jsonb;

begin
perform set_config('role', null, true);

columns =
    array_agg(
        (
            x->>'name',
            x->>'type',
            x->>'typeoid',
            realtime.cast(
                (x->'value') #>> '{}',
                coalesce(
                    (x->>'typeoid')::regtype, -- null when wal2json version <= 2.4
                    (x->>'type')::regtype
                )
            ),
            (pks ->> 'name') is not null,
            true
        )::realtime.wal_column
    )
    from
        jsonb_array_elements(wal -> 'columns') x
        left join jsonb_array_elements(wal -> 'pk') pks
            on (x ->> 'name') = (pks ->> 'name');

old_columns =
    array_agg(
        (
            x->>'name',
            x->>'type',
            x->>'typeoid',
            realtime.cast(
                (x->'value') #>> '{}',
                coalesce(
                    (x->>'typeoid')::regtype, -- null when wal2json version <= 2.4
                    (x->>'type')::regtype
                )
            ),
            (pks ->> 'name') is not null,
            true
        )::realtime.wal_column
    )
    from
        jsonb_array_elements(wal -> 'identity') x
        left join jsonb_array_elements(wal -> 'pk') pks
            on (x ->> 'name') = (pks ->> 'name');

for working_role in select * from unnest(roles) loop

    -- Update `is_selectable` for columns and old_columns
    columns =
        array_agg(
            (
                c.name,
                c.type_name,
                c.type_oid,
                c.value,
                c.is_pkey,
                pg_catalog.has_column_privilege(working_role, entity_, c.name, 'SELECT')
            )::realtime.wal_column
        )
        from
            unnest(columns) c;

    old_columns =
            array_agg(
                (
                    c.name,
                    c.type_name,
                    c.type_oid,
                    c.value,
                    c.is_pkey,
                    pg_catalog.has_column_privilege(working_role, entity_, c.name, 'SELECT')
                )::realtime.wal_column
            )
            from
                unnest(old_columns) c;

    if action <> 'DELETE' and count(1) = 0 from unnest(columns) c where c.is_pkey then
        return next (
            jsonb_build_object(
                'schema', wal ->> 'schema',
                'table', wal ->> 'table',
                'type', action
            ),
            is_rls_enabled,
            -- subscriptions is already filtered by entity
            (select array_agg(s.subscription_id) from unnest(subscriptions) as s where claims_role = working_role),
            array['Error 400: Bad Request, no primary key']
        )::realtime.wal_rls;

    -- The claims role does not have SELECT permission to the primary key of entity
    elsif action <> 'DELETE' and sum(c.is_selectable::int) <> count(1) from unnest(columns) c where c.is_pkey then
        return next (
            jsonb_build_object(
                'schema', wal ->> 'schema',
                'table', wal ->> 'table',
                'type', action
            ),
            is_rls_enabled,
            (select array_agg(s.subscription_id) from unnest(subscriptions) as s where claims_role = working_role),
            array['Error 401: Unauthorized']
        )::realtime.wal_rls;

    else
        output = jsonb_build_object(
            'schema', wal ->> 'schema',
            'table', wal ->> 'table',
            'type', action,
            'commit_timestamp', to_char(
                ((wal ->> 'timestamp')::timestamptz at time zone 'utc'),
                'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'
            ),
            'columns', (
                select
                    jsonb_agg(
                        jsonb_build_object(
                            'name', pa.attname,
                            'type', pt.typname
                        )
                        order by pa.attnum asc
                    )
                from
                    pg_attribute pa
                    join pg_type pt
                        on pa.atttypid = pt.oid
                where
                    attrelid = entity_
                    and attnum > 0
                    and pg_catalog.has_column_privilege(working_role, entity_, pa.attname, 'SELECT')
            )
        )
        -- Add "record" key for insert and update
        || case
            when action in ('INSERT', 'UPDATE') then
                jsonb_build_object(
                    'record',
                    (
                        select
                            jsonb_object_agg(
                                -- if unchanged toast, get column name and value from old record
                                coalesce((c).name, (oc).name),
                                case
                                    when (c).name is null then (oc).value
                                    else (c).value
                                end
                            )
                        from
                            unnest(columns) c
                            full outer join unnest(old_columns) oc
                                on (c).name = (oc).name
                        where
                            coalesce((c).is_selectable, (oc).is_selectable)
                            and ( not error_record_exceeds_max_size or (octet_length((c).value::text) <= 64))
                    )
                )
            else '{}'::jsonb
        end
        -- Add "old_record" key for update and delete
        || case
            when action = 'UPDATE' then
                jsonb_build_object(
                        'old_record',
                        (
                            select jsonb_object_agg((c).name, (c).value)
                            from unnest(old_columns) c
                            where
                                (c).is_selectable
                                and ( not error_record_exceeds_max_size or (octet_length((c).value::text) <= 64))
                        )
                    )
            when action = 'DELETE' then
                jsonb_build_object(
                    'old_record',
                    (
                        select jsonb_object_agg((c).name, (c).value)
                        from unnest(old_columns) c
                        where
                            (c).is_selectable
                            and ( not error_record_exceeds_max_size or (octet_length((c).value::text) <= 64))
                            and ( not is_rls_enabled or (c).is_pkey ) -- if RLS enabled, we can't secure deletes so filter to pkey
                    )
                )
            else '{}'::jsonb
        end;

        -- Create the prepared statement
        if is_rls_enabled and action <> 'DELETE' then
            if (select 1 from pg_prepared_statements where name = 'walrus_rls_stmt' limit 1) > 0 then
                deallocate walrus_rls_stmt;
            end if;
            execute realtime.build_prepared_statement_sql('walrus_rls_stmt', entity_, columns);
        end if;

        visible_to_subscription_ids = '{}';

        for subscription_id, claims in (
                select
                    subs.subscription_id,
                    subs.claims
                from
                    unnest(subscriptions) subs
                where
                    subs.entity = entity_
                    and subs.claims_role = working_role
                    and (
                        realtime.is_visible_through_filters(columns, subs.filters)
                        or (
                          action = 'DELETE'
                          and realtime.is_visible_through_filters(old_columns, subs.filters)
                        )
                    )
        ) loop

            if not is_rls_enabled or action = 'DELETE' then
                visible_to_subscription_ids = visible_to_subscription_ids || subscription_id;
            else
                -- Check if RLS allows the role to see the record
                perform
                    -- Trim leading and trailing quotes from working_role because set_config
                    -- doesn't recognize the role as valid if they are included
                    set_config('role', trim(both '"' from working_role::text), true),
                    set_config('request.jwt.claims', claims::text, true);

                execute 'execute walrus_rls_stmt' into subscription_has_access;

                if subscription_has_access then
                    visible_to_subscription_ids = visible_to_subscription_ids || subscription_id;
                end if;
            end if;
        end loop;

        perform set_config('role', null, true);

        return next (
            output,
            is_rls_enabled,
            visible_to_subscription_ids,
            case
                when error_record_exceeds_max_size then array['Error 413: Payload Too Large']
                else '{}'
            end
        )::realtime.wal_rls;

    end if;
end loop;

perform set_config('role', null, true);
end;
$$;


ALTER FUNCTION realtime.apply_rls(wal jsonb, max_record_bytes integer) OWNER TO supabase_admin;

--
-- TOC entry 765 (class 1255 OID 112687)
-- Name: broadcast_changes(text, text, text, text, text, record, record, text); Type: FUNCTION; Schema: realtime; Owner: supabase_admin
--

CREATE FUNCTION realtime.broadcast_changes(topic_name text, event_name text, operation text, table_name text, table_schema text, new record, old record, level text DEFAULT 'ROW'::text) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    -- Declare a variable to hold the JSONB representation of the row
    row_data jsonb := '{}'::jsonb;
BEGIN
    IF level = 'STATEMENT' THEN
        RAISE EXCEPTION 'function can only be triggered for each row, not for each statement';
    END IF;
    -- Check the operation type and handle accordingly
    IF operation = 'INSERT' OR operation = 'UPDATE' OR operation = 'DELETE' THEN
        row_data := jsonb_build_object('old_record', OLD, 'record', NEW, 'operation', operation, 'table', table_name, 'schema', table_schema);
        PERFORM realtime.send (row_data, event_name, topic_name);
    ELSE
        RAISE EXCEPTION 'Unexpected operation type: %', operation;
    END IF;
EXCEPTION
    WHEN OTHERS THEN
        RAISE EXCEPTION 'Failed to process the row: %', SQLERRM;
END;

$$;


ALTER FUNCTION realtime.broadcast_changes(topic_name text, event_name text, operation text, table_name text, table_schema text, new record, old record, level text) OWNER TO supabase_admin;

--
-- TOC entry 1058 (class 1255 OID 29073)
-- Name: build_prepared_statement_sql(text, regclass, realtime.wal_column[]); Type: FUNCTION; Schema: realtime; Owner: supabase_admin
--

CREATE FUNCTION realtime.build_prepared_statement_sql(prepared_statement_name text, entity regclass, columns realtime.wal_column[]) RETURNS text
    LANGUAGE sql
    AS $$
      /*
      Builds a sql string that, if executed, creates a prepared statement to
      tests retrive a row from *entity* by its primary key columns.
      Example
          select realtime.build_prepared_statement_sql('public.notes', '{"id"}'::text[], '{"bigint"}'::text[])
      */
          select
      'prepare ' || prepared_statement_name || ' as
          select
              exists(
                  select
                      1
                  from
                      ' || entity || '
                  where
                      ' || string_agg(quote_ident(pkc.name) || '=' || quote_nullable(pkc.value #>> '{}') , ' and ') || '
              )'
          from
              unnest(columns) pkc
          where
              pkc.is_pkey
          group by
              entity
      $$;


ALTER FUNCTION realtime.build_prepared_statement_sql(prepared_statement_name text, entity regclass, columns realtime.wal_column[]) OWNER TO supabase_admin;

--
-- TOC entry 1055 (class 1255 OID 29023)
-- Name: cast(text, regtype); Type: FUNCTION; Schema: realtime; Owner: supabase_admin
--

CREATE FUNCTION realtime."cast"(val text, type_ regtype) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    AS $$
    declare
      res jsonb;
    begin
      execute format('select to_jsonb(%L::'|| type_::text || ')', val)  into res;
      return res;
    end
    $$;


