CREATE VIEW public.purchase_view AS
 SELECT p.purchase_id,
    p.purchase_invoice,
    p.invoice_no,
    p.supplier_id,
    p.purchase_date,
    p.transaction_id,
    p.subtotal,
    p.discount_amount,
    p.tax_amount,
    p.shipping_charge,
    p.total_amount,
    p.paid_amount,
